	public void GetEntitiesFronEntityStrings(List<string> SL, ref List<Entity> refEntities)
	{
		bool flag = false;
		bool flag2 = false;
		List<Point3D> list = new List<Point3D>();
		refEntities = new List<Entity>();
		for (int i = 0; i <= SL.Count - 1; i++)
		{
			if (SL[i].Trim() == "</Arc>")
			{
				if (list.Count == 3)
				{
					Arc item = new Arc(list[0], list[1], list[2], flip: false);
					refEntities.Add(item);
				}
				list.Clear();
				flag = false;
			}
			if (SL[i].Trim() == "</Line>")
			{
				if (list.Count != 2)
				{
					if (list.Count >= 3)
					{
						LinearPath item2 = new LinearPath(list);
						refEntities.Add(item2);
					}
				}
				else
				{
					Line item3 = new Line(list[0], list[1]);
					refEntities.Add(item3);
				}
				list = new List<Point3D>();
				flag2 = false;
			}
			if (flag || flag2)
			{
				string[] array = SL[i].Trim().Split(';');
				if (array != null && array.Length != 0)
				{
					if (array.Length != 2)
					{
						if (array.Length >= 3)
						{
							Point3D point3D = new Point3D();
							if (double.TryParse(array[0], out point3D.X) & double.TryParse(array[1], out point3D.Y) & double.TryParse(array[2], out point3D.Z))
							{
								list.Add(point3D);
							}
						}
					}
					else
					{
						Point3D point3D2 = new Point3D();
						if (double.TryParse(array[0], out point3D2.X) & double.TryParse(array[1], out point3D2.Y))
						{
							list.Add(point3D2);
						}
					}
				}
			}
			if (SL[i].Trim() == "<Arc>")
			{
				list.Clear();
				list = new List<Point3D>();
				flag = true;
			}
			if (SL[i].Trim() == "<Line>")
			{
				list.Clear();
				list = new List<Point3D>();
				flag2 = true;
			}
		}
	}

	public void CurveCornerFromBoxSize(Point3D StartPoint, Point3D EndPoint, Point3D BoxMin, Point3D BoxMax, int Degree, double Deviation, ClockDirectionType ClockDir, ref List<Point3D> calcPoints)
	{
		List<Point3D> list = new List<Point3D>();
		if (ClockDir == ClockDirectionType.CCW)
		{
			if (buCompare5.EQ(StartPoint.X, BoxMax.X) & buCompare5.EQ(EndPoint.Y, BoxMax.Y))
			{
				list.Add(ToPoint3D(StartPoint));
				list.Add(new Point3D(BoxMax.X, BoxMax.Y, StartPoint.Z));
				list.Add(ToPoint3D(EndPoint));
			}
			if (buCompare5.EQ(EndPoint.X, BoxMin.X) & buCompare5.EQ(StartPoint.Y, BoxMax.Y))
			{
				list.Add(ToPoint3D(StartPoint));
				list.Add(new Point3D(BoxMin.X, BoxMax.Y, StartPoint.Z));
				list.Add(ToPoint3D(EndPoint));
			}
			if (buCompare5.EQ(StartPoint.X, BoxMin.X) & buCompare5.EQ(EndPoint.Y, BoxMin.Y))
			{
				list.Add(ToPoint3D(StartPoint));
				list.Add(new Point3D(BoxMin.X, BoxMin.Y, StartPoint.Z));
				list.Add(ToPoint3D(EndPoint));
			}
			if (buCompare5.EQ(EndPoint.X, BoxMax.X) & buCompare5.EQ(StartPoint.Y, BoxMin.Y))
			{
				list.Add(ToPoint3D(StartPoint));
				list.Add(new Point3D(BoxMax.X, BoxMin.Y, StartPoint.Z));
				list.Add(ToPoint3D(EndPoint));
			}
		}
		if (calcPoints == null)
		{
			calcPoints = new List<Point3D>();
		}
		calcPoints.Clear();
		if (list.Count >= 3)
		{
			if (Degree == 0 || Degree == 1)
			{
				calcPoints.AddRange(list);
			}
			if (Degree >= 2)
			{
				Curve curve = new Curve(Degree, list);
				curve.Regen(Deviation);
				Copy(curve.Vertices, ref calcPoints, 4);
			}
		}
	}

	public void LineaPathToLine(List<Entity> refEntities, double MinLen, HorizontalVertical Direction, ref List<Entity> LineEntities)
	{
		if (LineEntities == null)
		{
			LineEntities = new List<Entity>();
		}
		LineEntities.Clear();
		if (Direction == HorizontalVertical.Horizontal)
		{
			for (int i = 0; i <= refEntities.Count - 1; i++)
			{
				if (!(refEntities[i] is LinearPath))
				{
					continue;
				}
				for (int j = 1; j <= refEntities[i].Vertices.Length - 1; j++)
				{
					if (!buCompare5.EQ(refEntities[i].Vertices[j - 1].Y, refEntities[i].Vertices[j].Y))
					{
						continue;
					}
					Point3D point3D = ToPoint3D(refEntities[i].Vertices[j - 1]);
					Point3D point3D2 = ToPoint3D(refEntities[i].Vertices[j]);
					if (Point3D.Distance(point3D, point3D2) >= MinLen)
					{
						if (!(point3D.X > point3D2.X))
						{
							Line item = new Line(point3D, point3D2);
							LineEntities.Add(item);
						}
						else
						{
							Line item2 = new Line(point3D2, point3D);
							LineEntities.Add(item2);
						}
					}
				}
			}
		}
		if (Direction != HorizontalVertical.Vertical)
		{
			return;
		}
		for (int k = 0; k <= refEntities.Count - 1; k++)
		{
			if (!(refEntities[k] is LinearPath))
			{
				continue;
			}
			for (int l = 1; l <= refEntities[k].Vertices.Length - 1; l++)
			{
				if (!buCompare5.EQ(refEntities[k].Vertices[l - 1].X, refEntities[k].Vertices[l].X))
				{
					continue;
				}
				Point3D point3D3 = ToPoint3D(refEntities[k].Vertices[l - 1]);
				Point3D point3D4 = ToPoint3D(refEntities[k].Vertices[l]);
				if (Point3D.Distance(point3D3, point3D4) >= MinLen)
				{
					if (!(point3D3.Y > point3D4.Y))
					{
						Line item3 = new Line(point3D3, point3D4);
						LineEntities.Add(item3);
					}
					else
					{
						Line item4 = new Line(point3D4, point3D3);
						LineEntities.Add(item4);
					}
				}
			}
		}
	}

	public void CopyEntitiesToEntities(List<buEntity> refEntities, ref List<buEntity> copyEntities, EntitiesCopySettings Settings)
	{
		if (copyEntities == null)
		{
			copyEntities = new List<buEntity>();
		}
		copyEntities.Clear();
		for (int i = 0; i <= refEntities.Count - 1; i++)
		{
			bool flag = true;
			buEntity buEntity2 = null;
			if (!(refEntities[i] is buPoint))
			{
				if (!((refEntities[i] is buAngularDim) | (refEntities[i] is buDiametricDim) | (refEntities[i] is buLinearDim) | (refEntities[i] is buOrdinateDim) | (refEntities[i] is buRadialDim)))
				{
					if (!(refEntities[i] is buCurve))
					{
						if (!(refEntities[i] is buArc))
						{
							if (!(refEntities[i] is buCircle))
							{
								if (!(refEntities[i] is buEllipse))
								{
									if (!(refEntities[i] is buCompositeCurve))
									{
										if (refEntities[i] is buLinearPath && Settings.PolylineToLine)
										{
											bool flag2 = true;
											for (int j = 1; j <= refEntities[i].Vertices.Count - 1; j++)
											{
												double num = Point3D.Distance(refEntities[i].Vertices[j - 1], refEntities[i].Vertices[j]);
												if (num < Settings.PolylineToLineMinLength)
												{
													flag2 = false;
													j = refEntities[i].Vertices.Count;
												}
											}
											if (!flag2)
											{
												flag = true;
											}
											else
											{
												List<buEntity> list = new List<buEntity>();
												for (int k = 1; k <= refEntities[i].Vertices.Count - 1; k++)
												{
													buLine item = new buLine(refEntities[i].Vertices[k - 1], refEntities[i].Vertices[k]);
													list.Add(item);
												}
												copyEntities.AddRange(list);
												flag = false;
											}
										}
									}
									else if (Settings.AddCompositeCurve)
									{
										if (Settings.RegenDev > 0.0)
										{
											refEntities[i].Regen(Settings.RegenDev);
										}
										if (Settings.CompositeCurveToEntities)
										{
											List<buEntity> copyEntities2 = new List<buEntity>();
											CopyEntitiesToEntities(((buCompositeCurve)refEntities[i]).CurveList, ref copyEntities2, Settings);
											copyEntities.AddRange(copyEntities2);
											flag = false;
										}
									}
									else
									{
										flag = false;
									}
								}
								else if (Settings.AddEllipse)
								{
									if (Settings.RegenDev > 0.0)
									{
										if (Settings.ForcePlaneXY)
										{
											((buEllipse)refEntities[i]).Plane = Plane.XY;
										}
										refEntities[i].Regen(Settings.RegenDev);
									}
									if (Settings.EllipseToPoyline)
									{
										buEntity2 = new buLinearPath(refEntities[i].Vertices);
									}
								}
								else
								{
									flag = false;
								}
							}
							else if (Settings.AddCircular)
							{
								if (Settings.RegenDev > 0.0)
								{
									if (Settings.ForcePlaneXY)
									{
										((buCircle)refEntities[i]).Plane = Plane.XY;
									}
									refEntities[i].Regen(Settings.RegenDev);
								}
								if (!Settings.CircleToPoyline)
								{
									if (Settings.CircleTo4Arc)
									{
										buArc Arc = null;
										buArc Arc2 = null;
										buArc Arc3 = null;
										buArc Arc4 = null;
										CircletoFourArc((buCircle)refEntities[i], ref Arc, ref Arc2, ref Arc3, ref Arc4);
										copyEntities.Add(Arc);
										copyEntities.Add(Arc2);
										copyEntities.Add(Arc3);
										copyEntities.Add(Arc4);
										flag = false;
									}
								}
								else
								{
									buEntity2 = new buLinearPath(refEntities[i].Vertices);
								}
							}
							else
							{
								flag = false;
							}
						}
						else if (Settings.AddCircular)
						{
							if (Settings.RegenDev > 0.0)
							{
								if (Settings.ForcePlaneXY)
								{
									((buArc)refEntities[i]).Plane = Plane.XY;
								}
								refEntities[i].Regen(Settings.RegenDev);
							}
							if (Settings.ArcToPoyline)
							{
								buEntity2 = new buLinearPath(refEntities[i].Vertices);
							}
						}
						else
						{
							flag = false;
						}
					}
					else if (Settings.AddCurve)
					{
						if (Settings.RegenDev > 0.0)
						{
							refEntities[i].Regen(Settings.RegenDev);
						}
						if (Settings.CurveToPolyLine)
						{
							buEntity2 = new buLinearPath(refEntities[i].Vertices);
						}
					}
					else
					{
						flag = false;
					}
				}
				else if (!Settings.AddDimension)
				{
					flag = false;
				}
			}
			else if (!Settings.AddPoint)
			{
				flag = false;
			}
			if ((flag & (Settings.MinLength > 0.0)) && refEntities[i].Length() < Settings.MinLength)
			{
				flag = false;
			}
			if (flag)
			{
				if (buEntity2 != null)
				{
					copyEntities.Add(buEntity2);
				}
				else
				{
					copyEntities.Add(refEntities[i]);
				}
			}
		}
	}

	public void GetSelectedEntitiesInfo(Design Viewport, ref int SelectedCount, ref Point3D pntMin, ref Point3D pntMid, ref Point3D pntMax)
	{
		SelectedCount = 0;
		List<Entity> list = new List<Entity>();
		pntMin.X = 0.0;
		pntMin.Y = 0.0;
		pntMin.Z = 0.0;
		pntMid.X = 0.0;
		pntMid.Y = 0.0;
		pntMid.Z = 0.0;
		pntMax.X = 0.0;
		pntMax.Y = 0.0;
		pntMax.Z = 0.0;
		if (Viewport == null || !Viewport.IsHandleCreated)
		{
			return;
		}
		for (int i = 0; i <= Viewport.Entities.Count - 1; i++)
		{
			if (Viewport.Entities[i].Selected)
			{
				SelectedCount++;
				list.Add(Viewport.Entities[i]);
			}
		}
		if (list.Count > 0)
		{
			BoxSizeCalculate(list, ref pntMin, ref pntMid, ref pntMax);
		}
	}

	public void MakeIsClosedEntityWithTrim(int GoBackCount, ref buEntity refLinearPath, ref buEntity trimedEntity)
	{
		if (GoBackCount >= 2 && GoBackCount <= 4)
		{
			List<Point3D> copiedPoint = new List<Point3D>();
			Copy(refLinearPath.Vertices, ref copiedPoint);
			List<Point3D> list = new List<Point3D>();
			if (GoBackCount == 2)
			{
				list.Add(ToPoint3D(copiedPoint[copiedPoint.Count - 2]));
				list.Add(ToPoint3D(copiedPoint[copiedPoint.Count - 1]));
			}
			if (GoBackCount == 3)
			{
				list.Add(ToPoint3D(copiedPoint[copiedPoint.Count - 3]));
				list.Add(ToPoint3D(copiedPoint[copiedPoint.Count - 2]));
				list.Add(ToPoint3D(copiedPoint[copiedPoint.Count - 1]));
			}
			if (GoBackCount == 4)
			{
				list.Add(ToPoint3D(copiedPoint[copiedPoint.Count - 4]));
				list.Add(ToPoint3D(copiedPoint[copiedPoint.Count - 3]));
				list.Add(ToPoint3D(copiedPoint[copiedPoint.Count - 2]));
				list.Add(ToPoint3D(copiedPoint[copiedPoint.Count - 1]));
			}
			trimedEntity = new buLinearPath(list);
			buEntity.CopyProperties(refLinearPath, ref trimedEntity);
			if (GoBackCount == 2)
			{
				copiedPoint.RemoveAt(copiedPoint.Count - 1);
			}
			if (GoBackCount == 3)
			{
				copiedPoint.RemoveAt(copiedPoint.Count - 1);
				copiedPoint.RemoveAt(copiedPoint.Count - 1);
			}
			if (GoBackCount == 4)
			{
				copiedPoint.RemoveAt(copiedPoint.Count - 1);
				copiedPoint.RemoveAt(copiedPoint.Count - 1);
				copiedPoint.RemoveAt(copiedPoint.Count - 1);
			}
			refLinearPath = new buLinearPath(copiedPoint);
			buEntity.CopyProperties(trimedEntity, ref refLinearPath);
		}
	}

