				continue;
			}
			buCompositeCurve buCompositeCurve2 = buEntity3 as buCompositeCurve;
			for (int k = 0; k <= buCompositeCurve2.CurveList.Count - 1; k++)
			{
				buEntity copiedEntity9 = null;
