					continue;
				}
				if (!(((buArc)copiedEntity9).EndAngle - ((buArc)copiedEntity9).StartAngle > 170.0))
				{
					buEntity copiedEntity11 = null;
					buEntity.Copy(copiedEntity9, ref copiedEntity11);
					if (copiedEntity11 != null)
