					}
					continue;
				}
				List<buEntity> SplitedEntities2 = new List<buEntity>();
				SplitArcCircleEntities(copiedEntity9, ref SplitedEntities2);
				for (int l = 0; l <= SplitedEntities2.Count - 1; l++)
				{
					buEntity copiedEntity12 = null;
