	public void EntityToOriginalType(buEntity refEntity, ref entityOriginalType OriginalType, ref double Radius)
	{
		OriginalType = entityOriginalType.None;
		Radius = 0.0;
		if (refEntity.GetType() == typeof(buLine))
		{
			OriginalType = entityOriginalType.Line;
		}
		if (refEntity.GetType() == typeof(buArc))
		{
			OriginalType = entityOriginalType.Arc;
			Radius = ((buArc)refEntity).Radius;
		}
		if (refEntity.GetType() == typeof(buLinearPath))
		{
			OriginalType = entityOriginalType.LinearPath;
		}
		if (refEntity.GetType() == typeof(buCircle))
		{
			OriginalType = entityOriginalType.Circle;
			Radius = ((buArc)refEntity).Radius;
		}
		if (refEntity.GetType() == typeof(buEllipse))
		{
			OriginalType = entityOriginalType.Ellipse;
		}
		if (refEntity.GetType() == typeof(buCurve))
		{
			OriginalType = entityOriginalType.Curve;
		}
		if (refEntity.GetType() == typeof(buText))
		{
			OriginalType = entityOriginalType.Text;
		}
		if (refEntity.GetType() == typeof(buPoint))
		{
			OriginalType = entityOriginalType.Point;
		}
		if (refEntity.GetType() == typeof(buRegion))
		{
			OriginalType = entityOriginalType.Region;
		}
		if (refEntity.GetType() == typeof(buMesh))
		{
			OriginalType = entityOriginalType.Mesh;
		}
		if (refEntity.GetType() == typeof(buLinearDim))
		{
			OriginalType = entityOriginalType.Dimenstion;
		}
		if (refEntity.GetType() == typeof(buAngularDim))
		{
			OriginalType = entityOriginalType.Dimenstion;
		}
		if (refEntity.GetType() == typeof(buDiametricDim))
		{
			OriginalType = entityOriginalType.Dimenstion;
		}
		if (refEntity.GetType() == typeof(buRadialDim))
		{
			OriginalType = entityOriginalType.Dimenstion;
		}
		if (refEntity.GetType() == typeof(buOrdinateDim))
		{
			OriginalType = entityOriginalType.Dimenstion;
		}
		if (refEntity.GetType() == typeof(buCompositeCurve))
		{
			OriginalType = entityOriginalType.CompositeCurve;
		}
	}

	public void CheckEntities(CheckEntitesOption Option, ref List<Entity> Entities)
	{
		for (int i = 0; i <= Entities.Count - 1; i++)
		{
			if (Entities[i] is ICurve && ((ICurve)Entities[i]).Length() <= 0.01)
			{
				Entities[i].Selected = true;
			}
			if (Entities[i] is LinearPath && ((ICurve)Entities[i]).Length() <= 0.001)
			{
				Entities[i].Selected = true;
			}
			if (Entities[i].Vertices != null)
			{
				if (Entities[i].Vertices.Length == 0)
				{
					Entities[i].Selected = true;
				}
				if (Entities[i].Vertices.Length == 1)
				{
					Entities[i].Selected = true;
				}
			}
			for (int j = i + 1; j <= Entities.Count - 1; j++)
			{
				if (!Entities[j].Selected && isEntitySame(Entities[i], Entities[j]) && Option.RemoveSameEntities)
				{
					Entities[j].Selected = true;
				}
			}
			if ((!Entities[i].Selected & Option.ConvertCircleToArc) && Entities[i].GetType() == typeof(Circle))
			{
				Entities[i].Selected = true;
				Entity Arc = null;
				Entity Arc2 = null;
				Entity Arc3 = null;
				Entity Arc4 = null;
				CircletoFourArc((Circle)Entities[i], ref Arc, ref Arc2, ref Arc3, ref Arc4);
				Entities.Add(Arc);
				Entities.Add(Arc2);
				Entities.Add(Arc3);
				Entities.Add(Arc4);
			}
			if ((!Entities[i].Selected & Option.DevideArcIfGreater180) && Entities[i].GetType() == typeof(Arc) && ((Arc)Entities[i]).AngleInDegrees > 170.0)
			{
				Entity Arc5 = null;
				Entity Arc6 = null;
				ArcToTwoArc((Arc)Entities[i], ref Arc5, ref Arc6);
				Entities.Add(Arc5);
				Entities.Add(Arc6);
				Entities[i].Selected = true;
			}
			if ((Entities[i].GetType() == typeof(devDept.Eyeshot.Entities.Point)) & Option.RemovePoints)
			{
				Entities[i].Selected = true;
			}
			if ((Entities[i].GetType() == typeof(CompositeCurve)) & Option.CompositeCurveToEntities)
			{
				Entities[i].Selected = true;
				for (int k = 0; k <= ((CompositeCurve)Entities[i]).CurveList.Count - 1; k++)
				{
					Entity copiedEntity = null;
					buEntity.Copy((Entity)((CompositeCurve)Entities[i]).CurveList[k], ref copiedEntity);
					if (copiedEntity != null)
					{
						CopyEntityProperties(Entities[i], ref copiedEntity);
						Entities.Add(copiedEntity);
					}
				}
			}
			if ((Entities[i].GetType() == typeof(Curve)) & Option.CurveToLinearPath)
			{
				if (Entities[i].Vertices == null)
				{
					Entities[i].Regen(0.02);
				}
				List<Point3D> list = new List<Point3D>();
				for (int l = 0; l <= Entities[i].Vertices.Length - 1; l++)
				{
					list.Add(ToPoint3D(Entities[i].Vertices[l]));
				}
				if (list.Count >= 2)
				{
					Entities[i].Selected = true;
					Entity copiedEntity2 = new LinearPath(list);
					CopyEntityProperties(Entities[i], ref copiedEntity2);
					Entities.Add(copiedEntity2);
				}
			}
		}
		int num = 0;
		for (int num2 = Entities.Count - 1; num2 >= 0; num2--)
		{
			if (Entities[num2].Selected)
			{
				Entities.RemoveAt(num2);
				num++;
			}
		}
		for (int m = 0; m <= Entities.Count - 1; m++)
		{
			if (m == 706)
			{
				_ = Entities[m];
			}
			if (Option.ForceDefaultLayer)
			{
				Entities[m].LayerName = "Default";
			}
			if (Option.ColorFromEntity)
			{
				Entities[m].Color = Option.EntityColor;
				Entities[m].ColorMethod = colorMethodType.byEntity;
			}
			if (Option.ThicknessFromEntity)
			{
				Entities[m].LineWeight = (float)Option.EntityThickness;
				Entities[m].LineWeightMethod = colorMethodType.byEntity;
			}
		}
	}

	public void ExtendEntitiesIfOpenContour(ref buEntity refEntity, Plane refPlane, double LeadInDistance, double LeadOutDistance)
	{
		if (!(refEntity.GetType() == typeof(buLine)))
		{
			if (!(refEntity.GetType() == typeof(buCompositeCurve)))
			{
				return;
			}
			buCompositeCurve buCompositeCurve2 = refEntity as buCompositeCurve;
			if (buCompositeCurve2.CurveList.Count <= 0)
			{
				return;
			}
			List<buEntity> list = new List<buEntity>();
			for (int i = 0; i <= buCompositeCurve2.CurveList.Count - 1; i++)
			{
				bool flag = false;
				if (LeadInDistance > 0.0 && i == 0 && buCompositeCurve2.CurveList[i] is buLine)
				{
					buLine buLine2 = buCompositeCurve2.CurveList[i] as buLine;
					double angle = PointAngle(buLine2.StartPoint, buLine2.EndPoint, refPlane);
					Point3D EndPnt = new Point3D();
					LineWithLengthAndAngle(buLine2.StartPoint, LeadInDistance, angle, refPlane, ref EndPnt);
					buLine2.StartPoint = EndPnt;
					buLine2.Update(buEntityUpdateType.Line);
					list.Add(buLine2);
					flag = true;
				}
				if (((LeadOutDistance > 0.0) & (i == buCompositeCurve2.CurveList.Count - 1)) && buCompositeCurve2.CurveList[i] is buLine)
				{
					buLine buLine3 = buCompositeCurve2.CurveList[i] as buLine;
					double angle2 = PointAngle(buLine3.EndPoint, buLine3.StartPoint, refPlane);
					Point3D EndPnt2 = new Point3D();
					LineWithLengthAndAngle(buLine3.EndPoint, LeadOutDistance, angle2, refPlane, ref EndPnt2);
					buLine3.EndPoint = EndPnt2;
					buLine3.Update(buEntityUpdateType.Line);
				}
				if (!flag)
				{
					list.Add(buEntity.Copy(buCompositeCurve2.CurveList[i]));
				}
			}
			if (list.Count > 0 && list.Count == buCompositeCurve2.CurveList.Count)
			{
				refEntity = new buCompositeCurve(list);
			}
		}
		else
		{
			if (LeadInDistance > 0.0)
			{
				double angle3 = PointAngle(refEntity.StartPoint, refEntity.EndPoint, refPlane);
				Point3D EndPnt3 = new Point3D();
				LineWithLengthAndAngle(refEntity.StartPoint, LeadInDistance, angle3, refPlane, ref EndPnt3);
				buLine buLine4 = refEntity as buLine;
				buLine4.StartPoint = EndPnt3;
				buLine4.Update(buEntityUpdateType.Line);
			}
			if (LeadOutDistance > 0.0)
			{
				double angle4 = PointAngle(refEntity.EndPoint, refEntity.StartPoint, refPlane);
				Point3D EndPnt4 = new Point3D();
				LineWithLengthAndAngle(refEntity.EndPoint, LeadOutDistance, angle4, refPlane, ref EndPnt4);
				buLine buLine5 = refEntity as buLine;
				buLine5.EndPoint = EndPnt4;
				buLine5.Update(buEntityUpdateType.Line);
			}
		}
	}

	public void GetTangentStartAngleOfEntitiyByCamDir(buEntity RefEntity, Plane Plane, ref double TangentAngle)
	{
		double StartAngle = 0.0;
		double EndAngle = 0.0;
		GetTangentAngleOfEntity(RefEntity, Plane, ref StartAngle, ref EndAngle);
		if (RefEntity.sortDirection != entitySortDirection.Normal)
		{
			TangentAngle = EndAngle - 180.0;
		}
		else
		{
			TangentAngle = StartAngle;
		}
	}

	public void GetTangentEndAngleOfEntitiyByCamDir(buEntity RefEntity, Plane Plane, ref double TangentAngle)
	{
		double StartAngle = 0.0;
		double EndAngle = 0.0;
		GetTangentAngleOfEntity(RefEntity, Plane, ref StartAngle, ref EndAngle);
		if (RefEntity.sortDirection != entitySortDirection.Normal)
		{
			TangentAngle = StartAngle - 180.0;
		}
		else
		{
			TangentAngle = EndAngle;
		}
	}

	public void GetTangentAngleOfEntity(buEntity RefEntity, Plane Plane, ref double StartAngle, ref double EndAngle)
	{
		if (!(RefEntity.GetType() == typeof(buArc)))
		{
			if (!(RefEntity.GetType() == typeof(buLine)))
			{
				if (!(RefEntity.GetType() == typeof(buLinearPath)))
				{
					StartAngle = PointAngle(RefEntity.Vertices[1], RefEntity.Vertices[0], Plane);
					EndAngle = PointAngle(RefEntity.Vertices[RefEntity.Vertices.Count - 1], RefEntity.Vertices[RefEntity.Vertices.Count - 2], Plane);
				}
				else
				{
					StartAngle = PointAngle(RefEntity.Vertices[1], RefEntity.Vertices[0], Plane);
					EndAngle = PointAngle(RefEntity.Vertices[RefEntity.Vertices.Count - 1], RefEntity.Vertices[RefEntity.Vertices.Count - 2], Plane);
				}
			}
			else
			{
				StartAngle = PointAngle(RefEntity.Vertices[RefEntity.Vertices.Count - 1], RefEntity.Vertices[RefEntity.Vertices.Count - 2], Plane);
				EndAngle = StartAngle;
			}
		}
		else
		{
			StartAngle = ((buArc)RefEntity).StartAngle + 90.0;
			EndAngle = ((buArc)RefEntity).EndAngle + 90.0;
		}
	}

	public void GetClosestEntityToRefPoint(List<Entity> refEntities, Point3D refPoint, ref Entity foundEntity, double LimitDistance = 0.0)
	{
		double num = double.MaxValue;
		int num2 = -1;
		if (refPoint == null)
		{
			return;
		}
		for (int i = 0; i <= refEntities.Count - 1; i++)
		{
			if (!(refEntities[i] is ICurve))
			{
				continue;
			}
			ICurve curve = refEntities[i] as ICurve;
			double t = 0.0;
			curve.ClosestPointTo(refPoint, out t);
			Point3D a = curve.PointAt(t);
			double num3 = Point3D.Distance(a, refPoint);
			if (LimitDistance != 0.0)
			{
				if (num3 < num && num3 <= LimitDistance)
				{
					num = num3;
					num2 = i;
				}
			}
			else if (num3 < num)
			{
				num = num3;
				num2 = i;
			}
		}
		if (num2 >= 0)
		{
			buEntity.Copy(refEntities[num2], ref foundEntity);
		}
	}

	public void EntityUpdateByLength(buEntity BaseEntity, double StartLength, double EndLength, StartPointType PointType, ref buEntity CalcEntity, ref buEntity CuttedEntity)
	{
		try
		{
			Plane xY = Plane.XY;
			StartPointType startPointType = PointType;
			if (BaseEntity.sortDirection == entitySortDirection.Reverse)
			{
				if (PointType != StartPointType.Start)
				{
					if (PointType == StartPointType.End)
					{
						startPointType = StartPointType.Start;
					}
				}
				else
				{
					startPointType = StartPointType.End;
				}
			}
			if (BaseEntity.Vertices.Count <= 0)
			{
				return;
			}
			if (BaseEntity.GetType() == typeof(buLine))
			{
				Point3D point3D = new Point3D();
				if (startPointType == StartPointType.Start)
				{
					double angle = PointAngle(BaseEntity.Vertices[0], BaseEntity.Vertices[1], xY);
					Point3D EndPnt = new Point3D();
					LineWithLengthAndAngle(BaseEntity.Vertices[1], StartLength, angle, xY, ref EndPnt);
					point3D = ToPoint3D(BaseEntity.Vertices[0]);
					CalcEntity = new buLine(EndPnt, BaseEntity.Vertices[1]);
					CalcEntity.sortDirection = BaseEntity.sortDirection;
					CuttedEntity = new buLine(point3D, EndPnt);
				}
				if (startPointType == StartPointType.End)
				{
					double angle2 = PointAngle(BaseEntity.Vertices[1], BaseEntity.Vertices[0], xY);
					point3D = ToPoint3D(BaseEntity.Vertices[1]);
					Point3D EndPnt2 = new Point3D();
					LineWithLengthAndAngle(BaseEntity.Vertices[0], EndLength, angle2, xY, ref EndPnt2);
					CalcEntity = new buLine(BaseEntity.Vertices[0], EndPnt2);
					CalcEntity.sortDirection = BaseEntity.sortDirection;
					CuttedEntity = new buLine(EndPnt2, point3D);
				}
				if (startPointType == StartPointType.StartAndEnd)
				{
					double angle3 = PointAngle(BaseEntity.Vertices[0], BaseEntity.Vertices[1], xY);
					Point3D EndPnt3 = new Point3D();
					LineWithLengthAndAngle(BaseEntity.Vertices[1], StartLength, angle3, xY, ref EndPnt3);
					double angle4 = PointAngle(BaseEntity.Vertices[1], BaseEntity.Vertices[0], xY);
					Point3D EndPnt4 = new Point3D();
					LineWithLengthAndAngle(BaseEntity.Vertices[0], EndLength, angle4, xY, ref EndPnt4);
					CalcEntity = new buLine(EndPnt3, EndPnt4);
					CalcEntity.sortDirection = BaseEntity.sortDirection;
				}
			}
			if (BaseEntity.GetType() == typeof(buArc))
			{
				buArc buArc2 = new buArc();
				buArc2 = (buArc)BaseEntity;
				double num = ArcCircumference(buArc2.Radius, 0.0, 360.0);
				double num2 = (EntityLength(BaseEntity) - EndLength) * 360.0 / num;
				double num3 = (EntityLength(BaseEntity) - StartLength) * 360.0 / num;
				if (startPointType == StartPointType.Start)
				{
					CalcEntity = new buArc(buArc2.Plane, buArc2.Center, buArc2.Radius, buArc2.StartAngle + num3, buArc2.EndAngle);
					CuttedEntity = new buArc(buArc2.Plane, buArc2.Center, buArc2.Radius, buArc2.StartAngle, buArc2.StartAngle + num3);
				}
				if (startPointType == StartPointType.End)
				{
					CalcEntity = new buArc(buArc2.Plane, buArc2.Center, buArc2.Radius, buArc2.StartAngle, buArc2.EndAngle - num2);
					CuttedEntity = new buArc(buArc2.Plane, buArc2.Center, buArc2.Radius, buArc2.EndAngle - num2, buArc2.EndAngle);
				}
				if (startPointType == StartPointType.StartAndEnd)
				{
					CalcEntity = new buArc(buArc2.Plane, buArc2.Center, buArc2.Radius, buArc2.StartAngle + num3, buArc2.EndAngle - num2);
				}
			}
			if (CalcEntity != null && BaseEntity != null)
			{
				CalcEntity.Orientation = new OrientationAngle(BaseEntity.Orientation);
				buEntity.CopyProperties(BaseEntity, ref CalcEntity);
				if (CuttedEntity != null)
				{
					CuttedEntity.sortDirection = BaseEntity.sortDirection;
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "BaseEntity: " + BaseEntity.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void EntityUpdateByLength(buEntity BaseEntity, double StartLength, double EndLength, StartPointType PointType, ref buEntity CalcEntity)
	{
		try
		{
			buEntity CuttedEntity = null;
			EntityUpdateByLength(BaseEntity, StartLength, EndLength, PointType, ref CalcEntity, ref CuttedEntity);
