	public void EntityUpdateByCutLength(buEntity BaseEntity, double StartLength, double EndLength, StartPointType PointType, ref buEntity CalcEntity)
	{
		try
		{
			Plane xY = Plane.XY;
			StartPointType startPointType = PointType;
			if (BaseEntity.sortDirection == entitySortDirection.Reverse)
			{
				if (PointType != StartPointType.Start)
				{
					if (PointType == StartPointType.End)
					{
						startPointType = StartPointType.Start;
					}
				}
				else
				{
					startPointType = StartPointType.End;
				}
			}
			if (BaseEntity.Vertices.Count <= 0)
			{
				return;
			}
			if (BaseEntity.GetType() == typeof(buLine))
			{
				new Point3D();
				if (startPointType == StartPointType.Start)
				{
					double angle = PointAngle(BaseEntity.Vertices[1], BaseEntity.Vertices[0], xY);
					Point3D EndPnt = new Point3D();
					LineWithLengthAndAngle(BaseEntity.Vertices[0], StartLength, angle, xY, ref EndPnt);
					ToPoint3D(BaseEntity.Vertices[0]);
					CalcEntity = new buLine(EndPnt, BaseEntity.Vertices[1]);
