					Point3D EndPnt2 = new Point3D();
					LineWithLengthAndAngle(BaseEntity.Vertices[1], EndLength, angle2, xY, ref EndPnt2);
					CalcEntity = new buLine(BaseEntity.Vertices[0], EndPnt2);
					CalcEntity.sortDirection = BaseEntity.sortDirection;
				}
				if (startPointType == StartPointType.StartAndEnd)
				{
					double angle3 = PointAngle(BaseEntity.Vertices[1], BaseEntity.Vertices[0], xY);
					Point3D EndPnt3 = new Point3D();
					LineWithLengthAndAngle(BaseEntity.Vertices[0], StartLength, angle3, xY, ref EndPnt3);
					double angle4 = PointAngle(BaseEntity.Vertices[0], BaseEntity.Vertices[1], xY);
					Point3D EndPnt4 = new Point3D();
					LineWithLengthAndAngle(BaseEntity.Vertices[1], EndLength, angle4, xY, ref EndPnt4);
					CalcEntity = new buLine(EndPnt3, EndPnt4);
					CalcEntity.sortDirection = BaseEntity.sortDirection;
				}
			}
			if (BaseEntity.GetType() == typeof(buArc))
			{
				buArc buArc2 = new buArc();
				buArc2 = (buArc)BaseEntity;
				double num = ArcCircumference(buArc2.Radius, 0.0, 360.0);
				double num2 = StartLength * 360.0 / num;
				double num3 = EndLength * 360.0 / num;
				if (startPointType == StartPointType.Start)
				{
					CalcEntity = new buArc(buArc2.Plane, buArc2.Center, buArc2.Radius, buArc2.StartAngle + num2, buArc2.EndAngle);
				}
				if (startPointType == StartPointType.End)
				{
					CalcEntity = new buArc(buArc2.Plane, buArc2.Center, buArc2.Radius, buArc2.StartAngle, buArc2.EndAngle - num3);
				}
				if (startPointType == StartPointType.StartAndEnd)
				{
					CalcEntity = new buArc(buArc2.Plane, buArc2.Center, buArc2.Radius, buArc2.StartAngle + num2, buArc2.EndAngle - num3);
				}
				CalcEntity.sortDirection = BaseEntity.sortDirection;
				if (!buCompare5.EQ(buArc2.Center.Z, ((buArc)CalcEntity).Center.Z))
				{
					CalcEntity.Translate(0.0, 0.0, buArc2.Center.Z - ((buArc)CalcEntity).Center.Z);
				}
			}
			if (CalcEntity != null && BaseEntity != null)
			{
				CalcEntity.Orientation = new OrientationAngle(BaseEntity.Orientation);
				buEntity.CopyProperties(BaseEntity, ref CalcEntity);
			}
		}
		catch (Exception mSException)
		{
			string text = "BaseEntity: " + BaseEntity.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

