	public void EntityUpdateByLengthUsingCamDirection(buEntity BaseEntity, double CutLength, StartPointType PointType, Plane Plane, ref buEntity CalcEntity)
	{
		try
		{
			if (BaseEntity.Vertices.Count <= 0)
			{
				return;
			}
			if (BaseEntity.GetType() == typeof(buLine))
			{
				if (BaseEntity.sortDirection == entitySortDirection.Normal)
				{
					if (PointType == StartPointType.Start)
					{
						double angle = PointAngle(BaseEntity.Vertices[1], BaseEntity.Vertices[0], Plane);
						Point3D EndPnt = new Point3D();
						LineWithLengthAndAngle(BaseEntity.Vertices[0], CutLength, angle, Plane, ref EndPnt);
						CalcEntity = new buLine(EndPnt, BaseEntity.Vertices[1]);
					}
					if (PointType == StartPointType.End)
					{
						double angle2 = PointAngle(BaseEntity.Vertices[0], BaseEntity.Vertices[1], Plane);
						Point3D EndPnt2 = new Point3D();
						LineWithLengthAndAngle(BaseEntity.Vertices[1], CutLength, angle2, Plane, ref EndPnt2);
						CalcEntity = new buLine(BaseEntity.Vertices[0], EndPnt2);
					}
				}
				if (BaseEntity.sortDirection == entitySortDirection.Reverse)
				{
					if (PointType == StartPointType.Start)
					{
						double angle3 = PointAngle(BaseEntity.Vertices[0], BaseEntity.Vertices[1], Plane);
						Point3D EndPnt3 = new Point3D();
						LineWithLengthAndAngle(BaseEntity.Vertices[1], CutLength, angle3, Plane, ref EndPnt3);
						CalcEntity = new buLine(BaseEntity.Vertices[0], EndPnt3);
					}
					if (PointType == StartPointType.End)
					{
						double angle4 = PointAngle(BaseEntity.Vertices[1], BaseEntity.Vertices[0], Plane);
						Point3D EndPnt4 = new Point3D();
						LineWithLengthAndAngle(BaseEntity.Vertices[0], CutLength, angle4, Plane, ref EndPnt4);
						CalcEntity = new buLine(EndPnt4, BaseEntity.Vertices[1]);
					}
				}
				if (PointType == StartPointType.StartAndEnd)
				{
					double angle5 = PointAngle(BaseEntity.Vertices[1], BaseEntity.Vertices[0], Plane);
					Point3D EndPnt5 = new Point3D();
					LineWithLengthAndAngle(BaseEntity.Vertices[0], CutLength, angle5, Plane, ref EndPnt5);
					double angle6 = PointAngle(BaseEntity.Vertices[0], BaseEntity.Vertices[1], Plane);
					Point3D EndPnt6 = new Point3D();
					LineWithLengthAndAngle(BaseEntity.Vertices[1], CutLength, angle6, Plane, ref EndPnt6);
					CalcEntity = new buLine(EndPnt5, EndPnt6);
				}
			}
			if (!(BaseEntity.GetType() == typeof(buArc)))
			{
				return;
			}
			buArc buArc2 = new buArc();
			buArc2 = (buArc)BaseEntity;
			double num = ArcCircumference(buArc2.Radius, 0.0, 360.0);
			double num2 = CutLength * 360.0 / num;
			if (BaseEntity.sortDirection == entitySortDirection.Normal)
			{
				if (PointType == StartPointType.Start)
				{
					CalcEntity = new buArc(buArc2.Plane, buArc2.Center, buArc2.Radius, buArc2.StartAngle + num2, buArc2.EndAngle);
				}
				if (PointType == StartPointType.End)
				{
					CalcEntity = new buArc(buArc2.Plane, buArc2.Center, buArc2.Radius, buArc2.StartAngle, buArc2.EndAngle - num2);
				}
			}
			if (BaseEntity.sortDirection == entitySortDirection.Reverse)
			{
				if (PointType == StartPointType.End)
				{
					CalcEntity = new buArc(buArc2.Plane, buArc2.Center, buArc2.Radius, buArc2.StartAngle + num2, buArc2.EndAngle);
				}
				if (PointType == StartPointType.Start)
				{
					CalcEntity = new buArc(buArc2.Plane, buArc2.Center, buArc2.Radius, buArc2.StartAngle, buArc2.EndAngle - num2);
				}
			}
			if (PointType == StartPointType.StartAndEnd)
			{
				CalcEntity = new buArc(buArc2.Plane, buArc2.Center, buArc2.Radius, buArc2.StartAngle + num2, buArc2.EndAngle - num2);
			}
		}
		catch (Exception mSException)
		{
			string text = "BaseEntity: " + BaseEntity.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

