	public void EntityToProperties(Entity refEntity, ref List<string> Properties)
	{
		CustomData customData = null;
		if (refEntity.EntityData != null && refEntity.EntityData is CustomData)
		{
			customData = new CustomData((CustomData)refEntity.EntityData);
		}
		if (customData != null)
		{
			Properties.Add(AppLanguage.CadCamDynamic[40] + " = " + customData.EntityName);
			Properties.Add(AppLanguage.CadCamDynamic[47] + " = " + customData.OriginalEntityIndex);
		}
		if (!(refEntity is ICurve))
		{
			if (!(refEntity is IFace))
			{
				if (!(refEntity is Text))
				{
					if (refEntity.BoxMin != null)
					{
						Properties.Add(AppLanguage.CadCamDynamic[67] + " = " + buConversion5.ToString(refEntity.BoxMin));
					}
					if (refEntity.BoxMax != null)
					{
						Properties.Add(AppLanguage.CadCamDynamic[68] + " = " + buConversion5.ToString(refEntity.BoxMax));
					}
					Properties.Add(AppLanguage.CadCamDynamic[48] + " " + AppLanguage.CadCamDynamic[53] + " = " + refEntity.Vertices.Length);
				}
				else
				{
					if ((refEntity.BoxMax == null) & (baseModel != null))
					{
						refEntity.Regen(new RegenParams(buSystem.RegenDeviation, baseModel));
					}
					Properties.Add(AppLanguage.CadCamDynamic[67] + " = " + ((Text)refEntity).TextString);
					Properties.Add(AppLanguage.CadCamDynamic[67] + " = " + buConversion5.ToString(refEntity.BoxMin));
					Properties.Add(AppLanguage.CadCamDynamic[68] + " = " + buConversion5.ToString(refEntity.BoxMax));
					Properties.Add(AppLanguage.CadCamDynamic[48] + " " + AppLanguage.CadCamDynamic[53] + " = " + refEntity.Vertices.Length);
				}
			}
			else
			{
				if (refEntity.BoxMax == null)
				{
					refEntity.Regen(new RegenParams(buSystem.RegenDeviation));
				}
				Properties.Add(AppLanguage.CadCamDynamic[67] + " = " + buConversion5.ToString(refEntity.BoxMin));
				Properties.Add(AppLanguage.CadCamDynamic[68] + " = " + buConversion5.ToString(refEntity.BoxMax));
				Properties.Add(AppLanguage.CadCamDynamic[48] + " " + AppLanguage.CadCamDynamic[53] + " = " + refEntity.Vertices.Length);
			}
		}
		else
		{
			if (refEntity.BoxMax == null)
			{
				refEntity.Regen(buSystem.RegenDeviation);
			}
			Properties.Add(AppLanguage.CadCamDynamic[110] + " = " + buConversion5.ToString(((ICurve)refEntity).StartPoint));
			Properties.Add(AppLanguage.CadCamDynamic[111] + " = " + buConversion5.ToString(((ICurve)refEntity).EndPoint));
			Properties.Add(AppLanguage.CadCamDynamic[67] + " = " + buConversion5.ToString(refEntity.BoxMin));
			Properties.Add(AppLanguage.CadCamDynamic[68] + " = " + buConversion5.ToString(refEntity.BoxMax));
			Properties.Add(AppLanguage.CadCamDynamic[48] + " " + AppLanguage.CadCamDynamic[53] + " = " + refEntity.Vertices.Length);
			Properties.Add(AppLanguage.CadCamDynamic[0] + " = " + ((ICurve)refEntity).Length().ToString("f3"));
			if (!((ICurve)refEntity).IsClosed)
			{
				List<Point3D> list = new List<Point3D>();
				list.AddRange(refEntity.Vertices);
				list.Add(ToPoint3D(list[0]));
				double num = Utility.PolygonArea(list);
				Properties.Add(AppLanguage.CadCamDynamic[98] + " = " + num.ToString("f3"));
			}
			else
			{
				List<Point3D> list2 = new List<Point3D>();
				list2.AddRange(refEntity.Vertices);
				double num2 = Utility.PolygonArea(list2);
				Properties.Add(AppLanguage.CadCamDynamic[98] + " = " + num2.ToString("f3"));
			}
		}
		Properties.Add(AppLanguage.CadCamDynamic[24] + " = " + refEntity.LayerName);
	}

	public void EntityCutFromStartAndEndByLength(ICurve refCurve, double StartDistance, double EndDistance, ref ICurve cuttedCurve)
	{
		ICurve curve = null;
		if (!(StartDistance > 0.0))
		{
			curve = (ICurve)refCurve.Clone();
		}
		else
		{
			ICurve lower = null;
			ICurve upper = null;
			refCurve.SplitAt(StartDistance, out lower, out upper);
			curve = ((lower != null && upper != null) ? (buCompare5.EQ(lower.Length(), StartDistance, 0.1) ? ((ICurve)upper.Clone()) : (buCompare5.EQ(upper.Length(), StartDistance, 0.1) ? ((ICurve)lower.Clone()) : ((ICurve)refCurve.Clone()))) : ((ICurve)refCurve.Clone()));
		}
		if (EndDistance > 0.0)
		{
			ICurve lower2 = null;
			ICurve upper2 = null;
			curve.SplitAt(curve.Length() - EndDistance, out lower2, out upper2);
			curve = ((lower2 != null && upper2 != null) ? (buCompare5.EQ(lower2.Length(), EndDistance, 0.1) ? ((ICurve)upper2.Clone()) : (buCompare5.EQ(upper2.Length(), EndDistance, 0.1) ? ((ICurve)lower2.Clone()) : ((ICurve)curve.Clone()))) : ((ICurve)curve.Clone()));
		}
		if (curve == null)
		{
			cuttedCurve = refCurve;
		}
		else
		{
			cuttedCurve = curve;
		}
	}

	public void EntityCutFromStartAndEndByLength(ref ICurve refCurve, double StartDistance, double EndDistance)
	{
		ICurve cuttedCurve = null;
		EntityCutFromStartAndEndByLength(refCurve, StartDistance, EndDistance, ref cuttedCurve);
		refCurve = cuttedCurve;
	}

