	public void EntityXYToEntityPlane(Entity refEntity, Plane refPlane, ref Entity convertedEntity)
	{
		if (!(refEntity.GetType() == typeof(Arc)))
		{
			if (!(refEntity.GetType() == typeof(Circle)))
			{
				if (!(refEntity.GetType() == typeof(Line)))
				{
					if (!(refEntity.GetType() == typeof(Ellipse)))
					{
						if (refEntity.Vertices == null)
						{
							refEntity.Regen(buSystem.RegenDeviation);
						}
						Point2D[] vertices = refEntity.Vertices;
						convertedEntity = new LinearPath(refPlane, vertices);
					}
					else
					{
						convertedEntity = new Ellipse(refPlane, ((Ellipse)refEntity).Center, ((Ellipse)refEntity).RadiusX, ((Ellipse)refEntity).RadiusY);
					}
				}
				else
				{
					convertedEntity = new Line(refPlane, ((Line)refEntity).StartPoint, ((Line)refEntity).EndPoint);
				}
			}
			else
			{
				convertedEntity = new Circle(refPlane, ((Circle)refEntity).Center, ((Arc)refEntity).Radius);
			}
		}
		else
		{
			convertedEntity = new Arc(refPlane, ((Arc)refEntity).Center, ((Arc)refEntity).StartPoint, ((Arc)refEntity).EndPoint);
		}
		if (!(refEntity.EntityData is CustomData))
		{
			convertedEntity.EntityData = new CustomData();
		}
		else
		{
			convertedEntity.EntityData = new CustomData((CustomData)refEntity.EntityData);
		}
		convertedEntity.Regen(buSystem.RegenDeviation);
	}

	public void EntityXYToEntityPlane(buEntity refEntity, Plane refPlane, ref buEntity convertedEntity)
	{
		if (!(refEntity.GetType() == typeof(buArc)))
		{
			if (!(refEntity.GetType() == typeof(buPoint)))
			{
				if (!(refEntity.GetType() == typeof(buCircle)))
				{
					if (!(refEntity.GetType() == typeof(buLine)))
					{
						if (!(refEntity.GetType() == typeof(buEllipse)))
						{
							if (!(refEntity.GetType() == typeof(buLinearPath)))
							{
								convertedEntity = new buLinearPath(refPlane, refEntity.Vertices);
							}
							else
							{
								convertedEntity = new buLinearPath(refPlane, ((buLinearPath)refEntity).Vertices);
							}
						}
						else
						{
							convertedEntity = new buEllipse(refPlane, ((buEllipse)refEntity).Center, ((buEllipse)refEntity).RadiusX, ((buEllipse)refEntity).RadiusY);
						}
					}
					else
					{
						convertedEntity = new buLine(refPlane, ((buLine)refEntity).StartPoint, ((buLine)refEntity).EndPoint);
					}
				}
				else
				{
					convertedEntity = new buCircle(refPlane, ((buCircle)refEntity).Center, ((buCircle)refEntity).Radius);
				}
			}
			else
			{
				buCircle buCircle2 = new buCircle(refPlane, ((buPoint)refEntity).StartPoint, 1.0);
				convertedEntity = new buPoint(buCircle2.Center);
			}
		}
		else
		{
			convertedEntity = new buArc(refPlane, ((buArc)refEntity).StartPoint, ((buArc)refEntity).MiddlePoint, ((buArc)refEntity).EndPoint, flip: false);
		}
		convertedEntity.Orientation = new OrientationAngle(refEntity.Orientation);
		convertedEntity.sortDirection = refEntity.sortDirection;
		convertedEntity.typeDefination = refEntity.typeDefination;
	}

