				{
					Entity copiedEnt = null;
					CopyEntities(refEntities[i], ref copiedEnt);
					OtherEntities.Add(copiedEnt);
					continue;
				}
				Line line = refEntities[i] as Line;
				if (!buCompare5.EQ(line.StartPoint.X, line.EndPoint.X))
				{
					if (!buCompare5.EQ(line.StartPoint.Y, line.EndPoint.Y))
					{
						Entity copiedEnt2 = null;
						CopyEntities(refEntities[i], ref copiedEnt2);
						OtherEntities.Add(copiedEnt2);
