					else
					{
						Entity copiedEnt3 = null;
						CopyEntities(refEntities[i], ref copiedEnt3);
						HorizontalEntities.Add(copiedEnt3);
					}
				}
				else
				{
					Entity copiedEnt4 = null;
					CopyEntities(refEntities[i], ref copiedEnt4);
					VerticalEntities.Add(copiedEnt4);
				}
			}
		}
		catch (Exception)
		{
		}
	}

