	public ICurve CurveFromEntity(Entity refEntity)
	{
		ICurve result = null;
		if (!(refEntity is Line))
		{
			if (!(refEntity is Arc))
			{
				if (!(refEntity is Circle))
				{
					if (!(refEntity is CompositeCurve))
					{
						if (!(refEntity is Curve))
						{
							if (!(refEntity is Ellipse))
							{
								if (!(refEntity is EllipticalArc))
								{
									if (refEntity is LinearPath)
									{
										result = (LinearPath)refEntity.Clone();
									}
								}
								else
								{
									result = (EllipticalArc)refEntity.Clone();
								}
							}
							else
							{
								result = (Ellipse)refEntity.Clone();
							}
						}
						else
						{
							result = (Curve)refEntity.Clone();
						}
					}
					else
					{
						result = (CompositeCurve)refEntity.Clone();
					}
				}
				else
				{
					result = (Circle)refEntity.Clone();
				}
			}
			else
			{
				result = (Arc)refEntity.Clone();
			}
		}
		else
		{
			result = (Line)refEntity.Clone();
		}
		return result;
	}

	public void IntersectionOfEntities1(List<Entity> Entities, Entity refEntity, int RefEntityIndex, int ListStartIndex, ref List<OsnapPoint> OsnapPoints)
	{
		for (int i = ListStartIndex; i <= Entities.Count - 1; i++)
		{
			if (RefEntityIndex == i)
			{
				continue;
			}
			ICurve curve = CurveFromEntity(Entities[i]);
			string entityName = GetEntityName(Entities[i]);
			if ((((curve != null) ? 1u : 0u) & 1u) == 0)
			{
				continue;
			}
			Point3D[] array = null;
			string text = "";
			string layerName = refEntity.LayerName;
			if (refEntity is Line)
			{
				text = GetEntityCustomData(refEntity).EntityName;
				if (entityName != text)
				{
					array = ((Line)refEntity).IntersectWith(curve);
				}
			}
			if (refEntity is LinearPath)
			{
				text = GetEntityCustomData(refEntity).EntityName;
				if (entityName != text)
				{
					array = ((LinearPath)refEntity).IntersectWith(curve);
				}
			}
			if (refEntity is Arc)
			{
				text = GetEntityCustomData(refEntity).EntityName;
				if (entityName != text)
				{
					array = ((Arc)refEntity).IntersectWith(curve);
				}
			}
			if (refEntity is Circle)
			{
				text = GetEntityCustomData(refEntity).EntityName;
				if (entityName != text)
				{
					array = ((Circle)refEntity).IntersectWith(curve);
				}
			}
			if (refEntity is Ellipse)
			{
				text = GetEntityCustomData(refEntity).EntityName;
				if (entityName != text)
				{
					array = ((Ellipse)refEntity).IntersectWith(curve);
				}
			}
			if (refEntity is EllipticalArc)
			{
				text = GetEntityCustomData(refEntity).EntityName;
				if (entityName != text)
				{
					array = ((EllipticalArc)refEntity).IntersectWith(curve);
				}
			}
			if (refEntity is Curve)
			{
				text = GetEntityCustomData(refEntity).EntityName;
				if (entityName != text)
				{
					array = ((Curve)refEntity).IntersectWith(curve);
				}
			}
			if (refEntity is CompositeCurve)
			{
				text = GetEntityCustomData(refEntity).EntityName;
				if (entityName != text)
				{
					ICurve c = (ICurve)refEntity;
					ICurve c2 = (ICurve)Entities[i];
					array = Utility.Intersection2D(c, c2, Plane.XY);
				}
			}
			if (array == null)
			{
				continue;
			}
			for (int j = 0; j <= array.Length - 1; j++)
			{
				if (!isOsnapPointAvailable(array[j], OsnapPoints))
				{
					OsnapPoint item = new OsnapPoint(array[j], osnapType.Intersection, text, layerName, GetEntityName(Entities[i]));
					OsnapPoints.Add(item);
				}
			}
		}
	}

