	public void EntityDevideByLengthAsPolyline(Entity refEntity, EntityDevideData Settings, ref Entity devideEntity)
	{
		if (!(refEntity is ICurve))
		{
			return;
		}
		ICurve curve = (ICurve)refEntity;
		if (!((curve.GetType() == typeof(Line)) & Settings.Line & (Settings.LineLength > 0.0)))
		{
			if (!((curve.GetType() == typeof(LinearPath)) & Settings.Polyline & (Settings.PolylineLength > 0.0)))
			{
				if (!((curve.GetType() == typeof(Arc)) & Settings.Arc & (Settings.ArcLength > 0.0)))
				{
					if (!((curve.GetType() == typeof(LinearPath)) & Settings.Circle & (Settings.CircleLength > 0.0)))
					{
						if (!(((curve.GetType() == typeof(Ellipse)) | (curve.GetType() == typeof(EllipticalArc))) & Settings.Ellipse & (Settings.EllipseLength > 0.0)))
						{
							if (!((curve.GetType() == typeof(Curve)) & Settings.Curve & (Settings.CurveLength > 0.0)))
							{
								CopyEntities(refEntity, ref devideEntity);
								return;
							}
							Point3D[] pointsByLength = curve.GetPointsByLength(Settings.CurveLength);
							if (pointsByLength == null)
							{
								CopyEntities(refEntity, ref devideEntity);
								return;
							}
							devideEntity = new LinearPath(pointsByLength);
							devideEntity.EntityData = new CustomData((CustomData)refEntity.EntityData);
						}
						else
						{
							Point3D[] pointsByLength2 = curve.GetPointsByLength(Settings.EllipseLength);
							if (pointsByLength2 == null)
							{
								CopyEntities(refEntity, ref devideEntity);
								return;
							}
							devideEntity = new LinearPath(pointsByLength2);
							devideEntity.EntityData = new CustomData((CustomData)refEntity.EntityData);
						}
					}
					else
					{
						Point3D[] pointsByLength3 = curve.GetPointsByLength(Settings.CircleLength);
						if (pointsByLength3 == null)
						{
							CopyEntities(refEntity, ref devideEntity);
							return;
						}
						devideEntity = new LinearPath(pointsByLength3);
						devideEntity.EntityData = new CustomData((CustomData)refEntity.EntityData);
					}
				}
				else
				{
					Point3D[] pointsByLength4 = curve.GetPointsByLength(Settings.ArcLength);
					if (pointsByLength4 == null)
					{
						CopyEntities(refEntity, ref devideEntity);
						return;
					}
					devideEntity = new LinearPath(pointsByLength4);
					devideEntity.EntityData = new CustomData((CustomData)refEntity.EntityData);
				}
			}
			else
			{
				Point3D[] pointsByLength5 = curve.GetPointsByLength(Settings.PolylineLength);
				if (pointsByLength5 == null)
				{
					CopyEntities(refEntity, ref devideEntity);
					return;
				}
				devideEntity = new LinearPath(pointsByLength5);
				devideEntity.EntityData = new CustomData((CustomData)refEntity.EntityData);
			}
		}
		else
		{
			Point3D[] pointsByLength6 = curve.GetPointsByLength(Settings.LineLength);
			if (pointsByLength6 == null)
			{
				CopyEntities(refEntity, ref devideEntity);
				return;
			}
			devideEntity = new LinearPath(pointsByLength6);
