	public void EntitiesDevideByLengthAsPolyline(List<Entity> refEntities, EntityDevideData Settings, ref List<Entity> devideEntities)
	{
		devideEntities = new List<Entity>();
		for (int i = 0; i <= refEntities.Count - 1; i++)
		{
			if (!(refEntities[i] is ICurve))
			{
				continue;
			}
			ICurve curve = (ICurve)refEntities[i];
			if (!((curve.GetType() == typeof(Line)) & Settings.Line & (Settings.LineLength > 0.0)))
			{
				if (!((curve.GetType() == typeof(LinearPath)) & Settings.Polyline & (Settings.PolylineLength > 0.0)))
				{
					if (!((curve.GetType() == typeof(Arc)) & Settings.Arc & (Settings.ArcLength > 0.0)))
					{
						if (!((curve.GetType() == typeof(LinearPath)) & Settings.Circle & (Settings.CircleLength > 0.0)))
						{
							if (!(((curve.GetType() == typeof(Ellipse)) | (curve.GetType() == typeof(EllipticalArc))) & Settings.Ellipse & (Settings.EllipseLength > 0.0)))
							{
								if (!((curve.GetType() == typeof(Curve)) & Settings.Curve & (Settings.CurveLength > 0.0)))
								{
									devideEntities.Add(CopyEntities(refEntities[i]));
									continue;
								}
								Point3D[] pointsByLength = curve.GetPointsByLength(Settings.CurveLength);
								if (pointsByLength == null)
								{
									devideEntities.Add(CopyEntities(refEntities[i]));
									continue;
								}
								LinearPath linearPath = new LinearPath(pointsByLength);
								linearPath.EntityData = new CustomData((CustomData)refEntities[i].EntityData);
								devideEntities.Add(linearPath);
							}
							else
							{
								Point3D[] pointsByLength2 = curve.GetPointsByLength(Settings.EllipseLength);
								if (pointsByLength2 == null)
								{
									devideEntities.Add(CopyEntities(refEntities[i]));
									continue;
								}
								LinearPath linearPath2 = new LinearPath(pointsByLength2);
								linearPath2.EntityData = new CustomData((CustomData)refEntities[i].EntityData);
								devideEntities.Add(linearPath2);
							}
						}
						else
						{
							Point3D[] pointsByLength3 = curve.GetPointsByLength(Settings.CircleLength);
							if (pointsByLength3 == null)
							{
								devideEntities.Add(CopyEntities(refEntities[i]));
								continue;
							}
							LinearPath linearPath3 = new LinearPath(pointsByLength3);
							linearPath3.EntityData = new CustomData((CustomData)refEntities[i].EntityData);
							devideEntities.Add(linearPath3);
						}
					}
					else
					{
						Point3D[] pointsByLength4 = curve.GetPointsByLength(Settings.ArcLength);
						if (pointsByLength4 == null)
						{
							devideEntities.Add(CopyEntities(refEntities[i]));
							continue;
						}
						LinearPath linearPath4 = new LinearPath(pointsByLength4);
						linearPath4.EntityData = new CustomData((CustomData)refEntities[i].EntityData);
						devideEntities.Add(linearPath4);
					}
				}
				else
				{
					Point3D[] pointsByLength5 = curve.GetPointsByLength(Settings.PolylineLength);
					if (pointsByLength5 == null)
					{
						devideEntities.Add(CopyEntities(refEntities[i]));
						continue;
					}
					LinearPath linearPath5 = new LinearPath(pointsByLength5);
					linearPath5.EntityData = new CustomData((CustomData)refEntities[i].EntityData);
					devideEntities.Add(linearPath5);
				}
			}
			else
			{
				Point3D[] pointsByLength6 = curve.GetPointsByLength(Settings.LineLength);
				if (pointsByLength6 == null)
				{
					devideEntities.Add(CopyEntities(refEntities[i]));
					continue;
				}
				LinearPath linearPath6 = new LinearPath(pointsByLength6);
				linearPath6.EntityData = new CustomData((CustomData)refEntities[i].EntityData);
				devideEntities.Add(linearPath6);
			}
		}
	}

