	public void EntitiesToPointsWithCamDirection(List<Entity> refEntities, double RegenDeviation, ref List<Point3D> Points)
	{
		Points = new List<Point3D>();
		for (int i = 0; i <= refEntities.Count - 1; i++)
		{
			Entity entity = refEntities[i];
			if (entity.Vertices == null)
			{
				entity.Regen(RegenDeviation);
			}
			entitySortDirection sortDirection = GetSortDirection(entity);
			if (refEntities[i].Vertices == null)
			{
				continue;
			}
			List<Point3D> copiedPoint = new List<Point3D>();
			if (sortDirection != entitySortDirection.Normal)
			{
				Copy(entity.Vertices, ref copiedPoint);
				copiedPoint.Reverse();
			}
			else
			{
				Copy(entity.Vertices, ref copiedPoint);
			}
			if (copiedPoint.Count > 0)
			{
				if (Points.Count > 0 && buCompare5.EQ(Points[Points.Count - 1], copiedPoint[0], buSystem.resolutionCompare))
				{
					copiedPoint.RemoveAt(0);
				}
				if (copiedPoint.Count > 0)
				{
					Points.AddRange(copiedPoint);
				}
			}
		}
	}

