	public void EntitiesToPointsWithCamDirection(List<buEntity> refEntities, ref List<Pnt6D> Points, bool CircleFrom270 = false)
	{
		Points = new List<Pnt6D>();
		for (int i = 0; i <= refEntities.Count - 1; i++)
		{
			buEntity buEntity2 = refEntities[i];
			entitySortDirection sortDirection = GetSortDirection(buEntity2);
			bool flag = true;
			if (CircleFrom270 && (buEntity2 is buCircle || buEntity2 is buEllipse))
			{
				flag = false;
			}
			if (!flag)
			{
				if (!(buEntity2 is buCircle))
				{
					if (!(buEntity2 is buEllipse))
					{
						continue;
					}
					buEllipse buEllipse2 = buEntity2 as buEllipse;
					List<Point3D> Vertices = new List<Point3D>();
					double length = 0.5;
					if (!((buEllipse2.RadiusX + buEllipse2.RadiusY > 500.0) & (buEllipse2.RadiusX + buEllipse2.RadiusY < 1000.0)))
					{
						if (buEllipse2.RadiusX + buEllipse2.RadiusY >= 1000.0)
						{
							length = 2.0;
						}
					}
					else
					{
						length = 1.0;
					}
					ArcEllipseToLineer(buEllipse2.Center, buEllipse2.RadiusX, buEllipse2.RadiusY, -90.0, 270.0, buEllipse2.Angle, length, Plane.XY, ref Vertices);
					if (Vertices.Count > 0)
					{
						for (int j = 0; j <= Vertices.Count - 1; j++)
						{
							Points.Add(new Pnt6D(Vertices[j].X, Vertices[j].Y, Vertices[j].Z, buEntity2.Orientation.A, buEntity2.Orientation.B, buEntity2.Orientation.C));
						}
					}
				}
				else
				{
					buCircle buCircle2 = buEntity2 as buCircle;
					for (double num = -90.0; num <= 270.0; num += 0.5)
					{
						double x = buCircle2.Center.X + buCircle2.Radius * Math.Cos(buConversion5.DegreeToRadian(num));
						double y = buCircle2.Center.Y + buCircle2.Radius * Math.Sin(buConversion5.DegreeToRadian(num));
						double z = buCircle2.Center.Z;
						Points.Add(new Pnt6D(x, y, z, buEntity2.Orientation.A, buEntity2.Orientation.B, buEntity2.Orientation.C));
					}
				}
			}
			else
			{
				if (buEntity2.Vertices == null)
				{
					continue;
				}
				List<Pnt6D> list = new List<Pnt6D>();
				if (sortDirection != entitySortDirection.Normal)
				{
					list = new List<Pnt6D>();
					for (int k = 0; k <= buEntity2.Vertices.Count - 1; k++)
					{
						Pnt6D pnt6D = new Pnt6D(new Pnt6D(buEntity2.Vertices[k].X, buEntity2.Vertices[k].Y, buEntity2.Vertices[k].Z, buEntity2.Orientation.A, buEntity2.Orientation.B, buEntity2.Orientation.C));
						if (buEntity2.Marble != null && pnt6D.A == 0.0 && buEntity2.Marble.ExtraAngleA != 0.0)
						{
							pnt6D.A = buEntity2.Marble.ExtraAngleA;
						}
						list.Add(pnt6D);
					}
					list.Reverse();
				}
				else
				{
					list = new List<Pnt6D>();
					for (int l = 0; l <= buEntity2.Vertices.Count - 1; l++)
					{
						Pnt6D pnt6D2 = new Pnt6D(buEntity2.Vertices[l].X, buEntity2.Vertices[l].Y, buEntity2.Vertices[l].Z, buEntity2.Orientation.A, buEntity2.Orientation.B, buEntity2.Orientation.C);
						if (buEntity2.Marble != null && pnt6D2.A == 0.0 && buEntity2.Marble.ExtraAngleA != 0.0)
						{
							pnt6D2.A = buEntity2.Marble.ExtraAngleA;
						}
						list.Add(pnt6D2);
					}
				}
				if (list.Count > 0)
				{
					if (Points.Count > 0 && buCompare5.EQ(Points[Points.Count - 1], list[0], buSystem.resolutionCompare))
					{
						list.RemoveAt(0);
					}
					if (list.Count > 0)
					{
						Points.AddRange(list);
					}
				}
			}
		}
	}

	public void EntitiesToPointsWithCamDirection(List<buEntity> refEntities, ref List<Pnt6D> Points, List<GeometryTableItem> CircularTable, bool CircleFrom270 = false)
	{
		Points = new List<Pnt6D>();
		for (int i = 0; i <= refEntities.Count - 1; i++)
		{
			buEntity buEntity2 = refEntities[i];
			entitySortDirection sortDirection = GetSortDirection(buEntity2);
			bool flag = true;
			if (CircleFrom270 && (buEntity2 is buCircle || buEntity2 is buEllipse))
			{
				flag = false;
			}
			if (!flag)
			{
				if (!(buEntity2 is buCircle))
				{
					if (!(buEntity2 is buEllipse))
					{
						continue;
					}
					buEllipse buEllipse2 = buEntity2 as buEllipse;
					List<Point3D> Vertices = new List<Point3D>();
					double num = 0.0;
					double length = 2.0;
					num = ((buEllipse2.RadiusX < buEllipse2.RadiusY) ? (buEllipse2.RadiusX * 2.0) : (buEllipse2.RadiusY * 2.0));
					for (int j = 0; j <= CircularTable.Count - 1; j++)
					{
						if ((num >= CircularTable[j].DiameterMin) & (num <= CircularTable[j].DiameterMax))
						{
							length = CircularTable[j].DevideLength;
							j = CircularTable.Count;
						}
					}
					ArcEllipseToLineer(buEllipse2.Center, buEllipse2.RadiusX, buEllipse2.RadiusY, -90.0, 270.0, buEllipse2.Angle, length, Plane.XY, ref Vertices);
					if (Vertices.Count > 0)
					{
						for (int k = 0; k <= Vertices.Count - 1; k++)
						{
							Points.Add(new Pnt6D(Vertices[k].X, Vertices[k].Y, Vertices[k].Z, buEntity2.Orientation.A, buEntity2.Orientation.B, buEntity2.Orientation.C));
						}
					}
					continue;
				}
				buCircle buCircle2 = buEntity2 as buCircle;
				double num2 = Math.PI * buCircle2.Radius * 2.0;
				int num3 = 100;
				double num4 = 2.0;
				double num5 = 1.0;
				double num6 = 0.0;
				double num7 = 0.0;
				double num8 = 0.0;
				for (int l = 0; l <= CircularTable.Count - 1; l++)
				{
					if ((buCircle2.Radius * 2.0 >= CircularTable[l].DiameterMin) & (buCircle2.Radius * 2.0 <= CircularTable[l].DiameterMax))
					{
						num4 = CircularTable[l].DevideLength;
						l = CircularTable.Count;
					}
				}
				num3 = Convert.ToInt32(num2 / num4);
				if (num3 <= 50)
				{
					num3 = 50;
				}
				num5 = Math.Round(360.0 / (double)num3, 2);
				for (double num9 = -90.0; num9 <= 270.0; num9 += num5)
				{
					num6 = buCircle2.Center.X + buCircle2.Radius * Math.Cos(buConversion5.DegreeToRadian(num9));
					num7 = buCircle2.Center.Y + buCircle2.Radius * Math.Sin(buConversion5.DegreeToRadian(num9));
					num8 = buCircle2.Center.Z;
					Points.Add(new Pnt6D(num6, num7, num8, buEntity2.Orientation.A, buEntity2.Orientation.B, buEntity2.Orientation.C));
				}
				num6 = buCircle2.Center.X + buCircle2.Radius * Math.Cos(buConversion5.DegreeToRadian(270.0));
				num7 = buCircle2.Center.Y + buCircle2.Radius * Math.Sin(buConversion5.DegreeToRadian(270.0));
				num8 = buCircle2.Center.Z;
				Pnt6D pnt6D = new Pnt6D(num6, num7, num8, buEntity2.Orientation.A, buEntity2.Orientation.B, buEntity2.Orientation.C);
				if (!buCompare5.EQ(pnt6D, Points[Points.Count - 1], 0.01))
				{
					Points.Add(pnt6D);
				}
			}
			else
			{
				if (buEntity2.Vertices == null)
				{
					continue;
				}
				List<Pnt6D> list = new List<Pnt6D>();
				if (sortDirection != entitySortDirection.Normal)
				{
					list = new List<Pnt6D>();
					for (int m = 0; m <= buEntity2.Vertices.Count - 1; m++)
					{
						Pnt6D pnt6D2 = new Pnt6D(new Pnt6D(buEntity2.Vertices[m].X, buEntity2.Vertices[m].Y, buEntity2.Vertices[m].Z, buEntity2.Orientation.A, buEntity2.Orientation.B, buEntity2.Orientation.C));
						if (buEntity2.Marble != null && pnt6D2.A == 0.0 && buEntity2.Marble.ExtraAngleA != 0.0)
						{
							pnt6D2.A = buEntity2.Marble.ExtraAngleA;
						}
						list.Add(pnt6D2);
					}
					list.Reverse();
				}
				else
				{
					list = new List<Pnt6D>();
					for (int n = 0; n <= buEntity2.Vertices.Count - 1; n++)
					{
						Pnt6D pnt6D3 = new Pnt6D(buEntity2.Vertices[n].X, buEntity2.Vertices[n].Y, buEntity2.Vertices[n].Z, buEntity2.Orientation.A, buEntity2.Orientation.B, buEntity2.Orientation.C);
						if (buEntity2.Marble != null && pnt6D3.A == 0.0 && buEntity2.Marble.ExtraAngleA != 0.0)
						{
							pnt6D3.A = buEntity2.Marble.ExtraAngleA;
						}
						list.Add(pnt6D3);
					}
				}
				if (list.Count > 0)
				{
					if (Points.Count > 0 && buCompare5.EQ(Points[Points.Count - 1], list[0], buSystem.resolutionCompare))
					{
						list.RemoveAt(0);
					}
					if (list.Count > 0)
					{
						Points.AddRange(list);
					}
				}
			}
		}
	}

