	public void LineFromEntityEndPoint(Entity refEntity, double Length, ref Entity addedEntity)
	{
		addedEntity = null;
		if (!(refEntity is ICurve))
		{
			return;
		}
		if (refEntity.Vertices == null)
		{
			refEntity.Regen(buSystem.RegenDeviation);
		}
		if ((refEntity.EntityData != null) & (refEntity.EntityData is CustomData) & (refEntity.Vertices.Length >= 2))
		{
			CustomData customData = refEntity.EntityData as CustomData;
			if (customData.sortDirection != entitySortDirection.Normal)
			{
				Point3D basePoint = refEntity.Vertices[1];
				Point3D point3D = refEntity.Vertices[0];
				double angle = PointAngle(point3D, basePoint, Plane.XY);
				Point3D EndPnt = new Point3D();
				LineWithLengthAndAngle(point3D, Length, angle, ref EndPnt);
				addedEntity = new Line(point3D, EndPnt);
				CustomData customData2 = new CustomData();
				customData2.sortDirection = entitySortDirection.Normal;
				addedEntity.EntityData = customData2;
			}
			else
			{
				Point3D basePoint2 = refEntity.Vertices[refEntity.Vertices.Length - 2];
				Point3D point3D2 = refEntity.Vertices[refEntity.Vertices.Length - 1];
				double angle2 = PointAngle(point3D2, basePoint2, Plane.XY);
				Point3D EndPnt2 = new Point3D();
				LineWithLengthAndAngle(point3D2, Length, angle2, ref EndPnt2);
				addedEntity = new Line(point3D2, EndPnt2);
				CustomData customData3 = new CustomData();
				customData3.sortDirection = entitySortDirection.Normal;
				addedEntity.EntityData = customData3;
			}
		}
	}

