	public void EnitiesFirstInsideThenOutside(List<List<Entity>> refEntities, ref List<List<Entity>> InsideEntities, ref List<List<Entity>> OutsideEntities)
	{
		try
		{
			List<int> list = new List<int>();
			for (int i = 0; i <= refEntities.Count - 1; i++)
			{
				Point3D MinPoint = new Point3D();
				Point3D MidPoint = new Point3D();
				Point3D MaxPoint = new Point3D();
				BoxSizeCalculate(refEntities[i], ref MinPoint, ref MidPoint, ref MaxPoint);
				for (int j = 0; j <= refEntities.Count - 1; j++)
				{
					bool flag = false;
					if (i == j)
					{
						continue;
					}
					Point3D MinPoint2 = new Point3D();
					Point3D MidPoint2 = new Point3D();
					Point3D MaxPoint2 = new Point3D();
					BoxSizeCalculate(refEntities[j], ref MinPoint2, ref MidPoint2, ref MaxPoint2);
					if (!(IsPointInsideWindow(MinPoint, MaxPoint, MinPoint2, Plane.XY, UseEqualCondition: false) | IsPointInsideWindow(MinPoint, MaxPoint, MaxPoint2, Plane.XY, UseEqualCondition: false)))
					{
						continue;
					}
					if (list.Count != 0)
					{
						bool flag2 = false;
						for (int k = 0; k <= list.Count - 1; k++)
						{
							if (list[k] == j)
							{
								flag2 = true;
							}
						}
						if (!flag2)
						{
							list.Add(j);
							flag = true;
						}
					}
					else
					{
						list.Add(j);
						flag = true;
					}
					if (flag)
					{
						List<Entity> copiedEnt = new List<Entity>();
						CopyEntities(refEntities[j], ref copiedEnt);
						InsideEntities.Add(copiedEnt);
					}
				}
			}
			for (int l = 0; l <= refEntities.Count - 1; l++)
			{
				bool flag3 = false;
				for (int m = 0; m <= list.Count - 1; m++)
				{
					if (l == list[m])
					{
						flag3 = true;
					}
				}
				if (!flag3)
				{
					List<Entity> copiedEnt2 = new List<Entity>();
					CopyEntities(refEntities[l], ref copiedEnt2);
					OutsideEntities.Add(copiedEnt2);
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "EnitiesFirstInsideThenOutside: " + refEntities.Count;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

