	public void isEntitiesWhichPlane(List<buEntity> Entities, ref Plane whichPlane)
	{
		Point3D MinPoint = new Point3D();
		Point3D MaxPoint = new Point3D();
		BoxSizeCalculate(Entities, ref MinPoint, ref MaxPoint);
		if (buCompare5.EQ(MinPoint.Z, MaxPoint.Z))
		{
			whichPlane = Plane.XY;
		}
		if (buCompare5.EQ(MinPoint.Y, MaxPoint.Y))
		{
			whichPlane = Plane.XZ;
		}
		if (buCompare5.EQ(MinPoint.X, MaxPoint.X))
		{
			whichPlane = Plane.YZ;
		}
	}

