	public void getAvailableEntities(EntityList RefEntities, LayerKeyedCollection Layers, GetAvailableEntitiesSettings Settings, ref List<Entity> AvailableEntities)
	{
		for (int i = 0; i <= RefEntities.Count - 1; i++)
		{
			bool flag = false;
			Entity entity = RefEntities[i];
			if (!(((entity is ICurve) & Settings.AddICurveEntities) | ((entity is Text) & Settings.AddTextEntities)))
			{
				continue;
			}
			CustomData customData = null;
			if (entity.EntityData != null)
			{
				customData = (CustomData)entity.EntityData;
			}
			if (Settings.VisibleEntity)
			{
				bool visible = Layers[entity.LayerName].Visible;
				if (entity.Visible && visible)
				{
					flag = true;
				}
			}
			if (Settings.EntitiesNotAddName.Count > 0 && customData != null)
			{
				for (int j = 0; j <= Settings.EntitiesNotAddName.Count - 1; j++)
				{
					if (Settings.EntitiesNotAddName[j] == customData.EntityName)
					{
						flag = false;
					}
					if (flag && Settings.EntitiesNotAddName[j].IndexOf(customData.EntityName) >= 0)
					{
						flag = false;
					}
				}
			}
			if (Settings.EntitiesNotAddIndex.Count > 0)
			{
				for (int k = 0; k <= Settings.EntitiesNotAddIndex.Count - 1; k++)
				{
					if (Settings.EntitiesNotAddIndex[k] == i)
					{
						flag = false;
					}
				}
			}
			if (Settings.LayerNameNotAdd.Count > 0)
			{
				for (int l = 0; l <= Settings.LayerNameNotAdd.Count - 1; l++)
				{
					if (Settings.LayerNameNotAdd[l] == entity.LayerName)
					{
						flag = false;
					}
				}
			}
			if (flag)
			{
				Entity entity2 = CopyEntities(RefEntities[i]);
				((CustomData)entity2.EntityData).OriginalEntityIndex = i;
				AvailableEntities.Add(entity2);
			}
		}
	}

