	public void BreakEntitiesByRefLine(List<List<Entity>> refEntities, BreakEntitiesByRefLineEventVar Settings, ref List<List<Entity>> calcEntities)
	{
		for (int i = 0; i <= refEntities.Count - 1; i++)
		{
			List<Entity> calcEntities2 = new List<Entity>();
			BreakEntitiesByRefLine(refEntities[i], Settings, ref calcEntities2);
			calcEntities.Add(calcEntities2);
		}
	}

	public void BreakEntitiesByRefLine(List<Entity> refEntities, BreakEntitiesByRefLineEventVar Settings, ref List<Entity> calcEntities)
	{
		Point3D MinPoint = new Point3D();
		Point3D MidPoint = new Point3D();
		Point3D MaxPoint = new Point3D();
		ICurve curve = null;
		BoxSizeCalculate(refEntities, ref MinPoint, ref MidPoint, ref MaxPoint);
		double num = 0.0;
		if (Settings.RefDirection == TopBottomType.Bottom)
		{
			num = MinPoint.Y + (MaxPoint.Y - MinPoint.Y) * Settings.PersentageOfBoxSize / 100.0;
			curve = new Line(new Point3D(MinPoint.X - 10.0, num), new Point3D(MaxPoint.X + 10.0, num));
		}
		List<Entity> BaseRefEntities = new List<Entity>();
		for (int i = 0; i <= refEntities.Count - 1; i++)
		{
			refEntities[i].Regen(0.01);
			bool flag = false;
			Point3D[] array = curve.IntersectWith((ICurve)refEntities[i]);
			if (array != null && array.Length != 0)
			{
				double t = 0.0;
				ICurve lower = null;
				ICurve upper = null;
				((ICurve)refEntities[i]).ClosestPointTo(array[0], out t);
				((ICurve)refEntities[i]).SplitAt(t, out lower, out upper);
				if (lower != null && upper != null)
				{
					((Entity)lower).Regen(0.01);
					((Entity)upper).Regen(0.01);
					if (Settings.RefDirection == TopBottomType.Bottom)
					{
						if ((((Entity)lower).BoxMax.Y <= num) | buCompare5.EQ(((Entity)lower).BoxMax.Y, num))
						{
							BaseRefEntities.Add((Entity)lower);
						}
						if ((((Entity)upper).BoxMax.Y <= num) | buCompare5.EQ(((Entity)upper).BoxMax.Y, num))
						{
							BaseRefEntities.Add((Entity)upper);
						}
					}
					flag = true;
				}
			}
			if (!flag && Settings.RefDirection == TopBottomType.Bottom && ((refEntities[i].BoxMax.Y <= num) | buCompare5.EQ(refEntities[i].BoxMax.Y, num)))
			{
				BaseRefEntities.Add((Entity)refEntities[i].Clone());
			}
		}
		if (BaseRefEntities.Count > 0)
		{
			SortResult Result = new SortResult();
			SortSettings sortSettings = new SortSettings();
			sortSettings.Option.Resolution = Settings.SortResolution;
			SortEntitiesByRefPoint(new Point3D(MinPoint.X, MaxPoint.Y), ref BaseRefEntities, sortSettings, ref calcEntities, ref Result);
		}
	}

	public void EntitiesLengthFilter(ref List<Entity> refEntities, double FilterLen)
	{
		for (int num = refEntities.Count - 1; num >= 0; num--)
		{
			if (refEntities[num] is ICurve && ((ICurve)refEntities[num]).Length() < FilterLen)
			{
				refEntities.RemoveAt(num);
			}
		}
	}

	public void RemoveSmallLengthFromEntitiesPoints(ref List<Entity> refEntity, double FilterLen)
	{
		for (int i = 0; i <= refEntity.Count - 1; i++)
		{
			Entity refEntity2 = refEntity[i];
			RemoveSmallLengthFromEntityPoints(ref refEntity2, FilterLen);
			refEntity[i] = refEntity2;
		}
	}

	public void RemoveSmallLengthFromEntityPoints(ref Entity refEntity, double FilterLen)
	{
		if (refEntity is ICurve && refEntity is LinearPath)
		{
			List<Point3D> Vertice = new List<Point3D>();
			CustomData entityData = null;
			if (refEntity.EntityData is CustomData)
			{
				entityData = new CustomData((CustomData)refEntity.EntityData);
			}
			Vertice.AddRange(refEntity.Vertices);
			RemoveSmallLengthFromPoints(FilterLen, ref Vertice);
			if (Vertice.Count > 1)
			{
				refEntity = new LinearPath(Vertice);
				refEntity.EntityData = entityData;
			}
		}
	}

	public void RemoveDublicatedEntities(ref List<buEntity> refEntities)
	{
		List<buEntity> list = new List<buEntity>();
		list.Add(buEntity.Copy(refEntities[0]));
		for (int i = 1; i <= refEntities.Count - 1; i++)
		{
			bool flag = true;
			for (int j = 0; j <= list.Count - 1; j++)
			{
				if (isEntitySame(refEntities[i], list[j]))
				{
					flag = false;
					j = list.Count;
				}
			}
			if (flag)
			{
				list.Add(buEntity.Copy(refEntities[i]));
			}
		}
		refEntities.Clear();
		buEntity.Copy(list, ref refEntities);
	}

	public void ChangeEntitiesCamDirection(ref List<Entity> RefEntities)
	{
		for (int i = 0; i <= RefEntities.Count - 1; i++)
		{
			Entity entity = RefEntities[i];
			if (entity != null)
			{
				if (((CustomData)entity.EntityData).sortDirection != entitySortDirection.Normal)
				{
					((CustomData)entity.EntityData).sortDirection = entitySortDirection.Normal;
				}
				else
				{
					((CustomData)entity.EntityData).sortDirection = entitySortDirection.Reverse;
				}
			}
		}
	}

