	public void ChangeEntitiesDirection(List<buEntity> RefEntities, ref List<buEntity> ChangedEntities)
	{
		ChangedEntities = new List<buEntity>();
		for (int num = RefEntities.Count - 1; num >= 0; num--)
		{
			buEntity copiedEntity = null;
			buEntity.Copy(RefEntities[num], ref copiedEntity);
			if (copiedEntity != null)
			{
				if (!(copiedEntity is buLine))
				{
					if (!(copiedEntity is buLinearPath))
					{
						if (copiedEntity.sortDirection != entitySortDirection.Normal)
						{
							copiedEntity.sortDirection = entitySortDirection.Normal;
						}
						else
						{
							copiedEntity.sortDirection = entitySortDirection.Reverse;
						}
					}
					else
					{
						buFunctions.ExchangeDatas(ref copiedEntity.StartPoint, ref copiedEntity.EndPoint);
						copiedEntity.Vertices.Reverse();
					}
				}
				else
				{
					buFunctions.ExchangeDatas(ref copiedEntity.StartPoint, ref copiedEntity.EndPoint);
					copiedEntity.Vertices.Reverse();
				}
				ChangedEntities.Add(copiedEntity);
			}
		}
	}

