	public void BreakEntitiesWithIntersectionPoints(EntityList Entities, ref List<Entity> BrokeEntities)
	{
		BrokeEntities.Clear();
		BrokeEntities = new List<Entity>();
		for (int i = 0; i <= Entities.Count - 1; i++)
		{
			ICurve curve = Entities[i] as ICurve;
			List<Point3D> list = new List<Point3D>();
			for (int j = 0; j <= Entities.Count - 1; j++)
			{
				if (!((i != j) & (Entities[i] is ICurve) & (Entities[j] is ICurve)))
				{
					continue;
				}
				ICurve c = Entities[j] as ICurve;
				Point3D[] array = curve.IntersectWith(c);
				if (array == null)
				{
					continue;
				}
				for (int k = 0; k <= array.Length - 1; k++)
				{
					double t = 0.0;
					curve.ClosestPointTo(array[k], out t);
					if ((t > curve.Domain.t0) & (t < curve.Domain.t1))
					{
						list.Add(ToPoint3D(array[k]));
					}
				}
			}
			if (list.Count <= 0)
			{
				Entity entity = (Entity)Entities[i].Clone();
				entity.EntityData = new CustomData((CustomData)Entities[i].EntityData);
				BrokeEntities.Add(entity);
				continue;
			}
			ICurve[] segments = null;
			curve.SplitBy(list, out segments);
			if (segments != null)
			{
				for (int l = 0; l <= segments.Length - 1; l++)
				{
					Entity entity2 = (Entity)segments[l];
					entity2.EntityData = new CustomData((CustomData)Entities[i].EntityData);
					entity2.CopyAttributes(Entities[i]);
					BrokeEntities.Add(entity2);
				}
			}
		}
	}

	public bool isEntitySame(Entity baseEntity, Entity checkEntity, double Resolution = 0.001)
	{
		if (!(baseEntity.GetType() != checkEntity.GetType()))
		{
			if (!(baseEntity is ICurve && checkEntity is ICurve))
			{
				if (!(baseEntity is Dimension && checkEntity is Dimension))
				{
					if (!(baseEntity is Brep && checkEntity is Brep))
					{
						if (baseEntity is Mesh && checkEntity is Mesh && baseEntity.GetType() == checkEntity.GetType() && ((Mesh)baseEntity).Triangles.Length == ((Mesh)checkEntity).Triangles.Length)
						{
							if (((Mesh)baseEntity).BoxMin == null)
							{
								baseEntity.Regen(0.1);
							}
							if ((((Mesh)baseEntity).BoxMin == ((Mesh)checkEntity).BoxMin) & (((Mesh)baseEntity).BoxMax == ((Mesh)checkEntity).BoxMax))
							{
								return true;
							}
						}
					}
					else if (baseEntity.GetType() == checkEntity.GetType() && ((Brep)baseEntity).Edges.Length == ((Brep)checkEntity).Edges.Length && ((Brep)baseEntity).Faces.Length == ((Brep)checkEntity).Faces.Length)
					{
						if (!(((Brep)baseEntity).BoxMin != null))
						{
							return true;
						}
						if ((((Brep)baseEntity).BoxMin == ((Brep)checkEntity).BoxMin) & (((Brep)baseEntity).BoxMax == ((Brep)checkEntity).BoxMax))
						{
							return true;
						}
					}
				}
				else if (baseEntity.GetType() == checkEntity.GetType() && ((Dimension)baseEntity).TextString == ((Dimension)checkEntity).TextString)
				{
					return true;
				}
				return false;
			}
			ICurve curve = baseEntity as ICurve;
			ICurve curve2 = checkEntity as ICurve;
			double value = curve.Length();
			double value2 = curve2.Length();
			if (buCompare5.EQ(value, value2, 0.001))
			{
				if (baseEntity.BoxMin == null)
				{
					baseEntity.Regen(0.01);
				}
				if (checkEntity.BoxMin == null)
				{
					checkEntity.Regen(0.01);
				}
				if (buCompare5.EQ(baseEntity.BoxMin, checkEntity.BoxMin, 0.001))
				{
					if (buCompare5.EQ(baseEntity.BoxMax, checkEntity.BoxMax, 0.001))
					{
						if (baseEntity.Vertices.Length == checkEntity.Vertices.Length)
						{
							if (baseEntity.GetType() == typeof(Line))
							{
								if ((((Line)baseEntity).StartPoint != ((Line)checkEntity).StartPoint) & (((Line)baseEntity).EndPoint != ((Line)checkEntity).EndPoint))
								{
									return true;
								}
								if ((((Line)baseEntity).StartPoint != ((Line)checkEntity).EndPoint) & (((Line)baseEntity).EndPoint != ((Line)checkEntity).StartPoint))
								{
									return true;
								}
							}
							if (baseEntity.GetType() == typeof(Arc))
							{
								if (((Arc)baseEntity).Radius != ((Arc)checkEntity).Radius)
								{
									return false;
								}
								if (!buCompare5.EQ(((Arc)baseEntity).Center, ((Arc)checkEntity).Center, 0.01))
								{
									return false;
								}
								if (!buCompare5.EQ(((Arc)baseEntity).StartPoint, ((Arc)checkEntity).StartPoint, 0.01))
								{
									return false;
								}
								if (!buCompare5.EQ(((Arc)baseEntity).EndPoint, ((Arc)checkEntity).EndPoint, 0.01))
								{
									return false;
								}
								if (!buCompare5.EQ(((Arc)baseEntity).AngleInDegrees, ((Arc)checkEntity).AngleInDegrees, 0.01))
								{
									return false;
								}
							}
							return true;
						}
						return false;
					}
					return false;
				}
				return false;
			}
			return false;
		}
		return false;
	}

