									if (!(baseEntity.GetType() == typeof(buEllipse)) || !buCompare5.EQ(((buEllipse)baseEntity).RadiusX, ((buEllipse)checkEntity).RadiusX, Resolution) || !buCompare5.EQ(((buEllipse)baseEntity).RadiusY, ((buEllipse)checkEntity).RadiusY, Resolution) || !buCompare5.EQ(((buEllipse)baseEntity).Center, ((buEllipse)checkEntity).Center, Resolution))
									{
										return false;
									}
									return true;
