	public bool isEntitiesHasGapStartAndEndPoint(Entity baseEntity, Entity checkEntity, double GapMinDistance, double GapMaxDistance, ref Point3D pntFound)
	{
		if (baseEntity is ICurve && checkEntity is ICurve)
		{
			ICurve curve = baseEntity as ICurve;
			ICurve curve2 = checkEntity as ICurve;
			double num = Point3D.Distance(curve.StartPoint, curve2.StartPoint);
			double num2 = Point3D.Distance(curve.StartPoint, curve2.EndPoint);
			double num3 = Point3D.Distance(curve.EndPoint, curve2.StartPoint);
			double num4 = Point3D.Distance(curve.EndPoint, curve2.EndPoint);
			if (num >= GapMinDistance && num <= GapMaxDistance)
			{
				pntFound = Point3D.MidPoint(curve.StartPoint, curve2.StartPoint);
				return true;
			}
			if (num2 >= GapMinDistance && num2 <= GapMaxDistance)
			{
				pntFound = Point3D.MidPoint(curve.StartPoint, curve2.EndPoint);
				return true;
			}
			if (num3 >= GapMinDistance && num3 <= GapMaxDistance)
			{
				pntFound = Point3D.MidPoint(curve.EndPoint, curve2.StartPoint);
				return true;
			}
			if (num4 >= GapMinDistance && num4 <= GapMaxDistance)
			{
				pntFound = Point3D.MidPoint(curve.EndPoint, curve2.EndPoint);
				return true;
			}
		}
		return false;
	}

	public bool SplitArcEntitiesIfGreaterThen180Degree(Entity RefEntity, ref Entity FirstArc, ref Entity SecondArc, double SplitDegree = 170.0)
	{
		if (RefEntity.GetType() == typeof(Arc))
		{
			Arc arc = RefEntity as Arc;
			if (arc.AngleInDegrees > SplitDegree)
			{
				ICurve lower = null;
				ICurve upper = null;
				arc.SplitAt(arc.Domain.Mid, out lower, out upper);
				new Arc(Plane.XY, arc.Center, arc.EndPoint, arc.StartPoint);
				if (RefEntity.EntityData != null && RefEntity.EntityData is CustomData)
				{
					((Entity)lower).EntityData = new CustomData((CustomData)RefEntity.EntityData);
					((Entity)upper).EntityData = new CustomData((CustomData)RefEntity.EntityData);
				}
				FirstArc = (Arc)lower;
				SecondArc = (Arc)upper;
				CopyEntityProperties(RefEntity, ref FirstArc);
				CopyEntityProperties(RefEntity, ref SecondArc);
				return true;
			}
		}
		return false;
	}

