	public void EntityUpdateByNewPoint(Entity BaseEntity, Point3D CatchPoint, Point3D NewPoint, ref Entity CalcEntity, ref List<Point3D> Vertices)
	{
		if (BaseEntity.Vertices.Length == 0)
		{
			return;
		}
		if (BaseEntity.GetType() == typeof(devDept.Eyeshot.Entities.Point))
		{
			Move(BaseEntity.Vertices[0], NewPoint, BaseEntity, ref CalcEntity);
		}
		if (BaseEntity.GetType() == typeof(Line))
		{
			if (BaseEntity.Vertices[0] == CatchPoint)
			{
				CalcEntity = new Line(NewPoint, BaseEntity.Vertices[BaseEntity.Vertices.Length - 1]);
				CopyEntityProperties(BaseEntity, ref CalcEntity);
			}
			if (BaseEntity.Vertices[BaseEntity.Vertices.Length - 1] == CatchPoint)
			{
				CalcEntity = new Line(BaseEntity.Vertices[0], NewPoint);
				CopyEntityProperties(BaseEntity, ref CalcEntity);
			}
		}
		if (BaseEntity.GetType() == typeof(LinearPath))
		{
			List<Point3D> copiedPoint = new List<Point3D>();
			Copy(BaseEntity.Vertices, ref copiedPoint);
			for (int i = 0; i <= copiedPoint.Count - 1; i++)
			{
				if (copiedPoint[i] == CatchPoint)
				{
					copiedPoint[i] = ToPoint3D(NewPoint);
				}
			}
			CalcEntity = new LinearPath(copiedPoint);
			CopyEntityProperties(BaseEntity, ref CalcEntity);
		}
		if (BaseEntity.GetType() == typeof(Arc))
		{
			Arc arc = BaseEntity as Arc;
			if (arc.Center == CatchPoint)
			{
				Move(arc.Center, NewPoint, BaseEntity, ref CalcEntity);
			}
			if (arc.StartPoint == CatchPoint)
			{
				Arc arc2 = new Arc(NewPoint, arc.MidPoint, arc.EndPoint, flip: false);
				CalcEntity = new Arc(arc.Plane, arc2.Center, arc2.Radius, arc2.StartPoint, arc2.EndPoint, flip: false);
				if (!buCompare5.EQ(arc2.AngleInDegrees, ((Arc)CalcEntity).AngleInDegrees, 0.001))
				{
					CalcEntity = new Arc(arc.Plane, arc2.Center, arc2.Radius, arc2.StartPoint, arc2.EndPoint, flip: true);
				}
				CopyEntityProperties(BaseEntity, ref CalcEntity);
			}
			if (arc.MidPoint == CatchPoint)
			{
				Arc arc3 = new Arc(arc.StartPoint, NewPoint, arc.EndPoint, flip: false);
				CalcEntity = new Arc(arc.Plane, arc3.Center, arc3.Radius, arc3.StartPoint, arc3.EndPoint, flip: false);
				if (!buCompare5.EQ(arc3.AngleInDegrees, ((Arc)CalcEntity).AngleInDegrees, 0.001))
				{
					CalcEntity = new Arc(arc.Plane, arc3.Center, arc3.Radius, arc3.StartPoint, arc3.EndPoint, flip: true);
				}
				CopyEntityProperties(BaseEntity, ref CalcEntity);
			}
			if (arc.EndPoint == CatchPoint)
			{
				Arc arc4 = new Arc(arc.StartPoint, arc.MidPoint, NewPoint, flip: false);
				CalcEntity = new Arc(arc.Plane, arc4.Center, arc4.Radius, arc4.StartPoint, arc4.EndPoint, flip: false);
				if (!buCompare5.EQ(arc4.AngleInDegrees, ((Arc)CalcEntity).AngleInDegrees, 0.001))
				{
					CalcEntity = new Arc(arc.Plane, arc4.Center, arc4.Radius, arc4.StartPoint, arc4.EndPoint, flip: true);
				}
				CopyEntityProperties(BaseEntity, ref CalcEntity);
			}
		}
		if (BaseEntity.GetType() == typeof(Circle))
		{
			Circle circle = BaseEntity as Circle;
			if (circle.Center == CatchPoint)
			{
				Move(circle.Center, NewPoint, BaseEntity, ref CalcEntity);
			}
			if (circle.Vertices[0] == CatchPoint)
			{
				double radius = Length3D(NewPoint, circle.Center);
				CalcEntity = new Circle(circle.Plane, circle.Center, radius);
				CopyEntityProperties(BaseEntity, ref CalcEntity);
			}
		}
		if (BaseEntity.GetType() == typeof(Ellipse))
		{
			Ellipse ellipse = BaseEntity as Ellipse;
			if (ellipse.Center == CatchPoint)
			{
				Move(ellipse.Center, NewPoint, BaseEntity, ref CalcEntity);
			}
		}
		if (BaseEntity.GetType() == typeof(EllipticalArc))
		{
			EllipticalArc ellipticalArc = BaseEntity as EllipticalArc;
			if (ellipticalArc.Center == CatchPoint)
			{
				Move(ellipticalArc.Center, NewPoint, BaseEntity, ref CalcEntity);
			}
		}
		if (BaseEntity.GetType() == typeof(Curve))
		{
			Curve curve = BaseEntity as Curve;
			List<Point3D> copiedPoint2 = new List<Point3D>();
			Point3D[] controlPoints = curve.ControlPoints;
			Copy(controlPoints, ref copiedPoint2);
			for (int j = 0; j <= copiedPoint2.Count - 1; j++)
			{
				if (copiedPoint2[j] == CatchPoint)
				{
					copiedPoint2[j] = ToPoint3D(NewPoint);
				}
			}
			CalcEntity = new Curve(curve.Degree, copiedPoint2);
			CopyEntityProperties(BaseEntity, ref CalcEntity);
		}
		if (BaseEntity.GetType() == typeof(Picture))
		{
			Picture picture = BaseEntity as Picture;
			List<Point3D> copiedPoint3 = new List<Point3D>();
			Copy(picture.Vertices, ref copiedPoint3);
			for (int k = 0; k <= copiedPoint3.Count - 1; k++)
			{
				if (copiedPoint3[k] == CatchPoint)
				{
					copiedPoint3[k] = ToPoint3D(NewPoint);
				}
			}
			Point3D MinPoint = new Point3D();
			Point3D MidPoint = new Point3D();
			Point3D MaxPoint = new Point3D();
			BoxSizeCalculate(copiedPoint3, ref MinPoint, ref MidPoint, ref MaxPoint);
			CalcEntity = new Picture(picture.Plane, MaxPoint.X - MinPoint.X, MaxPoint.Y - MinPoint.Y, picture.Image);
			CalcEntity.Translate(MinPoint.X, MinPoint.Y, MinPoint.Z);
			CopyEntityProperties(BaseEntity, ref CalcEntity);
		}
		if (BaseEntity.GetType() == typeof(Text))
		{
			Move(BaseEntity.Vertices[0], NewPoint, BaseEntity, ref CalcEntity);
			CopyEntityProperties(BaseEntity, ref CalcEntity);
		}
		Vertices = new List<Point3D>();
