	public bool IsPointTouchEntityPoint(Point3D RefPoint, Entity RefEntities, Plane Plane, double Resolution, bool TipPoint, bool Middle, bool Outter, bool Center, bool Over, bool ControlPoint, ref int VerticeIndex, ref Point3D CatchPoint, ref osnapType OsnapTypes)
	{
		Point3D point3D = new Point3D();
		if (TipPoint)
		{
			if ((RefEntities.GetType() == typeof(Line)) | (RefEntities.GetType() == typeof(LinearPath)) | (RefEntities.GetType() == typeof(Curve)) | (RefEntities.GetType() == typeof(Picture)) | (RefEntities.GetType() == typeof(Text)) | (RefEntities.GetType() == typeof(eDimLineer)))
			{
				for (int i = 0; i <= RefEntities.Vertices.Length - 1; i++)
				{
					if (IsPointInsideWindow(RefPoint, RefEntities.Vertices[i], Resolution, Plane))
					{
						CatchPoint = ToPoint3D(RefEntities.Vertices[i]);
						VerticeIndex = i;
						OsnapTypes = osnapType.Point;
						return true;
					}
				}
			}
			if (RefEntities.GetType() == typeof(Arc))
			{
				if (IsPointInsideWindow(RefPoint, ((Arc)RefEntities).StartPoint, Resolution, Plane))
				{
					CatchPoint = ToPoint3D(((Arc)RefEntities).StartPoint);
					VerticeIndex = 0;
					OsnapTypes = osnapType.Point;
					return true;
				}
				if (IsPointInsideWindow(RefPoint, ((Arc)RefEntities).EndPoint, Resolution, Plane))
				{
					CatchPoint = ToPoint3D(((Arc)RefEntities).EndPoint);
					VerticeIndex = 1;
					OsnapTypes = osnapType.Point;
					return true;
				}
			}
			if (RefEntities.GetType() == typeof(EllipticalArc))
			{
				if (IsPointInsideWindow(RefPoint, ((EllipticalArc)RefEntities).StartPoint, Resolution, Plane))
				{
					CatchPoint = ToPoint3D(((EllipticalArc)RefEntities).StartPoint);
					VerticeIndex = 0;
					OsnapTypes = osnapType.Point;
					return true;
				}
				if (IsPointInsideWindow(RefPoint, ((EllipticalArc)RefEntities).EndPoint, Resolution, Plane))
				{
					CatchPoint = ToPoint3D(((EllipticalArc)RefEntities).EndPoint);
					VerticeIndex = 1;
					OsnapTypes = osnapType.Point;
					return true;
				}
			}
			if (RefEntities.GetType() == typeof(devDept.Eyeshot.Entities.Point) && IsPointInsideWindow(RefPoint, ((devDept.Eyeshot.Entities.Point)RefEntities).StartPoint, Resolution, Plane))
			{
				CatchPoint = ToPoint3D(((devDept.Eyeshot.Entities.Point)RefEntities).StartPoint);
				VerticeIndex = 0;
				OsnapTypes = osnapType.Point;
				return true;
			}
		}
		if (Middle)
		{
			if ((RefEntities.GetType() == typeof(Line)) | (RefEntities.GetType() == typeof(LinearPath)))
			{
				for (int j = 1; j <= RefEntities.Vertices.Length - 1; j++)
				{
					point3D = new Point3D();
					point3D = MiddlePointOfLine(RefEntities.Vertices[j - 1], RefEntities.Vertices[j]);
					if (IsPointInsideWindow(RefPoint, point3D, Resolution, Plane))
					{
						CatchPoint = point3D;
						VerticeIndex = j;
						OsnapTypes = osnapType.Middle;
						return true;
					}
				}
			}
			if (!(RefEntities.GetType() == typeof(Arc)))
			{
			}
		}
		if (Center)
		{
			if (RefEntities.GetType() == typeof(Circle) && IsPointInsideWindow(RefPoint, ((Circle)RefEntities).Center, Resolution, Plane))
			{
				CatchPoint = ToPoint3D(((Circle)RefEntities).Center);
				VerticeIndex = 2;
				OsnapTypes = osnapType.Center;
				return true;
			}
			if (RefEntities.GetType() == typeof(Arc) && IsPointInsideWindow(RefPoint, ((Arc)RefEntities).Center, Resolution, Plane))
			{
				CatchPoint = ToPoint3D(((Arc)RefEntities).Center);
				VerticeIndex = 2;
				OsnapTypes = osnapType.Center;
				return true;
			}
			if (RefEntities.GetType() == typeof(Ellipse) && IsPointInsideWindow(RefPoint, ((Ellipse)RefEntities).Center, Resolution, Plane))
			{
				CatchPoint = ToPoint3D(((Ellipse)RefEntities).Center);
				VerticeIndex = 2;
				OsnapTypes = osnapType.Center;
				return true;
			}
			if (RefEntities.GetType() == typeof(EllipticalArc) && IsPointInsideWindow(RefPoint, ((EllipticalArc)RefEntities).Center, Resolution, Plane))
			{
				CatchPoint = ToPoint3D(((EllipticalArc)RefEntities).Center);
				VerticeIndex = 2;
				OsnapTypes = osnapType.Center;
				return true;
			}
		}
		if (!Outter)
		{
		}
		if (!ControlPoint)
		{
		}
		if (!Over)
		{
		}
		return false;
	}

	public void EntityDevide(Entity refEntity, double DevideLength, bool DevideAsPolyline, ref List<Entity> entitiesDevided)
	{
		entitiesDevided.Clear();
		entitiesDevided = new List<Entity>();
		if (!(refEntity is ICurve))
		{
			return;
		}
		CustomData entityData = new CustomData();
		if (refEntity.EntityData != null && refEntity.EntityData is CustomData)
		{
			entityData = new CustomData((CustomData)refEntity.EntityData);
		}
		ICurve curve = refEntity as ICurve;
		double num = curve.Length();
		double num2 = Convert.ToInt32(num / DevideLength);
		if (num2 < 1.0)
		{
			num2 = 1.0;
		}
		List<Point3D> list = new List<Point3D>();
		for (double num3 = 0.0; num3 <= num2; num3 += 1.0)
		{
			Point3D point3D = curve.PointAt(curve.Domain.Min + num3 * (curve.Domain.Max - curve.Domain.Min) / num2);
			if (!(point3D != null))
			{
				continue;
			}
			if (!(num3 < num2))
			{
				if (DevideAsPolyline)
				{
					list.Add(point3D);
				}
			}
			else
			{
				list.Add(point3D);
			}
		}
		if (list.Count <= 0)
		{
			return;
		}
		if (DevideAsPolyline)
		{
			LinearPath linearPath = new LinearPath(list);
			linearPath.EntityData = entityData;
			entitiesDevided.Add(linearPath);
			return;
		}
		ICurve[] segments = null;
		curve.SplitBy(list, out segments);
		if (segments != null)
		{
			for (int i = 0; i <= segments.Length - 1; i++)
			{
				Entity entity = (Entity)segments[i];
				entity.EntityData = entityData;
				entitiesDevided.Add(entity);
			}
		}
	}

