	public bool isEntitiesGroupInsideEntities(List<Entity> BaseEntities, List<Entity> ChekcedEntities, Plane refPlane)
	{
		Point3D MinPoint = new Point3D();
		Point3D MaxPoint = new Point3D();
		Point3D MinPoint2 = new Point3D();
		Point3D MaxPoint2 = new Point3D();
		BoxSizeCalculate(BaseEntities, ref MinPoint, ref MaxPoint);
		BoxSizeCalculate(ChekcedEntities, ref MinPoint2, ref MaxPoint2);
		List<Point3D> Points = new List<Point3D>();
		EntitiesToPointsWithCamDirection(BaseEntities, buSystem.RegenDeviation, ref Points);
		if (!isBoxSizeInsideBoxSize(MinPoint, MaxPoint, MinPoint2, MaxPoint2, refPlane))
		{
			return false;
		}
		bool flag = true;
		for (int i = 0; i <= ChekcedEntities.Count - 1; i++)
		{
			Entity entity = ChekcedEntities[i];
			if (entity.Vertices == null)
			{
				entity.Regen(new RegenParams(buSystem.RegenDeviation));
			}
			for (int j = 0; j <= entity.Vertices.Length - 1; j++)
			{
				if (!IsPointInsidePolygon(Points, entity.Vertices[j]))
				{
					flag = false;
					j = entity.Vertices.Length;
				}
			}
		}
		if (!flag)
		{
			return false;
		}
		return true;
	}

