	public void EntityICurveOsnapPoints(Entity ent, Design Viewport, double OsnapSize, bool OnlyStartEndPoint, System.Drawing.Point mouseLocation, ref OsnapPoint foundPoint)
	{
		double num = double.MaxValue;
		foundPoint.Type = osnapType.None;
		if (!(ent is LinearPath && !OnlyStartEndPoint))
		{
			if (!(ent.GetType() == typeof(Circle)))
			{
				if (ent.Vertices.Length != 0)
				{
					Point3D a = Viewport.WorldToScreen(((ICurve)ent).StartPoint);
					Point2D b = new Point2D(mouseLocation.X, Viewport.Height - mouseLocation.Y);
					double num2 = Point2D.Distance(a, b);
					if (num2 < num && num2 <= OsnapSize)
					{
						num = num2;
						foundPoint.X = ((ICurve)ent).StartPoint.X;
						foundPoint.Y = ((ICurve)ent).StartPoint.Y;
						foundPoint.Z = ((ICurve)ent).StartPoint.Z;
						foundPoint.Type = osnapType.Point;
					}
					a = Viewport.WorldToScreen(((ICurve)ent).EndPoint);
					b = new Point2D(mouseLocation.X, Viewport.Height - mouseLocation.Y);
					num2 = Point2D.Distance(a, b);
					if (num2 < num && num2 <= OsnapSize)
					{
						num = num2;
						foundPoint.X = ((ICurve)ent).EndPoint.X;
						foundPoint.Y = ((ICurve)ent).EndPoint.Y;
						foundPoint.Z = ((ICurve)ent).EndPoint.Z;
						foundPoint.Type = osnapType.Point;
					}
					a = Viewport.WorldToScreen(Point3D.MidPoint(((ICurve)ent).StartPoint, ((ICurve)ent).EndPoint));
					b = new Point2D(mouseLocation.X, Viewport.Height - mouseLocation.Y);
					num2 = Point2D.Distance(a, b);
					if (num2 < num && num2 <= OsnapSize)
					{
						num = num2;
						foundPoint.X = Point3D.MidPoint(((ICurve)ent).StartPoint, ((ICurve)ent).EndPoint).X;
						foundPoint.Y = Point3D.MidPoint(((ICurve)ent).StartPoint, ((ICurve)ent).EndPoint).Y;
						foundPoint.Z = Point3D.MidPoint(((ICurve)ent).StartPoint, ((ICurve)ent).EndPoint).Z;
						foundPoint.Type = osnapType.Middle;
					}
				}
			}
			else
			{
				Point3D a2 = Viewport.WorldToScreen(((Circle)ent).Center);
				Point2D b2 = new Point2D(mouseLocation.X, Viewport.Height - mouseLocation.Y);
				double num3 = Point2D.Distance(a2, b2);
				if (num3 < num && num3 <= OsnapSize)
				{
					num = num3;
					foundPoint.X = ((Circle)ent).Center.X;
					foundPoint.Y = ((Circle)ent).Center.Y;
					foundPoint.Z = ((Circle)ent).Center.Z;
					foundPoint.Type = osnapType.Center;
				}
			}
			return;
		}
		for (int i = 0; i <= ent.Vertices.Length - 1; i++)
		{
			Point3D a3 = Viewport.WorldToScreen(ent.Vertices[i]);
			Point2D b3 = new Point2D(mouseLocation.X, Viewport.Height - mouseLocation.Y);
			double num4 = Point2D.Distance(a3, b3);
			if (num4 < num && num4 <= OsnapSize)
			{
				num = num4;
				foundPoint.X = ent.Vertices[i].X;
				foundPoint.Y = ent.Vertices[i].Y;
				foundPoint.Z = ent.Vertices[i].Z;
				foundPoint.Type = osnapType.Point;
			}
			if (i > 0)
			{
				a3 = Viewport.WorldToScreen(Point3D.MidPoint(ent.Vertices[i - 1], ent.Vertices[i]));
				b3 = new Point2D(mouseLocation.X, Viewport.Height - mouseLocation.Y);
				num4 = Point2D.Distance(a3, b3);
				if (num4 < num && num4 <= OsnapSize)
				{
					num = num4;
					foundPoint.X = Point3D.MidPoint(ent.Vertices[i - 1], ent.Vertices[i]).X;
					foundPoint.Y = Point3D.MidPoint(ent.Vertices[i - 1], ent.Vertices[i]).Y;
					foundPoint.Z = Point3D.MidPoint(ent.Vertices[i - 1], ent.Vertices[i]).Z;
					foundPoint.Type = osnapType.Middle;
				}
			}
		}
	}

	public void EntityLengthModify(buEntity RefEntity, StartPointType ModifyDirType, double ModifyLength, ref buEntity ModifiedEntity)
	{
		ModifiedEntity = new buEntity();
		double cutLength = ModifyLength / Math.Cos(buConversion5.DegreeToRadian(RefEntity.Orientation.A));
		if (ModifyDirType == StartPointType.Start)
		{
			if (RefEntity.sortDirection != entitySortDirection.Normal)
			{
				EntityUpdateByLengthUsingCamDirection(buEntity.Copy(RefEntity), cutLength, StartPointType.End, Plane.XY, ref ModifiedEntity);
			}
			else
			{
				EntityUpdateByLengthUsingCamDirection(buEntity.Copy(RefEntity), cutLength, StartPointType.Start, Plane.XY, ref ModifiedEntity);
			}
		}
		if (ModifyDirType == StartPointType.End)
		{
			if (RefEntity.sortDirection != entitySortDirection.Normal)
			{
				EntityUpdateByLengthUsingCamDirection(buEntity.Copy(RefEntity), cutLength, StartPointType.Start, Plane.XY, ref ModifiedEntity);
			}
			else
			{
				EntityUpdateByLengthUsingCamDirection(buEntity.Copy(RefEntity), cutLength, StartPointType.End, Plane.XY, ref ModifiedEntity);
			}
		}
		if (ModifyDirType == StartPointType.StartAndEnd)
		{
			EntityUpdateByLengthUsingCamDirection(buEntity.Copy(RefEntity), cutLength, StartPointType.StartAndEnd, Plane.XY, ref ModifiedEntity);
		}
		ModifiedEntity.Info.CamSelected = false;
	}

