	public void Arc3Point(Point3D FirstPoint, Point3D SecondPoint, Point3D ThirdPoint, Plane Plane, EntityResolution EntResolution, ref Point3D Center, ref double Radius, ref double StartAngle, ref double EndAngle, ref List<Point3D> Vertices)
	{
		try
		{
			double num = 0.0;
			double num2 = 0.0;
			double num3 = 0.0;
			double num4 = 0.0;
			double num5 = 0.0;
			double num6 = 0.0;
			double num7 = 0.0;
			double num8 = 0.0;
			double num9 = 0.0;
			double num10 = 0.0;
			int num11 = 10;
			Point3D point3D = new Point3D();
			if (isPlaneXYorYX(Plane))
