	public void Arc3Point(Point3D FirstPoint, Point3D SecondPoint, Point3D ThirdPoint, Plane Plane, EntityResolution EntResolution, ref List<Point3D> Vertices)
	{
		Point3D Center = new Point3D();
		double Radius = 0.0;
		double StartAngle = 0.0;
		double EndAngle = 0.0;
		Vertices.Clear();
		Arc3Point(FirstPoint, SecondPoint, ThirdPoint, Plane, EntResolution, ref Center, ref Radius, ref StartAngle, ref EndAngle, ref Vertices);
	}

	public void Arc3Point(Point3D FirstPoint, Point3D SecondPoint, Point3D ThirdPoint, Plane Plane, ref Point3D Center, ref double Radius, ref double StartAngle, ref double EndAngle)
	{
		List<Point3D> Vertices = new List<Point3D>();
		Arc3Point(FirstPoint, SecondPoint, ThirdPoint, Plane, new EntityResolution(), ref Center, ref Radius, ref StartAngle, ref EndAngle, ref Vertices);
	}

	public void Arc3Point(Point3D FirstPoint, Point3D SecondPoint, Point3D ThirdPoint, Plane Plane, ref buEntity entityArc)
	{
		List<Point3D> list = new List<Point3D>();
		list.Add(FirstPoint);
		list.Add(SecondPoint);
		list.Add(ThirdPoint);
		list.Add(FirstPoint);
		ClockDirectionType clockDirection = GetClockDirection(list, Plane);
		bool flip = false;
		if (clockDirection == ClockDirectionType.CW)
		{
			flip = true;
		}
		entityArc = new buArc(FirstPoint, SecondPoint, ThirdPoint, flip);
	}

	public int ArcVerticeCountByResolution(double Radius, double StartAngle, double EndAngle, EntityResolution EntResolution)
	{
		try
		{
			int num = 10;
			double num2 = 0.0;
			if (EntResolution.ResolutionTypes == EntityResolutionType.ByNumber)
			{
				num = EntResolution.GeometricCount;
				if (num < EntResolution.MinPointCount)
				{
					num = EntResolution.MinPointCount;
				}
			}
			if (EntResolution.ResolutionTypes == EntityResolutionType.ByLength)
			{
				if (buNumeric5.IsNumeric(Radius.ToString()))
				{
					num2 = Math.PI * 2.0 * Radius;
					num = Convert.ToInt32(num2 * ((EndAngle - StartAngle) / 360.0) / EntResolution.GeometricLength);
				}
				if (num < EntResolution.MinPointCount)
				{
					num = EntResolution.MinPointCount;
				}
			}
			if (EntResolution.ResolutionTypes == EntityResolutionType.ByLnRadius)
			{
				if (buNumeric5.IsNumeric(Radius.ToString()) && Radius > 0.0)
				{
					num = Convert.ToInt32(Math.Log(Radius, Math.E) * EntResolution.LnRatio);
				}
				if (num < EntResolution.MinPointCount)
				{
					num = EntResolution.MinPointCount;
				}
			}
			return num;
		}
		catch (Exception mSException)
		{
			string text = "R: " + Radius + " - SA: " + StartAngle + " - EA: " + EndAngle + " - Ent Res:" + EntResolution.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return -1;
		}
	}

	public void AnalyseEntities(List<Entity> refEntities, AnalyseEntitiesSetting Settings, ref AnalyseEntitiesResult Result)
	{
		try
		{
			if (refEntities.Count == 0)
			{
				return;
			}
			for (int i = 0; i <= refEntities.Count - 1; i++)
			{
				for (int j = i + 1; j <= refEntities.Count - 1; j++)
				{
					if (Settings.isSameMoreThanOneCheck && isEntitySame(refEntities[i], refEntities[j]))
					{
						AnalyseEntitiesResultError analyseEntitiesResultError = new AnalyseEntitiesResultError();
						analyseEntitiesResultError.ErrorType = AnalyseEntitiesResultErrorType.SameAvailable;
						analyseEntitiesResultError.IndexEntity = i;
						if (refEntities[i].EntityData != null && refEntities[i].EntityData is CustomData && ((CustomData)refEntities[i].EntityData).OriginalEntityIndex >= 0)
						{
							analyseEntitiesResultError.IndexEntity = ((CustomData)refEntities[i].EntityData).OriginalEntityIndex;
						}
						analyseEntitiesResultError.Action = AnalyseEntitiesActionType.Delete;
						analyseEntitiesResultError.pntError = ToPoint3D(MiddlePointOfLine(((ICurve)refEntities[i]).StartPoint, ((ICurve)refEntities[i]).EndPoint));
						refEntities[i].Selected = true;
						Result.isError = true;
						if (Result.ErrorList.Count != 0)
						{
							bool flag = true;
							for (int k = 0; k <= Result.ErrorList.Count - 1; k++)
							{
								if ((analyseEntitiesResultError.IndexEntity == Result.ErrorList[k].IndexEntity) & (analyseEntitiesResultError.ErrorType == Result.ErrorList[k].ErrorType))
								{
									flag = false;
									k = Result.ErrorList.Count;
								}
							}
							if (flag)
							{
								Result.ErrorList.Add(analyseEntitiesResultError);
							}
						}
						else
						{
							Result.ErrorList.Add(analyseEntitiesResultError);
						}
					}
					if (!Settings.isSmallGap)
					{
						continue;
					}
					Point3D pntFound = new Point3D();
					if (!isEntitiesHasGapStartAndEndPoint(refEntities[i], refEntities[j], Settings.SmallGapMinDistance, Settings.SmallGapMaxDistance, ref pntFound))
					{
						continue;
					}
					AnalyseEntitiesResultError analyseEntitiesResultError2 = new AnalyseEntitiesResultError();
					analyseEntitiesResultError2.ErrorType = AnalyseEntitiesResultErrorType.SmallGap;
					analyseEntitiesResultError2.IndexEntity = i;
					if (refEntities[i].EntityData != null && refEntities[i].EntityData is CustomData && ((CustomData)refEntities[i].EntityData).OriginalEntityIndex >= 0)
					{
						analyseEntitiesResultError2.IndexEntity = ((CustomData)refEntities[i].EntityData).OriginalEntityIndex;
					}
					analyseEntitiesResultError2.pntError = ToPoint3D(pntFound);
					analyseEntitiesResultError2.Action = AnalyseEntitiesActionType.Fix;
					refEntities[i].Selected = true;
					Result.isError = true;
					if (Result.ErrorList.Count != 0)
					{
						bool flag2 = true;
						for (int l = 0; l <= Result.ErrorList.Count - 1; l++)
						{
							if ((analyseEntitiesResultError2.IndexEntity == Result.ErrorList[l].IndexEntity) & (analyseEntitiesResultError2.ErrorType == Result.ErrorList[l].ErrorType))
							{
								flag2 = false;
								l = Result.ErrorList.Count;
							}
						}
						if (flag2)
						{
							Result.ErrorList.Add(analyseEntitiesResultError2);
						}
					}
					else
					{
						Result.ErrorList.Add(analyseEntitiesResultError2);
					}
				}
				if (!Settings.isEntityLengthSmall || !(refEntities[i] is ICurve) || !(((ICurve)refEntities[i]).Length() <= Settings.EntityLengthLimit))
				{
					continue;
				}
				AnalyseEntitiesResultError analyseEntitiesResultError3 = new AnalyseEntitiesResultError();
				analyseEntitiesResultError3.ErrorType = AnalyseEntitiesResultErrorType.SmallLength;
				analyseEntitiesResultError3.IndexEntity = i;
				if (refEntities[i].EntityData != null && refEntities[i].EntityData is CustomData && ((CustomData)refEntities[i].EntityData).OriginalEntityIndex >= 0)
				{
					analyseEntitiesResultError3.IndexEntity = ((CustomData)refEntities[i].EntityData).OriginalEntityIndex;
				}
				analyseEntitiesResultError3.Action = AnalyseEntitiesActionType.Delete;
				analyseEntitiesResultError3.pntError = ToPoint3D(MiddlePointOfLine(((ICurve)refEntities[i]).StartPoint, ((ICurve)refEntities[i]).EndPoint));
				refEntities[i].Selected = true;
				Result.isError = true;
				if (Result.ErrorList.Count != 0)
				{
					bool flag3 = true;
					for (int m = 0; m <= Result.ErrorList.Count - 1; m++)
					{
						if ((analyseEntitiesResultError3.IndexEntity == Result.ErrorList[m].IndexEntity) & (analyseEntitiesResultError3.ErrorType == Result.ErrorList[m].ErrorType))
						{
							flag3 = false;
							m = Result.ErrorList.Count;
						}
					}
					if (flag3)
					{
						Result.ErrorList.Add(analyseEntitiesResultError3);
					}
				}
				else
				{
					Result.ErrorList.Add(analyseEntitiesResultError3);
				}
			}
			if (!(Settings.isClosedEntities | Settings.IntersectionEntities))
			{
				return;
			}
			List<buEntity> copiedEntities = new List<buEntity>();
			buEntity.Copy(refEntities, ref copiedEntities);
			SortbuSettings sortbuSettings = new SortbuSettings();
			sortbuSettings.Option.NextGroupRules = SortingNextGroupFindRulesType.ClosestLength;
			sortbuSettings.Option.UseCamSelectedProps = true;
			List<buEntity> SortedEntities = new List<buEntity>();
			List<List<buEntity>> SplitedEntitites = new List<List<buEntity>>();
			SortEntitiesByRefPoint(copiedEntities[0].Vertices[0], ref copiedEntities, sortbuSettings, ref SortedEntities);
			EntitiesSplitByUpperLine(SortedEntities, ref SplitedEntitites);
			new List<int>();
			List<int> list = new List<int>();
			for (int n = 0; n <= SplitedEntitites.Count - 1; n++)
			{
				if (!isEntitiesClosed(SplitedEntitites[n]) & Settings.isClosedEntities)
				{
					AnalyseEntitiesResultError analyseEntitiesResultError4 = new AnalyseEntitiesResultError();
					analyseEntitiesResultError4.ErrorType = AnalyseEntitiesResultErrorType.NotClosedEntities;
					analyseEntitiesResultError4.pntError = ToPoint3D(SplitedEntitites[n][0].StartPoint);
					analyseEntitiesResultError4.Action = AnalyseEntitiesActionType.None;
					refEntities[n].Selected = true;
					Result.isError = true;
					for (int num = 0; num <= SplitedEntitites[n].Count - 1; num++)
					{
						analyseEntitiesResultError4.IndexEntityList.Add(SplitedEntitites[n][num].Info.OriginalEntityIndex);
					}
					Result.ErrorList.Add(analyseEntitiesResultError4);
				}
				if (!Settings.IntersectionEntities)
				{
					continue;
				}
				for (int num2 = 0; num2 <= SplitedEntitites[n].Count - 1; num2++)
				{
					for (int num3 = n + 1; num3 <= SplitedEntitites.Count - 1; num3++)
					{
						for (int num4 = 0; num4 <= SplitedEntitites[num3].Count - 1; num4++)
						{
							new List<OsnapPoint>();
							if (isIntersectionEntities(SplitedEntitites[n][num2], SplitedEntitites[num3][num4], Settings.IntersectionGap))
							{
								bool flag4 = buNumeric5.isNumberAvailableList(SplitedEntitites[n][num2].Info.OriginalEntityIndex, list);
								bool flag5 = buNumeric5.isNumberAvailableList(SplitedEntitites[num3][num4].Info.OriginalEntityIndex, list);
								if (!flag4 && !flag5)
								{
									AnalyseEntitiesResultError analyseEntitiesResultError5 = new AnalyseEntitiesResultError();
									analyseEntitiesResultError5.ErrorType = AnalyseEntitiesResultErrorType.Intersection;
									analyseEntitiesResultError5.IndexEntityList.Add(SplitedEntitites[n][num2].Info.OriginalEntityIndex);
									analyseEntitiesResultError5.IndexEntityList.Add(SplitedEntitites[num3][num4].Info.OriginalEntityIndex);
									analyseEntitiesResultError5.Action = AnalyseEntitiesActionType.None;
									analyseEntitiesResultError5.pntError = ToPoint3D(MiddlePointOfLine(SplitedEntitites[n][num2].BoxMin, SplitedEntitites[n][num2].BoxMax));
									refEntities[n].Selected = true;
									Result.isError = true;
									Result.ErrorList.Add(analyseEntitiesResultError5);
									list.Add(SplitedEntitites[n][num2].Info.OriginalEntityIndex);
								}
							}
						}
					}
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "Entities: " + refEntities.Count;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void CreateCompositeCurveFromEntities(List<buEntity> refEntities, ref buCompositeCurve calcCompositeCurve)
	{
		List<buEntity> list = new List<buEntity>();
		for (int i = 0; i <= refEntities.Count - 1; i++)
		{
			buEntity buEntity2 = null;
			if (!(refEntities[i] is buLine))
			{
				if (!(refEntities[i] is buArc))
				{
					if (!(refEntities[i] is buCircle))
					{
						if (!(refEntities[i] is buCurve))
						{
							if (!(refEntities[i] is buEllipse))
							{
								if (!(refEntities[i] is buLinearPath))
								{
									if (refEntities[i] is buCompositeCurve)
									{
										buEntity2 = (buCompositeCurve)refEntities[i];
									}
								}
								else
								{
									buEntity2 = (buLinearPath)refEntities[i];
								}
							}
							else
							{
								buEntity2 = (buEllipse)refEntities[i];
							}
						}
						else
						{
							buEntity2 = (buCurve)refEntities[i];
						}
					}
					else
					{
						buEntity2 = (buCircle)refEntities[i];
					}
				}
				else
				{
					buEntity2 = (buArc)refEntities[i];
				}
			}
			else
			{
				buEntity2 = (buLine)refEntities[i];
			}
			if (buEntity2 != null)
			{
				list.Add(buEntity2);
			}
		}
		if (list.Count > 0)
		{
			calcCompositeCurve = new buCompositeCurve(list);
		}
	}

