	public void CreateCompositeCurveFromEntitiesWithCamDirection(List<Entity> refEntities, ref CompositeCurve calcCompositeCurve)
	{
		List<ICurve> list = new List<ICurve>();
		for (int i = 0; i <= refEntities.Count - 1; i++)
		{
			Entity entity = CopyEntities(refEntities[i]);
			ICurve curve = null;
			if (!(refEntities[i] is Line))
			{
				if (!(refEntities[i] is Arc))
				{
					if (!(refEntities[i] is Circle))
					{
						if (!(refEntities[i] is Curve))
						{
							if (!(refEntities[i] is Ellipse))
							{
								if (!(refEntities[i] is LinearPath))
								{
									if (refEntities[i] is CompositeCurve)
									{
										if (entity.EntityData != null && entity.EntityData is CustomData && ((CustomData)entity.EntityData).sortDirection == entitySortDirection.Reverse)
										{
											((ICurve)entity).Reverse();
										}
										curve = (CompositeCurve)entity;
									}
								}
								else
								{
									if (entity.EntityData != null && entity.EntityData is CustomData && ((CustomData)entity.EntityData).sortDirection == entitySortDirection.Reverse)
									{
										((ICurve)entity).Reverse();
									}
									curve = (LinearPath)entity;
								}
							}
							else
							{
								if (entity.EntityData != null && entity.EntityData is CustomData && ((CustomData)entity.EntityData).sortDirection == entitySortDirection.Reverse)
								{
									((ICurve)entity).Reverse();
								}
								curve = (Ellipse)entity;
							}
						}
						else
						{
							if (entity.EntityData != null && entity.EntityData is CustomData && ((CustomData)entity.EntityData).sortDirection == entitySortDirection.Reverse)
							{
								((ICurve)entity).Reverse();
							}
							curve = (Curve)entity;
						}
					}
					else
					{
						if (entity.EntityData != null && entity.EntityData is CustomData && ((CustomData)entity.EntityData).sortDirection == entitySortDirection.Reverse)
						{
							((ICurve)entity).Reverse();
						}
						curve = (Circle)entity;
					}
				}
				else
				{
					if (entity.EntityData != null && entity.EntityData is CustomData && ((CustomData)entity.EntityData).sortDirection == entitySortDirection.Reverse)
					{
						((ICurve)entity).Reverse();
					}
					curve = (Arc)entity;
				}
			}
			else
			{
				if (entity.EntityData != null && entity.EntityData is CustomData && ((CustomData)entity.EntityData).sortDirection == entitySortDirection.Reverse)
				{
					((ICurve)entity).Reverse();
				}
				curve = (Line)entity;
			}
			if (curve != null)
			{
				list.Add(curve);
			}
		}
		if (list.Count > 0)
		{
			calcCompositeCurve = new CompositeCurve(list);
		}
	}

	public void CreateCompositeCurveFromEntitiesWithCamDirection(List<buEntity> refEntities, ref buCompositeCurve calcCompositeCurve)
	{
		List<buEntity> list = new List<buEntity>();
		for (int i = 0; i <= refEntities.Count - 1; i++)
		{
			buEntity buEntity2 = CopyEntities(refEntities[i]);
			if (!(refEntities[i] is buLine))
			{
				if (!(refEntities[i] is buArc))
				{
					if (!(refEntities[i] is buCircle))
					{
						if (!(refEntities[i] is buCurve))
						{
							if (!(refEntities[i] is buEllipse))
							{
								if (refEntities[i] is buLinearPath)
								{
									buLinearPath buLinearPath2 = refEntities[i] as buLinearPath;
									if (buEntity2.sortDirection != entitySortDirection.Reverse)
									{
										list.Add(buEntity2);
										continue;
									}
									List<Point3D> copiedPoint = new List<Point3D>();
									Copy(buLinearPath2.Vertices, ref copiedPoint);
									copiedPoint.Reverse();
									buEntity2 = new buLinearPath(copiedPoint);
									buEntity.CopyProperties(buLinearPath2, ref buEntity2);
									list.Add(buEntity2);
								}
							}
							else
							{
								list.Add(buEntity2);
							}
							continue;
						}
						buCurve buCurve2 = refEntities[i] as buCurve;
						if (buEntity2.sortDirection != entitySortDirection.Reverse)
						{
							list.Add(buEntity2);
							continue;
						}
						if (buCurve2.isRational)
						{
							Point4D[] array = new Point4D[buCurve2.ControlPoints.Count];
							double[] array2 = new double[buCurve2.KnotVector.Count];
							int num = 0;
							for (int num2 = buCurve2.ControlPoints.Count - 1; num2 >= 0; num2--)
							{
								array[num] = new Point4D(buCurve2.ControlPoints[num2].X, buCurve2.ControlPoints[num2].Y, buCurve2.ControlPoints[num2].Z, buCurve2.ControlPoints[num2].W);
								num++;
							}
							num = 0;
							for (int num3 = buCurve2.KnotVector.Count - 1; num3 >= 0; num3--)
							{
								array2[num] = buCurve2.KnotVector[num3];
								num++;
							}
							buEntity2 = new buCurve(buCurve2.Degree, array2, array);
						}
						else
						{
							List<Point3D> list2 = new List<Point3D>();
							for (int j = 0; j <= buCurve2.ControlPoints.Count - 1; j++)
							{
								list2.Add(new Point3D(buCurve2.ControlPoints[j].X, buCurve2.ControlPoints[j].Y, buCurve2.ControlPoints[j].Z));
							}
							list2.Reverse();
							buEntity2 = new buCurve(buCurve2.Degree, list2);
						}
						buEntity.CopyProperties(buCurve2, ref buEntity2);
						list.Add(buEntity2);
					}
					else
					{
						list.Add(buEntity2);
					}
				}
				else
				{
					buArc buArc2 = refEntities[i] as buArc;
					if (buEntity2.sortDirection != entitySortDirection.Reverse)
					{
						list.Add(buEntity2);
						continue;
					}
					Plane arcPlane = new Plane(buArc2.Plane.Origin, new Vector3D(0.0 - buArc2.Plane.Equation.X, 0.0 - buArc2.Plane.Equation.Y, 0.0 - buArc2.Plane.Equation.Z));
					buEntity2 = new buArc(arcPlane, buArc2.Center, buArc2.Radius, buArc2.EndPoint, buArc2.StartPoint, flip: false);
					buEntity.CopyProperties(buArc2, ref buEntity2);
					list.Add(buEntity2);
				}
			}
			else
			{
				buLine buLine2 = refEntities[i] as buLine;
				if (buEntity2.sortDirection != entitySortDirection.Reverse)
				{
					list.Add(buEntity2);
					continue;
				}
				buEntity2 = new buLine(buLine2.EndPoint, buLine2.StartPoint);
				buEntity.CopyProperties(buLine2, ref buEntity2);
				list.Add(buEntity2);
			}
		}
		if (list.Count > 0)
		{
			calcCompositeCurve = new buCompositeCurve(list);
		}
	}

	public void RegenEntities(double RegenDeviation, ref List<Entity> refEntities)
	{
		for (int i = 0; i <= refEntities.Count - 1; i++)
		{
			Entity refEntity = refEntities[i];
			RegenEntity(RegenDeviation, ref refEntity);
		}
	}

	public void RegenEntity(double RegenDeviation, ref Entity refEntity)
	{
		if (!(refEntity is ICurve))
		{
			if (!(refEntity is Mesh))
			{
				if (refEntity is Text)
				{
					refEntity.Regen(new RegenParams(RegenDeviation, baseModel));
				}
			}
			else
			{
				refEntity.Regen(new RegenParams(RegenDeviation));
			}
		}
		else
		{
			refEntity.Regen(new RegenParams(RegenDeviation));
		}
	}

	public void DirectionArrowFromEntities(Entity refEntity, DirectionArrowSetting Setting, ref List<buLinearPathArrow> DirArrows)
	{
		if (!(refEntity is ICurve))
		{
			return;
		}
		ICurve curve = refEntity as ICurve;
		if (refEntity.Vertices == null)
		{
			return;
		}
		if (refEntity.Vertices.Length != 2)
		{
			if (!(Setting.MinLength > 0.0))
			{
				if (Setting.ArrowPointCount > 0)
				{
					List<Point3D> Points = new List<Point3D>();
					List<Point3D> PrePoints = new List<Point3D>();
					GetPointsEntityFromCount(refEntity, Setting.ArrowPointCount, ref PrePoints, ref Points);
					for (int i = 0; i <= Points.Count - 1; i++)
					{
						DirectionArrow directionArrow = new DirectionArrow();
						directionArrow.Length = Setting.ArrowLength;
						directionArrow.PointAngle = Setting.ArrowAngle;
						directionArrow.PrePoint = buConversion5.Point3DToPnt3D(PrePoints[i]);
						directionArrow.Point = buConversion5.Point3DToPnt3D(Points[i]);
						geoTriangle BasePointArrow = new geoTriangle();
						geoTriangle RefPointArrow = new geoTriangle();
						List<Pnt3D> FirstArrorVertices = new List<Pnt3D>();
						List<Pnt3D> SecondArrorVertices = new List<Pnt3D>();
						buCall.buVector_0.DimensionAlignedWith2Point(directionArrow.Point, directionArrow.PrePoint, directionArrow.PointAngle, directionArrow.Length, new WorkPlane(), ReverseAngle: false, ref BasePointArrow, ref RefPointArrow, ref FirstArrorVertices, ref SecondArrorVertices);
						buLinearPathArrow item = new buLinearPathArrow(buConversion5.Pnt3dToPoint3D(FirstArrorVertices));
						DirArrows.Add(item);
					}
				}
				return;
			}
			int count = Convert.ToInt32(Math.Floor(curve.Length() / Setting.MinLength));
			List<Point3D> Points2 = new List<Point3D>();
			List<Point3D> PrePoints2 = new List<Point3D>();
			GetPointsEntityFromCount(refEntity, count, ref PrePoints2, ref Points2);
			if (((CustomData)refEntity.EntityData).sortDirection == entitySortDirection.Reverse)
			{
				PrePoints2.Reverse();
				Points2.Reverse();
			}
			for (int j = 0; j <= Points2.Count - 1; j++)
			{
				DirectionArrow directionArrow2 = new DirectionArrow();
				directionArrow2.Length = Setting.ArrowLength;
				directionArrow2.PointAngle = Setting.ArrowAngle;
				directionArrow2.PrePoint = buConversion5.Point3DToPnt3D(PrePoints2[j]);
				directionArrow2.Point = buConversion5.Point3DToPnt3D(Points2[j]);
				geoTriangle BasePointArrow2 = new geoTriangle();
				geoTriangle RefPointArrow2 = new geoTriangle();
				List<Pnt3D> FirstArrorVertices2 = new List<Pnt3D>();
				List<Pnt3D> SecondArrorVertices2 = new List<Pnt3D>();
				buCall.buVector_0.DimensionAlignedWith2Point(directionArrow2.Point, directionArrow2.PrePoint, directionArrow2.PointAngle, directionArrow2.Length, new WorkPlane(), ReverseAngle: false, ref BasePointArrow2, ref RefPointArrow2, ref FirstArrorVertices2, ref SecondArrorVertices2);
				buLinearPathArrow item2 = new buLinearPathArrow(buConversion5.Pnt3dToPoint3D(FirstArrorVertices2));
				DirArrows.Add(item2);
			}
		}
		else
		{
			DirectionArrow directionArrow3 = new DirectionArrow();
			directionArrow3.Length = Setting.ArrowLength;
			directionArrow3.PointAngle = Setting.ArrowAngle;
			directionArrow3.PrePoint = buConversion5.Point3DToPnt3D(refEntity.Vertices[0]);
			directionArrow3.Point = buConversion5.Point3DToPnt3D(Point3D.MidPoint(refEntity.Vertices[0], refEntity.Vertices[1]));
			geoTriangle BasePointArrow3 = new geoTriangle();
			geoTriangle RefPointArrow3 = new geoTriangle();
			List<Pnt3D> FirstArrorVertices3 = new List<Pnt3D>();
			List<Pnt3D> SecondArrorVertices3 = new List<Pnt3D>();
			buCall.buVector_0.DimensionAlignedWith2Point(directionArrow3.Point, directionArrow3.PrePoint, directionArrow3.PointAngle, directionArrow3.Length, new WorkPlane(), ReverseAngle: false, ref BasePointArrow3, ref RefPointArrow3, ref FirstArrorVertices3, ref SecondArrorVertices3);
			buLinearPathArrow item3 = new buLinearPathArrow(buConversion5.Pnt3dToPoint3D(FirstArrorVertices3));
			DirArrows.Add(item3);
		}
	}

	public void DirectionWireArrowHeadFromEntities(buEntity refEntity, Plane refPlane, double ArrowHeadLenght, double ArrowHeadAngle, ref buEntity arrowEntity)
	{
		if (refEntity is ICurve)
		{
			Entity copiedEntity = null;
			buEntity.Copy(refEntity, ref copiedEntity);
			ICurve curve = copiedEntity as ICurve;
			Point3D point3D = curve.PointAt(curve.Domain.Mid);
			Point3D basePoint = curve.PointAt(curve.Domain.Mid + 0.1);
			List<Point3D> list = new List<Point3D>();
			list.Clear();
			list = new List<Point3D>();
			double num = PointAngle(point3D, basePoint, refPlane);
			Point3D EndPnt = new Point3D();
			Point3D EndPnt2 = new Point3D();
			LineWithLengthAndAngle(point3D, ArrowHeadLenght, num + ArrowHeadAngle, refPlane, ref EndPnt);
			LineWithLengthAndAngle(point3D, ArrowHeadLenght, num - ArrowHeadAngle, refPlane, ref EndPnt2);
			list.Add(EndPnt);
			list.Add(point3D);
			list.Add(EndPnt2);
			arrowEntity = new buLinearPath(list);
		}
	}

	public void DirectionWireArrowHeadFromEntities(buEntity refEntity, Plane refPlane, double ArrowHeadLenght, double ArrowHeadAngle, ref List<Entity> arrowEntities)
	{
		Entity copiedEntity = null;
		if (!(refEntity is buLinearPath))
		{
			buEntity.Copy(refEntity, ref copiedEntity);
			ICurve curve = copiedEntity as ICurve;
			Point3D point3D = curve.PointAt(curve.Domain.Mid);
			Point3D basePoint = curve.PointAt(curve.Domain.Mid + 0.1);
			List<Point3D> list = new List<Point3D>();
			list.Clear();
			list = new List<Point3D>();
			double num = PointAngle(point3D, basePoint, refPlane);
			if (refEntity.sortDirection == entitySortDirection.Reverse)
			{
				num += 180.0;
			}
			Point3D EndPnt = new Point3D();
			Point3D EndPnt2 = new Point3D();
			LineWithLengthAndAngle(point3D, ArrowHeadLenght, num + ArrowHeadAngle, refPlane, ref EndPnt);
			LineWithLengthAndAngle(point3D, ArrowHeadLenght, num - ArrowHeadAngle, refPlane, ref EndPnt2);
			list.Add(EndPnt);
			list.Add(point3D);
			list.Add(EndPnt2);
			LinearPath item = new LinearPath(list);
			arrowEntities.Add(item);
		}
		else if (refEntity.sortDirection != entitySortDirection.Normal)
		{
			for (int num2 = refEntity.Vertices.Count - 2; num2 >= 0; num2--)
			{
				buLine refEntity2 = new buLine(refEntity.Vertices[num2 + 1], refEntity.Vertices[num2]);
				List<Entity> arrowEntities2 = new List<Entity>();
				DirectionWireArrowHeadFromEntities(refEntity2, refPlane, ArrowHeadLenght, ArrowHeadAngle, ref arrowEntities2);
				arrowEntities.AddRange(arrowEntities2);
			}
		}
		else
		{
			for (int i = 1; i <= refEntity.Vertices.Count - 1; i++)
			{
				buLine refEntity3 = new buLine(refEntity.Vertices[i - 1], refEntity.Vertices[i]);
				List<Entity> arrowEntities3 = new List<Entity>();
				DirectionWireArrowHeadFromEntities(refEntity3, refPlane, ArrowHeadLenght, ArrowHeadAngle, ref arrowEntities3);
				arrowEntities.AddRange(arrowEntities3);
			}
		}
	}

	public void GetArrowPointAndAngleFromEntities(Entity refEntity, ref Point3D arrowPoint, ref double Angle)
	{
		if (!(refEntity is ICurve))
		{
			return;
		}
		ICurve curve = refEntity as ICurve;
		if (refEntity.Vertices != null)
		{
			if (refEntity.Vertices.Length != 2)
			{
				arrowPoint = curve.PointAt(curve.Domain.Mid);
				Point3D basePoint = curve.PointAt(curve.Domain.Mid - 0.05);
				Angle = PointAngle(arrowPoint, basePoint);
			}
			else
			{
				arrowPoint = MiddlePointOfLine(refEntity.Vertices[0], refEntity.Vertices[1]);
				Angle = PointAngle(refEntity.Vertices[1], refEntity.Vertices[0]);
			}
		}
	}

	public void GetArrowPointAndAngleFromEntities(buEntity refEntity, bool Reverse, ref Point3D arrowPoint, ref double Angle)
	{
		if (refEntity.Vertices == null)
		{
			return;
		}
		if (refEntity.Vertices.Count != 2)
		{
			double num = 1.0;
			if (Reverse)
			{
				num = -1.0;
			}
			ClockDirectionType clockDirection = GetClockDirection(refEntity.Vertices);
			double num2 = 0.0;
			int num3 = refEntity.Vertices.Count / 2;
			if (num3 <= 0)
			{
				arrowPoint = MiddlePointOfLine(refEntity.Vertices[0], refEntity.Vertices[1]);
				Angle = PointAngle(refEntity.Vertices[1], refEntity.Vertices[0]) + num2;
				return;
			}
			arrowPoint = ToPoint3D(refEntity.Vertices[num3]);
			Angle = PointAngle(refEntity.Vertices[num3], refEntity.Vertices[num3 - 1]);
			if (clockDirection != ClockDirectionType.CW)
			{
				num2 = -10.0;
				if (refEntity is buArc || refEntity is buCircle || refEntity is buEllipse)
				{
					double num4 = PointAngle(refEntity.Vertices[num3 - 1], refEntity.Vertices[num3 - 2]) + num2;
					double num5 = Angle - num4;
					num2 = (0.0 - Math.Abs(num5 * num5)) / 10.0;
				}
			}
			else
			{
				num2 = 10.0;
				if (refEntity is buArc || refEntity is buCircle || refEntity is buEllipse)
				{
					double num6 = PointAngle(refEntity.Vertices[num3 - 1], refEntity.Vertices[num3 - 2]) + num2;
					double value = Angle - num6;
					num2 = Math.Abs(value) * 1.2;
				}
			}
			Angle += num * num2;
		}
		else
		{
			arrowPoint = MiddlePointOfLine(refEntity.Vertices[0], refEntity.Vertices[1]);
			Angle = PointAngle(refEntity.Vertices[1], refEntity.Vertices[0]);
		}
	}

	public void AngleOfTwoEntities(buEntity FirstEntity, buEntity SecondEntity, ref double Angle, Plane refPlane, double CompareLevel = 0.01)
	{
		Entity copiedEntity = null;
		Entity copiedEntity2 = null;
		buEntity.Copy(FirstEntity, ref copiedEntity);
		buEntity.Copy(SecondEntity, ref copiedEntity2);
		AngleOfTwoEntities(copiedEntity, copiedEntity2, ref Angle, refPlane, CompareLevel);
	}

	public void AngleOfTwoEntities(Entity FirstEntity, Entity SecondEntity, ref double Angle, Plane refPlane, double CompareLevel = 0.01)
	{
		if (FirstEntity is ICurve && SecondEntity is ICurve)
		{
			ICurve curve = FirstEntity as ICurve;
			ICurve curve2 = SecondEntity as ICurve;
			if (buCompare5.EQ(curve.StartPoint, curve2.StartPoint, CompareLevel))
			{
				Point3D firstLineStart = ToPoint3D(curve.StartPoint);
				Point3D firstLineEnd = curve.PointAt(curve.Domain.t0 + 0.01);
				Point3D secondLineStart = ToPoint3D(curve2.StartPoint);
				Point3D secondLineEnd = curve2.PointAt(curve2.Domain.t0 + 0.01);
				Angle = AngleOfTwoLines(firstLineStart, firstLineEnd, secondLineStart, secondLineEnd, refPlane);
			}
			if (buCompare5.EQ(curve.EndPoint, curve2.StartPoint, CompareLevel))
			{
				Point3D firstLineStart2 = ToPoint3D(curve.EndPoint);
				Point3D firstLineEnd2 = curve.PointAt(curve.Domain.t1 - 0.01);
				Point3D secondLineStart2 = ToPoint3D(curve2.StartPoint);
				Point3D secondLineEnd2 = curve2.PointAt(curve2.Domain.t0 + 0.01);
				Angle = AngleOfTwoLines(firstLineStart2, firstLineEnd2, secondLineStart2, secondLineEnd2, refPlane);
			}
			if (buCompare5.EQ(curve.StartPoint, curve2.EndPoint, CompareLevel))
			{
				Point3D firstLineStart3 = ToPoint3D(curve.StartPoint);
				Point3D firstLineEnd3 = curve.PointAt(curve.Domain.t0 + 0.01);
				Point3D secondLineStart3 = ToPoint3D(curve2.EndPoint);
				Point3D secondLineEnd3 = curve2.PointAt(curve2.Domain.t1 - 0.01);
				Angle = AngleOfTwoLines(firstLineStart3, firstLineEnd3, secondLineStart3, secondLineEnd3, refPlane);
			}
			if (buCompare5.EQ(curve.EndPoint, curve2.EndPoint, CompareLevel))
			{
				Point3D firstLineStart4 = ToPoint3D(curve.EndPoint);
				Point3D firstLineEnd4 = curve.PointAt(curve.Domain.t1 - 0.01);
				Point3D secondLineStart4 = ToPoint3D(curve2.EndPoint);
				Point3D secondLineEnd4 = curve2.PointAt(curve2.Domain.t1 - 0.01);
				Angle = AngleOfTwoLines(firstLineStart4, firstLineEnd4, secondLineStart4, secondLineEnd4, refPlane);
			}
		}
	}

	public void EntitiesLength(List<Entity> RefEntities, ref double Length)
	{
