		for (int i = 0; i <= RefEntities.Count - 1; i++)
		{
			if (RefEntities[i] is ICurve)
			{
				Length += ((ICurve)RefEntities[i]).Length();
			}
		}
	}

	public void EntitiesLength(List<buEntity> RefEntities, ref double Length)
	{
		Length = 0.0;
		for (int i = 0; i <= RefEntities.Count - 1; i++)
		{
			Length += RefEntities[i].Length();
		}
	}

