	public void SetSelectedToSortedEntities(List<Entity> SortedEntities, ref Design Viewport)
	{
		for (int i = 0; i <= SortedEntities.Count - 1; i++)
		{
			if (SortedEntities[i].EntityData != null)
			{
				CustomData customData = SortedEntities[i].EntityData as CustomData;
				if ((customData.OriginalEntityIndex >= 0) & (customData.OriginalEntityIndex <= Viewport.Entities.Count - 1))
				{
					Viewport.Entities[customData.OriginalEntityIndex].Selected = true;
				}
			}
		}
		Viewport.Invalidate();
	}

	public void ArcWithTwoPointAndRadius(Point3D ArcStartPoint, Point3D ArcEndPoint, double Radius, bool CW, Plane refPlane, ref Entity entArc)
	{
