		ArcWithTwoPointAndRadius(ArcStartPoint, ArcEndPoint, Radius, CW, refPlane, ref ArcCenter, ref ArcSA, ref ArcEA);
		entArc = new Arc(refPlane, ArcCenter, Radius, ArcStartPoint, ArcEndPoint, CW);
