	public void ArcWithTwoPointAndRadius(Point3D ArcStartPoint, Point3D ArcEndPoint, double Radius, bool CW, Plane refPlane, ref Point3D ArcCenter, ref double ArcSA, ref double ArcEA)
	{
		try
		{
			double num = 1.0;
			Point3D point3D = new Point3D();
			Point3D point3D2 = new Point3D();
			Point3D point3D3 = new Point3D();
			double num2 = 0.0;
			double num3 = 0.0;
			double num4 = 0.0;
			double num5 = 0.0;
			bool flag = false;
			if (Radius < 0.0)
			{
				flag = true;
			}
			point3D = MiddlePointOfLine(ArcStartPoint, ArcEndPoint);
			Radius = Math.Abs(Radius);
			if (buCompare5.EQ(ArcStartPoint.Y, ArcEndPoint.Y))
			{
				double x = Math.Sqrt(Math.Pow(ArcEndPoint.Y - point3D.Y, 2.0) + Math.Pow(ArcEndPoint.X - point3D.X, 2.0));
				double num6 = Math.Pow(Radius, 2.0) - Math.Pow(x, 2.0);
				if (num6 < 0.0)
				{
					num6 = 0.0;
				}
				double num7 = Math.Sqrt(num6);
				double num8 = num7;
				point3D2.Y = point3D.Y + num8;
				point3D3.Y = point3D.Y - num8;
				point3D2.X = point3D.X;
				point3D3.X = point3D.X;
				point3D2.Z = ArcStartPoint.Z;
				point3D3.Z = ArcStartPoint.Z;
			}
			else
			{
				num = (ArcStartPoint.X - ArcEndPoint.X) / (ArcEndPoint.Y - ArcStartPoint.Y);
				double x = Math.Sqrt(Math.Pow(ArcEndPoint.Y - point3D.Y, 2.0) + Math.Pow(ArcEndPoint.X - point3D.X, 2.0));
				double num7 = Math.Sqrt(Math.Abs(Math.Pow(Radius, 2.0) - Math.Pow(x, 2.0)));
				double num8 = num7 / Math.Sqrt(Math.Pow(num, 2.0) + 1.0);
				point3D2.Y = point3D.Y + num * num8;
				point3D3.Y = point3D.Y - num * num8;
				point3D2.X = point3D.X + num8;
				point3D3.X = point3D.X - num8;
				point3D2.Z = ArcStartPoint.Z;
				point3D3.Z = ArcStartPoint.Z;
			}
			if (CW)
			{
				num3 = PointAngle(ArcStartPoint, point3D2, refPlane);
				num2 = PointAngle(ArcEndPoint, point3D2, refPlane);
				num5 = PointAngle(ArcStartPoint, point3D3, refPlane);
				num4 = PointAngle(ArcEndPoint, point3D3, refPlane);
				if (!flag)
				{
					if (Math.Abs(num3 - num2) <= 180.0 && num3 > num2)
					{
						ArcCenter = ToPoint3D(point3D2);
						ArcSA = num2;
						ArcEA = num3;
						return;
					}
					if (Math.Abs(num5 - num4) <= 180.0 && num5 > num4)
					{
						ArcCenter = ToPoint3D(point3D3);
						ArcSA = num4;
						ArcEA = num5;
						return;
					}
					num3 += 360.0;
					if (Math.Abs(num3 - num2) <= 180.0 && num3 > num2)
					{
						ArcCenter = ToPoint3D(point3D2);
						ArcSA = num2;
						ArcEA = num3;
						return;
					}
					num5 += 360.0;
					if (Math.Abs(num5 - num4) <= 180.0 && num5 > num4)
					{
						ArcCenter = ToPoint3D(point3D3);
						ArcSA = num4;
						ArcEA = num5;
						return;
					}
				}
				if (flag)
				{
					if (Math.Abs(num3 - num2) > 180.0 && num3 > num2)
					{
						ArcCenter = ToPoint3D(point3D2);
						ArcSA = num2;
						ArcEA = num3;
						return;
					}
					if (Math.Abs(num5 - num4) > 180.0 && num5 > num4)
					{
						ArcCenter = ToPoint3D(point3D3);
						ArcSA = num4;
						ArcEA = num5;
						return;
					}
					num3 += 360.0;
					if (Math.Abs(num3 - num2) > 180.0 && num3 > num2)
					{
						ArcCenter = ToPoint3D(point3D2);
						ArcSA = num2;
						ArcEA = num3;
						return;
					}
					num5 += 360.0;
					if (Math.Abs(num5 - num4) > 180.0 && num5 > num4)
					{
						ArcCenter = ToPoint3D(point3D3);
						ArcSA = num4;
						ArcEA = num5;
						return;
					}
				}
			}
			if (CW)
			{
				return;
			}
			num2 = PointAngle(ArcStartPoint, point3D2, refPlane);
			num3 = PointAngle(ArcEndPoint, point3D2, refPlane);
			num4 = PointAngle(ArcStartPoint, point3D3, refPlane);
			num5 = PointAngle(ArcEndPoint, point3D3, refPlane);
			if (buCompare5.EQ(num2, 360.0, 0.001))
			{
				num2 = 0.0;
			}
			if (buCompare5.EQ(num4, 360.0, 0.001))
			{
				num4 = 0.0;
			}
			if (!flag)
			{
				Math.Abs(num3 - num2);
				if (Math.Abs(num3 - num2) <= 180.0 && num3 > num2)
				{
					ArcCenter = ToPoint3D(point3D2);
					ArcSA = num2;
					ArcEA = num3;
					return;
				}
				if (Math.Abs(num5 - num4) <= 180.0 && num5 > num4)
				{
					ArcCenter = ToPoint3D(point3D3);
					ArcSA = num4;
					ArcEA = num5;
					return;
				}
				num3 += 360.0;
				if (Math.Abs(num3 - num2) <= 180.0 && num3 > num2)
				{
					ArcCenter = ToPoint3D(point3D2);
					ArcSA = num2;
					ArcEA = num3;
					return;
				}
				num5 += 360.0;
				if (Math.Abs(num5 - num4) <= 180.0 && num5 > num4)
				{
					ArcCenter = ToPoint3D(point3D3);
					ArcSA = num4;
					ArcEA = num5;
					return;
				}
			}
			if (!flag)
			{
				return;
			}
			if (!(Math.Abs(num3 - num2) > 180.0) || !(num3 > num2))
			{
				if (!(Math.Abs(num5 - num4) > 180.0) || !(num5 > num4))
				{
					num3 += 360.0;
					if (!(Math.Abs(num3 - num2) > 180.0) || !(num3 > num2))
					{
						num5 += 360.0;
						if (Math.Abs(num5 - num4) > 180.0 && num5 > num4)
						{
							ArcCenter = ToPoint3D(point3D3);
							ArcSA = num4;
							ArcEA = num5;
						}
					}
					else
					{
						ArcCenter = ToPoint3D(point3D2);
						ArcSA = num2;
						ArcEA = num3;
					}
				}
				else
				{
					ArcCenter = ToPoint3D(point3D3);
					ArcSA = num4;
					ArcEA = num5;
				}
			}
			else
			{
				ArcCenter = ToPoint3D(point3D2);
				ArcSA = num2;
				ArcEA = num3;
			}
		}
		catch (Exception mSException)
		{
			string text = "ArcStartPoint: " + ArcStartPoint.ToString() + " - ArcEndPoint: " + ArcEndPoint.ToString() + " - Radius: " + Radius + " - CW: " + CW;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void ArcWithIJK(Point3D PreviousPoint, Point3D NextPoint, double I, double J, double K, int ArcDir, ref Point3D ArcCenter, ref double Radius, ref double StartAngle, ref double EndAngle)
	{
		ArcCenter = new Point3D();
		double num = 0.0;
		double num2 = 0.0;
		bool flag = false;
		ArcCenter.X = PreviousPoint.X + I;
		ArcCenter.Y = PreviousPoint.Y + J;
		ArcCenter.Z = PreviousPoint.Z + K;
		if (ArcDir == 2)
		{
			num = PointAngle(PreviousPoint, ArcCenter);
			num2 = PointAngle(NextPoint, ArcCenter);
			if (!flag)
			{
				if ((num2 > 180.0) & buCompare5.EQ(num, 0.0, 0.01))
				{
					num = 360.0;
				}
				if ((num < 180.0) & buCompare5.EQ(num2, 0.0, 0.01))
				{
					num2 = 0.0;
				}
			}
			if (num2 > num)
			{
				num = 360.0 + num;
			}
		}
		if (ArcDir == 3)
		{
			num = PointAngle(PreviousPoint, ArcCenter);
			num2 = PointAngle(NextPoint, ArcCenter);
			if (!flag)
			{
				if ((num > 180.0) & buCompare5.EQ(num2, 0.0, 0.01))
				{
					num2 = 360.0;
				}
				if ((num2 < 180.0) & buCompare5.EQ(num, 0.0, 0.01))
				{
					num = 0.0;
				}
			}
			if (num > num2)
			{
				num2 = 360.0 + num2;
			}
		}
		if (!(num > num2))
		{
			StartAngle = num;
			EndAngle = num2;
		}
		else
		{
			StartAngle = num2;
			EndAngle = num;
		}
		if (StartAngle > EndAngle)
		{
			EndAngle = 360.0 + EndAngle;
		}
		Radius = Length3D(PreviousPoint, ArcCenter);
	}

	public void BSplineQuadraticUniform(List<Point3D> controlPoints, double dt, bool Closed, ref List<Point3D> calculatedPoints)
	{
		try
		{
			List<Pnt3D> CopiedPnt = new List<Pnt3D>();
			List<Pnt3D> list = new List<Pnt3D>();
			List<Pnt3D> list2 = new List<Pnt3D>();
			List<Pnt3D> CalculatedPoints = new List<Pnt3D>();
			List<Pnt3D> list3 = new List<Pnt3D>();
			Pnt3D pnt3D = new Pnt3D();
			Pnt3D pnt3D2 = new Pnt3D();
			buConversion5.Point3DToPnt3D(controlPoints, ref CopiedPnt);
			int num = 0;
			double num2 = 0.0;
			double num3 = 0.0;
			double num4 = 0.0;
			double num5 = 1.0;
			double num6 = 1.0;
			double num7 = -2.0;
			double num8 = 1.0;
			double num9 = -2.0;
			double num10 = 2.0;
			double num11 = 0.0;
			double num12 = 1.0;
			double num13 = 1.0;
			double num14 = 0.0;
			double num15 = 0.0;
			double num16 = 0.0;
			double num17 = 0.0;
			double num18 = 0.0;
			double num19 = 0.0;
			double num20 = 0.0;
			double num21 = 0.0;
			double num22 = 0.0;
			double num23 = 0.0;
			if (dt <= 0.0)
			{
				dt = 0.1;
			}
			list.Clear();
			num = Convert.ToInt32(1.0 / dt);
			if (!Closed)
			{
				for (int i = 0; i <= CopiedPnt.Count - 1; i++)
				{
					list3.Add(new Pnt3D(CopiedPnt[i]));
				}
				if (list3.Count <= 1)
				{
					return;
				}
				if (list3.Count == 2)
				{
					pnt3D = new Pnt3D();
					pnt3D = buCall.buVector_0.MiddlePointOfLine(list3[0], list3[1]);
					list3.Insert(1, new Pnt3D(pnt3D));
				}
			}
			else
			{
				pnt3D = new Pnt3D(CopiedPnt[0]);
				pnt3D2 = new Pnt3D(CopiedPnt[CopiedPnt.Count - 1]);
				for (int j = 0; j <= CopiedPnt.Count - 1; j++)
				{
					list3.Add(new Pnt3D(CopiedPnt[j]));
				}
				list3.Insert(0, new Pnt3D(pnt3D2));
				list3.Add(new Pnt3D(pnt3D));
			}
			for (int k = 1; k <= list3.Count - 2; k++)
			{
