			double num6 = 0.0;
			if (CopiedPnt.Count <= 1)
			{
				return;
			}
			if (dt <= 0.0)
			{
				dt = 0.1;
			}
			dt /= (double)CopiedPnt.Count;
			list.Clear();
			num = Convert.ToInt32(1.0 / dt);
			num2 = CopiedPnt.Count - 1;
			for (int i = 0; i <= num; i++)
			{
				pnt3D = new Pnt3D();
				num6 = (double)i * dt;
				num3 = 0.0;
				num4 = 0.0;
				num5 = 0.0;
				for (int j = 0; j <= CopiedPnt.Count - 1; j++)
				{
					buVector.BezeirBlend(num2, j, num6);
					num3 += CopiedPnt[j].X * buVector.BezeirBlend(num2, j, num6);
					num4 += CopiedPnt[j].Y * buVector.BezeirBlend(num2, j, num6);
					num5 += CopiedPnt[j].Z * buVector.BezeirBlend(num2, j, num6);
				}
				pnt3D.X = num3;
				pnt3D.Y = num4;
				pnt3D.Z = num5;
				list.Add(pnt3D);
			}
			double num7 = (controlPoints[controlPoints.Count - 1].A - controlPoints[0].A) / (double)(list.Count - 1);
			double num8 = (controlPoints[controlPoints.Count - 1].B - controlPoints[0].B) / (double)(list.Count - 1);
			double num9 = (controlPoints[controlPoints.Count - 1].C - controlPoints[0].C) / (double)(list.Count - 1);
			_ = (controlPoints[controlPoints.Count - 1].U - controlPoints[0].U) / (double)(list.Count - 1);
			_ = (controlPoints[controlPoints.Count - 1].V - controlPoints[0].V) / (double)(list.Count - 1);
			_ = (controlPoints[controlPoints.Count - 1].W - controlPoints[0].W) / (double)(list.Count - 1);
			double num10 = controlPoints[0].A;
			double num11 = controlPoints[0].B;
			double num12 = controlPoints[0].C;
			calculatedPoints.Clear();
			for (int k = 0; k <= list.Count - 1; k++)
			{
				Pnt9D item = new Pnt9D(list[k].X, list[k].Y, list[k].Z, num10, num11, num12);
				calculatedPoints.Add(item);
				num10 += num7;
				num11 += num8;
				num12 += num9;
			}
		}
		catch (Exception mSException)
		{
			string text = "ControlPoints: " + CopiedPnt.Count + " - dt: " + dt;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void BSplineAtSharpCorner(List<Point3D> refPoints, double dt, double SharpAngle, bool isQuadratic, ref List<Point3D> calculatedPoints)
	{
		if (calculatedPoints == null)
		{
			calculatedPoints = new List<Point3D>();
		}
		calculatedPoints.Clear();
		if (refPoints.Count <= 1)
		{
			return;
		}
		calculatedPoints.Add(ToPoint3D(refPoints[0]));
		List<Point3D> list = new List<Point3D>();
		for (int i = 1; i < refPoints.Count - 1; i++)
		{
			double num = AngleOfTwoLines(refPoints[i - 1], refPoints[i], refPoints[i], refPoints[i + 1], Plane.XY);
			double num2 = Math.Abs(180.0 - num);
			if (!(num2 > SharpAngle))
			{
				if (list.Count > 0)
				{
					List<Point3D> calculatedPoints2 = new List<Point3D>();
					if (!isQuadratic)
					{
						BezeirCurve(list, 0.1, ref calculatedPoints2);
					}
					else
					{
						BSplineQuadraticUniform(list, 0.1, Closed: false, ref calculatedPoints2);
					}
					calculatedPoints2.RemoveAt(0);
					calculatedPoints2.RemoveAt(calculatedPoints2.Count - 1);
					calculatedPoints.AddRange(calculatedPoints2);
					list.Clear();
					list = new List<Point3D>();
				}
				calculatedPoints.Add(ToPoint3D(refPoints[i]));
			}
			else if (list.Count != 0)
			{
				list.Add(ToPoint3D(refPoints[i + 1]));
			}
			else
			{
				list.Add(ToPoint3D(refPoints[i - 1]));
				list.Add(ToPoint3D(refPoints[i]));
				list.Add(ToPoint3D(refPoints[i + 1]));
			}
		}
		calculatedPoints.Add(ToPoint3D(refPoints[refPoints.Count - 1]));
		CheckDuplicatedPointsWithPrevious(ref calculatedPoints);
	}

	public void MiddleTextPoint(Point3D P0, Point3D P1, double Distance, ref Point3D refPoint, ClockDirectionType Clock = ClockDirectionType.CCW)
	{
		double num = PointAngle(P1, P0);
		Point3D centerPnt = MiddlePointOfLine(P0, P1);
		if (Clock != ClockDirectionType.CCW)
		{
			LineWithLengthAndAngle(centerPnt, Distance, num + 90.0, ref refPoint);
		}
		else
		{
			LineWithLengthAndAngle(centerPnt, Distance, num - 90.0, ref refPoint);
		}
	}

	public void AlignedDimCalculate(Point3D pntStart, Point3D pntEnd, Point3D pntLine, double dimtextH, Plane currentPlane, ref Plane drawingPlane)
	{
		try
		{
			if (!(pntEnd.X >= pntStart.X) || pntEnd.Y < pntStart.Y)
			{
				Point3D first = pntStart;
				Point3D second = pntEnd;
				Utility.Swap(ref first, ref second);
				pntStart = first;
				pntEnd = second;
			}
			Vector3D vector3D = new Vector3D(pntStart, pntEnd);
			Vector3D y = Vector3D.Cross(currentPlane.AxisZ, vector3D);
			drawingPlane = new Plane(pntStart, vector3D, y);
			Vector2D u = new Vector2D(pntStart, pntEnd);
			Vector2D v = new Vector2D(pntStart, pntLine);
			double num = Math.Sign(Vector2D.SignedAngleBetween(u, v));
			Segment2D seg = new Segment2D(pntStart, pntEnd);
			double num2 = pntLine.DistanceTo(seg);
			_ = pntStart + num * drawingPlane.AxisY * (num2 + dimtextH / 2.0);
			_ = pntEnd + num * drawingPlane.AxisY * (num2 + dimtextH / 2.0);
			_ = pntStart + num * drawingPlane.AxisY * num2;
			_ = pntEnd + num * drawingPlane.AxisY * num2;
		}
		catch (Exception)
		{
		}
	}

	public void LinearDimCalculate(Point3D pntStart, Point3D pntEnd, Point3D pntLine, double dimtextH, Plane currentPlane, ref Plane drawingPlane)
	{
		Vector3D vector3D;
		Point3D point3D;
		Point3D point3D2;
		if ((pntLine.X <= pntStart.X || pntLine.X <= pntEnd.X) && (pntLine.X >= pntStart.X || !(pntLine.X < pntEnd.X)))
		{
			vector3D = currentPlane.AxisX;
			point3D = new Point3D(pntStart.X, pntLine.Y);
			point3D2 = new Point3D(pntEnd.X, pntLine.Y);
			if (pntLine.Y <= pntStart.Y || !(pntLine.Y > pntEnd.Y))
			{
				point3D.Y -= dimtextH / 2.0;
				point3D2.Y -= dimtextH / 2.0;
			}
			else
			{
				point3D.Y += dimtextH / 2.0;
				point3D2.Y += dimtextH / 2.0;
			}
		}
		else
		{
			vector3D = currentPlane.AxisY;
			point3D = new Point3D(pntLine.X, pntStart.Y);
			point3D2 = new Point3D(pntLine.X, pntEnd.Y);
			if (pntLine.X <= pntStart.X || !(pntLine.X > pntEnd.X))
			{
				point3D.X -= dimtextH / 2.0;
				point3D2.X -= dimtextH / 2.0;
			}
			else
			{
				point3D.X += dimtextH / 2.0;
				point3D2.X += dimtextH / 2.0;
			}
		}
		Vector3D y = Vector3D.Cross(currentPlane.AxisZ, vector3D);
		Segment3D seg = new Segment3D(pntStart, point3D);
		Segment3D seg2 = new Segment3D(pntEnd, point3D2);
		pntLine.ProjectTo(seg);
		pntLine.ProjectTo(seg2);
		drawingPlane = new Plane(pntStart, vector3D, y);
	}

	public BlockKeyedCollection CopyEyeBlockToEyeBlock(BlockKeyedCollection ExistingBlocks, BlockKeyedCollection BaseBlocks)
	{
		BlockKeyedCollection blockKeyedCollection = new BlockKeyedCollection();
		for (int i = 0; i <= BaseBlocks.Count - 1; i++)
		{
			bool flag = true;
			for (int j = 0; j <= ExistingBlocks.Count - 1; j++)
			{
				if (BaseBlocks[i].Name == ExistingBlocks[j].Name)
				{
					flag = false;
				}
			}
			if (flag)
			{
				Block block = new Block(BaseBlocks[i].Name);
				block = (Block)BaseBlocks[i].Clone();
				blockKeyedCollection.Add(block);
			}
		}
		return blockKeyedCollection;
	}

