	public static Entity CopyEntities(Entity refEnt, bool CheckDuplicated = false, double Resolution = 0.001)
	{
		if (refEnt == null)
		{
			return null;
		}
		Entity Entity;
		if (!(refEnt.GetType() == typeof(buUpperLineEnt)))
		{
			Entity = (Entity)refEnt.Clone();
			if (CheckDuplicated && Entity is LinearPath)
			{
				buEntity.FixVerticeDublicated(ref Entity, Resolution);
			}
			if (refEnt.EntityData == null)
			{
				Entity.EntityData = new CustomData();
			}
			else if (refEnt.EntityData is CustomData)
			{
				Entity.EntityData = new CustomData((CustomData)refEnt.EntityData);
			}
			if (Entity.Vertices == null)
			{
				if (!(refEnt is Text))
				{
					if (!(refEnt is BlockReference))
					{
						Entity.Regen(new RegenParams(buSystem.RegenDeviation, baseModel));
					}
				}
				else
				{
					Entity.Regen(new RegenParams(buSystem.RegenDeviation, baseModel));
				}
			}
		}
		else
		{
			Entity = new buUpperLineEnt(((buUpperLineEnt)refEnt).StartPoint, ((buUpperLineEnt)refEnt).EndPoint);
			if (refEnt.EntityData == null)
			{
				Entity.EntityData = new CustomData();
			}
			else if (refEnt.EntityData is CustomData)
			{
				Entity.EntityData = new CustomData((CustomData)refEnt.EntityData);
			}
		}
		return Entity;
	}

