	public void GetEdgesOfBrep(Brep refEntity, Brep.Edge refEdge, int SelectedIndex, ref List<Entity> Curves, ref List<int> EdgeIndex)
	{
		EdgeIndex.Clear();
		ICurve curve = refEntity.Edges[SelectedIndex].Curve;
		Curves.Add((Entity)curve);
		int num = refEdge.StartPointIndex;
		EdgeIndex.Add(SelectedIndex);
		for (int i = 0; i <= refEntity.Edges.Length - 1; i++)
		{
			for (int j = 0; j <= refEntity.Edges.Length - 1; j++)
			{
				if (j == SelectedIndex)
				{
					continue;
				}
				if (num != refEntity.Edges[j].StartPointIndex)
				{
					if (num != refEntity.Edges[j].EndPointIndex)
					{
						continue;
					}
					ICurve curve2 = refEntity.Edges[j].Curve;
					if (!buCompare5.EQ(((Entity)curve).BoxMin.Z, ((Entity)curve2).BoxMin.Z, buSystem.resolutionSorting))
					{
						continue;
					}
					bool flag = true;
					if (EdgeIndex.Count > 0)
					{
						for (int k = 0; k <= EdgeIndex.Count - 1; k++)
						{
							if (j == EdgeIndex[k])
							{
								flag = false;
								k = EdgeIndex.Count;
							}
						}
					}
					if (flag)
					{
						Curves.Add((Entity)curve2);
						num = refEntity.Edges[j].StartPointIndex;
						EdgeIndex.Add(j);
					}
					continue;
				}
				ICurve curve3 = refEntity.Edges[j].Curve;
				if (!buCompare5.EQ(((Entity)curve).BoxMin.Z, ((Entity)curve3).BoxMin.Z, buSystem.resolutionSorting))
				{
					continue;
				}
				bool flag2 = true;
				if (EdgeIndex.Count > 0)
				{
					for (int l = 0; l <= EdgeIndex.Count - 1; l++)
					{
						if (j == EdgeIndex[l])
						{
							flag2 = false;
							l = EdgeIndex.Count;
						}
					}
				}
				if (flag2)
				{
					Curves.Add((Entity)curve3);
					num = refEntity.Edges[j].EndPointIndex;
					EdgeIndex.Add(j);
				}
			}
		}
	}

