	public void GetOsnapPoints(List<Entity> Entities, OsnapProps OsnapProperties, ref List<OsnapPoint> OsnapPoints)
	{
		OsnapPoints.Clear();
		for (int i = 0; i <= Entities.Count - 1; i++)
		{
			if (Entities[i] == null)
			{
				continue;
			}
			if (!(Entities[i] is devDept.Eyeshot.Entities.Point))
			{
				if (!(Entities[i] is Line))
				{
					if (!(Entities[i] is LinearPath))
					{
						if (!(Entities[i] is CompositeCurve))
						{
							if (!(Entities[i] is Arc))
							{
								if (!(Entities[i] is Circle))
								{
									if (!(Entities[i] is Curve))
									{
										if (!(Entities[i] is EllipticalArc) && !(Entities[i] is Ellipse) && !(Entities[i] is Mesh) && Entities[i] is Brep && OsnapProperties.OsnapPoint)
										{
											Brep brep = (Brep)Entities[i];
											for (int j = 0; j <= brep.Vertices.Length - 1; j++)
											{
												Point3D point3D = brep.Vertices[j];
												OsnapPoints.Add(new OsnapPoint(point3D, osnapType.Point));
											}
										}
										continue;
									}
									Curve curve = (Curve)Entities[i];
									if (OsnapProperties.OsnapPoint)
									{
										OsnapPoints.Add(new OsnapPoint(curve.StartPoint, osnapType.Point));
										OsnapPoints.Add(new OsnapPoint(curve.EndPoint, osnapType.Point));
									}
									if (OsnapProperties.OsnapMiddle)
									{
										OsnapPoints.Add(new OsnapPoint(curve.PointAt(0.5), osnapType.Middle));
									}
									continue;
								}
								Circle circle = (Circle)Entities[i];
								if (OsnapProperties.OsnapPoint)
								{
									OsnapPoints.Add(new OsnapPoint(circle.EndPoint, osnapType.Point));
								}
								if (OsnapProperties.OsnapMiddle)
								{
									OsnapPoints.Add(new OsnapPoint(circle.PointAt(circle.Domain.Mid), osnapType.Middle));
								}
								if (OsnapProperties.OsnapCenter)
								{
									OsnapPoints.Add(new OsnapPoint(circle.Center, osnapType.Center));
								}
								if (OsnapProperties.OsnapOutside)
								{
									if (!isPlaneXZorZX(circle.Plane))
									{
										if (!isPlaneYZorZY(circle.Plane))
										{
											Point3D point3D2 = new Point3D(circle.Center.X + circle.Radius, circle.Center.Y);
											OsnapPoints.Add(new OsnapPoint(point3D2, osnapType.Outer));
											point3D2 = new Point3D(circle.Center.X, circle.Center.Y + circle.Radius);
											OsnapPoints.Add(new OsnapPoint(point3D2, osnapType.Outer));
											point3D2 = new Point3D(circle.Center.X - circle.Radius, circle.Center.Y);
											OsnapPoints.Add(new OsnapPoint(point3D2, osnapType.Outer));
											point3D2 = new Point3D(circle.Center.X, circle.Center.Y - circle.Radius);
											OsnapPoints.Add(new OsnapPoint(point3D2, osnapType.Outer));
										}
										else
										{
											Point3D point3D3 = new Point3D(circle.Center.Y + circle.Radius, circle.Center.Z);
											OsnapPoints.Add(new OsnapPoint(point3D3, osnapType.Outer));
											point3D3 = new Point3D(circle.Center.Y, circle.Center.Z + circle.Radius);
											OsnapPoints.Add(new OsnapPoint(point3D3, osnapType.Outer));
											point3D3 = new Point3D(circle.Center.Y - circle.Radius, circle.Center.Z);
											OsnapPoints.Add(new OsnapPoint(point3D3, osnapType.Outer));
											point3D3 = new Point3D(circle.Center.Y, circle.Center.Z - circle.Radius);
											OsnapPoints.Add(new OsnapPoint(point3D3, osnapType.Outer));
										}
									}
									else
									{
										Point3D point3D4 = new Point3D(circle.Center.X + circle.Radius, circle.Center.Z);
										OsnapPoints.Add(new OsnapPoint(point3D4, osnapType.Outer));
										point3D4 = new Point3D(circle.Center.X, circle.Center.Z + circle.Radius);
										OsnapPoints.Add(new OsnapPoint(point3D4, osnapType.Outer));
										point3D4 = new Point3D(circle.Center.X - circle.Radius, circle.Center.Z);
										OsnapPoints.Add(new OsnapPoint(point3D4, osnapType.Outer));
										point3D4 = new Point3D(circle.Center.X, circle.Center.Z - circle.Radius);
										OsnapPoints.Add(new OsnapPoint(point3D4, osnapType.Outer));
									}
								}
								if (!OsnapProperties.OsnapIntersection)
								{
								}
							}
							else
							{
								Arc arc = (Arc)Entities[i];
								if (OsnapProperties.OsnapPoint)
								{
									OsnapPoints.Add(new OsnapPoint(arc.StartPoint, osnapType.Point));
									OsnapPoints.Add(new OsnapPoint(arc.EndPoint, osnapType.Point));
								}
								if (OsnapProperties.OsnapMiddle)
								{
									OsnapPoints.Add(new OsnapPoint(arc.MidPoint, osnapType.Middle));
								}
								if (OsnapProperties.OsnapCenter)
								{
									OsnapPoints.Add(new OsnapPoint(arc.Center, osnapType.Center));
								}
								if (!OsnapProperties.OsnapIntersection)
								{
								}
							}
							continue;
						}
						CompositeCurve compositeCurve = (CompositeCurve)Entities[i];
						if (OsnapProperties.OsnapPoint)
						{
							foreach (ICurve curve2 in compositeCurve.CurveList)
							{
								OsnapPoints.Add(new OsnapPoint(curve2.EndPoint, osnapType.Point));
								OsnapPoints.Add(new OsnapPoint(compositeCurve.CurveList[0].StartPoint, osnapType.Point));
							}
						}
						if (OsnapProperties.OsnapMiddle)
						{
							OsnapPoints.Add(new OsnapPoint(compositeCurve.PointAt(0.5), osnapType.Middle));
						}
						continue;
					}
					LinearPath linearPath = (LinearPath)Entities[i];
					if (OsnapProperties.OsnapPoint)
					{
						for (int k = 0; k <= linearPath.Vertices.Length - 1; k++)
						{
							OsnapPoints.Add(new OsnapPoint(linearPath.Vertices[k], osnapType.Point));
						}
					}
					if (OsnapProperties.OsnapMiddle)
					{
						for (int l = 1; l <= linearPath.Vertices.Length - 1; l++)
						{
							OsnapPoints.Add(new OsnapPoint(Point3D.MidPoint(linearPath.Vertices[l - 1], linearPath.Vertices[l]), osnapType.Middle));
						}
					}
					if (!OsnapProperties.OsnapIntersection)
					{
					}
				}
				else
				{
					Line line = (Line)Entities[i];
					if (OsnapProperties.OsnapPoint)
					{
						OsnapPoints.Add(new OsnapPoint(line.StartPoint, osnapType.Point));
						OsnapPoints.Add(new OsnapPoint(line.EndPoint, osnapType.Point));
					}
					if (OsnapProperties.OsnapMiddle)
					{
						OsnapPoints.Add(new OsnapPoint(line.MidPoint, osnapType.Middle));
					}
					if (!OsnapProperties.OsnapIntersection)
					{
					}
				}
			}
			else if (OsnapProperties.OsnapPoint)
			{
				devDept.Eyeshot.Entities.Point point = (devDept.Eyeshot.Entities.Point)Entities[i];
				Point3D point3D5 = point.Vertices[0];
				OsnapPoints.Add(new OsnapPoint(point3D5, osnapType.Point));
			}
		}
	}

	public bool GetPointOnEntity(Point3D refPoint, object Entity, ref Point3D overPoint)
	{
		try
		{
			if (!(Entity.GetType() == typeof(Line)))
			{
				if (!(Entity.GetType() == typeof(LinearPath)))
				{
					if (!(Entity.GetType() == typeof(Circle)))
					{
						if (!(Entity.GetType() == typeof(Arc)))
						{
							if (!(Entity.GetType() == typeof(Ellipse)))
							{
								if (!(Entity.GetType() == typeof(EllipticalArc)))
								{
									if (!(Entity.GetType() == typeof(CompositeCurve)))
									{
										if (!(Entity.GetType() == typeof(Curve)))
										{
											return false;
										}
										double t = 0.0;
										((Curve)Entity).ClosestPointTo(refPoint, out t);
										overPoint = ((Curve)Entity).PointAt(t);
										return true;
									}
									double t2 = 0.0;
									((CompositeCurve)Entity).ClosestPointTo(refPoint, out t2);
									overPoint = ((CompositeCurve)Entity).PointAt(t2);
									return true;
								}
								double t3 = 0.0;
								((EllipticalArc)Entity).ClosestPointTo(refPoint, out t3);
								overPoint = ((EllipticalArc)Entity).PointAt(t3);
								return true;
							}
							double t4 = 0.0;
							((Ellipse)Entity).ClosestPointTo(refPoint, out t4);
							overPoint = ((Ellipse)Entity).PointAt(t4);
							return true;
						}
						double t5 = 0.0;
						((Arc)Entity).ClosestPointTo(refPoint, out t5);
						overPoint = ((Arc)Entity).PointAt(t5);
						return true;
					}
					double t6 = 0.0;
					((Circle)Entity).ClosestPointTo(refPoint, out t6);
					overPoint = ((Circle)Entity).PointAt(t6);
					return true;
				}
				double t7 = 0.0;
				((LinearPath)Entity).ClosestPointTo(refPoint, out t7);
				overPoint = ((LinearPath)Entity).PointAt(t7);
				return true;
			}
			double t8 = 0.0;
			((Line)Entity).ClosestPointTo(refPoint, out t8);
			overPoint = ((Line)Entity).PointAt(t8);
			return true;
		}
		catch (Exception)
		{
			return false;
		}
	}

