	public void GetAvailableGroupIndex(EntityList Entities, List<int> AlreadyUsedGroupIndex, ref int GroupIndex)
	{
		List<int> UsedGroupList = new List<int>();
		GetAvailableGroupIndex(Entities, AlreadyUsedGroupIndex, ref GroupIndex, ref UsedGroupList);
	}

	public void GetAvailableGroupIndex(EntityList Entities, List<int> AlreadyUsedGroupIndex, ref int GroupIndex, ref List<int> UsedGroupList)
	{
		try
		{
			UsedGroupList = new List<int>();
			for (int i = 0; i <= AlreadyUsedGroupIndex.Count - 1; i++)
			{
				UsedGroupList.Add(AlreadyUsedGroupIndex[i]);
			}
			for (int j = 0; j <= Entities.Count - 1; j++)
			{
				int groupIdIndex = GetGroupIdIndex(Entities[j]);
				if (groupIdIndex <= 0)
				{
					continue;
				}
				if (UsedGroupList.Count != 0)
				{
					bool flag = false;
					for (int k = 0; k <= UsedGroupList.Count - 1; k++)
					{
						if (groupIdIndex == UsedGroupList[k])
						{
							flag = true;
						}
					}
					if (!flag)
					{
						UsedGroupList.Add(groupIdIndex);
					}
				}
				else
				{
					UsedGroupList.Add(groupIdIndex);
				}
			}
			if (UsedGroupList.Count == 0)
			{
				GroupIndex = 1;
			}
			if (UsedGroupList.Count == 1)
			{
				GroupIndex = UsedGroupList[0] + 1;
			}
			if (UsedGroupList.Count <= 1)
			{
				return;
			}
			SortList(SortDirectionType.Lower, ref UsedGroupList);
			bool flag2 = false;
			for (int l = 1; l <= UsedGroupList.Count - 1; l++)
			{
				int num = UsedGroupList[l] - UsedGroupList[l - 1];
				if (num >= 2)
				{
					GroupIndex = UsedGroupList[l - 1] + 1;
					flag2 = true;
				}
			}
			if (!flag2)
			{
				GroupIndex = UsedGroupList[UsedGroupList.Count - 1] + 1;
			}
		}
		catch (Exception mSException)
		{
			string text = "Entities: " + Entities.Count;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void GetBoxSizeOFViewport(Design Viewport, Plane refPlane, ref Pnt3D MinPoint, ref Pnt3D MaxPoint)
	{
		try
		{
			Point3D point3D = new Point3D();
			Point3D point3D2 = new Point3D();
			point3D = buConversion5.Screen2DTo3D(Viewport, refPlane, new System.Drawing.Point(0, Viewport.Height));
			point3D2 = buConversion5.Screen2DTo3D(Viewport, refPlane, new System.Drawing.Point(Viewport.Width, 0));
			MinPoint.X = point3D.X;
			MinPoint.Y = point3D.Y;
			MinPoint.Z = point3D.Z;
			MaxPoint.X = point3D2.X;
			MaxPoint.Y = point3D2.Y;
			MaxPoint.Z = point3D2.Z;
			if (MinPoint.X > MaxPoint.X)
			{
				buFunctions.ExchangeDatas(ref MinPoint.X, ref MaxPoint.X);
			}
			if (MinPoint.Y > MaxPoint.Y)
			{
				buFunctions.ExchangeDatas(ref MinPoint.Y, ref MaxPoint.Y);
			}
			if (MinPoint.Z > MaxPoint.Z)
			{
				buFunctions.ExchangeDatas(ref MinPoint.Z, ref MaxPoint.Z);
			}
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, "");
		}
	}

	public Plane GetPlane(Point3D first, Point3D next)
	{
		Vector3D vector3D = new Vector3D(first, next);
		vector3D.Normalize();
		Vector3D vector3D2 = Vector3D.Cross(Vector3D.AxisX, vector3D);
		vector3D2.Normalize();
		return new Plane(first, vector3D, vector3D2);
	}

	public void GetClosestPointsOfTwoEntity(Entity FirstEntity, Entity SecondEntity, ref Point3D FirstFoundPoints, ref Point3D SecondFoundPoints)
	{
		double num = double.MaxValue;
		FirstFoundPoints = new Point3D();
		SecondFoundPoints = new Point3D();
		if (!((FirstEntity.Vertices != null) & (SecondEntity.Vertices != null)))
		{
			return;
		}
		for (int i = 0; i <= FirstEntity.Vertices.Length - 1; i++)
		{
			for (int j = 0; j <= SecondEntity.Vertices.Length - 1; j++)
			{
				double num2 = Point3D.Distance(FirstEntity.Vertices[i], SecondEntity.Vertices[j]);
				if (num2 < num)
				{
					FirstFoundPoints = ToPoint3D(FirstEntity.Vertices[i]);
					SecondFoundPoints = ToPoint3D(SecondEntity.Vertices[j]);
					num = num2;
				}
			}
		}
	}

	public void GetLongestPointsOfTwoEntity(Entity FirstEntity, Entity SecondEntity, ref Point3D FirstFoundPoints, ref Point3D SecondFoundPoints)
	{
		double num = double.MinValue;
		FirstFoundPoints = new Point3D();
		SecondFoundPoints = new Point3D();
		if (!((FirstEntity.Vertices != null) & (SecondEntity.Vertices != null)))
		{
			return;
		}
		for (int i = 0; i <= FirstEntity.Vertices.Length - 1; i++)
		{
			for (int j = 0; j <= SecondEntity.Vertices.Length - 1; j++)
			{
				double num2 = Point3D.Distance(FirstEntity.Vertices[i], SecondEntity.Vertices[j]);
				if ((num2 > num) & (Math.Abs(num2 - num) > 0.001))
				{
					FirstFoundPoints = ToPoint3D(FirstEntity.Vertices[i]);
					SecondFoundPoints = ToPoint3D(SecondEntity.Vertices[j]);
					num = num2;
				}
			}
		}
	}

	public void GetInformationBetweenTwoPoints(Point3D FirstPoint, Point3D SecondPoint, ref DistanceData Distance)
	{
		Distance.Length = Point3D.Distance(FirstPoint, SecondPoint);
		Distance.dX = SecondPoint.X - FirstPoint.X;
		Distance.dY = SecondPoint.Y - FirstPoint.Y;
		Distance.dZ = SecondPoint.Z - FirstPoint.Z;
	}

	public void GetPointsEntityFromCount(Entity refEntity, int Count, List<Point3D> Points)
	{
		List<Point3D> PrePoints = new List<Point3D>();
		GetPointsEntityFromCount(refEntity, Count, ref PrePoints, ref Points);
	}

	public void GetPointsEntityFromCount(Entity refEntity, int Count, ref List<Point3D> PrePoints, ref List<Point3D> Points)
	{
		if (!(refEntity is ICurve))
		{
			Points = new List<Point3D>();
			return;
		}
		ICurve curve = refEntity as ICurve;
		if (Count <= 0)
		{
			Points = new List<Point3D>();
			return;
		}
		double num = curve.Length() / Convert.ToDouble(Count);
		for (int i = 1; i <= Count - 1; i++)
		{
			Points.Add(curve.PointAt(num * (double)i));
			PrePoints.Add(curve.PointAt(num * (double)i - 0.05));
		}
	}

	public bool GetOtherPointOfEntity(Point3D RefPoint, Entity RefEntity, ref Point3D OtherPoint)
	{
		try
		{
			if (RefEntity is ICurve)
			{
				if (((ICurve)RefEntity).StartPoint == RefPoint)
				{
					OtherPoint = ToPoint3D(((ICurve)RefEntity).EndPoint);
					return true;
				}
				if (((ICurve)RefEntity).EndPoint == RefPoint)
				{
					OtherPoint = ToPoint3D(((ICurve)RefEntity).StartPoint);
					return true;
				}
			}
			return false;
		}
		catch (Exception mSException)
		{
			string text = "RefPoint: " + RefPoint.ToString() + " - RefEntity: " + RefEntity.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return false;
		}
	}

	public bool GetOtherPointOfEntity(Point3D RefPoint, buEntity RefEntity, ref Point3D OtherPoint)
	{
		try
		{
			if (RefEntity != null)
			{
				if (RefEntity.StartPoint == RefPoint)
				{
					OtherPoint = ToPoint3D(RefEntity.EndPoint);
					return true;
				}
				if (RefEntity.EndPoint == RefPoint)
				{
					OtherPoint = ToPoint3D(RefEntity.StartPoint);
					return true;
				}
			}
			return false;
		}
		catch (Exception mSException)
		{
			string text = "RefPoint: " + RefPoint.ToString() + " - RefEntity: " + RefEntity.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return false;
		}
	}

	public void SetCamDirection(Point3D RefPoint, ref Entity RefEntity)
	{
		try
		{
			if (RefEntity is ICurve)
			{
				if (((ICurve)RefEntity).StartPoint == RefPoint && RefEntity.EntityData != null && RefEntity.EntityData.GetType() == typeof(CustomData))
				{
					((CustomData)RefEntity.EntityData).sortDirection = entitySortDirection.Normal;
				}
				if (((ICurve)RefEntity).EndPoint == RefPoint && RefEntity.EntityData != null && RefEntity.EntityData.GetType() == typeof(CustomData))
				{
					((CustomData)RefEntity.EntityData).sortDirection = entitySortDirection.Reverse;
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "RefPoint: " + RefPoint.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void SetCamDirection(Point3D RefPoint, ref buEntity RefEntity)
	{
		try
		{
			if (RefEntity != null)
			{
				if (RefEntity.StartPoint == RefPoint)
				{
					RefEntity.sortDirection = entitySortDirection.Normal;
				}
				if (RefEntity.EndPoint == RefPoint)
				{
					RefEntity.sortDirection = entitySortDirection.Reverse;
