	public void Draw(ICurve theCurve, ref List<Point3D> refPoints)
	{
		if (!(theCurve is CompositeCurve))
		{
			DrawToVertices(theCurve, ref refPoints);
			return;
		}
		CompositeCurve compositeCurve = theCurve as CompositeCurve;
		Entity[] array = compositeCurve.Explode();
		Entity[] array2 = array;
		foreach (Entity entity in array2)
		{
			List<Point3D> refPoints2 = new List<Point3D>();
			DrawToVertices((ICurve)entity, ref refPoints2);
			if (((refPoints.Count > 0) & (refPoints2.Count > 0)) && refPoints[refPoints.Count - 1] == refPoints2[0])
			{
				refPoints2.RemoveAt(0);
			}
			refPoints.AddRange(refPoints2);
		}
	}

	public void DrawToVertices(ICurve curve, ref List<Point3D> refPoints)
	{
		refPoints.Clear();
		if (!(curve is Line))
		{
			if (!(curve is LinearPath))
			{
				if (!(curve is devDept.Eyeshot.Entities.Point))
				{
					for (int i = 0; i <= 100; i++)
					{
						refPoints.Add(curve.PointAt(curve.Domain.ParameterAt((double)i / 100.0)));
					}
				}
				else
				{
					refPoints.Add(ToPoint3D(((devDept.Eyeshot.Entities.Point)curve).Vertices[0]));
				}
			}
			else
			{
				for (int j = 0; j <= ((LinearPath)curve).Vertices.Length - 1; j++)
				{
					refPoints.Add(ToPoint3D(((LinearPath)curve).Vertices[j]));
				}
			}
		}
		else
		{
			for (int k = 0; k <= ((Line)curve).Vertices.Length - 1; k++)
			{
				refPoints.Add(ToPoint3D(((Line)curve).Vertices[k]));
			}
		}
	}

	public void DrawEntitiesToImage(int Width, int Height, List<Entity> EntityList, Color BackgroundColor, ref Image image)
	{
		Design design = new Design();
		design.InitializeViewports();
		design.CreateControl();
		design.Width = Width;
		design.Height = Height;
		design.Viewports[0].Grid.Visible = false;
		design.Viewports[0].OriginSymbol.Visible = false;
		design.Viewports[0].CoordinateSystemIcon.Visible = false;
		BackgroundSettings background = new BackgroundSettings(backgroundStyleType.LinearGradient, BackgroundColor, BackgroundColor, BackgroundColor, 0.75, null, colorThemeType.Auto, 0.3);
		design.Viewports[0].Background = background;
		for (int i = 0; i <= EntityList.Count - 1; i++)
		{
			design.Entities.Add(EntityList[i]);
		}
		design.SetView(viewType.Top);
		design.ZoomFit();
		design.Invalidate();
		design.CopyToClipboardRaster(new Size(Width, Height), drawBackground: true);
		Image image2 = Clipboard.GetImage();
		image = image2;
	}

	public void DrawLineAsRectangle(Point3D FirstPoint, Point3D SecondPoints, double Width, Plane refPlane, ref List<Point3D> calcPoints)
	{
		try
		{
			calcPoints.Clear();
			Point3D EndPnt = new Point3D();
			Point3D EndPnt2 = new Point3D();
			Point3D EndPnt3 = new Point3D();
			Point3D EndPnt4 = new Point3D();
			double num = PointAngle(SecondPoints, FirstPoint, refPlane);
			LineWithLengthAndAngle(FirstPoint, Width / 2.0, num + 90.0, ref EndPnt);
			LineWithLengthAndAngle(FirstPoint, Width / 2.0, num - 90.0, ref EndPnt2);
			LineWithLengthAndAngle(SecondPoints, Width / 2.0, num - 90.0, ref EndPnt3);
			LineWithLengthAndAngle(SecondPoints, Width / 2.0, num + 90.0, ref EndPnt4);
			calcPoints.Add(EndPnt);
			calcPoints.Add(EndPnt2);
			calcPoints.Add(EndPnt3);
			calcPoints.Add(EndPnt4);
			calcPoints.Add(EndPnt);
		}
		catch (Exception mSException)
		{
			string text = "DrawLineAsRectangle";
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void CreateEntitiesGroupFromEntities(List<buEntity> OutsideEntities, List<List<buEntity>> InsideEntities, List<List<buEntity>> OpenEntities, ref buEntitiesGroup EntGroup)
	{
		try
		{
			EntGroup = null;
			EntGroup = new buEntitiesGroup();
			if (OutsideEntities != null && OutsideEntities.Count > 0)
			{
				buEntity.Copy(OutsideEntities, ref EntGroup.Outside.Entities);
				EntGroup.Outside.Points = new List<Point3D>();
				EntitiesToPointsWithCamDirection(EntGroup.Outside.Entities, ref EntGroup.Outside.Points);
				if (EntGroup.Outside.Points.Count > 0)
				{
					EntGroup.Outside.pntMassCenter = CalculateCentroid(EntGroup.Outside.Points);
				}
			}
			if (InsideEntities != null && InsideEntities.Count > 0)
			{
				for (int i = 0; i <= InsideEntities.Count - 1; i++)
				{
					if (InsideEntities[i].Count <= 0)
					{
						continue;
					}
					buEntityList buEntityList2 = new buEntityList();
					buEntity.Copy(InsideEntities[i], ref buEntityList2.Entities);
					buEntityList2.Points = new List<Point3D>();
					EntitiesToPointsWithCamDirection(buEntityList2.Entities, ref buEntityList2.Points);
					if (buEntityList2.Points.Count > 0)
					{
						buEntityList2.pntMassCenter = CalculateCentroid(buEntityList2.Points);
					}
					if (buEntityList2.Entities.Count > 0)
					{
						if (EntGroup.Inside == null)
						{
							EntGroup.Inside = new List<buEntityList>();
						}
						EntGroup.Inside.Add(buEntityList2);
					}
				}
			}
			if (OpenEntities == null || OpenEntities.Count <= 0)
			{
				return;
			}
			for (int j = 0; j <= OpenEntities.Count - 1; j++)
			{
				if (OpenEntities[j].Count <= 0)
				{
					continue;
				}
				buEntityList buEntityList3 = new buEntityList();
				buEntity.Copy(OpenEntities[j], ref buEntityList3.Entities);
				buEntityList3.Points = new List<Point3D>();
				EntitiesToPointsWithCamDirection(buEntityList3.Entities, ref buEntityList3.Points);
				if (buEntityList3.Points.Count > 0)
				{
					buEntityList3.pntMassCenter = CalculateCentroid(buEntityList3.Points);
				}
				if (buEntityList3.Entities.Count > 0)
				{
					if (EntGroup.OpenEntities == null)
					{
						EntGroup.OpenEntities = new List<buEntityList>();
					}
					EntGroup.OpenEntities.Add(buEntityList3);
				}
			}
		}
		catch (Exception)
		{
		}
	}

	public void CurvePoints(List<Point3D> refPoints, double LimitMinAngle, double LimitMaxAngle, ref List<Point3D> filletedPoints)
	{
		List<Point3D> list = new List<Point3D>();
		filletedPoints.Add(ToPoint3D(refPoints[0]));
		list.Add(ToPoint3D(refPoints[0]));
		for (int i = 1; i <= refPoints.Count - 1; i++)
		{
			if (i > refPoints.Count - 2)
			{
				list.Add(ToPoint3D(refPoints[i]));
				continue;
			}
			Line line = new Line(refPoints[i - 1], refPoints[i]);
			Line line2 = new Line(refPoints[i], refPoints[i + 1]);
			double num = AngleOfTwoLines(line.StartPoint, line.EndPoint, line2.StartPoint, line2.EndPoint, Plane.XY);
			if (!(num < LimitMaxAngle && num > LimitMinAngle))
			{
				filletedPoints.Add(ToPoint3D(refPoints[i]));
			}
			else
			{
				list.Add(ToPoint3D(refPoints[i]));
			}
		}
		if (list.Count > 0)
		{
			Curve curve = new Curve(2, list);
			curve.Regen(0.1);
			filletedPoints.Clear();
			filletedPoints.AddRange(curve.Vertices);
		}
	}

	public void FilletPoints(List<Point3D> refPoints, double FilletRadius, double LimitMinAngle, double LimitMaxAngle, ref List<Point3D> filletedPoints)
	{
		filletedPoints.Add(ToPoint3D(refPoints[0]));
		for (int i = 1; i <= refPoints.Count - 2; i++)
		{
			Line line = new Line(refPoints[i - 1], refPoints[i]);
			Line line2 = new Line(refPoints[i], refPoints[i + 1]);
			Arc fillet = null;
			line.Length();
			line2.Length();
			double num = AngleOfTwoLines(line.StartPoint, line.EndPoint, line2.StartPoint, line2.EndPoint, Plane.XY);
			bool flag = Curve.Fillet(line, line2, FilletRadius, flip1: false, flip2: false, trim1: true, trim2: true, out fillet);
			if (!(fillet != null && flag && num < LimitMaxAngle && num > LimitMinAngle))
			{
				filletedPoints.Add(ToPoint3D(refPoints[i]));
				continue;
			}
			fillet.Regen(0.001);
			if (fillet.Vertices.Length <= 4)
			{
				fillet.Regen(0.0001);
			}
			if (fillet.Vertices.Length <= 2)
			{
				filletedPoints.Add(ToPoint3D(refPoints[i]));
				continue;
			}
			for (int j = 0; j <= fillet.Vertices.Length - 1; j++)
			{
				filletedPoints.Add(ToPoint3D(fillet.Vertices[j]));
			}
		}
		filletedPoints.Add(ToPoint3D(refPoints[refPoints.Count - 1]));
	}

	public void getPointAtEntitiesBetweenStartPointAndLength(Point3D pntStart, double Length, double Resolution, List<Entity> baseEntities, ref Point3D calcPoint)
	{
		Point3D point3D = ToPoint3D(pntStart);
		double num = 0.0;
		bool flag = false;
		for (int i = 0; i <= baseEntities.Count - 1; i++)
		{
			ICurve curve = (ICurve)baseEntities[i];
			curve.ClosestPointTo(point3D, out var t);
			if (!(isPointInsideEntity(curve, point3D, Resolution) & (t >= curve.Domain.t0) & (t <= curve.Domain.t1)))
			{
				if (flag)
				{
					num += curve.Length();
				}
				continue;
			}
			flag = true;
			double num2 = curve.Domain.t1 - curve.Domain.t0;
			double num3 = curve.Length();
			double num4 = num2 / num3;
			double num5 = Length - num;
			Point3D point3D2 = new Point3D();
			ICurve sub = null;
			double num6;
			if (((CustomData)baseEntities[i].EntityData).sortDirection != entitySortDirection.Normal)
			{
				num6 = t - num5 * num4;
				if (num6 < curve.Domain.t0)
				{
					num6 = curve.Domain.t0;
				}
				if (t - num6 > 0.001)
				{
					new Point3D();
					curve.SubCurve(num6, t, out sub);
					double num7 = sub.Length();
					point3D2 = ToPoint3D(curve.PointAt(num6));
					point3D = ToPoint3D(point3D2);
					double num8 = (t - num6) / num4;
					if (buCompare5.EQ(num8 + num, Length, Resolution) || num8 + num > Length)
					{
						calcPoint = ToPoint3D(point3D);
						break;
					}
					num += num7;
				}
				continue;
			}
			num6 = t + num5 * num4;
			if (num6 > curve.Domain.t1)
			{
				num6 = curve.Domain.t1;
			}
			if (num6 - t > Resolution)
			{
				new Point3D();
				curve.SubCurve(t, num6, out sub);
				double num9 = sub.Length();
				point3D2 = ToPoint3D(curve.PointAt(num6));
				point3D = ToPoint3D(point3D2);
				double num10 = (num6 - t) / num4;
				if (buCompare5.EQ(num10 + num, Length, Resolution) || num10 + num > Length)
				{
					calcPoint = ToPoint3D(point3D);
					break;
				}
				num += num9;
			}
		}
	}

	public void CreateBoxOrRectangleFromBoxSize(Point3D pntMin, Point3D pntMax, ref List<List<Point3D>> refPoints)
	{
		double num = pntMax.X - pntMin.X;
		double num2 = pntMax.Y - pntMin.Y;
		double num3 = pntMax.Z - pntMin.Z;
		if (!(!buCompare5.EQ(num, 0.0) & !buCompare5.EQ(num2, 0.0) & !buCompare5.EQ(num3, 0.0)))
		{
			if (!(!buCompare5.EQ(num, 0.0) & !buCompare5.EQ(num2, 0.0) & buCompare5.EQ(num3, 0.0)))
			{
				if (!(!buCompare5.EQ(num, 0.0) & buCompare5.EQ(num2, 0.0) & !buCompare5.EQ(num3, 0.0)))
				{
					if (buCompare5.EQ(num, 0.0) & !buCompare5.EQ(num2, 0.0) & !buCompare5.EQ(num3, 0.0))
					{
						CompositeCurve compositeCurve = CompositeCurve.CreateRectangle(Plane.YZ, num, num3);
						compositeCurve.Regen(0.01);
						compositeCurve.Translate(pntMin.X, pntMin.Y, pntMin.Z);
						List<Point3D> PointList = new List<Point3D>();
						VerticeToPointsList(compositeCurve.Vertices, ref PointList);
						refPoints.Add(PointList);
					}
				}
				else
				{
					CompositeCurve compositeCurve2 = CompositeCurve.CreateRectangle(Plane.XZ, num, num3);
					compositeCurve2.Regen(0.01);
					compositeCurve2.Translate(pntMin.X, pntMin.Y, pntMin.Z);
					List<Point3D> PointList2 = new List<Point3D>();
					VerticeToPointsList(compositeCurve2.Vertices, ref PointList2);
					refPoints.Add(PointList2);
				}
			}
			else
			{
				CompositeCurve compositeCurve3 = CompositeCurve.CreateRectangle(Plane.XY, num, num2);
				compositeCurve3.Regen(0.01);
				compositeCurve3.Translate(pntMin.X, pntMin.Y, pntMin.Z);
				List<Point3D> PointList3 = new List<Point3D>();
				VerticeToPointsList(compositeCurve3.Vertices, ref PointList3);
				refPoints.Add(PointList3);
			}
		}
		else
		{
			Mesh mesh = Mesh.CreateBox(num, num2, num3);
			mesh.Translate(pntMin.X, pntMin.Y, pntMin.Z);
			List<Point3D> PointList4 = new List<Point3D>();
			VerticeToPointsList(mesh.Vertices, ref PointList4);
			refPoints.Add(PointList4);
		}
	}

	public void LineWithLengthAndAngle(Point3D CenterPnt, double Length, double Angle, Plane refPlane, ref Point3D StartPnt, ref Point3D EndPnt)
	{
		LineWithLengthAndAngle(CenterPnt, Length, Angle, refPlane, ref EndPnt);
		StartPnt = ToPoint3D(CenterPnt);
	}

	public static void LineWithLengthAndAngleByPlane(Point3D CenterPnt, double Length, double Angle, Plane refPlane, ref Point3D EndPnt)
	{
		try
		{
			EndPnt = new Point3D();
			refPlane.Project(CenterPnt, out var s, out var t);
			double x = s + Length * Math.Cos(buConversion5.DegreeToRadian(Angle));
			double y = t + Length * Math.Sin(buConversion5.DegreeToRadian(Angle));
			List<Point3D> list = new List<Point3D>();
			list.Add(new Point3D(s, t));
			list.Add(new Point3D(x, y));
			baseModel.MoveToPlane(list, refPlane);
			EndPnt.X = list[1].X;
			EndPnt.Y = list[1].Y;
			EndPnt.Z = list[1].Z;
			if (isPlaneXYorYX(refPlane))
			{
				EndPnt.Z = CenterPnt.Z;
			}
			if (isPlaneXZorZX(refPlane))
			{
				EndPnt.Y = CenterPnt.Y;
			}
			if (isPlaneYZorZY(refPlane))
			{
				EndPnt.X = CenterPnt.X;
			}
		}
		catch (Exception mSException)
		{
			string text = "Center: " + CenterPnt.ToString() + " - Len: " + Length + " - Angle: " + Angle;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

