	public void LengthFromZLengthAndAngle(double ZLength, double Angle, ref double XLength)
	{
		try
		{
			if (Angle % 90.0 != 0.0)
			{
				XLength = ZLength * Math.Tan(buConversion5.DegreeToRadian(Angle));
			}
			else
			{
				XLength = 0.0;
			}
		}
		catch (Exception mSException)
		{
			string text = "ZLength: " + ZLength + " - Angle: " + Angle;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void LineWithOrientationAngle(Point3D BasePoint, OrientationAngle Angles, double Length, ref Point3D calcPoint)
	{
		try
		{
			calcPoint.X = BasePoint.X + Length * Math.Sin(buConversion5.DegreeToRadian(Angles.A)) * Math.Cos(buConversion5.DegreeToRadian(Angles.C + 90.0));
			calcPoint.Y = BasePoint.Y + Length * Math.Sin(buConversion5.DegreeToRadian(Angles.A)) * Math.Sin(buConversion5.DegreeToRadian(Angles.C + 90.0));
			calcPoint.Z = BasePoint.Z + Length * Math.Cos(buConversion5.DegreeToRadian(Angles.A));
		}
		catch (Exception mSException)
		{
			string text = "BasePoint: " + BasePoint.ToString() + " - Angles: " + Angles.ToString() + " - Length: " + Length;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void DiagonalLengthByAnglePerpendicularDistance(Point3D BasePoint, double Angle, double PerpendicularDistance, Plane Plane, ref Point3D CalcPoint)
	{
		try
		{
			if ((Math.Abs(Angle) >= -90.0) & (Math.Abs(Angle) <= 180.0))
			{
				double value = PerpendicularDistance / Math.Cos(buConversion5.DegreeToRadian(Angle));
				if (isPlaneXYorYX(Plane))
				{
					Point3D point3D = ToPoint3D(BasePoint);
					point3D.Y += PerpendicularDistance;
					double num = PointAngle(point3D, BasePoint, Plane);
					CalcPoint = ToPoint3D(BasePoint);
					LineWithLengthAndAngle(BasePoint, Math.Abs(value), num + Angle, Plane, ref CalcPoint);
				}
				if (isPlaneXZorZX(Plane))
				{
					Point3D point3D2 = ToPoint3D(BasePoint);
					point3D2.Z += PerpendicularDistance;
					double num2 = PointAngle(point3D2, BasePoint, Plane);
					CalcPoint = ToPoint3D(BasePoint);
					LineWithLengthAndAngle(BasePoint, Math.Abs(value), num2 + Angle, Plane, ref CalcPoint);
				}
				if (isPlaneYZorZY(Plane))
				{
					Point3D point3D3 = ToPoint3D(BasePoint);
					point3D3.Z += PerpendicularDistance;
					double num3 = PointAngle(point3D3, BasePoint, Plane);
					CalcPoint = ToPoint3D(BasePoint);
					LineWithLengthAndAngle(BasePoint, Math.Abs(value), num3 + Angle, Plane, ref CalcPoint);
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "BasePoint: " + BasePoint.ToString() + " - Angle: " + Angle + " - PerpendicularDistance: " + PerpendicularDistance + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void RectangleWithDxDy(Point3D pntBase, double dX, double dY, Plane refPlane, ref Point3D pntCalc)
	{
		pntCalc = new Point3D();
		Point3D point3D = new Point3D();
		refPlane.Project(pntBase, out var s, out var t);
		point3D.X = s + dX;
		point3D.Y = t + dY;
		List<Point3D> list = new List<Point3D>();
		list.Add(point3D);
		baseModel.MoveToPlane(list, refPlane);
		pntCalc = list[0];
	}

	public bool LineLineIntersection(Point3D FirstLineStart, Point3D FirstLineEnd, Point3D SecondLineStart, Point3D SecondLineEnd, Plane Plane, ref Point3D pntIntersect)
	{
		Point3D EndPnt = new Point3D();
		Point3D EndPnt2 = new Point3D();
		Point3D EndPnt3 = new Point3D();
		Point3D EndPnt4 = new Point3D();
		if (!buCompare5.EQ(FirstLineStart, SecondLineStart))
		{
			if (!buCompare5.EQ(FirstLineStart, SecondLineEnd))
			{
				if (!buCompare5.EQ(FirstLineEnd, SecondLineStart))
				{
					if (!buCompare5.EQ(FirstLineEnd, SecondLineEnd))
					{
						double num = PointAngle(FirstLineStart, FirstLineEnd, Plane);
						double num2 = PointAngle(SecondLineStart, SecondLineEnd, Plane);
						LineWithLengthAndAngle(FirstLineEnd, 1000000.0, num, ref EndPnt);
						LineWithLengthAndAngle(FirstLineStart, 1000000.0, num + 180.0, ref EndPnt2);
						LineWithLengthAndAngle(SecondLineEnd, 1000000.0, num2, ref EndPnt3);
						LineWithLengthAndAngle(SecondLineStart, 1000000.0, num2 + 180.0, ref EndPnt4);
						Line line = new Line(EndPnt, EndPnt2);
						Line c = new Line(EndPnt3, EndPnt4);
						Point3D[] array = line.IntersectWith(c);
						if (array != null)
						{
							if (array.Length != 0)
							{
								pntIntersect = ToPoint3D(array[0]);
								return true;
							}
							return false;
						}
						return false;
					}
					pntIntersect = ToPoint3D(FirstLineEnd);
					return true;
				}
				pntIntersect = ToPoint3D(FirstLineEnd);
				return true;
			}
			pntIntersect = ToPoint3D(FirstLineStart);
			return true;
		}
		pntIntersect = ToPoint3D(FirstLineStart);
		return true;
	}

	public void CreatebuShape(ref buShape Shape, ShapeCreateParameters Pars)
	{
		FindShapeDataValueType(Shape, clsVar5.ShapeTempPar.ValueGridIndex, ref clsVar5.ShapeTempPar.ValueType);
		if (Shape.ShapeGroup == ShapeGroup.Drill)
		{
			CreatebuShapeAsDrill(ref Shape, Pars);
		}
		if (Shape.ShapeGroup == ShapeGroup.Cut)
		{
			CreatebuShapeAsSlot(ref Shape, Pars);
		}
		if (Shape.ShapeGroup == ShapeGroup.Shape)
		{
			CreatebuShapeAsShape(ref Shape, Pars);
		}
		if (Shape.ShapeGroup == ShapeGroup.Profiling)
		{
			CreatebuShapeAsProfiling(ref Shape, Pars);
		}
		if (Shape.ShapeGroup == ShapeGroup.Junction)
		{
			CreatebuShapeAsJunction(ref Shape, Pars);
		}
		if (Shape.ShapeGroup == ShapeGroup.Engraving)
		{
			CreatebuShapeAsEngraving(ref Shape, Pars);
		}
	}

	public void CreatebuShapeAsSlot(ref buShape Shape, ShapeCreateParameters Pars)
	{
		double num = 0.0;
		bool onlyFirstEntity = false;
		bool flag = false;
		Point3D calcPoint = new Point3D();
		camParameters5 camParameters6 = null;
		ToolBase5 toolBase = null;
		camTp camTp2 = null;
		if (Shape.CamPar != null)
		{
			camParameters6 = new camParameters5(Shape.CamPar);
		}
		if (Shape.Tool != null)
		{
			toolBase = new ToolBase5(Shape.Tool);
		}
		if (Shape.Cam != null)
		{
			camTp2 = new camTp(Shape.Cam);
		}
		Shape.entitiesShape.Clear();
		CoordinateFromPlaneAndCorner(Pars.Size, Shape.Corner, Shape.planeName, ref Shape, ref calcPoint, Pars.SingX, Pars.SingY);
		Shape.CalculatedPoint.X = calcPoint.X;
		Shape.CalculatedPoint.Y = calcPoint.Y;
		Shape.CalculatedPoint.Z = calcPoint.Z;
		if (Shape.GetType() == typeof(buShapeCut))
		{
			buShapeCut buShapeCut2 = Shape as buShapeCut;
			if ((buShapeCut2.CutType == CutTypes.CutHorizontal) | (buShapeCut2.CutType == CutTypes.CutHorizontalLine))
			{
				if ((Shape.Corner == CornerLocation.RightBottom) | (Shape.Corner == CornerLocation.RightCenter) | (Shape.Corner == CornerLocation.RightTop))
				{
					Shape.Alignment = ObjectAlignment.MiddleRight;
				}
				if ((Shape.Corner == CornerLocation.LeftBottom) | (Shape.Corner == CornerLocation.LeftCenter) | (Shape.Corner == CornerLocation.LeftTop))
				{
					Shape.Alignment = ObjectAlignment.MiddleLeft;
				}
				if ((Shape.Corner == CornerLocation.BottomCenter) | (Shape.Corner == CornerLocation.TopCenter))
				{
					Shape.Alignment = ObjectAlignment.MiddleCenter;
				}
			}
			if ((buShapeCut2.CutType == CutTypes.CutVertical) | (buShapeCut2.CutType == CutTypes.CutVerticalLine))
			{
				if ((Shape.Corner == CornerLocation.RightBottom) | (Shape.Corner == CornerLocation.LeftBottom) | (Shape.Corner == CornerLocation.BottomCenter))
				{
					Shape.Alignment = ObjectAlignment.BottomCenter;
				}
				if ((Shape.Corner == CornerLocation.TopCenter) | (Shape.Corner == CornerLocation.LeftTop) | (Shape.Corner == CornerLocation.RightTop))
				{
					Shape.Alignment = ObjectAlignment.TopCenter;
				}
				if ((Shape.Corner == CornerLocation.RightCenter) | (Shape.Corner == CornerLocation.LeftCenter))
				{
					Shape.Alignment = ObjectAlignment.MiddleCenter;
				}
			}
			double degree = buShapeCut2.Angle;
			if (buShapeCut2.CutType == CutTypes.CutFree)
			{
				flag = true;
				if ((buShapeCut2.planeName == planeBoxNames.Front) | (buShapeCut2.planeName == planeBoxNames.Back))
				{
					degree = 0.0 - buShapeCut2.Angle;
				}
			}
			if (buShapeCut2.CutType == CutTypes.CutHorizontalLine)
			{
				Shape.CalculatedPoint.X = buShapeCut2.StartDistance;
			}
			calcBuShapeMultiSlots(Pars, ref Shape);
			calcPoint.X = Shape.CalculatedPoint.X;
			calcPoint.Y = Shape.CalculatedPoint.Y;
			calcPoint.Z = Shape.CalculatedPoint.Z;
			if ((buShapeCut2.Diameter > 0.0) & (buShapeCut2.Length > 0.0))
			{
				Shape.entitiesDim = new List<buEntity>();
				num = buShapeCut2.Depth;
				CompositeCurve compositeCurve = null;
				double length = buShapeCut2.Length - buShapeCut2.Diameter;
				if (buShapeCut2.isMilling)
				{
					length = buShapeCut2.Length;
				}
				if ((buShapeCut2.CutType == CutTypes.CutVertical) | (buShapeCut2.CutType == CutTypes.CutVerticalLine))
				{
					buShapeCut2.Angle = 90.0;
				}
				if ((buShapeCut2.CutType == CutTypes.CutHorizontal) | (buShapeCut2.CutType == CutTypes.CutHorizontalLine))
				{
					buShapeCut2.Angle = 0.0;
				}
				if ((buShapeCut2.planeName == planeBoxNames.Top) | (buShapeCut2.planeName == planeBoxNames.Bottom))
				{
					compositeCurve = CompositeCurve.CreateSlot(buShapeCut2.planeOperation, length, buShapeCut2.Diameter / 2.0);
					compositeCurve.Regen(0.01);
					Point3D EndPnt = new Point3D();
					Point3D point3D = new Point3D();
					Point3D EndPnt2 = new Point3D();
					Point3D EndPnt3 = new Point3D();
					Point3D EndPnt4 = new Point3D();
					Point3D EndPnt5 = new Point3D();
					Point3D EndPnt6 = new Point3D(EndPnt.X, EndPnt.Y, 0.0);
					LineWithLengthAndAngle(point3D, buShapeCut2.Length, buShapeCut2.Angle, buShapeCut2.planeOperation, ref EndPnt2);
					LineWithLengthAndAngle(point3D, buShapeCut2.Length / 2.0, buShapeCut2.Angle, buShapeCut2.planeOperation, ref EndPnt);
					double num2 = Point3D.Distance(point3D, EndPnt2);
					double num3 = num2 * 0.05;
					LineWithLengthAndAngle(EndPnt, buShapeCut2.Diameter / 2.0 + num3, buShapeCut2.Angle + 90.0, buShapeCut2.planeOperation, ref EndPnt6);
					buShapeCut2.pntEnd = new Point3D(EndPnt2.X, EndPnt2.Y, EndPnt2.Z);
					LineWithLengthAndAngle(EndPnt, buShapeCut2.Diameter / 2.0, buShapeCut2.Angle + 90.0, buShapeCut2.planeOperation, ref EndPnt3);
					LineWithLengthAndAngle(EndPnt, buShapeCut2.Diameter / 2.0, buShapeCut2.Angle - 90.0, buShapeCut2.planeOperation, ref EndPnt4);
					LineWithLengthAndAngle(EndPnt, buShapeCut2.Diameter / 2.0 + 5.0, buShapeCut2.Angle, buShapeCut2.planeOperation, ref EndPnt5);
					Plane drawingPlane = null;
					AlignedDimCalculate(point3D, EndPnt2, EndPnt6, num3, Shape.planeOperation, ref drawingPlane);
					buLinearDim buLinearDim2 = new buLinearDim(drawingPlane, point3D, EndPnt2, EndPnt6, num3);
					buLinearDim2.Info.Data = ShapeDataValueType.Length.ToString();
					Shape.entitiesDim.Add(buLinearDim2);
					Plane drawingPlane2 = null;
					num2 = Point3D.Distance(EndPnt3, EndPnt4);
					num3 = num2 * 0.05;
					if (num3 < 5.0)
					{
						num3 = 5.0;
					}
					AlignedDimCalculate(EndPnt3, EndPnt4, EndPnt5, num3, Shape.planeOperation, ref drawingPlane2);
					Point3D.Distance(EndPnt3, EndPnt4);
					buLinearDim buLinearDim3 = new buLinearDim(drawingPlane2, EndPnt3, EndPnt4, EndPnt5, num3);
					buLinearDim3.TextOverride = buShapeCut2.Diameter.ToString();
					buLinearDim3.Info.Data = ShapeDataValueType.Width.ToString();
					Shape.entitiesDim.Add(buLinearDim3);
					if ((buShapeCut2.CutType == CutTypes.CutVertical) | (buShapeCut2.CutType == CutTypes.CutVerticalLine))
					{
						compositeCurve.Rotate(buConversion5.DegreeToRadian(90.0), Vector3D.AxisZ, new Point3D());
						buLinearDim2.Rotate(buConversion5.DegreeToRadian(90.0), Vector3D.AxisZ, new Point3D());
						buLinearDim3.Rotate(buConversion5.DegreeToRadian(90.0), Vector3D.AxisZ, new Point3D());
					}
					if (buShapeCut2.CutType == CutTypes.CutFree)
					{
						compositeCurve.Rotate(buConversion5.DegreeToRadian(degree), Vector3D.AxisZ, new Point3D());
						buLinearDim2.Rotate(buConversion5.DegreeToRadian(degree), Vector3D.AxisZ, new Point3D());
						buLinearDim3.Rotate(buConversion5.DegreeToRadian(degree), Vector3D.AxisZ, new Point3D());
					}
				}
				if ((buShapeCut2.planeName == planeBoxNames.Front) | (buShapeCut2.planeName == planeBoxNames.Back))
				{
					compositeCurve = CompositeCurve.CreateSlot(buShapeCut2.planeOperation, length, buShapeCut2.Diameter / 2.0);
					if ((buShapeCut2.CutType == CutTypes.CutVertical) | (buShapeCut2.CutType == CutTypes.CutVerticalLine))
					{
						compositeCurve.Rotate(buConversion5.DegreeToRadian(90.0), Vector3D.AxisY, new Point3D());
					}
					if (buShapeCut2.CutType == CutTypes.CutFree)
					{
						compositeCurve.Rotate(buConversion5.DegreeToRadian(degree), Vector3D.AxisY, new Point3D());
					}
				}
				if ((buShapeCut2.planeName == planeBoxNames.Left) | (buShapeCut2.planeName == planeBoxNames.Right))
				{
					compositeCurve = CompositeCurve.CreateSlot(buShapeCut2.planeOperation, length, buShapeCut2.Diameter / 2.0);
					if ((buShapeCut2.CutType == CutTypes.CutVertical) | (buShapeCut2.CutType == CutTypes.CutVerticalLine))
					{
						compositeCurve.Rotate(buConversion5.DegreeToRadian(90.0), Vector3D.AxisX, new Point3D());
					}
					if (buShapeCut2.CutType == CutTypes.CutFree)
					{
						compositeCurve.Rotate(buConversion5.DegreeToRadian(degree), Vector3D.AxisX, new Point3D());
					}
				}
				if (compositeCurve != null)
				{
					Shape.entitiesShape.Add(buEntity.Copy(compositeCurve));
				}
			}
		}
		if (Shape.entitiesShape.Count > 0)
		{
			Point3D MoveDistance = new Point3D();
			List<buEntity> copiedEntities = null;
			if (!flag)
			{
				CoordinateFromObjectLocation(Shape.Alignment, Shape.planeName, Shape.entitiesShape, ref MoveDistance, onlyFirstEntity);
			}
			if (Shape.multiCenter != null && Shape.multiCenter.Count > 0)
			{
				copiedEntities = new List<buEntity>();
				buEntity.Copy(Shape.entitiesShape, ref copiedEntities);
				Shape.entitiesShape.Clear();
			}
			Move(MoveDistance.X + calcPoint.X, MoveDistance.Y + calcPoint.Y, MoveDistance.Z + calcPoint.Z, ref Shape.entitiesShape);
			if (Shape.entitiesDim != null)
			{
				Move(MoveDistance.X + calcPoint.X, MoveDistance.Y + calcPoint.Y, MoveDistance.Z + calcPoint.Z, ref Shape.entitiesDim);
			}
			if (Shape.entitiesShape.Count <= 0)
			{
				BoxSizeCalculate(copiedEntities, ref Shape.ItemSize.MinBox, ref Shape.ItemSize.MaxBox);
			}
			else
			{
