			}
			for (int j = 0; j <= Shape.entitiesShape.Count - 1; j++)
			{
				if ((j >= 1) & (Shape.DepthLevel.Count >= 2))
				{
					num = Shape.DepthLevel[1];
				}
				List<ICurve> list = new List<ICurve>();
				bool flag2 = true;
				if (!buCompare5.EQ(Shape.entitiesShape[j].StartPoint, Shape.entitiesShape[j].EndPoint, 0.01))
				{
					flag2 = false;
