	public void CreatebuShapeAsEngraving(ref buShape Shape, ShapeCreateParameters Pars)
	{
		Point3D calcPoint = new Point3D();
		camParameters5 camParameters6 = null;
		ToolBase5 toolBase = null;
		camTp camTp2 = null;
		if (Shape.CamPar != null)
		{
			camParameters6 = new camParameters5(Shape.CamPar);
		}
		if (Shape.Tool != null)
		{
			toolBase = new ToolBase5(Shape.Tool);
		}
		if (Shape.Cam != null)
		{
			camTp2 = new camTp(Shape.Cam);
		}
		if (Pars.entitiesEngraving == null || Pars.entitiesEngraving.Count == 0)
		{
			return;
		}
		Shape.entitiesShape.Clear();
		if (Shape.planeName == planeBoxNames.Top)
		{
			Shape.BasePoint.Z = Pars.Size.Depth;
		}
		if (!(Pars.SingY > 0.0))
		{
			if (Shape.planeName == planeBoxNames.Front)
			{
				Shape.BasePoint.Y = 0.0 - Pars.Size.Height;
			}
			if (Shape.planeName == planeBoxNames.Back)
			{
				Shape.BasePoint.Y = 0.0;
			}
		}
		else
		{
			if (Shape.planeName == planeBoxNames.Front)
			{
				Shape.BasePoint.Y = 0.0;
			}
			if (Shape.planeName == planeBoxNames.Back)
			{
				Shape.BasePoint.Y = Pars.Size.Height;
			}
		}
		CoordinateFromPlaneAndCorner(Pars.Size, Shape.Corner, Shape.planeName, ref Shape, ref calcPoint, Pars.SingX, Pars.SingY);
		if ((Shape is buShapeEngrave) & ((Shape.planeName == planeBoxNames.Top) | (Shape.planeName == planeBoxNames.Bottom)))
		{
			buShapeEngrave buShapeEngrave2 = Shape as buShapeEngrave;
			Point3D MinPoint = new Point3D();
			Point3D MidPoint = new Point3D();
			Point3D MaxPoint = new Point3D();
			buEntity.Copy(Pars.entitiesEngraving, ref Shape.entitySolid);
			if (Shape.planeName == planeBoxNames.Bottom)
			{
				for (int i = 0; i <= Shape.entitySolid.Count - 1; i++)
				{
					Shape.entitySolid[i].Rotate(buConversion5.DegreeToRadian(180.0), Vector3D.AxisX);
				}
			}
			BoxSizeCalculate(Pars.entitiesEngraving, ref MinPoint, ref MidPoint, ref MaxPoint);
			double num = 1.0;
			double num2 = 1.0;
			double num3 = 1.0;
			if (Math.Abs(MaxPoint.X - MinPoint.X - buShapeEngrave2.Width) > 0.01)
			{
				num = buShapeEngrave2.Width / (MaxPoint.X - MinPoint.X);
			}
			if (Math.Abs(MaxPoint.Y - MinPoint.Y - buShapeEngrave2.Height) > 0.01)
			{
				num2 = buShapeEngrave2.Height / (MaxPoint.Y - MinPoint.Y);
			}
			if (Math.Abs(MaxPoint.Z - MinPoint.Z - buShapeEngrave2.Depth) > 0.01)
			{
				num3 = buShapeEngrave2.Depth / (MaxPoint.Z - MinPoint.Z);
			}
			if (!buCompare5.EQ(num, 1.0) | !buCompare5.EQ(num2, 1.0) | !buCompare5.EQ(num3, 1.0))
			{
				for (int j = 0; j <= Shape.entitySolid.Count - 1; j++)
				{
					Shape.entitySolid[j].Scale(num, num2, num3);
				}
			}
			Point3D MoveDistance = new Point3D();
			CoordinateFromObjectLocation(Shape.Alignment, Shape.planeName, Pars.entitiesEngraving, ref MoveDistance);
			BoxSizeCalculate(Shape.entitySolid, ref MinPoint, ref MidPoint, ref MaxPoint);
			if (Shape.planeName == planeBoxNames.Top)
			{
				if (!(MaxPoint.Z - MinPoint.Z > Pars.Size.Depth))
				{
					Move(MoveDistance.X + calcPoint.X, MoveDistance.Y + calcPoint.Y, MoveDistance.Z + calcPoint.Z + buShapeEngrave2.Offset.Z, ref Shape.entitySolid);
				}
				else
				{
					Move(MoveDistance.X + calcPoint.X, MoveDistance.Y + calcPoint.Y, 0.0 - MinPoint.Z + buShapeEngrave2.Offset.Z, ref Shape.entitySolid);
				}
			}
			if (Shape.planeName == planeBoxNames.Bottom)
			{
				if (!(MaxPoint.Z - MinPoint.Z > Pars.Size.Depth))
				{
					Move(MoveDistance.X + calcPoint.X, MoveDistance.Y + calcPoint.Y, 0.0 - MinPoint.Z + buShapeEngrave2.Offset.Z, ref Shape.entitySolid);
				}
				else
				{
					Move(MoveDistance.X + calcPoint.X, MoveDistance.Y + calcPoint.Y, Pars.Size.Depth - MaxPoint.Z + buShapeEngrave2.Offset.Z, ref Shape.entitySolid);
				}
			}
			BoxSizeCalculate(Shape.entitySolid, ref Shape.ItemSize.MinBox, ref Shape.ItemSize.MaxBox);
		}
		if (camParameters6 != null)
		{
			Shape.CamPar = new camParameters5(camParameters6);
		}
		if (toolBase != null)
		{
			Shape.Tool = new ToolBase5(toolBase);
		}
		if (camTp2 != null)
		{
			Shape.Cam = new camTp(camTp2);
		}
	}

	public void CreatebuShapeAsJunction(ref buShape Shape, ShapeCreateParameters Pars)
	{
		double depth = 0.0;
