		CoordinateFromPlaneAndCorner(Pars.Size, Shape.Corner, Shape.planeName, ref Shape, ref calcPoint, Pars.SingX, Pars.SingY);
		Shape.CalculatedPoint.X = calcPoint.X;
		Shape.CalculatedPoint.Y = calcPoint.Y;
		Shape.CalculatedPoint.Z = calcPoint.Z;
