		{
			buShapeJunction buShapeJunction2 = Shape as buShapeJunction;
			calcBuShapeJunctionHoles(Pars, ref Shape);
			if (buShapeJunction2.Diameter > 0.0)
			{
				depth = buShapeJunction2.Depth;
				Circle circle = null;
				if ((buShapeJunction2.planeName == planeBoxNames.Top) | (buShapeJunction2.planeName == planeBoxNames.Bottom))
				{
					circle = new Circle(buShapeJunction2.planeOperation, buShapeJunction2.Diameter / 2.0);
				}
				if ((buShapeJunction2.planeName == planeBoxNames.Front) | (buShapeJunction2.planeName == planeBoxNames.Back))
				{
					circle = new Circle(buShapeJunction2.planeOperation, buShapeJunction2.Diameter / 2.0);
				}
				if ((buShapeJunction2.planeName == planeBoxNames.Left) | (buShapeJunction2.planeName == planeBoxNames.Right))
				{
					circle = new Circle(buShapeJunction2.planeOperation, buShapeJunction2.Diameter / 2.0);
				}
				if (circle != null)
				{
					Shape.entitiesShape.Add(buEntity.Copy(circle));
				}
			}
