	public bool calcBuShapeMultiSlots(ShapeCreateParameters Pars, ref buShape Shape)
	{
		bool result = false;
		if (Shape is buShapeCut)
		{
			buShapeCut buShapeCut2 = Shape as buShapeCut;
			if (((buShapeCut2.CutType == CutTypes.CutHorizontal) | (buShapeCut2.CutType == CutTypes.CutHorizontalLine)) && buShapeCut2.CutType == CutTypes.CutHorizontalLine && buShapeCut2.Length > 0.0)
			{
				double num = Pars.Size.Width - buShapeCut2.StartDistance - buShapeCut2.EndDistance;
				if ((buShapeCut2.planeName == planeBoxNames.Front) | (buShapeCut2.planeName == planeBoxNames.Back) | (buShapeCut2.planeName == planeBoxNames.Top) | (buShapeCut2.planeName == planeBoxNames.Bottom))
				{
					buShapeCut2.CalculatedPoint.X = buShapeCut2.CornerPoint.X + buShapeCut2.CornerDirection.X * buShapeCut2.StartDistance;
				}
				if ((buShapeCut2.planeName == planeBoxNames.Right) | (buShapeCut2.planeName == planeBoxNames.Left))
				{
					num = Pars.Size.Height - buShapeCut2.StartDistance - buShapeCut2.EndDistance;
					buShapeCut2.CalculatedPoint.Y = buShapeCut2.CornerPoint.Y + buShapeCut2.CornerDirection.Y * buShapeCut2.StartDistance;
				}
				if (num > 0.0)
				{
					buShapeCut2.Length = num;
				}
			}
			if (((buShapeCut2.CutType == CutTypes.CutVertical) | (buShapeCut2.CutType == CutTypes.CutVerticalLine)) && buShapeCut2.CutType == CutTypes.CutVerticalLine && buShapeCut2.Length > 0.0)
			{
				double num2 = Pars.Size.Depth - buShapeCut2.StartDistance - buShapeCut2.EndDistance;
				if ((buShapeCut2.planeName == planeBoxNames.Top) | (buShapeCut2.planeName == planeBoxNames.Bottom))
				{
					buShapeCut2.CalculatedPoint.Y = buShapeCut2.CornerPoint.Y + buShapeCut2.CornerDirection.Y * buShapeCut2.StartDistance;
					num2 = Pars.Size.Height - buShapeCut2.StartDistance - buShapeCut2.EndDistance;
				}
				if ((buShapeCut2.planeName == planeBoxNames.Back) | (buShapeCut2.planeName == planeBoxNames.Front) | (buShapeCut2.planeName == planeBoxNames.Right) | (buShapeCut2.planeName == planeBoxNames.Left))
				{
					buShapeCut2.CalculatedPoint.Z = buShapeCut2.CornerPoint.Z + buShapeCut2.CornerDirection.Z * buShapeCut2.StartDistance;
					num2 = Pars.Size.Depth - buShapeCut2.StartDistance - buShapeCut2.EndDistance;
				}
				if (num2 > 0.0)
				{
					buShapeCut2.Length = num2;
				}
			}
		}
		return result;
	}

	public void calcBuShapeHole3Point(Point3D pntCenter, planeBoxNames PlaneName, double DistanceX, double DistanceY, double Diameter, double Angle, ref Point3D calcCenter1, ref Point3D calcCenter2)
	{
		if (PlaneName == planeBoxNames.Top || PlaneName == planeBoxNames.Bottom)
		{
			Circle circle = new Circle(Plane.XY, pntCenter, Diameter / 2.0);
			Circle circle2 = new Circle(Plane.XY, pntCenter, Diameter / 2.0);
			circle.Translate(DistanceX / 2.0, DistanceY);
			circle2.Translate((0.0 - DistanceX) / 2.0, DistanceY);
			if (Angle != 0.0)
			{
				circle.Rotate(buConversion5.DegreeToRadian(Angle), Vector3D.AxisZ, pntCenter);
				circle2.Rotate(buConversion5.DegreeToRadian(Angle), Vector3D.AxisZ, pntCenter);
			}
			circle.Regen(0.01);
			circle2.Regen(0.01);
			calcCenter1 = ToPoint3D(circle.Center);
			calcCenter2 = ToPoint3D(circle2.Center);
		}
		if (PlaneName == planeBoxNames.Front || PlaneName == planeBoxNames.Back)
		{
			Circle circle3 = new Circle(Plane.XZ, pntCenter, Diameter / 2.0);
			Circle circle4 = new Circle(Plane.XZ, pntCenter, Diameter / 2.0);
			circle3.Translate(DistanceX / 2.0, 0.0, DistanceY);
			circle4.Translate((0.0 - DistanceX) / 2.0, 0.0, DistanceY);
			if (Angle != 0.0)
			{
				circle3.Rotate(buConversion5.DegreeToRadian(Angle), Vector3D.AxisY, pntCenter);
				circle4.Rotate(buConversion5.DegreeToRadian(Angle), Vector3D.AxisY, pntCenter);
			}
			circle3.Regen(0.01);
			circle4.Regen(0.01);
			calcCenter1 = ToPoint3D(circle3.Center);
			calcCenter2 = ToPoint3D(circle4.Center);
		}
		if (PlaneName == planeBoxNames.Right || PlaneName == planeBoxNames.Left)
		{
			Circle circle5 = new Circle(Plane.YZ, pntCenter, Diameter / 2.0);
			Circle circle6 = new Circle(Plane.YZ, pntCenter, Diameter / 2.0);
			circle5.Translate(0.0, DistanceX / 2.0, DistanceY);
			circle6.Translate(0.0, (0.0 - DistanceX) / 2.0, DistanceY);
			if (Angle != 0.0)
			{
				circle5.Rotate(buConversion5.DegreeToRadian(Angle), Vector3D.AxisX, pntCenter);
				circle6.Rotate(buConversion5.DegreeToRadian(Angle), Vector3D.AxisX, pntCenter);
			}
			circle5.Regen(0.01);
			circle6.Regen(0.01);
			calcCenter1 = ToPoint3D(circle5.Center);
			calcCenter2 = ToPoint3D(circle6.Center);
		}
	}

	public bool calcBuShapeMultiHoles(ShapeCreateParameters Pars, ref buShape Shape)
	{
		bool result = false;
		if (Shape is buShapeHoleMulti)
		{
			buShapeHoleMulti buShapeHoleMulti2 = Shape as buShapeHoleMulti;
			if ((buShapeHoleMulti2.DrillType == drillTypes.HorizontalHoles) | (buShapeHoleMulti2.DrillType == drillTypes.HorizontalLineHoles))
			{
				int num = buShapeHoleMulti2.Count;
				double num2 = buShapeHoleMulti2.Distance;
				if (buShapeHoleMulti2.DrillType == drillTypes.HorizontalLineHoles && buShapeHoleMulti2.Distance > 0.0)
				{
					double num3 = Pars.Size.Width - buShapeHoleMulti2.StartDistance - buShapeHoleMulti2.EndDistance;
					int num4 = Convert.ToInt32(buNumeric5.RoundToLower(num3 / buShapeHoleMulti2.Distance));
					num3 = (double)num4 * buShapeHoleMulti2.Distance;
					if (!buCompare5.EQ(num3, Pars.Size.Width - buShapeHoleMulti2.StartDistance - buShapeHoleMulti2.EndDistance))
					{
						buShapeHoleMulti2.InfoMessages = new List<string>();
