					}
					if (num3 > 0.0)
					{
						double value = num3 / buShapeHoleMulti2.Distance;
						num = Convert.ToInt32(value);
						if (num == 0)
						{
							num = 1;
						}
						num2 = num3 / (double)num;
						num++;
						if (!buCompare5.EQ(num2, buShapeHoleMulti2.Distance, 0.01))
