					}
				}
				if ((buShapeHoleMulti2.planeName == planeBoxNames.Top) | (buShapeHoleMulti2.planeName == planeBoxNames.Bottom) | (buShapeHoleMulti2.planeName == planeBoxNames.Front) | (buShapeHoleMulti2.planeName == planeBoxNames.Back))
				{
