						new Point3D(buShapeHoleMulti2.CalculatedPoint.X, buShapeHoleMulti2.CalculatedPoint.Y, buShapeHoleMulti2.CalculatedPoint.Z);
						shapeMultiCenterData.Center.X = shapeMultiCenterData.Center.X + buShapeHoleMulti2.CornerDirection.X * num2 * (double)i;
