				}
				if ((buShapeHoleMulti2.planeName == planeBoxNames.Left) | (buShapeHoleMulti2.planeName == planeBoxNames.Right))
				{
					buShapeHoleMulti2.multiCenter = new List<ShapeMultiCenterData>();
					for (int j = 0; j <= num - 1; j++)
					{
						ShapeMultiCenterData shapeMultiCenterData2 = new ShapeMultiCenterData(buShapeHoleMulti2.CalculatedPoint, buShapeHoleMulti2.Diameter);
						shapeMultiCenterData2.Center.Y = shapeMultiCenterData2.Center.Y + buShapeHoleMulti2.CornerDirection.Y * num2 * (double)j;
						buShapeHoleMulti2.multiCenter.Add(shapeMultiCenterData2);
