					if ((buShapeHoleMulti2.planeName == planeBoxNames.Back) | (buShapeHoleMulti2.planeName == planeBoxNames.Front) | (buShapeHoleMulti2.planeName == planeBoxNames.Right) | (buShapeHoleMulti2.planeName == planeBoxNames.Left))
					{
						buShapeHoleMulti2.CalculatedPoint.Z = buShapeHoleMulti2.CornerPoint.Z + buShapeHoleMulti2.CornerDirection.Z * buShapeHoleMulti2.StartDistance;
						num7 = Pars.Size.Depth - buShapeHoleMulti2.StartDistance - buShapeHoleMulti2.EndDistance;
					}
					if (num7 > 0.0)
					{
						double value2 = num7 / buShapeHoleMulti2.Distance;
						num5 = Convert.ToInt32(value2);
						if (num5 == 0)
						{
							num5 = 1;
						}
						num6 = num7 / (double)num5;
						num5++;
						if (!buCompare5.EQ(num6, buShapeHoleMulti2.Distance, 0.01))
						{
							result = true;
						}
					}
				}
				if ((buShapeHoleMulti2.planeName == planeBoxNames.Top) | (buShapeHoleMulti2.planeName == planeBoxNames.Bottom))
				{
					buShapeHoleMulti2.multiCenter = new List<ShapeMultiCenterData>();
					for (int k = 0; k <= num5 - 1; k++)
