				if ((buShapeHoleMulti2.planeName == planeBoxNames.Right) | (buShapeHoleMulti2.planeName == planeBoxNames.Left) | (buShapeHoleMulti2.planeName == planeBoxNames.Front) | (buShapeHoleMulti2.planeName == planeBoxNames.Back))
