						shapeMultiCenterData4.Center.Z = shapeMultiCenterData4.Center.Z + buShapeJunction2.CornerDirection.Z * distance2 * (double)l;
						buShapeJunction2.multiCenter.Add(shapeMultiCenterData4);
					}
				}
			}
			if (buShapeJunction2.JunctionType == JunctionTypes.Junction2HoleNearByHorizontal)
			{
				double distance3 = buShapeJunction2.Distance;
				if ((buShapeJunction2.planeName == planeBoxNames.Top) | (buShapeJunction2.planeName == planeBoxNames.Bottom) | (buShapeJunction2.planeName == planeBoxNames.Front) | (buShapeJunction2.planeName == planeBoxNames.Back))
				{
					buShapeJunction2.multiCenter = new List<ShapeMultiCenterData>();
					ShapeMultiCenterData item = new ShapeMultiCenterData(buShapeJunction2.CalculatedPoint, buShapeJunction2.Diameter);
					buShapeJunction2.multiCenter.Add(item);
					item = new ShapeMultiCenterData(buShapeJunction2.CalculatedPoint, buShapeJunction2.DiameterOutside);
					item.Center.X = item.Center.X + buShapeJunction2.CornerDirection.X * distance3;
					buShapeJunction2.multiCenter.Add(item);
				}
				if ((buShapeJunction2.planeName == planeBoxNames.Left) | (buShapeJunction2.planeName == planeBoxNames.Right))
				{
					buShapeJunction2.multiCenter = new List<ShapeMultiCenterData>();
					ShapeMultiCenterData item2 = new ShapeMultiCenterData(buShapeJunction2.CalculatedPoint, buShapeJunction2.Diameter);
					buShapeJunction2.multiCenter.Add(item2);
					item2 = new ShapeMultiCenterData(buShapeJunction2.CalculatedPoint, buShapeJunction2.DiameterOutside);
					item2.Center.Y = item2.Center.Y + buShapeJunction2.CornerDirection.Y * distance3;
					buShapeJunction2.multiCenter.Add(item2);
				}
				buShapeJunction2.Distance = distance3;
			}
			if (buShapeJunction2.JunctionType == JunctionTypes.Junction2HoleNearByVertical)
			{
				double distance4 = buShapeJunction2.Distance;
				if ((buShapeJunction2.planeName == planeBoxNames.Top) | (buShapeJunction2.planeName == planeBoxNames.Bottom))
				{
					buShapeJunction2.multiCenter = new List<ShapeMultiCenterData>();
					ShapeMultiCenterData item3 = new ShapeMultiCenterData(buShapeJunction2.CalculatedPoint, buShapeJunction2.Diameter);
					buShapeJunction2.multiCenter.Add(item3);
					item3 = new ShapeMultiCenterData(buShapeJunction2.CalculatedPoint, buShapeJunction2.DiameterOutside);
					item3.Center.Y = item3.Center.Y + buShapeJunction2.CornerDirection.Y * distance4;
					buShapeJunction2.multiCenter.Add(item3);
				}
				if ((buShapeJunction2.planeName == planeBoxNames.Right) | (buShapeJunction2.planeName == planeBoxNames.Left) | (buShapeJunction2.planeName == planeBoxNames.Front) | (buShapeJunction2.planeName == planeBoxNames.Back))
