					item4.Center.Z = item4.Center.Z + buShapeJunction2.CornerDirection.Z * distance4;
					buShapeJunction2.multiCenter.Add(item4);
				}
			}
		}
		return result;
	}

	public void calcBuShapeProfilingArcStartEndAngles(buShapeProfiling S, ref double SA, ref double EA)
	{
		if (S.Corner == CornerLocation.LeftBottom)
		{
			SA = 180.0;
			EA = 270.0;
		}
		if (S.Corner == CornerLocation.LeftTop)
		{
			SA = 90.0;
			EA = 180.0;
		}
		if (S.Corner == CornerLocation.RightTop)
		{
			SA = 0.0;
			EA = 90.0;
		}
		if (S.Corner == CornerLocation.RightBottom)
		{
			SA = 270.0;
			EA = 360.0;
		}
	}

	public void calcBuShapeProfilingRoundConcaveArcStartEndAngles(buShapeProfiling S, ref double SA, ref double EA)
	{
		if (S.Corner == CornerLocation.LeftBottom)
		{
			SA = 0.0;
			EA = 90.0;
		}
		if (S.Corner == CornerLocation.LeftTop)
		{
			SA = 270.0;
			EA = 360.0;
		}
		if (S.Corner == CornerLocation.RightTop)
		{
			SA = 180.0;
			EA = 270.0;
		}
		if (S.Corner == CornerLocation.RightBottom)
		{
			SA = 90.0;
			EA = 180.0;
		}
	}

	public void FindShapeDataValueType(buShape Shape, int indexRow, ref ShapeDataValueType DataValue)
	{
		DataValue = ShapeDataValueType.None;
		if (Shape.ShapeGroup == ShapeGroup.Drill)
		{
			buShapeHole buShapeHole4 = Shape as buShapeHole;
			if (!((buShapeHole4.DrillType == drillTypes.HorizontalLineHoles) | (buShapeHole4.DrillType == drillTypes.VerticalLineHoles)))
			{
				if (indexRow == 0)
				{
					if ((buShapeHole4.planeName == planeBoxNames.Top) | (buShapeHole4.planeName == planeBoxNames.Bottom) | (buShapeHole4.planeName == planeBoxNames.Front) | (buShapeHole4.planeName == planeBoxNames.Back))
					{
						DataValue = ShapeDataValueType.XPosition;
					}
					if ((buShapeHole4.planeName == planeBoxNames.Left) | (buShapeHole4.planeName == planeBoxNames.Right))
					{
						DataValue = ShapeDataValueType.YPosition;
					}
				}
				if (indexRow == 1)
				{
					if ((buShapeHole4.planeName == planeBoxNames.Top) | (buShapeHole4.planeName == planeBoxNames.Bottom))
					{
						DataValue = ShapeDataValueType.YPosition;
					}
					if ((buShapeHole4.planeName == planeBoxNames.Front) | (buShapeHole4.planeName == planeBoxNames.Back) | (buShapeHole4.planeName == planeBoxNames.Left) | (buShapeHole4.planeName == planeBoxNames.Right))
					{
						DataValue = ShapeDataValueType.ZPosition;
					}
				}
				if (indexRow == 2)
				{
					DataValue = ShapeDataValueType.Diameter;
				}
				if (indexRow == 3)
				{
					DataValue = ShapeDataValueType.Depth;
				}
				if ((buShapeHole4.DrillType == drillTypes.HorizontalHoles) | (buShapeHole4.DrillType == drillTypes.VerticalHoles) | (buShapeHole4.DrillType == drillTypes.InclineHoles))
				{
					if (indexRow == 4)
					{
						DataValue = ShapeDataValueType.DrillDistance;
					}
					if (indexRow == 5)
					{
						DataValue = ShapeDataValueType.Count;
					}
					if (indexRow == 6)
					{
						DataValue = ShapeDataValueType.Angle;
					}
				}
				if (buShapeHole4.DrillType == drillTypes.ThreeHole)
				{
					if (indexRow == 4)
					{
						DataValue = ShapeDataValueType.DiameterOutside;
					}
					if (indexRow == 5)
					{
						DataValue = ShapeDataValueType.Hole3XDistance;
					}
					if (indexRow == 6)
					{
						DataValue = ShapeDataValueType.Hole3YDistance;
					}
