					if ((buShapeCut2.planeName == planeBoxNames.Front) | (buShapeCut2.planeName == planeBoxNames.Back) | (buShapeCut2.planeName == planeBoxNames.Left) | (buShapeCut2.planeName == planeBoxNames.Right))
