	public void calcProjectionPointAtSide(buShape Shape, MaterialBase5 Material, ref Point3D pntHorizontalCalc, ref Point3D pntVerticalCalc, ref Point3D pntHorizontalOpositeCalc, ref Point3D pntVerticalOpositeCalc)
	{
		if ((Shape.planeName == planeBoxNames.Top) | (Shape.planeName == planeBoxNames.Bottom))
		{
			pntHorizontalCalc.X = Shape.CornerPoint.X;
			pntHorizontalCalc.Y = Shape.CalculatedPoint.Y;
			pntHorizontalCalc.Z = Shape.CalculatedPoint.Z;
			pntHorizontalOpositeCalc.X = Shape.CornerPoint.X;
			if ((Shape.Corner == CornerLocation.RightBottom) | (Shape.Corner == CornerLocation.RightCenter) | (Shape.Corner == CornerLocation.RightTop))
			{
				pntHorizontalOpositeCalc.X = Shape.CornerPoint.X - Material.Size.Width;
			}
			if ((Shape.Corner == CornerLocation.LeftBottom) | (Shape.Corner == CornerLocation.LeftCenter) | (Shape.Corner == CornerLocation.LeftTop))
			{
				pntHorizontalOpositeCalc.X = Shape.CornerPoint.X + Material.Size.Width;
			}
			pntHorizontalOpositeCalc.Y = Shape.CalculatedPoint.Y;
			pntHorizontalOpositeCalc.Z = Shape.CalculatedPoint.Z;
			pntVerticalCalc.X = Shape.CalculatedPoint.X;
			pntVerticalCalc.Y = Shape.CornerPoint.Y;
			pntVerticalCalc.Z = Shape.CalculatedPoint.Z;
			pntVerticalOpositeCalc.Y = Shape.CornerPoint.Y;
			if ((Shape.Corner == CornerLocation.TopCenter) | (Shape.Corner == CornerLocation.LeftTop) | (Shape.Corner == CornerLocation.RightTop))
			{
				pntVerticalOpositeCalc.Y = Shape.CornerPoint.Y - Material.Size.Height;
			}
			if ((Shape.Corner == CornerLocation.BottomCenter) | (Shape.Corner == CornerLocation.LeftBottom) | (Shape.Corner == CornerLocation.RightBottom))
			{
				pntVerticalOpositeCalc.Y = Shape.CornerPoint.Y + Material.Size.Height;
			}
			pntVerticalOpositeCalc.X = Shape.CalculatedPoint.X;
			pntVerticalOpositeCalc.Z = Shape.CalculatedPoint.Z;
		}
		if ((Shape.planeName == planeBoxNames.Front) | (Shape.planeName == planeBoxNames.Back))
		{
			pntHorizontalCalc.X = Shape.CornerPoint.X;
			pntHorizontalCalc.Y = Shape.CalculatedPoint.Y;
			pntHorizontalCalc.Z = Shape.CalculatedPoint.Z;
			pntHorizontalOpositeCalc.X = Shape.CornerPoint.X;
			if ((Shape.Corner == CornerLocation.RightBottom) | (Shape.Corner == CornerLocation.RightCenter) | (Shape.Corner == CornerLocation.RightTop))
			{
				pntHorizontalOpositeCalc.X = Shape.CornerPoint.X - Material.Size.Width;
			}
			if ((Shape.Corner == CornerLocation.LeftBottom) | (Shape.Corner == CornerLocation.LeftCenter) | (Shape.Corner == CornerLocation.LeftTop))
			{
				pntHorizontalOpositeCalc.X = Shape.CornerPoint.X + Material.Size.Width;
			}
			pntHorizontalOpositeCalc.Y = Shape.CalculatedPoint.Y;
			pntHorizontalOpositeCalc.Z = Shape.CalculatedPoint.Z;
			pntVerticalCalc.X = Shape.CalculatedPoint.X;
			pntVerticalCalc.Y = Shape.CalculatedPoint.Y;
			pntVerticalCalc.Z = Shape.CornerPoint.Z;
			pntVerticalOpositeCalc.Z = Shape.CornerPoint.Z;
			if ((Shape.Corner == CornerLocation.TopCenter) | (Shape.Corner == CornerLocation.LeftTop) | (Shape.Corner == CornerLocation.RightTop))
			{
				pntVerticalOpositeCalc.Z = Shape.CornerPoint.Z - Material.Size.Depth;
			}
			if ((Shape.Corner == CornerLocation.BottomCenter) | (Shape.Corner == CornerLocation.LeftBottom) | (Shape.Corner == CornerLocation.RightBottom))
			{
				pntVerticalOpositeCalc.Z = Shape.CornerPoint.Z + Material.Size.Depth;
			}
			pntVerticalOpositeCalc.X = Shape.CalculatedPoint.X;
			pntVerticalOpositeCalc.Y = Shape.CalculatedPoint.Y;
		}
		if (!((Shape.planeName == planeBoxNames.Left) | (Shape.planeName == planeBoxNames.Right)))
		{
			return;
		}
		if (clsVar5.ShapeSettingsParameters.LeftRigthViewType == LeftRightType.Left)
		{
			pntHorizontalCalc.X = Shape.CalculatedPoint.X;
			pntHorizontalCalc.Y = Shape.CornerPoint.Y;
			pntHorizontalCalc.Z = Shape.CalculatedPoint.Z;
			pntHorizontalOpositeCalc.Y = Shape.CornerPoint.Y;
			if ((Shape.Corner == CornerLocation.RightBottom) | (Shape.Corner == CornerLocation.RightCenter) | (Shape.Corner == CornerLocation.RightTop))
			{
				pntHorizontalOpositeCalc.Y = Shape.CornerPoint.Y + Material.Size.Height;
			}
			if ((Shape.Corner == CornerLocation.LeftBottom) | (Shape.Corner == CornerLocation.LeftCenter) | (Shape.Corner == CornerLocation.LeftTop))
			{
				pntHorizontalOpositeCalc.Y = Shape.CornerPoint.Y - Material.Size.Height;
			}
			pntHorizontalOpositeCalc.X = Shape.CalculatedPoint.X;
			pntHorizontalOpositeCalc.Z = Shape.CalculatedPoint.Z;
			pntVerticalCalc.X = Shape.CalculatedPoint.X;
			pntVerticalCalc.Y = Shape.CalculatedPoint.Y;
			pntVerticalCalc.Z = Shape.CornerPoint.Z;
			pntVerticalOpositeCalc.Z = Shape.CornerPoint.Z;
			if ((Shape.Corner == CornerLocation.TopCenter) | (Shape.Corner == CornerLocation.LeftTop) | (Shape.Corner == CornerLocation.RightTop))
			{
				pntVerticalOpositeCalc.Z = Shape.CornerPoint.Z - Material.Size.Depth;
			}
			if ((Shape.Corner == CornerLocation.BottomCenter) | (Shape.Corner == CornerLocation.LeftBottom) | (Shape.Corner == CornerLocation.RightBottom))
			{
				pntVerticalOpositeCalc.Z = Shape.CornerPoint.Z + Material.Size.Depth;
			}
			pntVerticalOpositeCalc.X = Shape.CalculatedPoint.X;
			pntVerticalOpositeCalc.Y = Shape.CalculatedPoint.Y;
		}
		if (clsVar5.ShapeSettingsParameters.LeftRigthViewType == LeftRightType.Right)
		{
			pntHorizontalCalc.X = Shape.CalculatedPoint.X;
			pntHorizontalCalc.Y = Shape.CornerPoint.Y;
			pntHorizontalCalc.Z = Shape.CalculatedPoint.Z;
			pntHorizontalOpositeCalc.Y = Shape.CornerPoint.Y;
			if ((Shape.Corner == CornerLocation.RightBottom) | (Shape.Corner == CornerLocation.RightCenter) | (Shape.Corner == CornerLocation.RightTop))
			{
				pntHorizontalOpositeCalc.Y = Shape.CornerPoint.Y - Material.Size.Height;
			}
			if ((Shape.Corner == CornerLocation.LeftBottom) | (Shape.Corner == CornerLocation.LeftCenter) | (Shape.Corner == CornerLocation.LeftTop))
			{
				pntHorizontalOpositeCalc.Y = Shape.CornerPoint.Y + Material.Size.Height;
			}
			pntHorizontalOpositeCalc.X = Shape.CalculatedPoint.X;
			pntHorizontalOpositeCalc.Z = Shape.CalculatedPoint.Z;
			pntVerticalCalc.X = Shape.CalculatedPoint.X;
			pntVerticalCalc.Y = Shape.CalculatedPoint.Y;
			pntVerticalCalc.Z = Shape.CornerPoint.Z;
			pntVerticalOpositeCalc.Z = Shape.CornerPoint.Z;
			if ((Shape.Corner == CornerLocation.TopCenter) | (Shape.Corner == CornerLocation.LeftTop) | (Shape.Corner == CornerLocation.RightTop))
			{
				pntVerticalOpositeCalc.Z = Shape.CornerPoint.Z - Material.Size.Depth;
			}
			if ((Shape.Corner == CornerLocation.BottomCenter) | (Shape.Corner == CornerLocation.LeftBottom) | (Shape.Corner == CornerLocation.RightBottom))
			{
				pntVerticalOpositeCalc.Z = Shape.CornerPoint.Z + Material.Size.Depth;
			}
			pntVerticalOpositeCalc.X = Shape.CalculatedPoint.X;
			pntVerticalOpositeCalc.Y = Shape.CalculatedPoint.Y;
		}
	}

	public void CreateShapeDimensionDiameter(buShape Shape, MaterialBase5 Material, ShapeDataValueType ValueType, ref List<Entity> entitiesDim)
	{
		Point3D point3D = null;
		double num = 0.0;
		double num2 = 0.0;
		double num3 = 0.0;
		double num4 = 15.0;
		Entity entity = null;
		if (Shape.planeName != planeBoxNames.Top)
		{
			if (Shape.planeName != planeBoxNames.Bottom)
			{
				if (Shape.planeName != planeBoxNames.Front)
				{
					if (Shape.planeName != planeBoxNames.Back)
					{
						if (Shape.planeName != planeBoxNames.Left)
						{
							if (Shape.planeName == planeBoxNames.Right)
							{
								num = Material.Sing.X * (Shape.Depth + 1.0);
							}
						}
						else
						{
							num = Material.Sing.X * (Material.Size.Width + 1.0);
						}
					}
					else
					{
						num2 = Material.Sing.Y * (Shape.Depth + 1.0);
					}
				}
				else
				{
					num2 = Material.Sing.Y * 1.0;
				}
			}
			else
			{
				num3 = Shape.Depth + 1.0;
			}
		}
		else
		{
			num3 = 1.0;
		}
		if (Shape.ShapeGroup != ShapeGroup.Drill)
		{
			return;
		}
		double num5 = 0.0;
		if (((buShapeHole)Shape).DrillType != drillTypes.ThreeHole)
		{
			num4 = ((buShapeHole)Shape).Diameter * 0.3;
			point3D = new Point3D(Shape.CalculatedPoint.X + num, Shape.CalculatedPoint.Y + num2, Shape.CalculatedPoint.Z + num3);
			num5 = ((buShapeHole)Shape).Diameter;
		}
		else
		{
			buShapeHole3 buShapeHole4 = Shape as buShapeHole3;
			if (ValueType != ShapeDataValueType.Diameter)
			{
				num4 = buShapeHole4.DiameterOutside * 0.3;
				if (buShapeHole4.entitiesShape.Count >= 2 && buShapeHole4.entitiesShape[1] is buCircle)
				{
					buCircle buCircle2 = buShapeHole4.entitiesShape[1] as buCircle;
					point3D = new Point3D(buCircle2.Center.X + num, buCircle2.Center.Y + num2, buCircle2.Center.Z + num3);
					num5 = buShapeHole4.DiameterOutside;
				}
			}
			else
			{
				num4 = buShapeHole4.Diameter * 0.3;
				point3D = new Point3D(Shape.CalculatedPoint.X + num, Shape.CalculatedPoint.Y + num2, Shape.CalculatedPoint.Z + num3);
				num5 = buShapeHole4.Diameter;
			}
		}
		if (num5 > 0.0)
		{
			entity = new DiametricDim(new Circle(Shape.planeOperation, point3D, num5 / 2.0), point3D, num4);
			if ((Shape.planeName == planeBoxNames.Left) | (Shape.planeName == planeBoxNames.Right))
			{
				entity.Rotate(Math.PI, Vector3D.AxisZ, point3D);
			}
			entitiesDim.Add(entity);
		}
	}

	public void CreateShapeDimensionDepth(buShape Shape, MaterialBase5 Material, ShapeDataValueType ValueType, ref List<Entity> entitiesDim)
	{
		Point3D point3D = null;
		Point3D point3D2 = null;
		Point3D point3D3 = null;
		double num = 0.0;
		double num2 = 0.0;
		double num3 = 0.0;
		double num4 = 15.0;
		Entity entity = null;
		if (Shape.planeName != planeBoxNames.Top)
		{
			if (Shape.planeName != planeBoxNames.Bottom)
			{
				if (Shape.planeName != planeBoxNames.Front)
				{
					if (Shape.planeName != planeBoxNames.Back)
					{
						if (Shape.planeName != planeBoxNames.Left)
						{
							if (Shape.planeName == planeBoxNames.Right)
							{
								num2 = 20.0;
							}
						}
						else
						{
							num2 = 20.0;
						}
					}
					else
					{
						num = 20.0;
					}
				}
				else
				{
					num = 20.0;
				}
			}
			else
			{
				num = 20.0;
			}
		}
		else
		{
			num = 20.0;
		}
		if (!((Shape.ShapeGroup == ShapeGroup.Drill) | (Shape.ShapeGroup == ShapeGroup.Cut) | (Shape.ShapeGroup == ShapeGroup.Shape)))
		{
			return;
		}
		if (Shape is buShapeHole)
		{
			num4 = ((buShapeHole)Shape).Diameter * 0.3;
		}
		if (Shape is buShapeCut)
		{
			num4 = ((buShapeCut)Shape).Diameter * 0.3;
		}
		if ((Shape != null) & (Shape.ShapeGroup == ShapeGroup.Shape))
		{
			if (Shape.ShapeType == ShapeTypes.Rectangle)
			{
				num4 = ((buShapeRectangle)Shape).Width * 0.3;
			}
			if (Shape.ShapeType == ShapeTypes.Circle)
			{
				num4 = ((buShapeCircle)Shape).Radius * 0.3;
			}
			if (Shape.ShapeType == ShapeTypes.Ellipse)
			{
				num4 = ((buShapeEllipse)Shape).RadiusX * 0.3;
			}
			if (Shape.ShapeType == ShapeTypes.KeyHole)
			{
				num4 = ((buShapeKeyHole)Shape).Length * 0.3;
			}
			if (Shape.ShapeType == ShapeTypes.Polygon)
			{
				num4 = ((buShapePolygon)Shape).Radius * 0.3;
			}
			if (Shape.ShapeType == ShapeTypes.Slot)
			{
				num4 = ((buShapeSlot)Shape).Diameter * 0.3;
			}
			if (Shape.ShapeType == ShapeTypes.FreeDraw)
			{
				num4 = ((buShapeFreeDraw)Shape).Width * 0.3;
			}
		}
		if (Shape.planeName != planeBoxNames.Top)
		{
			if (Shape.planeName != planeBoxNames.Bottom)
			{
				if (Shape.planeName != planeBoxNames.Front)
				{
					if (Shape.planeName != planeBoxNames.Back)
					{
						if (Shape.planeName != planeBoxNames.Left)
						{
							if (Shape.planeName == planeBoxNames.Right)
							{
								point3D = new Point3D(Shape.CalculatedPoint.X, Shape.CalculatedPoint.Y, Shape.CalculatedPoint.Z);
								point3D2 = new Point3D(Shape.CalculatedPoint.X - Shape.Depth, Shape.CalculatedPoint.Y, Shape.CalculatedPoint.Z);
								point3D3 = new Point3D((point3D.X + point3D2.X) / 2.0 + num, point3D.Y + num2, point3D.Z + num3);
							}
						}
						else
						{
							point3D = new Point3D(Shape.CalculatedPoint.X, Shape.CalculatedPoint.Y, Shape.CalculatedPoint.Z);
							point3D2 = new Point3D(Shape.CalculatedPoint.X + Shape.Depth, Shape.CalculatedPoint.Y, Shape.CalculatedPoint.Z);
							point3D3 = new Point3D((point3D.X + point3D2.X) / 2.0 + num, point3D.Y + num2, point3D.Z + num3);
						}
					}
					else
					{
						point3D = new Point3D(Shape.CalculatedPoint.X, Shape.CalculatedPoint.Y, Shape.CalculatedPoint.Z);
						point3D2 = new Point3D(Shape.CalculatedPoint.X, Shape.CalculatedPoint.Y - Shape.Depth, Shape.CalculatedPoint.Z);
						point3D3 = new Point3D(point3D.X + num, (point3D.Y + point3D2.Y) / 2.0 + num2, point3D.Z + num3);
					}
				}
				else
				{
					point3D = new Point3D(Shape.CalculatedPoint.X, Shape.CalculatedPoint.Y, Shape.CalculatedPoint.Z);
					point3D2 = new Point3D(Shape.CalculatedPoint.X, Shape.CalculatedPoint.Y + Shape.Depth, Shape.CalculatedPoint.Z);
					point3D3 = new Point3D(point3D.X + num, (point3D.Y + point3D2.Y) / 2.0 + num2, point3D.Z + num3);
				}
			}
			else
			{
				point3D = new Point3D(Shape.CalculatedPoint.X, Shape.CalculatedPoint.Y, Shape.CalculatedPoint.Z);
				point3D2 = new Point3D(Shape.CalculatedPoint.X, Shape.CalculatedPoint.Y, Shape.CalculatedPoint.Z + Shape.Depth);
				point3D3 = new Point3D(point3D.X + num, point3D.Y + num2, (point3D.Z + point3D2.Z) / 2.0 + num3);
			}
		}
		else
		{
			point3D = new Point3D(Shape.CalculatedPoint.X, Shape.CalculatedPoint.Y, Shape.CalculatedPoint.Z);
			point3D2 = new Point3D(Shape.CalculatedPoint.X, Shape.CalculatedPoint.Y, Shape.CalculatedPoint.Z - Shape.Depth);
			point3D3 = new Point3D(point3D.X + num, point3D.Y + num2, (point3D.Z + point3D2.Z) / 2.0 + num3);
		}
		Plane drawingPlane = null;
		if (!((Shape.planeName == planeBoxNames.Top) | (Shape.planeName == planeBoxNames.Bottom)))
		{
			LinearDimCalculate(point3D, point3D2, point3D3, num4, Plane.XY, ref drawingPlane);
		}
		else
		{
			LinearDimCalculate(point3D, point3D2, point3D3, num4, Plane.XZ, ref drawingPlane);
		}
