	public void CreateShapeDimension2Point(Point3D firstPoint, Point3D secondPoint, buShape Shape, MaterialBase5 Material, ShapeDataValueType ValueType, ref List<Entity> entitiesDim)
	{
		Point3D point3D = ToPoint3D(firstPoint);
		Point3D point3D2 = ToPoint3D(secondPoint);
		Point3D point3D3 = null;
		double num = 15.0;
		Entity entity = null;
		if (Shape.planeName == planeBoxNames.Top || Shape.planeName == planeBoxNames.Bottom || Shape.planeName == planeBoxNames.Front || Shape.planeName == planeBoxNames.Back || Shape.planeName == planeBoxNames.Left || Shape.planeName != planeBoxNames.Right)
		{
		}
		point3D3 = MiddlePointOfLine(point3D, point3D2);
		Plane drawingPlane = null;
		AlignedDimCalculate(point3D, point3D2, point3D3, num, Shape.planeOperation, ref drawingPlane);
		if (drawingPlane != null)
		{
			entity = new LinearDim(drawingPlane, point3D, point3D2, point3D3, num);
			if (!((Shape.planeName == planeBoxNames.Left) | (Shape.planeName == planeBoxNames.Right)))
			{
			}
			entitiesDim.Add(entity);
		}
	}

	public void CreateShapeDimension3Hole(buShape Shape, MaterialBase5 Material, ShapeDataValueType ValueType, ref List<Entity> entitiesDim)
	{
		if (Shape.planeName == planeBoxNames.Top || Shape.planeName == planeBoxNames.Bottom || Shape.planeName == planeBoxNames.Front || Shape.planeName == planeBoxNames.Back || Shape.planeName == planeBoxNames.Left || Shape.planeName != planeBoxNames.Right)
		{
		}
		if (Shape.ShapeGroup == ShapeGroup.Drill && ((buShapeHole)Shape).DrillType == drillTypes.ThreeHole)
		{
			buShapeHole3 buShapeHole4 = Shape as buShapeHole3;
			if (ValueType == ShapeDataValueType.Hole3XDistance && buShapeHole4.entitiesShape.Count >= 3)
			{
				buCircle buCircle2 = buShapeHole4.entitiesShape[1] as buCircle;
				buCircle buCircle3 = buShapeHole4.entitiesShape[2] as buCircle;
				CreateShapeDimension2Point(buCircle2.Center, buCircle3.Center, Shape, Material, ValueType, ref entitiesDim);
			}
			if (ValueType == ShapeDataValueType.Hole3YDistance && buShapeHole4.entitiesShape.Count >= 3)
			{
				buCircle buCircle4 = buShapeHole4.entitiesShape[0] as buCircle;
				buCircle buCircle5 = buShapeHole4.entitiesShape[1] as buCircle;
				buCircle buCircle6 = buShapeHole4.entitiesShape[2] as buCircle;
				Point3D secondPoint = MiddlePointOfLine(buCircle5.Center, buCircle6.Center);
				CreateShapeDimension2Point(buCircle4.Center, secondPoint, Shape, Material, ValueType, ref entitiesDim);
			}
		}
	}

	public void CreateShapeDimension(buShape Shape, MaterialBase5 Material, ShapeDataValueType ValueType, ref List<Entity> entitiesDim, ref viewType SetView)
	{
