		Point3D point3D3 = null;
		double num = 0.0;
		double num2 = 0.0;
		double num3 = 0.0;
		double num4 = 15.0;
		bool flag = false;
		Entity entity = null;
		entitiesDim.Clear();
		if (ValueType != ShapeDataValueType.Diameter)
		{
			if (ValueType != ShapeDataValueType.DiameterOutside)
			{
				if (ValueType != ShapeDataValueType.Angle)
				{
					if (ValueType != ShapeDataValueType.Depth)
					{
						if (ValueType != ShapeDataValueType.DrillDistance)
						{
							if (ValueType != ShapeDataValueType.Hole3XDistance)
							{
								if (ValueType != ShapeDataValueType.Hole3YDistance)
								{
									if (ValueType != ShapeDataValueType.Count)
									{
										if (ValueType != ShapeDataValueType.Width)
										{
											if (ValueType != ShapeDataValueType.Height)
											{
												if (ValueType != ShapeDataValueType.Length)
												{
													if (ValueType != ShapeDataValueType.StartDistance)
													{
														if (ValueType != ShapeDataValueType.EndDistance)
														{
															if (ValueType == ShapeDataValueType.YPosition && ((Shape.planeName == planeBoxNames.Top) | (Shape.planeName == planeBoxNames.Bottom)))
															{
																flag = true;
															}
															if (ValueType == ShapeDataValueType.ZPosition && ((Shape.planeName == planeBoxNames.Front) | (Shape.planeName == planeBoxNames.Back) | (Shape.planeName == planeBoxNames.Left) | (Shape.planeName == planeBoxNames.Right)))
															{
																flag = true;
															}
															if (!flag)
															{
																if ((Shape.planeName == planeBoxNames.Top) | (Shape.planeName == planeBoxNames.Bottom))
																{
																	if ((Shape.Corner == CornerLocation.RightTop) | (Shape.Corner == CornerLocation.LeftTop) | (Shape.Corner == CornerLocation.TopCenter))
																	{
																		num2 = 20.0;
																	}
																	if ((Shape.Corner == CornerLocation.BottomCenter) | (Shape.Corner == CornerLocation.RightBottom) | (Shape.Corner == CornerLocation.LeftBottom))
																	{
																		num2 = -20.0;
																	}
																	if ((Shape.Corner == CornerLocation.LeftCenter) | (Shape.Corner == CornerLocation.RightCenter))
																	{
																		num2 = -20.0;
																	}
																	if (Shape.planeName == planeBoxNames.Top)
																	{
																		num3 = 1.0;
																	}
																	if (Shape.planeName == planeBoxNames.Bottom)
																	{
																		num3 = Material.Size.Depth + 1.0;
																	}
																}
																if ((Shape.planeName == planeBoxNames.Front) | (Shape.planeName == planeBoxNames.Back) | (Shape.planeName == planeBoxNames.Left) | (Shape.planeName == planeBoxNames.Right))
																{
																	if ((Shape.Corner == CornerLocation.RightTop) | (Shape.Corner == CornerLocation.LeftTop) | (Shape.Corner == CornerLocation.TopCenter))
																	{
																		num3 = 20.0;
																	}
																	if ((Shape.Corner == CornerLocation.BottomCenter) | (Shape.Corner == CornerLocation.RightBottom) | (Shape.Corner == CornerLocation.LeftBottom))
																	{
																		num3 = -20.0;
																	}
																	if ((Shape.Corner == CornerLocation.LeftCenter) | (Shape.Corner == CornerLocation.RightCenter))
																	{
																		num3 = -20.0;
																	}
																	if ((Shape.planeName == planeBoxNames.Front) | (Shape.planeName == planeBoxNames.Back))
																	{
																		num2 = 1.0;
																	}
																	if ((Shape.planeName == planeBoxNames.Left) | (Shape.planeName == planeBoxNames.Right))
																	{
																		num = 1.0;
																	}
																}
															}
															else
															{
																if ((Shape.planeName == planeBoxNames.Top) | (Shape.planeName == planeBoxNames.Bottom) | (Shape.planeName == planeBoxNames.Front) | (Shape.planeName == planeBoxNames.Back))
																{
																	if ((Shape.Corner == CornerLocation.RightBottom) | (Shape.Corner == CornerLocation.RightCenter) | (Shape.Corner == CornerLocation.RightTop))
																	{
																		num = 20.0;
																	}
																	if ((Shape.Corner == CornerLocation.LeftCenter) | (Shape.Corner == CornerLocation.LeftBottom) | (Shape.Corner == CornerLocation.LeftTop))
																	{
																		num = -20.0;
																	}
																	if ((Shape.Corner == CornerLocation.TopCenter) | (Shape.Corner == CornerLocation.BottomCenter))
																	{
																		num = -20.0;
																	}
																	if ((Shape.planeName == planeBoxNames.Top) | (Shape.planeName == planeBoxNames.Bottom))
