															}
															if (ValueType == ShapeDataValueType.XPosition)
															{
																point3D2 = new Point3D(Shape.CalculatedPoint.X, Shape.CalculatedPoint.Y, Shape.CalculatedPoint.Z);
																point3D = new Point3D(Shape.CornerPoint.X, Shape.CalculatedPoint.Y, Shape.CalculatedPoint.Z);
																point3D3 = new Point3D((point3D.X + point3D2.X) / 2.0 + num, point3D.Y + num2, point3D.Z + num3);
																entity = new LinearDim(Shape.planeOperation, point3D, point3D2, point3D3, num4);
																entitiesDim.Add(entity);
															}
															if (ValueType == ShapeDataValueType.YPosition)
															{
																point3D = new Point3D(Shape.CalculatedPoint.X, Shape.CalculatedPoint.Y, Shape.CalculatedPoint.Z);
																point3D2 = new Point3D(Shape.CalculatedPoint.X, Shape.CornerPoint.Y, Shape.CalculatedPoint.Z);
																point3D3 = new Point3D(point3D.X + num, (point3D.Y + point3D2.Y) / 2.0 + num2, point3D.Z + num3);
																Plane drawingPlane = null;
																if (!((Shape.planeName == planeBoxNames.Left) | (Shape.planeName == planeBoxNames.Right)))
																{
																	AlignedDimCalculate(point3D, point3D2, point3D3, num4, Shape.planeOperation, ref drawingPlane);
																}
																else
																{
																	AlignedDimCalculate(point3D, point3D2, point3D3, num4, Plane.YZ, ref drawingPlane);
																}
																if (drawingPlane != null)
																{
																	entity = new LinearDim(drawingPlane, point3D, point3D2, point3D3, num4);
																	if (!((Shape.planeName == planeBoxNames.Left) | (Shape.planeName == planeBoxNames.Right)))
																	{
																	}
																	entitiesDim.Add(entity);
																}
															}
															if (ValueType != ShapeDataValueType.ZPosition)
															{
																return;
															}
															point3D = new Point3D(Shape.CalculatedPoint.X, Shape.CalculatedPoint.Y, Shape.CalculatedPoint.Z);
															point3D2 = new Point3D(Shape.CalculatedPoint.X, Shape.CalculatedPoint.Y, Shape.CornerPoint.Z);
															point3D3 = new Point3D(point3D.X + num, point3D.Y + num2, (point3D.Z + point3D2.Z) / 2.0 + num3);
															Plane drawingPlane2 = null;
															if (!((Shape.planeName == planeBoxNames.Left) | (Shape.planeName == planeBoxNames.Right)))
															{
																AlignedDimCalculate(point3D, point3D2, point3D3, num4, Shape.planeOperation, ref drawingPlane2);
															}
															else
															{
																AlignedDimCalculate(point3D, point3D2, point3D3, num4, Plane.YZ, ref drawingPlane2);
															}
															if (drawingPlane2 != null)
															{
																entity = new LinearDim(drawingPlane2, point3D, point3D2, point3D3, num4);
																if (!((Shape.planeName == planeBoxNames.Left) | (Shape.planeName == planeBoxNames.Right)))
																{
																}
																entitiesDim.Add(entity);
															}
															return;
														}
														Point3D pntHorizontalCalc = new Point3D();
														Point3D pntVerticalCalc = new Point3D();
														Point3D pntHorizontalOpositeCalc = new Point3D();
														Point3D pntVerticalOpositeCalc = new Point3D();
														calcProjectionPointAtSide(Shape, Material, ref pntHorizontalCalc, ref pntVerticalCalc, ref pntHorizontalOpositeCalc, ref pntVerticalOpositeCalc);
														if (Shape.ShapeGroup == ShapeGroup.Drill)
														{
															buShapeHole buShapeHole4 = Shape as buShapeHole;
															if (buShapeHole4.DrillType != drillTypes.HorizontalLineHoles)
															{
																if (buShapeHole4.DrillType == drillTypes.VerticalLineHoles)
																{
																	CreateShapeDimension2Point(Shape.multiCenter[Shape.multiCenter.Count - 1].Center, pntVerticalOpositeCalc, Shape, Material, ValueType, ref entitiesDim);
																}
															}
															else if (Shape.multiCenter.Count > 0)
															{
																CreateShapeDimension2Point(Shape.multiCenter[Shape.multiCenter.Count - 1].Center, pntHorizontalOpositeCalc, Shape, Material, ValueType, ref entitiesDim);
															}
														}
														SetView = PlaneNameToViewType(Shape.planeName);
														return;
													}
													Point3D pntHorizontalCalc2 = new Point3D();
													Point3D pntVerticalCalc2 = new Point3D();
													Point3D pntHorizontalOpositeCalc2 = new Point3D();
													Point3D pntVerticalOpositeCalc2 = new Point3D();
													calcProjectionPointAtSide(Shape, Material, ref pntHorizontalCalc2, ref pntVerticalCalc2, ref pntHorizontalOpositeCalc2, ref pntVerticalOpositeCalc2);
													if (Shape.ShapeGroup == ShapeGroup.Drill)
													{
														buShapeHole buShapeHole5 = Shape as buShapeHole;
														if (buShapeHole5.DrillType != drillTypes.HorizontalLineHoles)
														{
															if (buShapeHole5.DrillType == drillTypes.VerticalLineHoles)
															{
																CreateShapeDimension2Point(Shape.CalculatedPoint, pntVerticalCalc2, Shape, Material, ValueType, ref entitiesDim);
															}
														}
														else
														{
															CreateShapeDimension2Point(Shape.CalculatedPoint, pntHorizontalCalc2, Shape, Material, ValueType, ref entitiesDim);
														}
													}
													SetView = PlaneNameToViewType(Shape.planeName);
													return;
												}
												if (Shape.entitiesDim != null)
												{
													for (int i = 0; i <= Shape.entitiesDim.Count - 1; i++)
													{
														if (Shape.entitiesDim[i].Info.Data == ShapeDataValueType.Length.ToString())
														{
															Entity copiedEntity = null;
															buEntity.Copy(Shape.entitiesDim[i], ref copiedEntity);
															entitiesDim.Add(copiedEntity);
														}
													}
												}
												SetView = PlaneNameToViewType(Shape.planeName);
												return;
											}
											if (Shape.entitiesDim != null)
											{
												for (int j = 0; j <= Shape.entitiesDim.Count - 1; j++)
												{
													if (Shape.entitiesDim[j].Info.Data == ShapeDataValueType.Height.ToString())
													{
														Entity copiedEntity2 = null;
														buEntity.Copy(Shape.entitiesDim[j], ref copiedEntity2);
														entitiesDim.Add(copiedEntity2);
													}
												}
											}
											SetView = PlaneNameToViewType(Shape.planeName);
											return;
										}
										if (Shape.entitiesDim != null)
										{
											for (int k = 0; k <= Shape.entitiesDim.Count - 1; k++)
											{
												if (Shape.entitiesDim[k].Info.Data == ShapeDataValueType.Width.ToString())
												{
													Entity copiedEntity3 = null;
													buEntity.Copy(Shape.entitiesDim[k], ref copiedEntity3);
													entitiesDim.Add(copiedEntity3);
												}
											}
										}
										SetView = PlaneNameToViewType(Shape.planeName);
									}
									else
									{
										if (Shape.multiCenter.Count >= 2)
										{
											CreateShapeDimension2Point(Shape.multiCenter[0].Center, Shape.multiCenter[Shape.multiCenter.Count - 1].Center, Shape, Material, ValueType, ref entitiesDim);
											((Dimension)entitiesDim[0]).TextOverride = Shape.multiCenter.Count.ToString();
										}
										SetView = PlaneNameToViewType(Shape.planeName);
									}
								}
								else
								{
									if (Shape.entitiesShape.Count >= 2)
									{
										CreateShapeDimension3Hole(Shape, Material, ValueType, ref entitiesDim);
									}
									SetView = PlaneNameToViewType(Shape.planeName);
								}
							}
							else
							{
								if (Shape.entitiesShape.Count >= 2)
								{
									CreateShapeDimension3Hole(Shape, Material, ValueType, ref entitiesDim);
								}
								SetView = PlaneNameToViewType(Shape.planeName);
							}
						}
						else
						{
							if (Shape.multiCenter != null && Shape.multiCenter.Count >= 2)
							{
								CreateShapeDimension2Point(Shape.multiCenter[0].Center, Shape.multiCenter[1].Center, Shape, Material, ValueType, ref entitiesDim);
							}
							SetView = PlaneNameToViewType(Shape.planeName);
						}
					}
					else
					{
						CreateShapeDimensionDepth(Shape, Material, ValueType, ref entitiesDim);
						if (!((Shape.planeName == planeBoxNames.Top) | (Shape.planeName == planeBoxNames.Bottom)))
						{
							SetView = viewType.Top;
						}
						else
						{
							SetView = viewType.Front;
						}
					}
				}
				else
				{
					CreateShapeDimensionAngle(Shape, Material, ValueType, ref entitiesDim);
					SetView = PlaneNameToViewType(Shape.planeName);
				}
			}
			else
			{
				CreateShapeDimensionDiameter(Shape, Material, ValueType, ref entitiesDim);
				SetView = PlaneNameToViewType(Shape.planeName);
			}
			return;
		}
		bool flag2 = false;
		if (Shape.entitiesDim != null)
		{
			for (int l = 0; l <= Shape.entitiesDim.Count - 1; l++)
			{
				if (Shape.entitiesDim[l].Info.Data == ShapeDataValueType.Diameter.ToString())
				{
					Entity copiedEntity4 = null;
					buEntity.Copy(Shape.entitiesDim[l], ref copiedEntity4);
					entitiesDim.Add(copiedEntity4);
					flag2 = true;
				}
			}
		}
		if (!flag2)
		{
			CreateShapeDimensionDiameter(Shape, Material, ValueType, ref entitiesDim);
		}
		SetView = PlaneNameToViewType(Shape.planeName);
	}

	public void calcBuShapeCommonForShapeEntities(ref buShape Shape, Point3D pntCalc, ShapeCreateParameters Pars, double Depth)
	{
		Point3D MoveDistance = new Point3D();
		List<buEntity> copiedEntities = null;
		CoordinateFromObjectLocation(Shape.Alignment, Shape.planeName, Shape.entitiesShape, ref MoveDistance);
		if (Shape.multiCenter != null && Shape.multiCenter.Count > 0)
		{
			copiedEntities = new List<buEntity>();
			buEntity.Copy(Shape.entitiesShape, ref copiedEntities);
			Shape.entitiesShape.Clear();
		}
		Move(MoveDistance.X + pntCalc.X, MoveDistance.Y + pntCalc.Y, MoveDistance.Z + pntCalc.Z, ref Shape.entitiesShape);
		if (Shape.entitiesShape.Count <= 0)
		{
			BoxSizeCalculate(copiedEntities, ref Shape.ItemSize.MinBox, ref Shape.ItemSize.MaxBox);
		}
		else
		{
			BoxSizeCalculate(Shape.entitiesShape[0], ref Shape.ItemSize.MinBox, ref Shape.ItemSize.MaxBox);
		}
		Shape.entitySolid.Clear();
		Shape.entitySolid = new List<Entity>();
		if (Shape.multiCenter != null && copiedEntities != null)
		{
			for (int i = 0; i <= Shape.multiCenter.Count - 1; i++)
			{
				List<buEntity> copiedEntities2 = new List<buEntity>();
				buEntity.Copy(copiedEntities, ref copiedEntities2);
				if (Shape.multiCenter[i].Diameter > 0.0)
				{
					for (int j = 0; j <= copiedEntities2.Count - 1; j++)
					{
						if (copiedEntities2[j] is buCircle)
						{
							((buCircle)copiedEntities2[j]).Radius = Shape.multiCenter[i].Diameter / 2.0;
							((buCircle)copiedEntities2[j]).Update(buEntityUpdateType.CircleCenterRadiusPlane);
						}
					}
				}
				Move(MoveDistance.X + Shape.multiCenter[i].Center.X, MoveDistance.Y + Shape.multiCenter[i].Center.Y, MoveDistance.Z + Shape.multiCenter[i].Center.Z, ref copiedEntities2);
				Shape.entitiesShape.AddRange(copiedEntities2);
			}
		}
		if (Shape.entitiesCam.Count > 0)
		{
			Move(MoveDistance.X + pntCalc.X, MoveDistance.Y + pntCalc.Y, MoveDistance.Z + pntCalc.Z, ref Shape.entitiesCam);
		}
		for (int k = 0; k <= Shape.entitiesShape.Count - 1; k++)
		{
			if ((k >= 1) & (Shape.DepthLevel.Count >= 2))
			{
				Depth = Shape.DepthLevel[1];
			}
			List<ICurve> list = new List<ICurve>();
			bool flag = true;
			if (!buCompare5.EQ(Shape.entitiesShape[k].StartPoint, Shape.entitiesShape[k].EndPoint, 0.01))
			{
				flag = false;
			}
			if (!flag)
			{
				Entity copiedEntity = null;
				buEntity.Copy(Shape.entitiesShape[k], ref copiedEntity);
				if (copiedEntity is CompositeCurve)
				{
					Line item = new Line(Shape.entitiesShape[k].EndPoint, Shape.entitiesShape[k].StartPoint);
					((CompositeCurve)copiedEntity).CurveList.Add(item);
					copiedEntity.Regen(0.01);
				}
				list.Add((ICurve)copiedEntity);
			}
			else
			{
				Entity copiedEntity2 = null;
				buEntity.Copy(Shape.entitiesShape[k], ref copiedEntity2);
				copiedEntity2.Regen(0.01);
				list.Add((ICurve)copiedEntity2);
			}
			if (Shape.planeName == planeBoxNames.Top)
			{
				Shape.CalculatedPoint.X = pntCalc.X;
				Shape.CalculatedPoint.Y = pntCalc.Y;
				Shape.CalculatedPoint.Z = pntCalc.Z;
			}
			if (Shape.planeName == planeBoxNames.Bottom)
			{
				Shape.CalculatedPoint.X = pntCalc.X;
				Shape.CalculatedPoint.Y = pntCalc.Y;
				Shape.CalculatedPoint.Z = 0.0;
			}
			if (Shape.planeName == planeBoxNames.Front)
			{
				Shape.CalculatedPoint.X = pntCalc.X;
				Shape.CalculatedPoint.Y = pntCalc.Y;
				Shape.CalculatedPoint.Z = pntCalc.Z;
			}
			if (Shape.planeName == planeBoxNames.Back)
			{
				Shape.CalculatedPoint.X = pntCalc.X;
				Shape.CalculatedPoint.Y = pntCalc.Y;
				Shape.CalculatedPoint.Z = pntCalc.Z;
			}
			if (Shape.planeName == planeBoxNames.Left)
			{
				Shape.CalculatedPoint.X = pntCalc.X;
				Shape.CalculatedPoint.Y = pntCalc.Y;
				Shape.CalculatedPoint.Z = pntCalc.Z;
			}
			if (Shape.planeName == planeBoxNames.Right)
			{
				Shape.CalculatedPoint.X = pntCalc.X;
				Shape.CalculatedPoint.Y = pntCalc.Y;
				Shape.CalculatedPoint.Z = pntCalc.Z;
			}
			Entity entSolid = null;
			calcBuShapeCommonSolidEntity(Shape, list, Pars, Depth, k, ref entSolid);
			if (entSolid != null)
			{
				Shape.entitySolid.Add(entSolid);
			}
		}
	}

	public void calcBuShapeCommonSolidEntity(buShape Shape, List<ICurve> CL, ShapeCreateParameters Pars, double Depth, int indexDepthLevel, ref Entity entSolid)
	{
		try
		{
			devDept.Eyeshot.Entities.Region region = new devDept.Eyeshot.Entities.Region(CL, Shape.planeOperation);
			if (region.Vertices == null)
			{
				region.Regen(0.01);
			}
			if (region.Vertices.Length <= 2)
			{
				return;
			}
			region.Translate(0.0, 0.0, Pars.StartOffset);
			region.Regen(0.01);
			if (Shape.planeName == planeBoxNames.Top)
			{
				entSolid = region.ExtrudeAsMesh(0.0 - (Depth + Pars.DepthOffset), Pars.SolidTolerance, Mesh.natureType.RichPlain);
				entSolid.Translate(0.0, 0.0, Pars.Size.Depth);
			}
			if (Shape.planeName == planeBoxNames.Bottom)
			{
				entSolid = region.ExtrudeAsMesh(Depth + Pars.DepthOffset, Pars.SolidTolerance, Mesh.natureType.RichPlain);
			}
			if (Shape.planeName == planeBoxNames.Back)
			{
				entSolid = region.ExtrudeAsMesh(Depth + Pars.DepthOffset, Pars.SolidTolerance, Mesh.natureType.RichPlain);
				if (Pars.SingY > 0.0)
				{
					entSolid.Translate(0.0, Pars.Size.Height);
				}
			}
			if (Shape.planeName == planeBoxNames.Front)
			{
				entSolid = region.ExtrudeAsMesh(0.0 - (Depth + Pars.DepthOffset), Pars.SolidTolerance, Mesh.natureType.RichPlain);
				if (Pars.SingY < 0.0)
				{
					entSolid.Translate(0.0, 0.0 - Pars.Size.Height);
				}
				entSolid.Regen(0.01);
			}
			if (Shape.planeName == planeBoxNames.Left)
			{
				entSolid = region.ExtrudeAsMesh((0.0 - Shape.CornerDirection.X) * (Depth + Pars.DepthOffset), Pars.SolidTolerance, Mesh.natureType.RichPlain);
				if (Pars.SingX < 0.0)
				{
					entSolid.Translate(0.0 - Pars.Size.Width, 0.0);
				}
			}
			if (Shape.planeName == planeBoxNames.Right)
			{
				entSolid = region.ExtrudeAsMesh((0.0 - Shape.CornerDirection.X) * (Depth + Pars.DepthOffset), Pars.SolidTolerance, Mesh.natureType.RichPlain);
				if (Pars.SingX > 0.0)
				{
					entSolid.Translate(Pars.Size.Width, 0.0);
				}
			}
			entSolid.ColorMethod = colorMethodType.byEntity;
			if (!((indexDepthLevel == 0) | (Shape.DepthLevel.Count == 0)))
			{
				entSolid.Color = buImage5.ColorToneChange(Pars.SolidColor, 1.0 + (double)indexDepthLevel * 0.2);
			}
			else
			{
				entSolid.Color = Color.FromArgb(200, Pars.SolidColor);
			}
			entSolid.Regen(0.01);
			if (!Shape.Enable)
			{
				entSolid.Color = Pars.SolidDisableColor;
			}
			if (Pars.LayerName.Trim().Length > 0)
			{
				entSolid.LayerName = Pars.LayerName.Trim();
			}
		}
		catch (Exception)
		{
		}
	}

	public Color setbuShapeColors(buShape S)
	{
		Color result = Color.FromArgb(clsVar5.VarbuShapeVisilation.colorOperation.Transperancy, clsVar5.VarbuShapeVisilation.colorOperation.Color);
		if (S.ShapeGroup == ShapeGroup.Drill)
		{
			result = Color.FromArgb(clsVar5.VarbuShapeVisilation.colorHole.Transperancy, clsVar5.VarbuShapeVisilation.colorHole.Color);
			if (((buShapeHole)S).isMilling)
			{
				result = buImage5.ColorToneChange(clsVar5.VarbuShapeVisilation.colorHole.Color, 0.8);
			}
		}
		if (S.ShapeGroup == ShapeGroup.Shape)
		{
			result = Color.FromArgb(clsVar5.VarbuShapeVisilation.colorShape.Transperancy, clsVar5.VarbuShapeVisilation.colorShape.Color);
		}
		if (S.ShapeGroup == ShapeGroup.Cut)
		{
			result = Color.FromArgb(clsVar5.VarbuShapeVisilation.colorCut.Transperancy, clsVar5.VarbuShapeVisilation.colorCut.Color);
			if (((buShapeCut)S).isMilling)
			{
				result = buImage5.ColorToneChange(clsVar5.VarbuShapeVisilation.colorCut.Color, 0.8);
			}
		}
		if (S.ShapeGroup == ShapeGroup.Profiling)
		{
			result = Color.FromArgb(clsVar5.VarbuShapeVisilation.colorProfiling.Transperancy, clsVar5.VarbuShapeVisilation.colorProfiling.Color);
		}
		if (S.ShapeGroup == ShapeGroup.Junction)
		{
			result = Color.FromArgb(clsVar5.VarbuShapeVisilation.colorJunktion.Transperancy, clsVar5.VarbuShapeVisilation.colorJunktion.Color);
			if (((buShapeJunction)S).isMilling)
			{
				result = buImage5.ColorToneChange(clsVar5.VarbuShapeVisilation.colorJunktion.Color, 0.8);
			}
		}
		if (S.ShapeGroup == ShapeGroup.Engraving)
		{
			result = Color.FromArgb(clsVar5.VarbuShapeVisilation.colorEngraving.Transperancy, clsVar5.VarbuShapeVisilation.colorEngraving.Color);
		}
		if (S.ShapeGroup == ShapeGroup.Text)
		{
			result = Color.FromArgb(clsVar5.VarbuShapeVisilation.colorText.Transperancy, clsVar5.VarbuShapeVisilation.colorText.Color);
		}
		if (!S.Enable)
		{
			result = Color.FromArgb(clsVar5.VarbuShapeVisilation.colorOperationDisable.Transperancy, clsVar5.VarbuShapeVisilation.colorOperationDisable.Color);
		}
		return result;
	}

	public void DrawWireArrowHead(Point3D pntArrow, Point3D pntTip, double ArrowHeadLenght, double ArrowHeadAngle, bool Reverse, Plane refPlane, ref List<Point3D> calcPoints)
	{
		calcPoints.Clear();
		calcPoints = new List<Point3D>();
		double num = PointAngle(pntArrow, pntTip, refPlane);
		if (Reverse)
		{
			num = PointAngle(pntTip, pntArrow, refPlane);
		}
		Point3D EndPnt = new Point3D();
		Point3D EndPnt2 = new Point3D();
		LineWithLengthAndAngle(pntArrow, ArrowHeadLenght, num + ArrowHeadAngle, refPlane, ref EndPnt);
		LineWithLengthAndAngle(pntArrow, ArrowHeadLenght, num - ArrowHeadAngle, refPlane, ref EndPnt2);
		calcPoints.Add(EndPnt);
		calcPoints.Add(pntArrow);
		calcPoints.Add(EndPnt2);
	}

	public void DrawWireArrow(Point3D pntStart, Point3D pntTip, double ArrowHeadLenght, double ArrowHeadAngle, Plane refPlane, ref List<Entity> calcEntities)
	{
		double num = PointAngle(pntStart, pntTip, refPlane);
		Point3D EndPnt = new Point3D();
		Point3D EndPnt2 = new Point3D();
		LineWithLengthAndAngle(pntTip, ArrowHeadLenght, num + ArrowHeadAngle, ref EndPnt);
		LineWithLengthAndAngle(pntTip, ArrowHeadLenght, num - ArrowHeadAngle, ref EndPnt2);
		Entity item = new Line(pntStart, pntTip);
		List<Point3D> list = new List<Point3D>();
		list.Add(EndPnt);
		list.Add(pntTip);
		list.Add(EndPnt2);
		Entity item2 = new LinearPath(list);
		calcEntities.Clear();
		calcEntities = new List<Entity>();
		calcEntities.Add(item);
		calcEntities.Add(item2);
	}

	public void TriangleAtPointByLineRef(Point3D BasePoint, Point3D RefPoint, double TrianglePointAngle, double TriangleLength, Plane Plane, bool Reverse, bool FromBaseLine, ref List<Point3D> TriangleVertice)
	{
		try
		{
			Point3D FirstPoint = new Point3D();
			Point3D SecondPoint = new Point3D();
			Point3D ThirdPoint = new Point3D();
			TriangleAtPointByLineRef(BasePoint, RefPoint, TrianglePointAngle, TriangleLength, Plane, Reverse, FromBaseLine, ref FirstPoint, ref SecondPoint, ref ThirdPoint);
			TriangleVertice.Clear();
			TriangleVertice.Add(FirstPoint);
			TriangleVertice.Add(SecondPoint);
			TriangleVertice.Add(ThirdPoint);
		}
		catch (Exception mSException)
		{
			string text = "BasePoint: " + BasePoint.ToString() + " - RefPoint: " + RefPoint.ToString() + " - TrianglePointAngle: " + TrianglePointAngle + " - TriangleLength: " + TriangleLength + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void TriangleAtPointByLineRef(Point3D BasePoint, Point3D RefPoint, double TrianglePointAngle, double TriangleLength, Plane Plane, bool Reverse, bool FromBaseLine, ref Point3D FirstPoint, ref Point3D SecondPoint, ref Point3D ThirdPoint)
	{
		try
		{
			Point3D EndPnt = new Point3D();
			double num = 0.0;
			double num2 = 0.0;
			Point3D point3D = ToPoint3D(BasePoint);
			if (Reverse)
			{
				num2 = 180.0;
			}
			num = PointAngle(RefPoint, BasePoint, Plane);
			if (FromBaseLine)
			{
				num = PointAngle(BasePoint, RefPoint, Plane);
				point3D = ToPoint3D(RefPoint);
			}
			LineWithLengthAndAngle(point3D, TriangleLength, num + TrianglePointAngle + num2, Plane, ref EndPnt);
			FirstPoint = ToPoint3D(point3D);
			SecondPoint = ToPoint3D(EndPnt);
			EndPnt = new Point3D();
			LineWithLengthAndAngle(point3D, TriangleLength, num - TrianglePointAngle + num2, Plane, ref EndPnt);
			ThirdPoint = ToPoint3D(EndPnt);
		}
		catch (Exception mSException)
		{
			string text = "BasePoint: " + BasePoint.ToString() + " - RefPoint: " + RefPoint.ToString() + " - TrianglePointAngle: " + TrianglePointAngle + " - TriangleLength: " + TriangleLength + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void QuadToTriangle(Quad3D Quad, ref Triangle3D FirstTriangle, ref Triangle3D SecondTriangle)
	{
		try
		{
			double num = 0.0;
			double num2 = 0.0;
			Pnt3D pnt3D = new Pnt3D();
			num = Length3D(Quad.FirstPoint, Quad.ThirdPoint);
			num2 = Length3D(Quad.SecondPoint, Quad.FourthPoint);
			if (!(num > num2))
			{
				pnt3D = new Pnt3D();
				pnt3D = new Pnt3D(Quad.SecondPoint);
				FirstTriangle.FirstPoint = new Pnt3D(pnt3D);
				pnt3D = new Pnt3D();
				pnt3D = new Pnt3D(Quad.ThirdPoint);
				FirstTriangle.SecondPoint = new Pnt3D(pnt3D);
				pnt3D = new Pnt3D();
				pnt3D = new Pnt3D(Quad.FourthPoint);
				FirstTriangle.ThirdPoint = new Pnt3D(pnt3D);
				pnt3D = new Pnt3D();
				pnt3D = new Pnt3D(Quad.SecondPoint);
				SecondTriangle.FirstPoint = new Pnt3D(pnt3D);
				pnt3D = new Pnt3D();
				pnt3D = new Pnt3D(Quad.FourthPoint);
				SecondTriangle.SecondPoint = new Pnt3D(pnt3D);
				pnt3D = new Pnt3D();
				pnt3D = new Pnt3D(Quad.FirstPoint);
				SecondTriangle.ThirdPoint = new Pnt3D(pnt3D);
			}
			else
			{
				pnt3D = new Pnt3D();
				pnt3D = new Pnt3D(Quad.FirstPoint);
				FirstTriangle.FirstPoint = new Pnt3D(pnt3D);
				pnt3D = new Pnt3D();
				pnt3D = new Pnt3D(Quad.SecondPoint);
				FirstTriangle.SecondPoint = new Pnt3D(pnt3D);
				pnt3D = new Pnt3D();
				pnt3D = new Pnt3D(Quad.ThirdPoint);
				FirstTriangle.ThirdPoint = new Pnt3D(pnt3D);
				pnt3D = new Pnt3D();
				pnt3D = new Pnt3D(Quad.FirstPoint);
				SecondTriangle.FirstPoint = new Pnt3D(pnt3D);
				pnt3D = new Pnt3D();
				pnt3D = new Pnt3D(Quad.ThirdPoint);
				SecondTriangle.SecondPoint = new Pnt3D(pnt3D);
				pnt3D = new Pnt3D();
				pnt3D = new Pnt3D(Quad.FourthPoint);
				SecondTriangle.ThirdPoint = new Pnt3D(pnt3D);
			}
		}
		catch (Exception mSException)
		{
			string text = "Quad: " + Quad.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
