	public double RegenDevisionFromRadius(double Rad)
	{
		if (!(Rad < 1.0))
		{
			if (!(Rad >= 1.0 && Rad < 2.0))
			{
				if (!(Rad >= 2.0 && Rad < 4.0))
				{
					if (!(Rad >= 4.0 && Rad < 8.0))
					{
						if (!(Rad >= 8.0 && Rad < 15.0))
						{
							if (!(Rad >= 15.0 && Rad < 25.0))
							{
								if (!(Rad >= 25.0 && Rad < 50.0))
								{
									if (!(Rad >= 50.0 && Rad < 100.0))
									{
										if (!(Rad >= 100.0 && Rad < 10000000000000.0))
										{
											return 0.05;
										}
										return 0.05;
									}
									return 0.05;
								}
								return 0.04;
							}
							return 0.03;
						}
						return 0.02;
					}
					return 0.01;
				}
				return 0.01;
			}
			return 0.01;
		}
		return 0.005;
	}

	public void ArcWithCenter(Point3D Center, double Radius, double StartAngle, double EndAngle, Plane refPlane, EntityResolution EntResolution, ref List<Point3D> Vertices)
	{
		try
		{
			int num = 0;
			Point3D point3D = new Point3D();
			Vertices.Clear();
			num = ArcVerticeCountByResolution(Radius, StartAngle, EndAngle, EntResolution);
			for (int i = 0; i <= num; i++)
			{
				point3D = new Point3D();
				if (isPlaneXYorYX(refPlane))
				{
					point3D.X = Center.X + Radius * Math.Cos(buConversion5.DegreeToRadianGreat360(StartAngle + (double)i * (EndAngle - StartAngle) / (double)num));
					point3D.Y = Center.Y + Radius * Math.Sin(buConversion5.DegreeToRadianGreat360(StartAngle + (double)i * (EndAngle - StartAngle) / (double)num));
					point3D.Z = Center.Z;
					Vertices.Add(point3D);
				}
				if (isPlaneXZorZX(refPlane))
				{
					point3D.X = Center.X + Radius * Math.Cos(buConversion5.DegreeToRadianGreat360(StartAngle + (double)i * (EndAngle - StartAngle) / (double)num));
					point3D.Y = Center.Y;
					point3D.Z = Center.Z + Radius * Math.Sin(buConversion5.DegreeToRadianGreat360(StartAngle + (double)i * (EndAngle - StartAngle) / (double)num));
					Vertices.Add(point3D);
				}
				if (isPlaneYZorZY(refPlane))
				{
					point3D.X = Center.X;
					point3D.Y = Center.Y + Radius * Math.Cos(buConversion5.DegreeToRadianGreat360(StartAngle + (double)i * (EndAngle - StartAngle) / (double)num));
					point3D.Z = Center.Z + Radius * Math.Sin(buConversion5.DegreeToRadianGreat360(StartAngle + (double)i * (EndAngle - StartAngle) / (double)num));
					Vertices.Add(point3D);
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "Center: " + Center.ToString() + " - Rad: " + Radius + " - SA: " + StartAngle + " - EA: " + EndAngle + " - Plane: " + refPlane.ToString() + " - EntResolution: " + EntResolution.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public double ArcCircumference(double Radius, double StartAngle, double EndAngle)
	{
		try
		{
			return Radius * Math.PI * 2.0 * (EndAngle - StartAngle) / 360.0;
		}
		catch (Exception mSException)
		{
			string text = "R: " + Radius + " - SA: " + StartAngle + " - EA: " + EndAngle;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return 0.0;
		}
	}

	public void ArcTo3Point(buEntity RefArc, ref List<Point3D> Points)
	{
		try
		{
			if (RefArc.GetType() == typeof(buArc) && RefArc.Vertices.Count >= 3)
			{
				if (RefArc.sortDirection == entitySortDirection.Normal)
				{
					int index = Convert.ToInt32(RefArc.Vertices.Count / 2);
					Points.Add(ToPoint3D(RefArc.Vertices[0]));
					Points.Add(ToPoint3D(RefArc.Vertices[index]));
					Points.Add(ToPoint3D(RefArc.Vertices[RefArc.Vertices.Count - 1]));
				}
				if (RefArc.sortDirection == entitySortDirection.Reverse)
				{
					int index2 = Convert.ToInt32(RefArc.Vertices.Count / 2);
					Points.Add(ToPoint3D(RefArc.Vertices[RefArc.Vertices.Count - 1]));
					Points.Add(ToPoint3D(RefArc.Vertices[index2]));
					Points.Add(ToPoint3D(RefArc.Vertices[0]));
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "RefArc: " + RefArc.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void ArcToTwoArc(buArc refArc, ref buEntity Arc1, ref buEntity Arc2)
	{
		Entity copiedEntity = null;
		buEntity.Copy(refArc, ref copiedEntity);
		double num = refArc.EndAngle - refArc.StartAngle;
		if (num > 1.0)
		{
			ICurve lower = null;
			ICurve upper = null;
			((Arc)copiedEntity).SplitAt(((Arc)copiedEntity).Domain.Mid, out lower, out upper);
			buEntity.Copy((Entity)lower, ref Arc1);
			buEntity.Copy((Entity)upper, ref Arc2);
		}
	}

	public void ArcToTwoArc(Arc refArc, ref Entity Arc1, ref Entity Arc2)
	{
		if (refArc.AngleInDegrees > 0.1)
		{
			ICurve lower = null;
			ICurve upper = null;
			refArc.SplitAt(refArc.Domain.Mid, out lower, out upper);
			buEntity.Copy((Entity)lower, ref Arc1);
			buEntity.Copy((Entity)upper, ref Arc2);
			CopyEntityProperties(refArc, ref Arc1);
			CopyEntityProperties(refArc, ref Arc1);
		}
	}

