	public void ArcEllipseToLineer(Point3D Center, double Major, double Minor, double StartAngle, double EndAngle, double Angle, double Length, Plane refPlane, ref List<Point3D> Vertices)
	{
		try
		{
			double num = 0.0;
			double num2 = 0.0;
			double num3 = 0.0;
			double num4 = 0.0;
			double num5 = 0.0;
			double num6 = 0.0;
			int num7 = 0;
			double num8 = 0.0;
			double num9 = 0.0;
			double num10 = 0.0;
			Point3D point3D = new Point3D();
			Vertices.Clear();
			if (Length <= 0.0)
			{
				return;
			}
			num = EndAngle - StartAngle;
			num3 = Math.PI * 2.0 * Math.Sqrt(0.5 * (Math.Pow(Major, 2.0) + Math.Pow(Minor, 2.0)));
			num7 = Convert.ToInt32(num3 / Length);
			if (num7 <= 0)
			{
				return;
			}
			if (num7 > 0)
			{
				num2 = num / (double)num7;
			}
			num6 = (360.0 - Angle) * Math.PI / 180.0;
			num4 = Math.Sin(num6);
			num5 = Math.Cos(num6);
			for (int i = 0; i <= num7; i++)
			{
				point3D = new Point3D();
				num8 = StartAngle + (double)i * num2;
				num9 = Major * Math.Cos(buConversion5.DegreeToRadianGreat360(num8));
				num10 = Minor * Math.Sin(buConversion5.DegreeToRadianGreat360(num8));
				if (isPlaneXYorYX(refPlane))
				{
					point3D.X = Center.X + num9 * num5 + num10 * num4;
					point3D.Y = Center.Y - num9 * num4 + num10 * num5;
					point3D.Z = Center.Z;
				}
				if (isPlaneXZorZX(refPlane))
				{
					point3D.X = Center.X + num9 * num5 + num10 * num4;
					point3D.Y = Center.Y;
					point3D.Z = Center.Z - num9 * num4 + num10 * num5;
				}
				if (isPlaneYZorZY(refPlane))
				{
					point3D.X = Center.X;
					point3D.Y = Center.Y + num9 * num5 + num10 * num4;
					point3D.Z = Center.Z - num9 * num4 + num10 * num5;
				}
				Vertices.Add(point3D);
			}
		}
		catch (Exception mSException)
		{
			string text = "Center: " + Center.ToString() + " - MajRad: " + Major + " - MinRad: " + Minor + " - SA: " + StartAngle + " - EA: " + EndAngle + " - Ang: " + Angle + " - Len: " + Length;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void EllipseToLineer(Point3D Center, double Major, double Minor, double Angle, double Length, Plane refPlane, ref List<Point3D> Vertices)
	{
		try
		{
			double num = 0.0;
			double num2 = 360.0;
			double num3 = 0.0;
			double num4 = 0.0;
			double num5 = 0.0;
			double num6 = 0.0;
			double num7 = 0.0;
			double num8 = 0.0;
			int num9 = 0;
			double num10 = 0.0;
			double num11 = 0.0;
			double num12 = 0.0;
			Point3D point3D = new Point3D();
			Vertices.Clear();
			if (Length <= 0.0)
			{
				return;
			}
			num3 = num2 - num;
			num5 = Math.PI * 2.0 * Math.Sqrt(0.5 * (Math.Pow(Major, 2.0) + Math.Pow(Minor, 2.0)));
			num9 = Convert.ToInt32(num5 / Length);
			if (num9 <= 0)
			{
				return;
			}
			if (num9 > 0)
			{
				num4 = num3 / (double)num9;
			}
			num8 = (360.0 - Angle) * Math.PI / 180.0;
			num6 = Math.Sin(num8);
			num7 = Math.Cos(num8);
			for (int i = 0; i <= num9; i++)
			{
				point3D = new Point3D();
				num10 = num + (double)i * num4;
				num11 = Major * Math.Cos(buConversion5.DegreeToRadianGreat360(num10));
				num12 = Minor * Math.Sin(buConversion5.DegreeToRadianGreat360(num10));
				if (isPlaneXYorYX(refPlane))
				{
					point3D.X = Center.X + num11 * num7 + num12 * num6;
					point3D.Y = Center.Y - num11 * num6 + num12 * num7;
					point3D.Z = Center.Z;
				}
				if (isPlaneXZorZX(refPlane))
				{
					point3D.X = Center.X + num11 * num7 + num12 * num6;
					point3D.Y = Center.Y;
					point3D.Z = Center.Z - num11 * num6 + num12 * num7;
				}
				if (isPlaneYZorZY(refPlane))
				{
					point3D.X = Center.X;
					point3D.Y = Center.Y + num11 * num7 + num12 * num6;
					point3D.Z = Center.Z - num11 * num6 + num12 * num7;
				}
				Vertices.Add(point3D);
			}
		}
		catch (Exception mSException)
		{
			string text = "Center: " + Center.ToString() + " - MajRad: " + Major + " - MinRad: " + Minor + " - Ang: " + Angle + " - Len: " + Length;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

