		buEntity BottomFirstLine = null;
		buEntity TopLastLine = null;
		buEntity BottomLastLine = null;
		Trapezoid3D(TopLeftPoint, TrapezTopWidth, TrapezHeight, TrapezTopLeftAngle, TrapezTopRightAngle, LengthDirection, DirectionLength, Rotation, ref TopFirstLine, ref BottomFirstLine, ref TopLastLine, ref BottomLastLine, ref SurfaceEntity);
