	public void Trapezoid3D(Point3D TopLeftPoint, double TrapezTopWidth, double TrapezHeight, double TrapezTopLeftAngle, double TrapezTopRightAngle, Vec3D LengthDirection, double DirectionLength, double Rotation, ref buEntity TopFirstLine, ref buEntity BottomFirstLine, ref buEntity TopLastLine, ref buEntity BottomLastLine, ref Entity SurfaceEntity)
	{
		Point3D point3D = new Point3D();
		Point3D point3D2 = new Point3D();
		Point3D CalcPoint = new Point3D();
		Point3D CalcPoint2 = new Point3D();
		AlingmentPoints3D AlignPoints = new AlingmentPoints3D();
		new List<Point3D>();
		List<Point3D> Points = new List<Point3D>();
		List<Point3D> copiedPoint = new List<Point3D>();
		new List<Point3D>();
		new Quad3D();
		new Triangle3D();
		new Triangle3D();
		Plane pln = Plane.XY;
		if (Vec3D.isVectorZAxis(LengthDirection))
		{
			pln = Plane.XY;
			point3D = new Point3D(0.0, TrapezHeight, 0.0);
			point3D2 = new Point3D(TrapezTopWidth, TrapezHeight, 0.0);
			DiagonalLengthByAnglePerpendicularDistance(point3D, 90.0 - TrapezTopLeftAngle, 0.0 - TrapezHeight, Plane.XY, ref CalcPoint);
			DiagonalLengthByAnglePerpendicularDistance(point3D2, TrapezTopRightAngle - 90.0, 0.0 - TrapezHeight, Plane.XY, ref CalcPoint2);
			Points.Add(point3D);
			Points.Add(point3D2);
			Points.Add(CalcPoint2);
			Points.Add(CalcPoint);
			Points.Add(point3D);
			BoxSizeWithContentAlignment(Points, new WorkPlane(LengthDirection), ref AlignPoints);
			Move(AlignPoints.pntTopLeft, TopLeftPoint, ref Points);
			ClockDirectionType clockDirection = GetClockDirection(Points, Plane.YZ);
			if (clockDirection == ClockDirectionType.CW)
			{
				Points.Reverse();
			}
		}
		if (Vec3D.isVectorYAxis(LengthDirection))
		{
			double angle = Rotation - 90.0;
			pln = Plane.XZ;
			point3D = new Point3D(0.0, 0.0, TrapezHeight);
			point3D2 = new Point3D(TrapezTopWidth, 0.0, TrapezHeight);
			DiagonalLengthByAnglePerpendicularDistance(point3D, 90.0 - TrapezTopLeftAngle, 0.0 - TrapezHeight, Plane.XZ, ref CalcPoint);
			DiagonalLengthByAnglePerpendicularDistance(point3D2, TrapezTopRightAngle - 90.0, 0.0 - TrapezHeight, Plane.XZ, ref CalcPoint2);
			Points.Add(point3D);
			Points.Add(point3D2);
			Points.Add(CalcPoint2);
			Points.Add(CalcPoint);
			Points.Add(point3D);
			BoxSizeWithContentAlignment(Points, new WorkPlane(LengthDirection), ref AlignPoints);
			Move(AlignPoints.pntTopLeft, TopLeftPoint, ref Points);
			Copy(Points, ref copiedPoint);
			Rotate(TopLeftPoint, angle, Plane.XY, ref Points);
			pln = new Plane(Points[0], Points[1], Points[2]);
			OffsetPoint3D(ref copiedPoint, 0.0, DirectionLength, 0.0);
			Rotate(TopLeftPoint, angle, Plane.XY, ref copiedPoint);
			TopFirstLine = new buLine(Points[0], copiedPoint[0]);
			BottomFirstLine = new buLine(Points[3], copiedPoint[3]);
			BottomLastLine = new buLine(Points[2], copiedPoint[2]);
			TopLastLine = new buLine(Points[1], copiedPoint[1]);
		}
		if (Vec3D.isVectorXAxis(LengthDirection))
		{
			double angle2 = 0.0 - Rotation;
			pln = Plane.YZ;
			point3D = new Point3D(0.0, 0.0, TrapezHeight);
			point3D2 = new Point3D(0.0, TrapezTopWidth, TrapezHeight);
			DiagonalLengthByAnglePerpendicularDistance(point3D, 90.0 - TrapezTopLeftAngle, 0.0 - TrapezHeight, Plane.YZ, ref CalcPoint);
			DiagonalLengthByAnglePerpendicularDistance(point3D2, TrapezTopRightAngle - 90.0, 0.0 - TrapezHeight, Plane.YZ, ref CalcPoint2);
			Points.Add(point3D);
			Points.Add(CalcPoint);
			Points.Add(CalcPoint2);
			Points.Add(point3D2);
			Points.Add(point3D);
			BoxSizeWithContentAlignment(Points, new WorkPlane(LengthDirection), ref AlignPoints);
			Move(AlignPoints.pntTopLeft, TopLeftPoint, ref Points);
			Copy(Points, ref copiedPoint);
			Rotate(TopLeftPoint, angle2, Plane.XY, ref Points);
			pln = new Plane(Points[0], Points[1], Points[2]);
			OffsetPoint3D(ref copiedPoint, DirectionLength, 0.0, 0.0);
			Rotate(TopLeftPoint, angle2, Plane.XY, ref copiedPoint);
			TopFirstLine = new buLine(Points[0], copiedPoint[0]);
			BottomFirstLine = new buLine(Points[1], copiedPoint[1]);
			BottomLastLine = new buLine(Points[2], copiedPoint[2]);
			TopLastLine = new buLine(Points[3], copiedPoint[3]);
		}
		LinearPath outer = new LinearPath(Points);
		devDept.Eyeshot.Entities.Region region = new devDept.Eyeshot.Entities.Region(outer, pln);
		Brep brep = region.ExtrudeAsBrep(DirectionLength);
		SurfaceEntity = brep;
	}

	public void TrapezoidPerpendicular(Point3D BottomLeftPoint, double BottomWidth, double TopWidth, double TrapezHeight, double Rotation, double Thickness, bool CreateAsCompositeCurve, ref List<Point3D> Vertice2D, ref ICurve WireEntitiy, ref Entity SurfaceEntity)
	{
		try
		{
			Vertice2D.Clear();
			Vertice2D = new List<Point3D>();
			Vertice2D.Add(new Point3D(BottomLeftPoint.X, BottomLeftPoint.Y, 0.0));
			Vertice2D.Add(new Point3D(BottomLeftPoint.X + BottomWidth, BottomLeftPoint.Y, 0.0));
			Vertice2D.Add(new Point3D(BottomLeftPoint.X + TopWidth, BottomLeftPoint.Y + TrapezHeight, 0.0));
			Vertice2D.Add(new Point3D(BottomLeftPoint.X, BottomLeftPoint.Y + TrapezHeight, 0.0));
			Vertice2D.Add(new Point3D(BottomLeftPoint.X, BottomLeftPoint.Y, 0.0));
			Rotate(BottomLeftPoint, Rotation, Plane.XY, ref Vertice2D);
			Plane xY = Plane.XY;
			xY = new Plane(Vertice2D[0], Vertice2D[1], Vertice2D[2]);
			if (CreateAsCompositeCurve)
			{
				List<ICurve> list = new List<ICurve>();
				for (int i = 1; i <= Vertice2D.Count - 1; i++)
				{
					list.Add(new Line(Vertice2D[i - 1], Vertice2D[i]));
				}
				WireEntitiy = new CompositeCurve(list);
			}
			else
			{
				WireEntitiy = new LinearPath(Vertice2D);
			}
			devDept.Eyeshot.Entities.Region region = new devDept.Eyeshot.Entities.Region(WireEntitiy, xY);
			Brep brep = region.ExtrudeAsBrep(Thickness);
			SurfaceEntity = brep;
		}
		catch (Exception)
		{
		}
	}

	public void RectangleChamfer(Point3D CornerPnt1, double Width, double Height, double Chamfer, Plane Plane, ref List<Point3D> Points)
	{
		Point3D cornerPnt = new Point3D();
		if (isPlaneXYorYX(Plane))
		{
			cornerPnt = new Point3D(CornerPnt1.X + Width, CornerPnt1.Y + Height, CornerPnt1.Z);
		}
		if (isPlaneXZorZX(Plane))
		{
			cornerPnt = new Point3D(CornerPnt1.X + Width, CornerPnt1.Y, CornerPnt1.Z + Height);
		}
		if (isPlaneYZ(Plane))
		{
			cornerPnt = new Point3D(CornerPnt1.X, CornerPnt1.Y + Width, CornerPnt1.Z + Height);
		}
		RectangleChamfer(CornerPnt1, cornerPnt, Chamfer, Plane, ref Points);
	}

	public void RectangleChamfer(Point3D CornerPnt1, Point3D CornerPnt2, double Chamfer, Plane Plane, ref List<Point3D> Points)
	{
		try
		{
			double num = 0.0;
			double num2 = 0.0;
			double num3 = 0.0;
			Points.Clear();
			if (isPlaneXYorYX(Plane))
			{
				num = Math.Sqrt(Math.Pow(Chamfer, 2.0) / 2.0);
				num2 = Math.Sqrt(Math.Pow(Chamfer, 2.0) / 2.0);
				if (!(CornerPnt2.X > CornerPnt1.X))
				{
					if (!(CornerPnt2.Y > CornerPnt1.Y))
					{
						num *= -1.0;
						num2 *= -1.0;
					}
					else
					{
						num *= -1.0;
						num2 *= 1.0;
					}
				}
				else if (!(CornerPnt2.Y > CornerPnt1.Y))
				{
					num *= 1.0;
					num2 *= -1.0;
				}
				else
				{
					num *= 1.0;
					num2 *= 1.0;
				}
				Points.Add(new Point3D(CornerPnt1.X + num, CornerPnt1.Y, CornerPnt1.Z));
				Points.Add(new Point3D(CornerPnt2.X - num, CornerPnt1.Y, CornerPnt1.Z));
				Points.Add(new Point3D(CornerPnt2.X, CornerPnt1.Y + num2, CornerPnt1.Z));
				Points.Add(new Point3D(CornerPnt2.X, CornerPnt2.Y - num2, CornerPnt1.Z));
				Points.Add(new Point3D(CornerPnt2.X - num, CornerPnt2.Y, CornerPnt1.Z));
				Points.Add(new Point3D(CornerPnt1.X + num, CornerPnt2.Y, CornerPnt1.Z));
				Points.Add(new Point3D(CornerPnt1.X, CornerPnt2.Y - num2, CornerPnt1.Z));
				Points.Add(new Point3D(CornerPnt1.X, CornerPnt1.Y + num2, CornerPnt1.Z));
				Points.Add(new Point3D(CornerPnt1.X + num, CornerPnt1.Y, CornerPnt1.Z));
			}
			if (isPlaneXZorZX(Plane))
			{
				num = Math.Sqrt(Math.Pow(Chamfer, 2.0) / 2.0);
				num3 = Math.Sqrt(Math.Pow(Chamfer, 2.0) / 2.0);
				if (!(CornerPnt2.X > CornerPnt1.X))
				{
					if (!(CornerPnt2.Z > CornerPnt1.Z))
					{
						num *= -1.0;
						num3 *= -1.0;
					}
					else
					{
						num *= -1.0;
						num3 *= 1.0;
					}
				}
				else if (!(CornerPnt2.Z > CornerPnt1.Z))
				{
					num *= 1.0;
					num3 *= -1.0;
				}
				else
				{
					num *= 1.0;
					num3 *= 1.0;
				}
				Points.Add(new Point3D(CornerPnt1.X, CornerPnt1.Y, CornerPnt1.Z + num3));
				Points.Add(new Point3D(CornerPnt1.X, CornerPnt1.Y, CornerPnt2.Z - num3));
				Points.Add(new Point3D(CornerPnt1.X + num, CornerPnt1.Y, CornerPnt2.Z));
				Points.Add(new Point3D(CornerPnt2.X - num, CornerPnt1.Y, CornerPnt2.Z));
				Points.Add(new Point3D(CornerPnt2.X, CornerPnt1.Y, CornerPnt2.Z - num3));
				Points.Add(new Point3D(CornerPnt2.X, CornerPnt1.Y, CornerPnt1.Z + num3));
				Points.Add(new Point3D(CornerPnt2.X - num, CornerPnt1.Y, CornerPnt1.Z));
				Points.Add(new Point3D(CornerPnt1.X + num, CornerPnt1.Y, CornerPnt1.Z));
				Points.Add(new Point3D(CornerPnt1.X, CornerPnt1.Y, CornerPnt1.Z + num3));
				Points.Add(new Point3D());
			}
			if (!isPlaneYZorZY(Plane))
			{
				return;
			}
			num2 = Math.Sqrt(Math.Pow(Chamfer, 2.0) / 2.0);
			num3 = Math.Sqrt(Math.Pow(Chamfer, 2.0) / 2.0);
			if (!(CornerPnt2.Y > CornerPnt1.Y))
			{
				if (!(CornerPnt2.Z > CornerPnt1.Z))
				{
					num2 *= -1.0;
					num3 *= -1.0;
				}
				else
				{
					num2 *= -1.0;
					num3 *= 1.0;
				}
			}
			else if (!(CornerPnt2.Z > CornerPnt1.Z))
			{
				num2 *= 1.0;
				num3 *= -1.0;
			}
			else
			{
				num2 *= 1.0;
				num3 *= 1.0;
			}
			Points.Add(new Point3D(CornerPnt1.X, CornerPnt1.Y, CornerPnt1.Z + num3));
			Points.Add(new Point3D(CornerPnt1.X, CornerPnt1.Y, CornerPnt2.Z - num3));
			Points.Add(new Point3D(CornerPnt1.X, CornerPnt1.Y + num2, CornerPnt2.Z));
			Points.Add(new Point3D(CornerPnt1.X, CornerPnt2.Y - num2, CornerPnt2.Z));
			Points.Add(new Point3D(CornerPnt1.X, CornerPnt2.Y, CornerPnt2.Z - num3));
			Points.Add(new Point3D(CornerPnt1.X, CornerPnt2.Y, CornerPnt1.Z + num3));
			Points.Add(new Point3D(CornerPnt2.X, CornerPnt2.Y - num2, CornerPnt1.Z));
			Points.Add(new Point3D(CornerPnt1.X, CornerPnt1.Y + num2, CornerPnt1.Z));
			Points.Add(new Point3D(CornerPnt1.X, CornerPnt1.Y, CornerPnt1.Z + num3));
		}
		catch (Exception mSException)
		{
			string text = "CornerPnt1: " + CornerPnt1.ToString() + " - CornerPnt2: " + CornerPnt2.ToString() + " - Plane: " + Plane.ToString() + " - Chamfer: " + Chamfer;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

