	}

	public void Rectangle3Point(Point3D FirstPoint, Point3D SecondPoint, Point3D ThirdPoint, Plane refPlane, ref List<Point3D> Vertices, ref Point3D ConnectPoint)
	{
		try
		{
			double num = 0.0;
			double num2 = 0.0;
			double num3 = 0.0;
			double num4 = 0.0;
			double num5 = 0.0;
			int num6 = 0;
			Point3D pntOver = new Point3D();
			Point3D point3D = new Point3D();
			Point3D point3D2 = new Point3D();
			Point3D point3D3 = new Point3D();
			Vertices.Clear();
			if (isPointReflectionOverLine(FirstPoint, SecondPoint, ThirdPoint, 0.1, ref pntOver) && IsPointInsideLine(FirstPoint, SecondPoint, ThirdPoint, refPlane, 0.1))
			{
				Vertices.Add(ToPoint3D(FirstPoint));
				Vertices.Add(ToPoint3D(SecondPoint));
			}
			if (!isPointReflectionOverLine(FirstPoint, SecondPoint, ThirdPoint, 0.1, ref pntOver))
			{
				num = Length3D(FirstPoint, ThirdPoint);
				num2 = Length3D(SecondPoint, ThirdPoint);
				point3D = ((num < num2) ? ToPoint3D(FirstPoint) : ToPoint3D(SecondPoint));
			}
			else
			{
				point3D = pntOver;
			}
			ConnectPoint = ToPoint3D(point3D);
			num = Length3D(point3D, ThirdPoint);
			num2 = Length3D(FirstPoint, SecondPoint);
			num5 = PointAngle(FirstPoint, SecondPoint, refPlane);
			Vertices.Add(ToPoint3D(FirstPoint));
			Vertices.Add(ToPoint3D(SecondPoint));
			Point3D StartPnt = new Point3D();
			Point3D StartPnt2 = new Point3D();
			Point3D EndPnt = new Point3D();
			Point3D EndPnt2 = new Point3D();
			LineWithLengthAndAngle(SecondPoint, num, num5 - 90.0, refPlane, ref StartPnt, ref EndPnt);
			LineWithLengthAndAngle(SecondPoint, num, num5 + 90.0, refPlane, ref StartPnt2, ref EndPnt2);
			num3 = Length3D(EndPnt, ThirdPoint);
			num4 = Length3D(EndPnt2, ThirdPoint);
			if (!(num3 < num4))
			{
				Vertices.Add(ToPoint3D(EndPnt2));
				point3D2 = ToPoint3D(StartPnt2);
				point3D3 = ToPoint3D(EndPnt2);
				num6 = 1;
			}
			else
			{
				Vertices.Add(ToPoint3D(EndPnt));
				point3D2 = ToPoint3D(StartPnt);
				point3D3 = ToPoint3D(EndPnt);
				num6 = -1;
			}
			num5 = PointAngle(point3D2, point3D3, refPlane);
			LineWithLengthAndAngle(point3D3, num2, num5 + (double)(90 * num6), refPlane, ref StartPnt, ref EndPnt);
			Vertices.Add(ToPoint3D(EndPnt));
			point3D2 = ToPoint3D(StartPnt);
			point3D3 = ToPoint3D(EndPnt);
			num5 = PointAngle(point3D2, point3D3, refPlane);
			LineWithLengthAndAngle(point3D3, num, num5 + (double)(90 * num6), refPlane, ref StartPnt, ref EndPnt);
			Vertices.Add(ToPoint3D(EndPnt));
			point3D2 = ToPoint3D(StartPnt);
			point3D3 = ToPoint3D(EndPnt);
		}
		catch (Exception mSException)
		{
			string text = "FirstPoint: " + FirstPoint.ToString() + " - SecondPoint: " + SecondPoint.ToString() + " - ThirdPoint: " + ThirdPoint.ToString() + " - Plane: " + refPlane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void Rectangle2Point(Point3D FirstPoint, Point3D SecondPoint, Plane refPlane, ref Entity entRectangle)
	{
		List<Point3D> Vertices = new List<Point3D>();
		Rectangle2Point(FirstPoint, SecondPoint, refPlane, ref Vertices, ref entRectangle);
		Vertices.Clear();
	}

	public void Rectangle2Point(Point3D FirstPoint, Point3D SecondPoint, Plane refPlane, ref List<Point3D> Vertices, ref Entity entRectangle)
	{
		try
		{
			refPlane.Project(SecondPoint, out var s, out var t);
			refPlane.Project(FirstPoint, out var s2, out var t2);
			double width = s - s2;
			double height = t - t2;
			entRectangle = CompositeCurve.CreateRectangle(refPlane, s2, t2, width, height);
			entRectangle.Regen(0.1);
			Vertices.Clear();
			for (int i = 0; i <= entRectangle.Vertices.Length - 1; i++)
			{
				Vertices.Add(new Point3D(entRectangle.Vertices[i].X, entRectangle.Vertices[i].Y, entRectangle.Vertices[i].Z));
			}
		}
		catch (Exception mSException)
		{
			string text = "FirstPoint: " + FirstPoint.ToString() + " - SecondPoint: " + SecondPoint.ToString() + " - Plane: " + refPlane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void PolygonCenter(Point3D pntBase, Point3D pntTip, int Side, Plane refPlane, ref List<Point3D> Vertices)
	{
		try
		{
			if (Side <= 2)
			{
				return;
			}
			Vertices.Clear();
			if (isPlaneXYorYX(refPlane))
			{
				double num = Length3D(pntBase, pntTip);
				double num2 = 360f / (float)Side;
				double num3 = PointAngle(pntTip, pntTip, refPlane);
				double x = Math.Round(pntBase.X + num * Math.Cos(buConversion5.DegreeToRadian(num3 + 0.0 * num2)), 8);
				double y = Math.Round(pntBase.Y + num * Math.Sin(buConversion5.DegreeToRadian(num3 + 0.0 * num2)), 8);
				double z = Math.Round(pntBase.Z, 8);
				Vertices.Add(new Point3D(x, y, z));
				for (int i = 0; i <= Side - 1; i++)
				{
					x = Math.Round(pntBase.X + num * Math.Cos(buConversion5.DegreeToRadian(num3 + (double)(i + 1) * num2)), 8);
					y = Math.Round(pntBase.Y + num * Math.Sin(buConversion5.DegreeToRadian(num3 + (double)(i + 1) * num2)), 8);
					z = Math.Round(pntBase.Z, 8);
					Vertices.Add(new Point3D(x, y, z));
				}
			}
			if (isPlaneXZorZX(refPlane))
			{
				double num = Length3D(pntBase, pntTip);
				double num2 = 360f / (float)Side;
				double num3 = PointAngle(pntTip, pntTip, refPlane);
				double x2 = Math.Round(pntBase.X + num * Math.Cos(buConversion5.DegreeToRadian(num3 + 0.0 * num2)), 8);
				double y2 = Math.Round(pntBase.Y, 8);
				double z2 = Math.Round(pntBase.Z + num * Math.Sin(buConversion5.DegreeToRadian(num3 + 0.0 * num2)), 8);
				Vertices.Add(new Point3D(x2, y2, z2));
				for (int j = 0; j <= Side - 1; j++)
				{
					x2 = Math.Round(pntBase.X + num * Math.Cos(buConversion5.DegreeToRadian(num3 + (double)(j + 1) * num2)), 8);
					y2 = Math.Round(pntBase.Y, 8);
					z2 = Math.Round(pntBase.Z + num * Math.Sin(buConversion5.DegreeToRadian(num3 + (double)(j + 1) * num2)), 8);
					Vertices.Add(new Point3D(x2, y2, z2));
				}
			}
			if (isPlaneYZorZY(refPlane))
			{
				double num = Length3D(pntBase, pntTip);
				double num2 = 360f / (float)Side;
				double num3 = PointAngle(pntTip, pntTip, refPlane);
				double x3 = Math.Round(pntBase.X, 8);
				double y3 = Math.Round(pntBase.Y + num * Math.Cos(buConversion5.DegreeToRadian(num3 + 0.0 * num2)), 8);
				double z3 = Math.Round(pntBase.Z + num * Math.Sin(buConversion5.DegreeToRadian(num3 + 0.0 * num2)), 8);
				Vertices.Add(new Point3D(x3, y3, z3));
				for (int k = 0; k <= Side - 1; k++)
				{
					x3 = Math.Round(pntBase.X, 8);
					y3 = Math.Round(pntBase.Y + num * Math.Cos(buConversion5.DegreeToRadian(num3 + (double)(k + 1) * num2)), 8);
					z3 = Math.Round(pntBase.Z + num * Math.Sin(buConversion5.DegreeToRadian(num3 + (double)(k + 1) * num2)), 8);
					Vertices.Add(new Point3D(x3, y3, z3));
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "";
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void PolygonCenter(Point3D pntBase, double Radius, int Side, Plane refPlane, ref List<Point3D> Vertices)
	{
		Point3D pntTip = new Point3D();
		if (isPlaneXYorYX(refPlane))
		{
			pntTip = new Point3D(pntBase.X + Radius, pntBase.Y, pntBase.Z);
		}
		if (isPlaneXZorZX(refPlane))
		{
			pntTip = new Point3D(pntBase.X + Radius, pntBase.Y, pntBase.Z);
		}
		if (isPlaneYZ(refPlane))
		{
			pntTip = new Point3D(pntBase.X, pntBase.Y + Radius, pntBase.Z);
		}
		PolygonCenter(pntBase, pntTip, Side, refPlane, ref Vertices);
	}

	public double CrossProductLength(Point3D PA, Point3D PB, Point3D PC)
	{
		return CrossProductLength(PA.X, PA.Y, PB.X, PB.Y, PC.X, PC.Y);
	}

	public double CrossProductLength(double Ax, double Ay, double Bx, double By, double Cx, double Cy)
	{
		double num = Ax - Bx;
		double num2 = Ay - By;
		double num3 = Cx - Bx;
		double num4 = Cy - By;
		return num * num4 - num2 * num3;
	}

	public Entity Slot3Point(Point3D First, Point3D Second, Point3D Third, Plane refPlane)
	{
		double num = SlotRad(First, Second, Third);
		if (num <= 0.0)
		{
			num = 0.1;
		}
		return CompositeCurve.CreateSlot(refPlane, First.X, First.Y, First.DistanceTo(Second), num, (Second - First).AsVector.Angle);
	}

	public Entity Slot3Point(Point2D First, Point2D Second, Point2D Third)
	{
		double num = SlotRad(First, Second, Third);
		if (num <= 0.0)
		{
			num = 0.1;
		}
		return CompositeCurve.CreateSlot(Plane.XY, First.X, First.Y, First.DistanceTo(Second), num, (Second - First).AsVector.Angle);
	}

	public double SlotRad(Point2D start, Point2D end, Point2D radial)
	{
		Segment2D segment2D = new Segment2D(start, end);
		Point2D b = segment2D.PointAt(segment2D.ClosestPointTo(radial));
		return radial.DistanceTo(b);
	}

	public void KeyHole(Point3D HeadPosition, double HeadRadius, double TaleRadius, double Length, double Angle, bool Reverse, Plane refPlane, ref buArc HeadArc, ref buArc TaleArc)
	{
		try
		{
			double num = 0.0;
			if (Reverse)
			{
				num = 180.0;
			}
			Point3D point3D = new Point3D();
			if (!isPlaneXYorYX(refPlane))
			{
				if (!isPlaneXZorZX(refPlane))
				{
					if (isPlaneYZorZY(refPlane))
					{
						double num2 = HeadPosition.Z + TaleRadius;
						double num3 = Math.Sqrt(Math.Pow(HeadRadius, 2.0) - Math.Pow(HeadPosition.Z - num2, 2.0));
						double num4 = HeadPosition.Y + num3;
						double num5 = buConversion5.RadianToDegree(Math.Atan((num2 - HeadPosition.Z) / (num4 - HeadPosition.Y)));
						double num6 = 360.0 - num5;
						double num7 = num5 + Angle + num;
						double num8 = num6 + Angle + num;
						if (num7 > 360.0 && num8 > 360.0)
						{
							num7 -= 360.0;
							num8 -= 360.0;
						}
						HeadArc = new buArc(refPlane, ToPoint3D(HeadPosition), HeadRadius, num7, num8);
						point3D = new Point3D();
						Point3D StartPnt = new Point3D();
						LineWithLengthAndAngle(HeadPosition, Length + num, Angle, refPlane, ref StartPnt, ref point3D);
						num7 = 270.0 + Angle + num;
						num8 = 450.0 + Angle + num;
						if (num7 > 360.0 && num8 > 360.0)
						{
							num7 -= 360.0;
							num8 -= 360.0;
						}
						TaleArc = new buArc(refPlane, ToPoint3D(point3D), TaleRadius, num7, num8);
					}
				}
				else
				{
					double num9 = HeadPosition.Z + TaleRadius;
					double num10 = Math.Sqrt(Math.Pow(HeadRadius, 2.0) - Math.Pow(HeadPosition.Z - num9, 2.0));
					double num11 = HeadPosition.X + num10;
					double num12 = buConversion5.RadianToDegree(Math.Atan((num9 - HeadPosition.Z) / (num11 - HeadPosition.X)));
					double num13 = 360.0 - num12;
					double num14 = num12 + Angle + num;
					double num15 = num13 + Angle + num;
					if (num14 > 360.0 && num15 > 360.0)
					{
						num14 -= 360.0;
						num15 -= 360.0;
					}
					HeadArc = new buArc(refPlane, ToPoint3D(HeadPosition), HeadRadius, num14, num15);
					point3D = new Point3D();
					Point3D StartPnt2 = new Point3D();
					LineWithLengthAndAngle(HeadPosition, Length, Angle + num, refPlane, ref StartPnt2, ref point3D);
					num14 = 270.0 + Angle + num;
					num15 = 450.0 + Angle + num;
					if (num14 > 360.0 && num15 > 360.0)
					{
						num14 -= 360.0;
						num15 -= 360.0;
					}
					TaleArc = new buArc(refPlane, ToPoint3D(point3D), TaleRadius, num14, num15);
				}
			}
			else
			{
				double num16 = HeadPosition.Y + TaleRadius;
				double num17 = Math.Sqrt(Math.Pow(HeadRadius, 2.0) - Math.Pow(HeadPosition.Y - num16, 2.0));
				double num18 = HeadPosition.X + num17;
				double num19 = buConversion5.RadianToDegree(Math.Atan((num16 - HeadPosition.Y) / (num18 - HeadPosition.X)));
				double num20 = 360.0 - num19;
				double num21 = num19 + Angle + num;
				double num22 = num20 + Angle + num;
				if (num21 > 360.0 && num22 > 360.0)
				{
					num21 -= 360.0;
					num22 -= 360.0;
				}
				HeadArc = new buArc(refPlane, ToPoint3D(HeadPosition), HeadRadius, num21, num22);
				point3D = new Point3D();
				Point3D StartPnt3 = new Point3D();
				LineWithLengthAndAngle(HeadPosition, Length, Angle + num, refPlane, ref StartPnt3, ref point3D);
				num21 = 270.0 + Angle + num;
				num22 = 450.0 + Angle + num;
				if (num21 > 360.0 && num22 > 360.0)
				{
					num21 -= 360.0;
					num22 -= 360.0;
				}
				TaleArc = new buArc(refPlane, ToPoint3D(point3D), TaleRadius, num21, num22);
			}
		}
		catch (Exception mSException)
		{
			string text = "HeadPosition: " + HeadPosition.ToString() + " - HeadRadius: " + HeadRadius + " - TaleRadius: " + TaleRadius + " - Length: " + Length + " - Angle: " + Angle + " - Plane: " + refPlane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void KeyHole(Point3D HeadPosition, double HeadRadius, double TaleRadius, double Length, double Angle, bool Reverse, Plane refPlane, ref buArc HeadArc, ref buArc TaleArc, ref buLine FirstLine, ref buLine SecondLine)
	{
		try
		{
			new buArc();
			new buArc();
			KeyHole(HeadPosition, HeadRadius, TaleRadius, Length, Angle, Reverse, refPlane, ref HeadArc, ref TaleArc);
			FirstLine = new buLine(ToPoint3D(HeadArc.Vertices[HeadArc.Vertices.Count - 1]), ToPoint3D(TaleArc.Vertices[0]));
			SecondLine = new buLine(ToPoint3D(TaleArc.Vertices[TaleArc.Vertices.Count - 1]), ToPoint3D(HeadArc.Vertices[0]));
		}
		catch (Exception)
		{
		}
	}

	public void EntitiesToSweep(List<buEntity> refEntities, double RampHeight, double RampLength, double TargetZ, CamZRampType RampType, ref buEntity SweepEntity, double Resolution = 0.1)
	{
		List<Point3D> Points = new List<Point3D>();
		for (int i = 0; i <= refEntities.Count - 1; i++)
		{
			List<Point3D> pntDevided = new List<Point3D>();
			EntityDevideByCamDir(refEntities[i], Resolution, ref pntDevided);
			Points.AddRange(pntDevided);
		}
		CheckDuplicatedPointsWithPrevious(ref Points);
		List<Point3D> calcStartPoints = new List<Point3D>();
		List<Point3D> calcMiddlePoints = new List<Point3D>();
		List<Point3D> calcEndPoints = new List<Point3D>();
		DevidePointList(Points, Resolution + 0.1, RampLength, RampLength, DevideMiddlePoints: true, DevideTipType.StartAndEnd, ref calcStartPoints, ref calcMiddlePoints, ref calcEndPoints);
		Move(0.0, 0.0, TargetZ, ref calcStartPoints);
		Move(0.0, 0.0, TargetZ, ref calcMiddlePoints);
		Move(0.0, 0.0, TargetZ, ref calcEndPoints);
		List<double> list = new List<double>();
		if (RampType == CamZRampType.Linear)
		{
			list = new List<double>();
			buNumeric5.DevideMinMaxValueByNumber(RampHeight, TargetZ, calcStartPoints.Count, ref list);
			for (int j = 0; j <= list.Count - 1; j++)
			{
				calcStartPoints[j] = new Point3D(calcStartPoints[j].X, calcStartPoints[j].Y, list[j]);
			}
			list = new List<double>();
			buNumeric5.DevideMinMaxValueByNumber(TargetZ, RampHeight, calcEndPoints.Count, ref list);
			for (int k = 0; k <= list.Count - 1; k++)
			{
				calcEndPoints[k] = new Point3D(calcEndPoints[k].X, calcEndPoints[k].Y, list[k]);
			}
		}
		if (RampType == CamZRampType.Circular)
		{
			List<Point3D> Points2 = new List<Point3D>();
			list = new List<double>();
			CircularZHeightRampByLengthAndHeight(RampLength, RampHeight, TargetZ, 1.0, 200, ref list, ref Points2);
			double num = 0.0;
			calcStartPoints[0] = new Point3D(calcStartPoints[0].X, calcStartPoints[0].Y, list[0]);
			for (int l = 1; l <= calcStartPoints.Count - 1; l++)
			{
				double num2 = Length3D(calcStartPoints[l - 1], calcStartPoints[l], Plane.XY);
				num += num2;
				double num3 = 0.0;
				double num4 = 0.0;
				for (int m = 1; m <= Points2.Count - 1; m++)
				{
					double num5 = Length3D(Points2[m - 1], Points2[m], Plane.XY);
					num3 += num5;
					if (num4 <= num && num <= num3)
					{
						calcStartPoints[l] = new Point3D(calcStartPoints[l].X, calcStartPoints[l].Y, list[m]);
						m = 100000;
					}
					num4 = num3;
				}
			}
			calcStartPoints[calcStartPoints.Count - 1] = new Point3D(calcStartPoints[calcStartPoints.Count - 1].X, calcStartPoints[calcStartPoints.Count - 1].Y, list[list.Count - 1]);
			list = new List<double>();
			CircularZHeightRampByLengthAndHeight(RampLength, TargetZ, RampHeight, 1.0, 200, ref list, ref Points2);
			num = 0.0;
			calcEndPoints[0] = new Point3D(calcEndPoints[0].X, calcEndPoints[0].Y, list[0]);
			for (int n = 1; n <= calcEndPoints.Count - 1; n++)
			{
				double num6 = Length3D(calcEndPoints[n - 1], calcEndPoints[n], Plane.XY);
				num += num6;
				double num7 = 0.0;
				double num8 = 0.0;
				for (int num9 = 1; num9 <= Points2.Count - 1; num9++)
				{
					double num10 = Length3D(Points2[num9 - 1], Points2[num9], Plane.XY);
					num7 += num10;
					if (num8 <= num && num <= num7)
					{
						calcEndPoints[n] = new Point3D(calcEndPoints[n].X, calcEndPoints[n].Y, list[num9]);
						num9 = 100000;
					}
					num8 = num7;
				}
			}
			calcEndPoints[calcEndPoints.Count - 1] = new Point3D(calcEndPoints[calcEndPoints.Count - 1].X, calcEndPoints[calcEndPoints.Count - 1].Y, list[list.Count - 1]);
		}
		List<Point3D> Points3 = new List<Point3D>();
		Points3.AddRange(calcStartPoints);
		Points3.AddRange(calcMiddlePoints);
		Points3.AddRange(calcEndPoints);
		CheckDuplicatedPointsWithPrevious(ref Points3);
		if (Points3.Count < 2)
		{
			SweepEntity = null;
		}
		else
		{
			SweepEntity = new buLinearPath(Points3);
		}
	}

	public void DrawHelix(Point3D Center, double Diameter, double Depth, double Pitch, Plane refPlane, ref List<Point3D> Points, double DegreeResolution = 1.0)
	{
		double num = Depth / Pitch;
		double num2 = num * 360.0;
		Point3D point3D = null;
		if (Points == null)
		{
			Points = new List<Point3D>();
		}
		Points.Clear();
		for (double num3 = 0.0; num3 <= num2; num3 += DegreeResolution)
		{
			point3D = new Point3D();
			if (refPlane.Equation.Z > 0.0)
			{
				point3D.X = Center.X + Diameter * 0.5 * Math.Cos(buConversion5.DegreeToRadian(num3));
				point3D.Y = Center.Y + Diameter * 0.5 * Math.Sin(buConversion5.DegreeToRadian(num3));
				point3D.Z = Center.Z - Pitch * num3 / 360.0;
			}
			if (refPlane.Equation.Z < 0.0)
			{
				point3D.X = Center.X + Diameter * 0.5 * Math.Cos(buConversion5.DegreeToRadian(num3));
				point3D.Y = Center.Y + Diameter * 0.5 * Math.Sin(buConversion5.DegreeToRadian(num3));
				point3D.Z = Center.Z + Pitch * num3 / 360.0;
			}
			if (refPlane.Equation.Y > 0.0)
			{
				point3D.X = Center.X + Diameter * 0.5 * Math.Cos(buConversion5.DegreeToRadian(num3));
				point3D.Y = Center.Y - Pitch * num3 / 360.0;
				point3D.Z = Center.Z + Diameter * 0.5 * Math.Sin(buConversion5.DegreeToRadian(num3));
			}
			if (refPlane.Equation.Y < 0.0)
			{
				point3D.X = Center.X + Diameter * 0.5 * Math.Cos(buConversion5.DegreeToRadian(num3));
				point3D.Y = Center.Y + Pitch * num3 / 360.0;
				point3D.Z = Center.Z + Diameter * 0.5 * Math.Sin(buConversion5.DegreeToRadian(num3));
			}
			Points.Add(point3D);
		}
	}

	public void SurfaceToFaceAsMesh(Entity entSurface, ref List<Mesh> FaceMeshes)
	{
		FaceMeshes = new List<Mesh>();
		if (!(entSurface is Brep))
		{
			if (entSurface is Surface)
			{
				Mesh item = ((Surface)entSurface).ConvertToMesh(0.01);
				FaceMeshes.Add(item);
			}
			return;
		}
		Brep brep = entSurface as Brep;
		if (brep.Faces == null)
		{
			return;
		}
		for (int i = 0; i <= brep.Faces.Length - 1; i++)
		{
			if (brep.Faces[i].Tessellation == null)
			{
				brep.Regen(0.01);
			}
			if (brep.Faces[i].Tessellation != null)
			{
				FastMesh fastMesh = (FastMesh)brep.Faces[i].Tessellation.Clone();
				FaceMeshes.Add(fastMesh.ConvertToMesh());
			}
		}
	}

	public void SurfaceToFaceAsSurface(Entity entSurface, ref List<Surface> FaceSurface)
	{
		FaceSurface = new List<Surface>();
		if (!(entSurface is Brep))
		{
			return;
		}
		Brep brep = entSurface as Brep;
		if (brep.Faces == null)
		{
			return;
		}
		brep.Rebuild();
		for (int i = 0; i <= brep.Faces.Length - 1; i++)
		{
			Surface[] array = brep.Faces[i].ConvertToSurface();
			if (array != null)
			{
				for (int j = 0; j <= array.Length - 1; j++)
				{
					Surface item = (Surface)array[j].Clone();
					FaceSurface.Add(item);
				}
			}
		}
	}

	public void SurfaceToFaceAsCurve(Entity entSurface, ref List<Entity> CurveSurface)
	{
		CurveSurface = new List<Entity>();
		if (entSurface is Brep)
		{
			Brep brep = entSurface as Brep;
			if (brep.Edges != null)
			{
				brep.Rebuild();
				for (int i = 0; i <= brep.Edges.Length - 1; i++)
				{
					Entity entity = (Entity)brep.Edges[i].Curve;
					if (entity != null)
					{
						CurveSurface.Add((Entity)entity.Clone());
					}
				}
			}
		}
		if (!(entSurface is Surface) || !(entSurface is Surface surface))
		{
			return;
		}
		surface.RebuildEdges(0.01);
		ICurve[] array = surface.ExtractEdges();
		for (int j = 0; j <= array.Length - 1; j++)
		{
			Entity entity2 = (Entity)array[j];
			if (entity2 != null)
			{
				CurveSurface.Add((Entity)entity2.Clone());
			}
		}
	}

	public void SurfaceToControlPoints(Entity entSurface, ref List<List<Point3D>> ControlPoints)
	{
		if (!(entSurface is Brep))
		{
			if (!(entSurface is Surface))
			{
				return;
			}
			ControlPoints = new List<List<Point3D>>();
			Surface surface = entSurface as Surface;
			if (surface.ControlPoints == null)
			{
				return;
			}
			_ = surface.KnotVectorU.Length - surface.DegreeU - 1;
			int num = surface.KnotVectorV.Length - surface.DegreeV - 1;
			int num2 = 0;
			int num3 = 0;
			List<Point3D> list = new List<Point3D>();
			for (int i = 0; i <= surface.ControlPoints.Length - 1; i++)
			{
				Point3D euclid = surface.ControlPoints[num2, num3].Euclid;
				list.Add(euclid);
				if (!((i > 0) & (list.Count == num)))
				{
					num3++;
					continue;
				}
				num3 = 0;
				num2++;
				ControlPoints.Add(list);
				list = new List<Point3D>();
			}
			return;
		}
		Brep brep = entSurface as Brep;
		if (brep.Faces == null)
		{
			return;
		}
		for (int j = 0; j <= brep.Faces.Length - 1; j++)
		{
			if (brep.Faces[j].Tessellation == null)
			{
				brep.Regen(0.01);
			}
			if (brep.Faces[j].Tessellation == null)
			{
			}
		}
	}

	public void GetMeshSurfacePointsFromDepth(List<Entity> entMesh, double DepthLevel, Plane refPlane, MeshToSurfacePointsSettings Settings, ref List<Point3D> Outside, ref List<List<Point3D>> Insides)
	{
		Point3D MinPoint = new Point3D();
		Point3D MidPoint = new Point3D();
		Point3D MaxPoint = new Point3D();
		BoxSizeCalculate(entMesh, ref MinPoint, ref MidPoint, ref MaxPoint);
		if (!isPlaneXYorYX(refPlane))
		{
			return;
		}
		if (Settings.BoxBoundOffset > 0.0)
		{
			MinPoint.X -= Settings.BoxBoundOffset;
			MinPoint.Y -= Settings.BoxBoundOffset;
			MaxPoint.X += Settings.BoxBoundOffset;
			MaxPoint.Y += Settings.BoxBoundOffset;
		}
		double num = Length2D(MinPoint, MaxPoint, refPlane);
		if (!(num > 0.0))
		{
			return;
		}
		List<Line> list = new List<Line>();
		int num2 = Convert.ToInt32(Settings.RotationSweepAngle / Settings.RotationStep);
		for (int i = 0; i <= num2; i++)
		{
			double num3 = (double)i * Settings.RotationStep;
			Point3D EndPnt = new Point3D();
			Point3D EndPnt2 = new Point3D();
			LineWithLengthAndAngle(MidPoint, num / 2.0, num3, refPlane, ref EndPnt);
			LineWithLengthAndAngle(MidPoint, num / 2.0, num3 + 180.0, refPlane, ref EndPnt2);
			Line item = new Line(new Point3D(MidPoint.X, MidPoint.Y, DepthLevel), new Point3D(EndPnt.X, EndPnt.Y, DepthLevel));
			list.Add(item);
		}
		Outside = new List<Point3D>();
		Insides = new List<List<Point3D>>();
		List<Point3D> list2 = new List<Point3D>();
		List<Point3D> list3 = new List<Point3D>();
		for (int j = 0; j <= entMesh.Count - 1; j++)
		{
			Mesh mesh = (Mesh)entMesh[j];
			for (int k = 0; k <= list.Count - 1; k++)
			{
				IList<HitTriangle> list4 = new List<HitTriangle>();
				Segment3D seg = new Segment3D(list[k].StartPoint, list[k].EndPoint);
				list4 = mesh.FindClosestTriangle(null, seg);
				if (list4.Count <= 0)
				{
					continue;
				}
				if (list4.Count != 1)
				{
					if (list4.Count == 2)
					{
						if (Settings.isOutside)
						{
							Outside.Add(list4[1].IntersectionPoint);
						}
						if (Settings.isInside)
						{
							list2.Add(list4[0].IntersectionPoint);
						}
					}
				}
				else if (Settings.isOutside)
				{
					Outside.Add(list4[0].IntersectionPoint);
				}
			}
		}
		if (!IsClosed(Outside))
		{
			Outside.Add(ToPoint3D(Outside[0]));
		}
		if (list2.Count > 0)
		{
			if (!IsClosed(list2))
			{
				list2.Add(ToPoint3D(list2[0]));
			}
			Insides.Add(list2);
		}
		if (list3.Count > 0)
		{
			Insides.Add(list3);
		}
	}

	public void GetMeshSurfacePointsFromDepth(List<Entity> entMesh, double StartOFfset, double EndOffset, double ZStep, Plane refPlane, MeshToSurfacePointsSettings Settings, ref List<Point3DList> Outside, ref List<List<Point3DList>> Insides)
	{
		Point3D MinPoint = new Point3D();
		Point3D MidPoint = new Point3D();
		Point3D MaxPoint = new Point3D();
		Mesh mesh = (Mesh)entMesh[0].Clone();
		mesh.MaterialName = string.Empty;
		for (int i = 1; i < entMesh.Count; i++)
		{
			mesh.MergeWith((Mesh)entMesh[i].Clone(), weldNow: false, recomputeEdges: false);
		}
		mesh.Weld(0.001, updateEdges: true);
		if (buEyeBaseForms.FrmProgress == null)
		{
			buEyeBaseForms.FrmProgress = new F_ProgressCalculation();
		}
		buEyeBaseForms.FrmProgress.TopMost = true;
		buEyeBaseForms.FrmProgress.Show();
		BoxSizeCalculate(mesh, ref MinPoint, ref MidPoint, ref MaxPoint);
		if (!isPlaneXYorYX(refPlane))
		{
			return;
		}
		MaxPoint.Z -= StartOFfset;
		MinPoint.Z += EndOffset;
		int num = Convert.ToInt32((MaxPoint.Z - MinPoint.Z) / ZStep);
		double num2 = (MaxPoint.Z - MinPoint.Z) / (double)num;
		if (Settings.BoxBoundOffset > 0.0)
		{
			MinPoint.X -= Settings.BoxBoundOffset;
			MinPoint.Y -= Settings.BoxBoundOffset;
			MaxPoint.X += Settings.BoxBoundOffset;
			MaxPoint.Y += Settings.BoxBoundOffset;
		}
		double num3 = Length2D(MinPoint, MaxPoint, refPlane);
		if (num3 > 0.0)
		{
			Outside = new List<Point3DList>();
			Insides = new List<List<Point3DList>>();
			int num4 = Convert.ToInt32(Settings.RotationSweepAngle / Settings.RotationStep);
			for (int j = 0; j <= num4; j++)
			{
				List<Line> list = new List<Line>();
				Point3DList point3DList = new Point3DList();
				Point3DList point3DList2 = new Point3DList();
				for (int k = 0; k <= num - 1; k++)
				{
					double z = MinPoint.Z + (double)k * num2;
					double num5 = Settings.RotationStartAngle + (double)j * Settings.RotationStep;
					Point3D EndPnt = new Point3D();
					Point3D EndPnt2 = new Point3D();
					LineWithLengthAndAngle(MidPoint, num3 / 2.0, num5, refPlane, ref EndPnt);
					LineWithLengthAndAngle(MidPoint, num3 / 2.0, num5 + 180.0, refPlane, ref EndPnt2);
					Line item = new Line(new Point3D(MidPoint.X, MidPoint.Y, z), new Point3D(EndPnt.X, EndPnt.Y, z));
					list.Add(item);
				}
				new List<Point3D>();
				new List<Point3D>();
				for (int l = 0; l <= entMesh.Count - 1; l++)
				{
					Mesh f = (Mesh)entMesh[l];
					for (int m = 0; m <= list.Count - 1; m++)
					{
						IList<HitTriangle> IL = new List<HitTriangle>();
						FindPointsOnMeshSurfaces(f, list[m].StartPoint, list[m].EndPoint, ref IL, 0, 0.0);
						bool flag = true;
						if (point3DList.Points.Count > 0)
						{
							flag = IsPointOnMeshIsCorrect(IL, Settings.MaxChangeDistanceFormPrevious + num2, point3DList.Points[point3DList.Points.Count - 1]);
						}
						if (!flag)
						{
							for (int n = 1; n <= Settings.FindCorrectPosIterationCount; n++)
							{
								IL = new List<HitTriangle>();
								FindPointsOnMeshSurfaces(f, list[m].StartPoint, list[m].EndPoint, ref IL, n, Settings.FindCorrectPosMoveStep);
								flag = IsPointOnMeshIsCorrect(IL, Settings.MaxChangeDistanceFormPrevious, point3DList.Points[point3DList.Points.Count - 1]);
							}
						}
						if (IL.Count <= 0)
						{
							continue;
						}
						if (IL.Count != 1)
						{
							if (IL.Count != 2)
							{
								if (Settings.isOutside)
								{
									point3DList.Points.Add(IL[IL.Count - 1].IntersectionPoint);
								}
								continue;
							}
							if (Settings.isOutside)
							{
								point3DList.Points.Add(IL[1].IntersectionPoint);
							}
							if (Settings.isInside)
							{
								point3DList2.Points.Add(IL[0].IntersectionPoint);
							}
						}
						else if (Settings.isOutside)
						{
							point3DList.Points.Add(IL[0].IntersectionPoint);
						}
					}
				}
				if (point3DList.Points.Count > 0)
				{
					if (Settings.CheckIsClosedContour && !IsClosed(point3DList.Points))
					{
						point3DList.Points.Add(ToPoint3D(point3DList.Points[0]));
					}
					Outside.Add(point3DList);
				}
				if (point3DList2.Points.Count > 0)
				{
					if (Settings.CheckIsClosedContour && !IsClosed(point3DList2.Points))
					{
						point3DList2.Points.Add(ToPoint3D(point3DList2.Points[0]));
					}
					List<Point3DList> list2 = new List<Point3DList>();
					list2.Add(point3DList2);
					Insides.Add(list2);
				}
				buEyeBaseForms.FrmProgress.Init((double)j / (double)num4 * 100.0, 100.0, buLangTranslate.preDef.Surface + " " + buLangTranslate.preDef.Calculating);
				buEyeBaseForms.FrmProgress.Refresh();
				Application.DoEvents();
			}
		}
		if (buEyeBaseForms.FrmProgress != null)
		{
			buEyeBaseForms.FrmProgress.Visible = false;
		}
	}

	public void FindPointsOnMeshSurfaces(Mesh F, Point3D StartPoint, Point3D EndPoint, ref IList<HitTriangle> IL, int iteration, double MoveDis)
	{
		int num = iteration % 6;
		double num2 = 0.0;
		double num3 = 0.0;
		double num4 = 0.0;
		double num5 = 0.0;
		IL = new List<HitTriangle>();
		Segment3D segment3D = null;
		switch (num)
		{
		case 0:
			num2 += 1.0;
			num5 = MoveDis * num2;
			break;
		case 1:
			num2 += 1.0;
			num5 = -1.0 * MoveDis * num2;
			break;
		case 2:
			num2 += 1.0;
			num4 = MoveDis * num2;
			break;
		case 3:
			num2 += 1.0;
			num4 = -1.0 * MoveDis * num2;
			break;
		case 4:
			num2 += 1.0;
			num3 = MoveDis * num2;
			break;
		case 5:
			num2 += 1.0;
			num3 = -1.0 * MoveDis * num2;
			break;
		}
		segment3D = new Segment3D(new Point3D(StartPoint.X + num3, StartPoint.Y + num4, StartPoint.Z + num5), new Point3D(EndPoint.X + num3, EndPoint.Y + num4, EndPoint.Z + num5));
		IL = F.FindClosestTriangle(null, segment3D);
	}

	public bool IsPointOnMeshIsCorrect(IList<HitTriangle> IL, double MaxDis, Point3D LAstPosition)
	{
		bool result = false;
		if (!((IL.Count == 0) | (IL.Count == 1)))
		{
			for (int i = 0; i <= IL.Count - 1; i++)
			{
				double num = Point3D.Distance(LAstPosition, IL[i].IntersectionPoint);
				if (num < MaxDis)
				{
					result = true;
				}
			}
			return result;
		}
		return false;
	}

