	public void Hatch(List<Entity> entHatchContour, double LayerHeight, double Angle, double StepOver, ref List<Entity> entHat)
	{
		Entity[] source = entHatchContour.ToArray();
		List<LinearPath> list = new List<LinearPath>();
		Plane plane = new Plane(new Point3D(0.0, 0.0, LayerHeight), Vector3D.AxisX, Vector3D.AxisY);
		devDept.Eyeshot.Entities.Region[] array = Utility.DetectRegionsFromContours(source.Select((Entity entity_0) => (ICurve)entity_0).ToList(), plane);
		devDept.Eyeshot.Entities.Region region = new devDept.Eyeshot.Entities.Region((ICurve)entHatchContour[0]);
		region.Regen(0.01);
		(from point3D_0 in Machining.BuildSmartHatch(region, Utility.DegToRad(Angle), StepOver, 0.1, region.BoxMin)
			select new LinearPath(point3D_0)).ToArray();
		devDept.Eyeshot.Entities.Region[] array2 = array;
		foreach (devDept.Eyeshot.Entities.Region region2 in array2)
		{
			region2.Regen(0.01);
			LinearPath[] collection = (from point3D_0 in Machining.BuildSmartHatch(region2, Utility.DegToRad(Angle), StepOver, 0.1, region2.BoxMin)
				select new LinearPath(point3D_0)).ToArray();
			list.AddRange(collection);
		}
		entHat.AddRange(list);
		for (int num2 = 0; num2 <= entHat.Count - 1; num2++)
		{
			if (entHat[num2].Vertices == null)
			{
				entHat[num2].Regen(0.1);
			}
			if (!buCompare5.EQ(entHat[num2].Vertices[0].Z, LayerHeight))
			{
				entHat[num2].Translate(0.0, 0.0, LayerHeight - entHat[num2].Vertices[0].Z);
			}
		}
	}

