					point3D.Z = list[num].IntersectionPoint.Z;
					if ((num5 > Settings.AMinLimit) & (num5 < Settings.AMaxLimit) & (num4 > Settings.BMinLimit) & (num4 < Settings.BMaxLimit))
					{
						Line item = new Line(new Point3D(point3D.X, point3D.Y, point3D.Z), new Point3D(point3D.X + 30.0 * vector3D.X, point3D.Y + 30.0 * vector3D.Y, point3D.Z + 30.0 * vector3D.Z));
						calcEntities.Add(item);
						calcPoints.Add(new Pnt6D(point3D.X, point3D.Y, point3D.Z, num5, num4, c));
					}
				}
			}
		}
	}

	public bool GetHitPointsFromMeshSurfaceByPoint(List<Entity> entMesh, Point3D prePoints, Point3D refPoints, Point3D nextPoints, MeshToSurfacePointsSettings Settings, ref MeshToSurfacePointsCalculations Calc)
	{
		try
		{
			Point3D point3D = new Point3D(refPoints.X, refPoints.Y, refPoints.Z);
			int num = -1;
			int num2 = 0;
			Mesh mesh = null;
			IList<HitTriangle> list = new List<HitTriangle>();
			for (int i = 0; i <= 4; i++)
			{
				double num3 = 0.0;
				double num4 = 0.0;
				if (i == 1)
				{
					num3 = 0.1;
				}
				if (i == 2)
				{
					num3 = -0.1;
				}
				if (i == 3)
				{
					num4 = 0.1;
				}
				if (i == 4)
				{
					num4 = -0.1;
				}
				double num5 = double.MaxValue;
				for (int j = 0; j <= entMesh.Count - 1; j++)
				{
					Mesh mesh2 = (Mesh)entMesh[j];
					Segment3D seg = new Segment3D(new Point3D(refPoints.X + num3, refPoints.Y + num4, -100000.0), new Point3D(refPoints.X + num3, refPoints.Y + num4, 10000.0));
					list = mesh2.FindClosestTriangle(null, seg);
					if (list.Count > 0)
					{
						double num6 = Point3D.Distance(list[0].IntersectionPoint, refPoints);
						if (num6 < num5)
						{
							num5 = num6;
							mesh = (Mesh)mesh2.Clone();
							num = 0;
							num2 = list[0].TriangleIndex;
						}
					}
				}
				if (list.Count > 0)
				{
					i = 1000;
				}
			}
			if (!(num >= 0 && mesh != null))
			{
				return false;
			}
			Calc.NormalVector = new Vector3D(mesh.Vertices[mesh.Triangles[num2].V1], mesh.Vertices[mesh.Triangles[num2].V2], mesh.Vertices[mesh.Triangles[num2].V3]);
			new Plane(Calc.NormalVector);
			double c = PointAngle(new Point3D(Calc.NormalVector.X, Calc.NormalVector.Y, Calc.NormalVector.Z), new Point3D(), Plane.XY);
			double num7 = PointAngle(new Point3D(Calc.NormalVector.X, Calc.NormalVector.Y, Calc.NormalVector.Z), new Point3D(), Plane.XZ);
			double num8 = PointAngle(new Point3D(Calc.NormalVector.X, Calc.NormalVector.Y, Calc.NormalVector.Z), new Point3D(), Plane.YZ);
			double num9 = 0.0;
			double num10 = 0.0;
			double num11 = 0.0;
			if (!((num8 > Settings.AMinLimit) & (num8 < Settings.AMaxLimit) & (num7 > Settings.BMinLimit) & (num7 < Settings.BMaxLimit)))
			{
				return false;
			}
			Line refEnt = new Line(new Point3D(point3D.X, point3D.Y, point3D.Z), new Point3D(point3D.X + Settings.ExtraDepth * Calc.NormalVector.X, point3D.Y + Settings.ExtraDepth * Calc.NormalVector.Y, point3D.Z + Settings.ExtraDepth * Calc.NormalVector.Z));
			Line line = (Line)CopyEntities(refEnt);
			if (Settings.isLastEachSegment)
			{
				line.Rotate(buConversion5.DegreeToRadian(Settings.TangentAngleFromNormal), new Vector3D(prePoints, refPoints), new Point3D(point3D.X, point3D.Y, point3D.Z));
			}
			else
			{
				line.Rotate(buConversion5.DegreeToRadian(Settings.TangentAngleFromNormal), new Vector3D(refPoints, nextPoints), new Point3D(point3D.X, point3D.Y, point3D.Z));
			}
			Calc.TangentVector = new Vector3D(line.Direction.X, line.Direction.Y, line.Direction.Z);
			if (Settings.ToolOffset != 0.0)
			{
				point3D = new Point3D(point3D.X + Settings.ToolOffset * Calc.NormalVector.X, point3D.Y + Settings.ToolOffset * Calc.NormalVector.Y, point3D.Z + Settings.ToolOffset * Calc.NormalVector.Z);
			}
			if (Settings.ExtraDepth != 0.0)
			{
				point3D = new Point3D(point3D.X + Calc.TangentVector.X, point3D.Y + Calc.TangentVector.Y, point3D.Z + Calc.TangentVector.Z);
			}
			Line line2 = new Line(new Point3D(point3D.X, point3D.Y, point3D.Z), new Point3D(point3D.X + Settings.SurfaceNormalLength * Calc.NormalVector.X, point3D.Y + Settings.SurfaceNormalLength * Calc.NormalVector.Y, point3D.Z + Settings.SurfaceNormalLength * Calc.NormalVector.Z));
			Calc.normalEntities = line2;
			Calc.tangentEntities = CopyEntities(line2);
			if (Settings.isLastEachSegment)
			{
				Calc.tangentEntities.Rotate(buConversion5.DegreeToRadian(Settings.TangentAngleFromNormal), new Vector3D(prePoints, refPoints), new Point3D(point3D.X, point3D.Y, point3D.Z));
			}
			else
			{
				Calc.tangentEntities.Rotate(buConversion5.DegreeToRadian(Settings.TangentAngleFromNormal), new Vector3D(refPoints, nextPoints), new Point3D(point3D.X, point3D.Y, point3D.Z));
			}
			Point3D point3D2 = new Point3D(point3D.X, point3D.Y, point3D.Z);
			Point3D pnt = new Point3D(point3D.X + Settings.LeadInDistance * Calc.NormalVector.X, point3D.Y + Settings.LeadInDistance * Calc.NormalVector.Y, point3D.Z + Settings.LeadInDistance * Calc.NormalVector.Z);
			if (Settings.isFirst)
			{
				Calc.LeadInEntities = new Line(ToPoint3D(pnt), ToPoint3D(point3D2));
				Calc.SafeInEntities = new Line(ToPoint3D(pnt), ToPoint3D(point3D2));
				Calc.SafeInEntities.Rotate(buConversion5.DegreeToRadian(Settings.TangentAngleFromNormal), new Vector3D(refPoints, nextPoints), point3D2);
				double dx = ((Line)Calc.LeadInEntities).StartPoint.X - ((Line)Calc.LeadInEntities).EndPoint.X;
				double dy = ((Line)Calc.LeadInEntities).StartPoint.Y - ((Line)Calc.LeadInEntities).EndPoint.Y;
				double dz = ((Line)Calc.LeadInEntities).StartPoint.Z - ((Line)Calc.LeadInEntities).EndPoint.Z;
				Calc.SafeInEntities.Translate(dx, dy, dz);
			}
			if (Settings.isLast)
			{
				Calc.LeadOutEntities = new Line(ToPoint3D(point3D2), ToPoint3D(pnt));
				Calc.SafeOutEntities = new Line(ToPoint3D(point3D2), ToPoint3D(pnt));
				Calc.SafeOutEntities.Rotate(buConversion5.DegreeToRadian(Settings.TangentAngleFromNormal), new Vector3D(prePoints, refPoints), point3D2);
				double dx2 = ((Line)Calc.LeadOutEntities).EndPoint.X - ((Line)Calc.LeadOutEntities).StartPoint.X;
				double dy2 = ((Line)Calc.LeadOutEntities).EndPoint.Y - ((Line)Calc.LeadOutEntities).StartPoint.Y;
				double dz2 = ((Line)Calc.LeadOutEntities).EndPoint.Z - ((Line)Calc.LeadOutEntities).StartPoint.Z;
				Calc.SafeOutEntities.Translate(dx2, dy2, dz2);
			}
			num9 = PointAngle(((Line)Calc.tangentEntities).EndPoint, ((Line)Calc.tangentEntities).StartPoint, Plane.XY);
			num10 = PointAngle(((Line)Calc.tangentEntities).EndPoint, ((Line)Calc.tangentEntities).StartPoint, Plane.XZ);
			num11 = PointAngle(((Line)Calc.tangentEntities).EndPoint, ((Line)Calc.tangentEntities).StartPoint, Plane.YZ);
			Calc.normalPoint = new Pnt6D(point3D.X, point3D.Y, point3D.Z, num8, num7, c);
			Calc.tangentPoint = new Pnt6D(point3D.X, point3D.Y, point3D.Z, num11, num10, num9);
			return true;
		}
		catch (Exception mSException)
		{
			string text = "";
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return false;
		}
	}

	public bool GetHitPointsFromSurface(List<Entity> entSurfaces, Point3D refPoints, HitSurfacePointsSettings Settings, Plane refPlane, ref HitSurfacePointsCalculations Calc)
	{
		try
		{
			Point3D point3D = new Point3D(refPoints.X, refPoints.Y, refPoints.Z);
			Point3D point3D2 = new Point3D(refPoints.X, refPoints.Y, refPoints.Z);
			Segment3D seg = new Segment3D();
			if (!isPlaneXYorYX(refPlane))
			{
				if (!isPlaneXZorZX(refPlane))
				{
					if (isPlaneYZorZY(refPlane))
					{
						if (Settings.PointGetType == HitSurfacePointsGetType.Top)
						{
							point3D2.Z = 1000000.0;
						}
						if (Settings.PointGetType == HitSurfacePointsGetType.Bottom)
						{
							point3D2.Z = -1000000.0;
						}
						seg = new Segment3D(new Point3D(-100000.0, refPoints.Y, refPoints.Z), new Point3D(10000.0, refPoints.Y, refPoints.Z));
					}
				}
				else
				{
					if (Settings.PointGetType == HitSurfacePointsGetType.Top)
					{
						point3D2.Y = 1000000.0;
					}
					if (Settings.PointGetType == HitSurfacePointsGetType.Bottom)
					{
						point3D2.Y = -1000000.0;
					}
					seg = new Segment3D(new Point3D(refPoints.X, -100000.0, refPoints.Z), new Point3D(refPoints.X, 10000.0, refPoints.Z));
				}
			}
			else
			{
				if (Settings.PointGetType == HitSurfacePointsGetType.Top)
				{
					point3D2.Z = 1000000.0;
				}
				if (Settings.PointGetType == HitSurfacePointsGetType.Bottom)
				{
					point3D2.Z = -1000000.0;
				}
				seg = new Segment3D(new Point3D(refPoints.X, refPoints.Y, -100000.0), new Point3D(refPoints.X, refPoints.Y, 10000.0));
			}
			int num = -1;
			int num2 = 0;
			Point3D point3D3 = new Point3D();
			Mesh mesh = null;
			IList<HitTriangle> list = new List<HitTriangle>();
			double num3 = double.MaxValue;
			for (int i = 0; i <= entSurfaces.Count - 1; i++)
			{
				if (!(entSurfaces[i] is Mesh))
				{
					if (!(entSurfaces[i] is Brep))
					{
						if (!(entSurfaces[i] is Surface))
						{
							continue;
						}
						Surface surface = (Surface)entSurfaces[i];
						list = surface.FindClosestTriangle(null, seg);
						if (list.Count <= 0)
						{
							continue;
						}
						for (int j = 0; j <= list.Count - 1; j++)
						{
							double num4 = Point3D.Distance(list[j].IntersectionPoint, point3D2);
							if (num4 < num3)
							{
								num3 = num4;
								mesh = (Mesh)surface.ConvertToMesh().Clone();
								num = 0;
								num2 = list[j].TriangleIndex;
								point3D3 = ToPoint3D(list[j].IntersectionPoint);
							}
						}
						continue;
					}
					Brep brep = (Brep)entSurfaces[i];
					list = brep.FindClosestTriangle(null, seg);
					if (list.Count <= 0)
					{
						continue;
					}
					for (int k = 0; k <= list.Count - 1; k++)
					{
						double num5 = Point3D.Distance(list[k].IntersectionPoint, point3D2);
						if (num5 < num3)
						{
							num3 = num5;
							mesh = (Mesh)brep.ConvertToMesh().Clone();
							num = 0;
							num2 = list[k].TriangleIndex;
							point3D3 = ToPoint3D(list[k].IntersectionPoint);
						}
					}
					continue;
				}
				Mesh mesh2 = (Mesh)entSurfaces[i];
				list = mesh2.FindClosestTriangle(null, seg);
				if (list.Count <= 0)
				{
					continue;
				}
				for (int l = 0; l <= list.Count - 1; l++)
				{
					double num6 = Point3D.Distance(list[l].IntersectionPoint, point3D2);
					if (num6 < num3)
					{
						num3 = num6;
						mesh = (Mesh)mesh2.Clone();
						num = 0;
						num2 = list[l].TriangleIndex;
						point3D3 = ToPoint3D(list[l].IntersectionPoint);
					}
				}
			}
			if (!(num >= 0 && mesh != null))
			{
				return false;
			}
			if (isPlaneXYorYX(refPlane))
			{
				point3D.Z = point3D3.Z;
			}
			if (isPlaneXZorZX(refPlane))
			{
				point3D.Y = point3D3.Y;
			}
			if (isPlaneYZorZY(refPlane))
			{
				point3D.X = point3D3.X;
			}
			Calc.NormalVector = new Vector3D(mesh.Vertices[mesh.Triangles[num2].V1], mesh.Vertices[mesh.Triangles[num2].V2], mesh.Vertices[mesh.Triangles[num2].V3]);
			new Plane(Calc.NormalVector);
			double c = PointAngle(new Point3D(Calc.NormalVector.X, Calc.NormalVector.Y, Calc.NormalVector.Z), new Point3D(), Plane.XY);
			double b = PointAngle(new Point3D(Calc.NormalVector.X, Calc.NormalVector.Y, Calc.NormalVector.Z), new Point3D(), Plane.XZ);
			double a = PointAngle(new Point3D(Calc.NormalVector.X, Calc.NormalVector.Y, Calc.NormalVector.Z), new Point3D(), Plane.YZ);
			Line normalEntities = new Line(new Point3D(point3D.X, point3D.Y, point3D.Z), new Point3D(point3D.X + Settings.SurfaceNormalLength * Calc.NormalVector.X, point3D.Y + Settings.SurfaceNormalLength * Calc.NormalVector.Y, point3D.Z + Settings.SurfaceNormalLength * Calc.NormalVector.Z));
			Calc.normalEntities = normalEntities;
			Calc.normalPoint = new Pnt6D(point3D.X, point3D.Y, point3D.Z, a, b, c);
			return true;
		}
		catch (Exception mSException)
		{
			string text = "";
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return false;
		}
	}

	public void SurfaceWithTwoVerticeList(List<Point3D> FirstVertice, List<Point3D> SecondVertice, ref List<Triangle> SurfaceTriangles)
	{
		try
		{
			Point3D point3D = new Point3D();
			Point3D point3D2 = new Point3D();
			Point3D point3D3 = new Point3D();
			Triangle triangle = null;
			SurfaceTriangles.Clear();
			if (FirstVertice.Count == SecondVertice.Count && FirstVertice.Count > 0)
			{
				for (int i = 0; i <= FirstVertice.Count - 2; i++)
				{
					point3D = ToPoint3D(FirstVertice[i]);
					point3D2 = ToPoint3D(SecondVertice[i]);
					point3D3 = ToPoint3D(FirstVertice[i + 1]);
					triangle = new Triangle(point3D, point3D2, point3D3);
					SurfaceTriangles.Add(triangle);
					point3D = ToPoint3D(FirstVertice[i + 1]);
					point3D2 = ToPoint3D(SecondVertice[i + 1]);
					point3D3 = ToPoint3D(SecondVertice[i]);
					triangle = new Triangle(point3D, point3D2, point3D3);
					SurfaceTriangles.Add(triangle);
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "FirstVertice: " + FirstVertice.Count + " - SecondVertice: " + SecondVertice.Count;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void CreateBoxProfile(double Width, double Height, double Length, double FirstAngle, double EndAngle, bool IfLengthSmallFitLength, ref Entity entProfile)
	{
		double num = 0.0;
		int num2 = 1;
		double num3 = Length;
		List<Point3D> list;
		List<Point3D> list2;
		while (true)
		{
			list = new List<Point3D>();
			num = Math.Tan(buConversion5.DegreeToRadian(FirstAngle)) * Width;
			list.Add(new Point3D(0.0, 0.0, 0.0));
			list.Add(new Point3D(0.0, 0.0, Height));
			list.Add(new Point3D(0.0 - num, Width, Height));
			list.Add(new Point3D(0.0 - num, Width, 0.0));
			list.Add(new Point3D(0.0, 0.0, 0.0));
			new LinearPath(list);
			list2 = new List<Point3D>();
			num = Math.Tan(buConversion5.DegreeToRadian(EndAngle)) * Width;
			list2.Add(new Point3D(0.0 + num3, 0.0, 0.0));
			list2.Add(new Point3D(0.0 + num3, 0.0, Height));
			list2.Add(new Point3D(0.0 - num + num3, Width, Height));
			list2.Add(new Point3D(0.0 - num + num3, Width, 0.0));
			list2.Add(new Point3D(0.0 + num3, 0.0, 0.0));
			new LinearPath(list2);
			num2++;
			if (!IfLengthSmallFitLength || !(list[2].X > list2[2].X && num2 < 20))
			{
				break;
			}
			num3 += Math.Round(list[2].X - list2[2].X, 3);
		}
		Surface surface = Surface.GlobalInterpolation(new Point3D[2, 5]
		{
			{
				list[0],
				list[1],
				list[2],
				list[3],
				list[4]
			},
			{
				list2[0],
				list2[1],
				list2[2],
				list2[3],
				list2[4]
			}
		}, 1, 1);
		entProfile = surface;
		entProfile.Color = Color.Gray;
		entProfile.ColorMethod = colorMethodType.byEntity;
	}

	public void SurfaceExturudeByEntities(List<buEntity> refEntities, Vector3D Direction, double Length, bool MoveToZero, double DevideLen, ref Entity entSureface)
	{
		buEntity entSureface2 = null;
		SurfaceExturudeByEntities(refEntities, Direction, Length, MoveToZero, DevideLen, ref entSureface2);
		buEntity.Copy(entSureface2, ref entSureface);
	}

	public void SurfaceExturudeByEntities(List<buEntity> refEntities, Vector3D Direction, double Length, bool MoveToZero, double DevideLen, ref buEntity entSureface)
	{
		List<Point3D> Points = new List<Point3D>();
		Point3D MinPoint = new Point3D();
		Point3D MaxPoint = new Point3D();
		SortbuSettings sortbuSettings = new SortbuSettings();
		SortbuResult Result = new SortbuResult();
		sortbuSettings.Option.IntersectionRules = SortingIntersectionRulesType.FromDrawing;
		sortbuSettings.Option.NextGroupRules = SortingNextGroupFindRulesType.NoNextGroup;
		new Point3D();
		ClockDirectionType clockDirectionType = ClockDirectionType.CW;
		List<buEntity> SortedEntities = new List<buEntity>();
		BoxSizeCalculate(refEntities, ref MinPoint, ref MaxPoint);
		if (!MoveToZero)
		{
			SortEntitiesByRefPoint(MinPoint, ref refEntities, sortbuSettings, ref SortedEntities, ref Result);
		}
		else
		{
			Move(0.0 - MinPoint.X, 0.0 - MinPoint.Y, 0.0 - MinPoint.Z, ref refEntities);
			MinPoint = new Point3D();
			SortEntitiesByRefPoint(MinPoint, ref refEntities, sortbuSettings, ref SortedEntities, ref Result);
		}
		if (!(DevideLen > 0.0))
		{
			EntitiesToPointsWithCamDirection(SortedEntities, ref Points);
		}
		else
		{
			for (int i = 0; i <= SortedEntities.Count - 1; i++)
			{
				List<Point3D> pntDevided = new List<Point3D>();
				EntityDevideByCamDir(SortedEntities[i], 0.5, ref pntDevided);
				Points.AddRange(pntDevided);
			}
		}
		CheckDuplicatedPointsWithPrevious(ref Points);
		clockDirectionType = GetClockDirection(Points);
		Plane whichPlane = Plane.XY;
		isPointsWhichPlane(Points, ref whichPlane);
		if (!isPlaneXYorYX(whichPlane))
		{
			return;
		}
		if (Direction == Vector3D.AxisX)
		{
			if (clockDirectionType == ClockDirectionType.CW)
			{
				Points.Reverse();
			}
			Rotate(MinPoint, 90.0, Plane.YZ, ref Points);
			Rotate(MinPoint, 90.0, Plane.XY, ref Points);
			LinearPath outer = new LinearPath(Points);
			devDept.Eyeshot.Entities.Region region = new devDept.Eyeshot.Entities.Region(outer);
			Mesh mesh = region.ExtrudeAsMesh(Length, 0.1, Mesh.natureType.RichSmooth);
			if (mesh != null)
			{
				entSureface = new buMesh(mesh);
			}
		}
		if (Direction == Vector3D.AxisY)
		{
			if (clockDirectionType != ClockDirectionType.CW)
			{
			}
			Rotate(MinPoint, 90.0, Plane.YZ, ref Points);
			LinearPath outer2 = new LinearPath(Points);
			devDept.Eyeshot.Entities.Region region2 = new devDept.Eyeshot.Entities.Region(outer2);
			Mesh mesh2 = region2.ExtrudeAsMesh(Length, 0.1, Mesh.natureType.RichSmooth);
			if (mesh2 != null)
			{
				entSureface = new buMesh(mesh2);
			}
		}
	}

	public void SurfaceExturudeByPoints(List<Point3D> refPoints, Vector3D Direction, double Length, ref Entity entSureface, bool AsMesh = false)
	{
		ClockDirectionType clockDirectionType = ClockDirectionType.CW;
		Point3D MinPoint = new Point3D();
		Point3D MaxPoint = new Point3D();
		List<Point3D> copiedPoint = new List<Point3D>();
		Copy(refPoints, ref copiedPoint);
		BoxSizeCalculate(copiedPoint, ref MinPoint, ref MaxPoint);
		clockDirectionType = GetClockDirection(copiedPoint);
		Plane whichPlane = Plane.XY;
		isPointsWhichPlane(copiedPoint, ref whichPlane);
		if (isPlaneXYorYX(whichPlane))
		{
			if (Direction == Vector3D.AxisX)
			{
				if (clockDirectionType == ClockDirectionType.CW)
				{
					copiedPoint.Reverse();
				}
				Rotate(MinPoint, 90.0, Plane.YZ, ref copiedPoint);
				Rotate(MinPoint, 90.0, Plane.XY, ref copiedPoint);
				LinearPath outer = new LinearPath(copiedPoint);
				devDept.Eyeshot.Entities.Region region = new devDept.Eyeshot.Entities.Region(outer);
				Brep brep = region.ExtrudeAsBrep(Length);
				if (brep != null)
				{
					entSureface = brep;
				}
			}
			if (Direction == Vector3D.AxisY)
			{
				if (clockDirectionType != ClockDirectionType.CW)
				{
				}
				Rotate(MinPoint, 90.0, Plane.YZ, ref copiedPoint);
				LinearPath outer2 = new LinearPath(copiedPoint);
				devDept.Eyeshot.Entities.Region region2 = new devDept.Eyeshot.Entities.Region(outer2);
				Brep brep2 = region2.ExtrudeAsBrep(Length);
				if (brep2 != null)
				{
					entSureface = brep2;
				}
			}
		}
		if (isPlaneXZorZX(whichPlane) && Direction == Vector3D.AxisY)
		{
			LinearPath linearPath = new LinearPath(copiedPoint);
			Mesh mesh = linearPath.ExtrudeAsMesh(new Vector3D(0.0, Length, 0.0), 0.1, Mesh.natureType.RichSmooth);
			devDept.Eyeshot.Entities.Region region3 = new devDept.Eyeshot.Entities.Region(linearPath);
			Brep brep3 = region3.ExtrudeAsBrep(Length);
			if (brep3 != null)
			{
				entSureface = mesh;
			}
		}
		if (isPlaneYZorZY(whichPlane) && Direction == Vector3D.AxisX)
		{
			LinearPath outer3 = new LinearPath(copiedPoint);
			devDept.Eyeshot.Entities.Region region4 = new devDept.Eyeshot.Entities.Region(outer3);
			Brep brep4 = region4.ExtrudeAsBrep(new Vector3D(Length, 0.0, 0.0));
			brep4.Regen(0.1);
			if (brep4 != null)
			{
				entSureface = brep4;
			}
		}
		if (entSureface == null)
		{
			return;
		}
		if (!(entSureface is Brep))
		{
			if (entSureface is Mesh)
			{
				entSureface.Regen(0.1);
			}
		}
		else
		{
			entSureface.Regen(0.1);
			entSureface = ((Brep)entSureface).ConvertToMesh();
		}
	}

	public void SurfaceExturudeByPoints(List<Point3D> refPoints, Vector3D Direction, double Length, bool MoveToZero, double DevideLen, ref buEntity entSureface)
	{
		ClockDirectionType clockDirectionType = ClockDirectionType.CW;
		Point3D MinPoint = new Point3D();
		Point3D MaxPoint = new Point3D();
		List<Point3D> copiedPoint = new List<Point3D>();
		Copy(refPoints, ref copiedPoint);
		BoxSizeCalculate(copiedPoint, ref MinPoint, ref MaxPoint);
		clockDirectionType = GetClockDirection(copiedPoint);
		Plane whichPlane = Plane.XY;
		isPointsWhichPlane(copiedPoint, ref whichPlane);
		if (isPlaneXYorYX(whichPlane))
		{
			if (Direction == Vector3D.AxisX)
			{
				if (clockDirectionType == ClockDirectionType.CW)
				{
					copiedPoint.Reverse();
				}
				Rotate(MinPoint, 90.0, Plane.YZ, ref copiedPoint);
				Rotate(MinPoint, 90.0, Plane.XY, ref copiedPoint);
				LinearPath outer = new LinearPath(copiedPoint);
				devDept.Eyeshot.Entities.Region region = new devDept.Eyeshot.Entities.Region(outer);
				Mesh mesh = region.ExtrudeAsMesh(Length, 0.1, Mesh.natureType.RichSmooth);
				mesh.Regen(0.01);
				if (mesh != null)
				{
					entSureface = new buMesh(mesh);
				}
			}
			if (Direction == Vector3D.AxisY)
			{
				if (clockDirectionType != ClockDirectionType.CW)
				{
				}
				Rotate(MinPoint, 90.0, Plane.YZ, ref copiedPoint);
				LinearPath linearPath = new LinearPath(copiedPoint);
				Mesh mesh2 = linearPath.ExtrudeAsMesh(new Vector3D(0.0, Length, 0.0), 0.1, Mesh.natureType.RichSmooth);
				if (mesh2 != null)
				{
					entSureface = new buMesh(mesh2);
				}
			}
		}
		if (isPlaneXZorZX(whichPlane) && Direction == Vector3D.AxisY)
		{
			LinearPath linearPath2 = new LinearPath(copiedPoint);
			Mesh mesh3 = linearPath2.ExtrudeAsMesh(new Vector3D(0.0, Length, 0.0), 0.1, Mesh.natureType.RichSmooth);
			if (mesh3 != null)
			{
				entSureface = new buMesh(mesh3);
			}
		}
	}

	public int surfaceRevolveByPath(CompositeCurve refCurve, Vector3D Axis, Point3D refPoint, double StartAngle, double DeltaAngle, ref Entity entRevolved, double Regen = 0.1, bool AsMesh = false, int MeshSlices = 360)
	{
		Entity entTop = null;
		Entity entBottom = null;
		return surfaceRevolveByPath(refCurve, Axis, refPoint, StartAngle, DeltaAngle, ref entRevolved, ref entTop, ref entBottom, Regen, AsMesh, MeshSlices, CreateTop: false, CreateBottom: false);
