	public int surfaceRevolveByPath(CompositeCurve refCurve, Vector3D Axis, Point3D refPoint, double StartAngle, double DeltaAngle, ref Entity entRevolved, ref Entity entTop, ref Entity entBottom, double Regen = 0.1, bool AsMesh = false, int MeshSlices = 360, bool CreateTop = true, bool CreateBottom = true)
	{
		try
		{
			devDept.Eyeshot.Entities.Region region = new devDept.Eyeshot.Entities.Region(refCurve);
			region.Regen(0.05);
			refCurve.Regen(0.05);
			Entity entity = null;
			Entity entity2 = null;
			Entity entity3 = null;
			Plane plane = new Plane(Axis);
			double radius = Length3D(refPoint, refCurve.Vertices[0], plane);
			double radius2 = Length3D(refPoint, refCurve.Vertices[refCurve.Vertices.Length - 1], plane);
			if (AsMesh)
			{
				entity = region.RevolveAsMesh(Utility.DegToRad(StartAngle), Utility.DegToRad(DeltaAngle), Axis, refPoint, MeshSlices, 0.01, Mesh.natureType.RichSmooth);
				Circle circle = new Circle(plane, refPoint, radius);
				entity3 = circle.ExtrudeAsMesh(Axis * 0.1, Regen, Mesh.natureType.RichSmooth);
				entity3.Translate(Axis.X * refCurve.Vertices[0].X, Axis.Y * refCurve.Vertices[0].Y, Axis.Z * refCurve.Vertices[0].Z);
				((Mesh)entity3).Regen(Regen);
				circle = new Circle(plane, refPoint, radius2);
				entity2 = circle.ExtrudeAsMesh(Axis * 0.1, Regen, Mesh.natureType.RichSmooth);
				entity2.Translate(Axis.X * refCurve.Vertices[refCurve.Vertices.Length - 1].X, Axis.Y * refCurve.Vertices[refCurve.Vertices.Length - 1].Y, Axis.Z * refCurve.Vertices[refCurve.Vertices.Length - 1].Z);
				((Mesh)entity2).Regen(Regen);
			}
			else
			{
				entity = region.RevolveAsBrep(Utility.DegToRad(StartAngle), Utility.DegToRad(DeltaAngle), Axis, refPoint);
				((Brep)entity).Regen(Regen);
				Circle outer = new Circle(plane, refPoint, radius);
				devDept.Eyeshot.Entities.Region region2 = new devDept.Eyeshot.Entities.Region(outer);
				entity3 = region2.ExtrudeAsBrep(Axis * 0.1);
				entity3.Translate(Axis.X * refCurve.Vertices[0].X, Axis.Y * refCurve.Vertices[0].Y, Axis.Z * refCurve.Vertices[0].Z);
				((Brep)entity3).Regen(Regen);
				outer = new Circle(plane, refPoint, radius2);
				devDept.Eyeshot.Entities.Region region3 = new devDept.Eyeshot.Entities.Region(outer);
				entity2 = region3.ExtrudeAsBrep(Axis * -0.1);
				entity2.Translate(Axis.X * refCurve.Vertices[refCurve.Vertices.Length - 1].X, Axis.Y * refCurve.Vertices[refCurve.Vertices.Length - 1].Y, Axis.Z * refCurve.Vertices[refCurve.Vertices.Length - 1].Z);
				((Brep)entity2).Regen(Regen);
			}
			entRevolved = entity;
			entTop = entity2;
			entBottom = entity3;
			return 1;
		}
		catch (Exception)
		{
			return -1;
		}
	}

