	public void surfaceBox(Point3D refPoint, double Width, double Height, double Depth, eyeSurfaceType surfaceType, ref Entity surfaceEntity, double Deviation = 0.05)
	{
		CompositeCurve compositeCurve = CompositeCurve.CreateRectangle(Width, Height);
		compositeCurve.Translate(refPoint.X, refPoint.Y);
		devDept.Eyeshot.Entities.Region region = new devDept.Eyeshot.Entities.Region(compositeCurve);
		switch (surfaceType)
		{
		case eyeSurfaceType.Mesh:
			surfaceEntity = region.ExtrudeAsMesh(Depth, Deviation, Mesh.natureType.RichSmooth);
			return;
		case eyeSurfaceType.Brep:
			surfaceEntity = region.ExtrudeAsBrep(Depth);
			return;
		case eyeSurfaceType.Solid:
			surfaceEntity = region.ExtrudeAsSolid(Depth, Deviation);
			return;
		}
		Surface[] array = region.ExtrudeAsSurface(Depth);
		if (array != null && array.Length != 0)
		{
			surfaceEntity = array[0];
		}
	}

