	public void GetSlicesContourFromMeshAtZPosition(Entity refMesh, double Z, bool Simplify, ref buEntitiesGroup EntGroup, double Deviation = 0.1)
	{
		if (refMesh == null || !(refMesh is Mesh))
		{
			return;
		}
		Mesh mesh = refMesh as Mesh;
		if (mesh.BoxMin == null)
		{
			mesh.Regen(Deviation);
		}
		Utility.GetEdgesWithoutDuplicates(mesh.Triangles, mesh.Vertices.Length, out var edgesPerVertex);
		Plane plane_ = new Plane(mesh.BoxMin, Vector3D.AxisX, Vector3D.AxisY);
		Size3D size3D = new Size3D(mesh.BoxMax, mesh.BoxMax);
		double num = size3D.Z / 100.0;
		double double_ = 0.0001 * (mesh.BoxMax.Z - mesh.BoxMin.Z) * num;
		double num2 = Point2D.Distance(new Point2D(mesh.BoxMin.X, mesh.BoxMin.Y), new Point2D(mesh.BoxMax.X, mesh.BoxMax.Y));
		double deviation = 0.0001 * num2;
		List<ICurve> list = new List<ICurve>();
		ICurve[] icurve_ = default(ICurve[]);
		Class186.smethod_48(double_, ref icurve_, edgesPerVertex, mesh, plane_, this);
		ICurve[] array = icurve_;
		foreach (ICurve curve in array)
		{
			if (Simplify)
			{
				Point3D[] pointList = Utility.Simplify(((Entity)curve).Vertices, deviation);
				Point3D[] points = Utility.RemoveDuplicates(pointList);
				list.Add(new LinearPath(points));
			}
			else
			{
				list.Add(curve);
			}
		}
	}

