	public void DimensionLinear(Point3D StartPoint, Point3D EndPoint, Point3D SetPoint, double dimtextH, ref buEntity StartPointExtension, ref buEntity EndPointExtension, ref buEntity DimLine)
	{
		bool flag = (!(SetPoint.X <= StartPoint.X) && !(SetPoint.X <= EndPoint.X)) || (!(SetPoint.X >= StartPoint.X) && SetPoint.X < EndPoint.X);
		Point3D point3D = new Point3D();
		Point3D point3D2 = new Point3D();
		if (!flag)
		{
			point3D = new Point3D(StartPoint.X, SetPoint.Y);
			point3D2 = new Point3D(EndPoint.X, SetPoint.Y);
			if (SetPoint.Y <= StartPoint.Y || !(SetPoint.Y > EndPoint.Y))
			{
				point3D.Y -= dimtextH / 2.0;
				point3D2.Y -= dimtextH / 2.0;
			}
			else
			{
				point3D.Y += dimtextH / 2.0;
				point3D2.Y += dimtextH / 2.0;
			}
		}
		else
		{
			point3D = new Point3D(SetPoint.X, StartPoint.Y);
			point3D2 = new Point3D(SetPoint.X, EndPoint.Y);
			if (SetPoint.X <= StartPoint.X || !(SetPoint.X > EndPoint.X))
			{
				point3D.X -= dimtextH / 2.0;
				point3D2.X -= dimtextH / 2.0;
			}
			else
			{
				point3D.X += dimtextH / 2.0;
				point3D2.X += dimtextH / 2.0;
			}
		}
		StartPointExtension = new buLine(StartPoint, point3D);
		EndPointExtension = new buLine(EndPoint, point3D2);
		DimLine = new buLine(point3D, point3D2);
	}

