	public void CreateArrow(Point3D refPoint, double Width, double Height, double Angle, ref Entity entArrow, double Thickness = 0.1)
	{
		List<Point3D> list = new List<Point3D>();
		list.Add(new Point3D(0.0, 0.0, 0.0));
		list.Add(new Point3D(0.0 - Width, Height / 2.0, 0.0));
		list.Add(new Point3D(0.0 - Width, (0.0 - Height) / 2.0, 0.0));
		list.Add(new Point3D(0.0, 0.0, 0.0));
		LinearPath outer = new LinearPath(list);
		devDept.Eyeshot.Entities.Region region = new devDept.Eyeshot.Entities.Region(outer, Plane.XY);
		entArrow = region.ExtrudeAsMesh(Thickness, 0.1, Mesh.natureType.RichSmooth);
		entArrow.Rotate(buConversion5.DegreeToRadian(Angle), Vector3D.AxisZ);
		entArrow.Translate(refPoint.X, refPoint.Y, refPoint.Z);
	}

	public double Length2D(double X1, double Y1, double X2, double Y2)
	{
		try
		{
			return Math.Sqrt((X1 - X2) * (X1 - X2) + (Y1 - Y2) * (Y1 - Y2));
		}
		catch (Exception mSException)
		{
			string text = "X1: " + X1 + " - X2: " + X2 + " - Y1: " + Y1 + " - Y2: " + Y2;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return 0.0;
		}
	}

	public double Length2D(Point3D StartPoint, Point3D EndPoint, Plane refPlane)
	{
		try
		{
			double result = 0.0;
			if ((refPlane == Plane.XY) | (refPlane == Plane.YX))
			{
				result = Math.Sqrt((StartPoint.X - EndPoint.X) * (StartPoint.X - EndPoint.X) + (StartPoint.Y - EndPoint.Y) * (StartPoint.Y - EndPoint.Y));
			}
			if ((refPlane == Plane.XZ) | (refPlane == Plane.ZX))
			{
				result = Math.Sqrt((StartPoint.X - EndPoint.X) * (StartPoint.X - EndPoint.X) + (StartPoint.Z - EndPoint.Z) * (StartPoint.Z - EndPoint.Z));
			}
			if ((refPlane == Plane.YZ) | (refPlane == Plane.ZY))
			{
				result = Math.Sqrt((StartPoint.Y - EndPoint.Y) * (StartPoint.Y - EndPoint.Y) + (StartPoint.Z - EndPoint.Z) * (StartPoint.Z - EndPoint.Z));
			}
			return result;
		}
		catch (Exception mSException)
		{
			_ = "Pnt1: " + StartPoint.ToString() + " - Pnt1: " + StartPoint.ToString();
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, "");
			return 0.0;
		}
	}

	public double Length3D(Point3D StartPoint, Point3D EndPoint)
	{
		try
		{
			double num = 0.0;
			return Math.Sqrt((StartPoint.X - EndPoint.X) * (StartPoint.X - EndPoint.X) + (StartPoint.Y - EndPoint.Y) * (StartPoint.Y - EndPoint.Y) + (StartPoint.Z - EndPoint.Z) * (StartPoint.Z - EndPoint.Z));
		}
		catch (Exception mSException)
		{
			_ = "Pnt1: " + StartPoint.ToString() + " - Pnt1: " + StartPoint.ToString();
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, "");
			return 0.0;
		}
	}

	public double Length3D(Point3D StartPoint, Point3D EndPoint, WorkPlane Plane)
	{
		try
		{
			if (!WorkPlane.isPlaneXY(Plane))
			{
				if (!WorkPlane.isPlaneXZ(Plane))
				{
					if (!WorkPlane.isPlaneYZ(Plane))
					{
						return Length3D(StartPoint, EndPoint);
					}
					return Math.Sqrt((StartPoint.Y - EndPoint.Y) * (StartPoint.Y - EndPoint.Y) + (StartPoint.Z - EndPoint.Z) * (StartPoint.Z - EndPoint.Z));
				}
				return Math.Sqrt((StartPoint.X - EndPoint.X) * (StartPoint.X - EndPoint.X) + (StartPoint.Z - EndPoint.Z) * (StartPoint.Z - EndPoint.Z));
			}
			return Math.Sqrt((StartPoint.X - EndPoint.X) * (StartPoint.X - EndPoint.X) + (StartPoint.Y - EndPoint.Y) * (StartPoint.Y - EndPoint.Y));
		}
		catch (Exception mSException)
		{
			string text = "StartPnt : " + StartPoint.ToString() + " - EndPnt : " + EndPoint.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return 0.0;
		}
	}

	public double Length3D(Point3D StartPoint, Point3D EndPoint, Plane Plane)
	{
		try
		{
			if (!isPlaneXYorYX(Plane))
			{
				if (!isPlaneXZorZX(Plane))
				{
					if (!isPlaneYZorZY(Plane))
					{
						return Length3D(StartPoint, EndPoint);
					}
					return Math.Sqrt((StartPoint.Y - EndPoint.Y) * (StartPoint.Y - EndPoint.Y) + (StartPoint.Z - EndPoint.Z) * (StartPoint.Z - EndPoint.Z));
				}
				return Math.Sqrt((StartPoint.X - EndPoint.X) * (StartPoint.X - EndPoint.X) + (StartPoint.Z - EndPoint.Z) * (StartPoint.Z - EndPoint.Z));
			}
			return Math.Sqrt((StartPoint.X - EndPoint.X) * (StartPoint.X - EndPoint.X) + (StartPoint.Y - EndPoint.Y) * (StartPoint.Y - EndPoint.Y));
		}
		catch (Exception mSException)
		{
			string text = "StartPnt : " + StartPoint.ToString() + " - EndPnt : " + EndPoint.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return 0.0;
		}
	}

