	public double PolygonArea(List<Point3D> Vertices, Plane refPlane)
	{
		try
		{
			double num = 0.0;
			if (Vertices != null)
			{
				if (Vertices.Count != 0)
				{
					if (isPlaneXYorYX(refPlane))
					{
						for (int i = 1; i <= Vertices.Count - 1; i++)
						{
							num += (Vertices[i].X - Vertices[i - 1].X) * (Vertices[i].Y + Vertices[i - 1].Y) / 2.0;
						}
					}
					if (isPlaneXZorZX(refPlane))
					{
						for (int j = 1; j <= Vertices.Count - 1; j++)
						{
							num += (Vertices[j].X - Vertices[j - 1].X) * (Vertices[j].Z + Vertices[j - 1].Z) / 2.0;
						}
					}
					if (isPlaneYZorZY(refPlane))
					{
						for (int k = 1; k <= Vertices.Count - 1; k++)
						{
							num += (Vertices[k].Y - Vertices[k - 1].Y) * (Vertices[k].Z + Vertices[k - 1].Z) / 2.0;
						}
					}
					return Math.Abs(num);
				}
				return 0.0;
			}
			return 0.0;
		}
		catch (Exception mSException)
		{
			string text = "Vertices: " + Vertices.Count + " - Plane: " + refPlane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return 0.0;
		}
	}

	public void AreaUnitRatioFromMM(LengthUnit Unit, ref double UnitRatio)
