		case LengthUnit.dm:
			UnitRatio = 10000.0;
			break;
		case LengthUnit.m:
			UnitRatio = 1000000.0;
			break;
		case LengthUnit.dam:
			UnitRatio = 100000000.0;
			break;
		case LengthUnit.hm:
			UnitRatio = 10000000000.0;
			break;
