			UnitRatio = 1000000000000.0;
			break;
		}
	}

	public void StepCalculation(double Start, double End, double Step, ref List<double> calcSteps)
	{
		calcSteps.Clear();
		if (buCompare5.EQ(Start, End))
		{
			return;
		}
		if (!(Math.Abs(Start - End) <= Step))
		{
			int num = (int)buNumeric5.RoundToLower(Math.Abs(Start - End) / Step);
			if (!(End > Start))
			{
				double num2 = Start;
				for (int i = 0; i <= num - 1; i++)
				{
					num2 = ((i == 0) ? (num2 - Step / 2.0) : (num2 - Step));
					calcSteps.Add(num2);
				}
				num2 = End + Step;
				if (calcSteps.Count <= 0)
				{
					return;
				}
				if (!(num2 < calcSteps[calcSteps.Count - 1]))
				{
					num2 = End + Step / 2.0;
					if (num2 < calcSteps[calcSteps.Count - 1])
					{
						calcSteps.Add(num2);
					}
				}
				else
				{
					calcSteps.Add(num2);
				}
				return;
			}
			double num3 = Start;
			for (int j = 0; j <= num - 1; j++)
			{
				num3 = ((j == 0) ? (num3 + Step / 2.0) : (num3 + Step));
				calcSteps.Add(num3);
			}
			num3 = End - Step;
			if (calcSteps.Count <= 0)
			{
				return;
			}
			if (!(num3 > calcSteps[calcSteps.Count - 1]))
			{
				num3 = End - Step / 2.0;
				if (num3 > calcSteps[calcSteps.Count - 1])
				{
					calcSteps.Add(num3);
				}
			}
			else
			{
				calcSteps.Add(num3);
			}
		}
		else
		{
			calcSteps.Add((Start + End) / 2.0);
		}
	}

	public void FindBiggestAndSmallestAreaPointListFromBox(List<List<Point3D>> refPoints, ref List<Point3D> Biggest, ref List<Point3D> Smallest)
	{
		try
		{
			Biggest = new List<Point3D>();
			Smallest = new List<Point3D>();
			if (refPoints.Count <= 0)
			{
				return;
			}
			int num = -1;
			int num2 = -1;
			double num3 = -999999.0;
			double num4 = -9999999.0;
			double num5 = 9999999.0;
			double num6 = 9999999.0;
			for (int i = 0; i <= refPoints.Count - 1; i++)
			{
				Point3D MinPoint = new Point3D();
				Point3D MaxPoint = new Point3D();
				BoxSizeCalculate(refPoints[i], ref MinPoint, ref MaxPoint);
				double num7 = MaxPoint.X - MinPoint.X;
				double num8 = MaxPoint.Y - MinPoint.Y;
				if (num7 > num3 && num8 > num4)
				{
					num3 = num7;
					num4 = num8;
					num = i;
				}
				if (num7 < num6 && num8 < num5)
				{
					num6 = num7;
					num5 = num8;
					num2 = i;
				}
			}
			if (num >= 0)
			{
				Copy(refPoints[num], ref Biggest);
			}
			if (num2 >= 0)
			{
				Copy(refPoints[num2], ref Smallest);
			}
		}
		catch (Exception)
		{
		}
	}

