	public Point3D CalculateCentroid(List<Point3D> Vertices)
	{
		if (Vertices.Count != 0)
		{
			if (Vertices.Count != 1)
			{
				Vector3D vector3D = new Vector3D();
				double num = 0.0;
				Point3D point3D = Vertices[0];
				Point3D point3D2 = Vertices[1];
				for (int i = 2; i < Vertices.Count; i++)
				{
					Point3D point3D3 = Vertices[i];
					Point3D a = point3D3 - point3D;
					Point3D b = point3D3 - point3D2;
					Vector3D vector3D2 = Vector3D.Cross(a, b);
					double num2 = vector3D2.Length / 2.0;
					vector3D.X += num2 * (point3D.X + point3D2.X + point3D3.X) / 3.0;
					vector3D.Y += num2 * (point3D.Y + point3D2.Y + point3D3.Y) / 3.0;
					vector3D.Z += num2 * (point3D.Z + point3D2.Z + point3D3.Z) / 3.0;
					num += num2;
					point3D2 = point3D3;
				}
				return new Point3D
				{
					X = vector3D.X / num,
					Y = vector3D.Y / num,
					Z = vector3D.Z / num
				};
			}
			return new Point3D(Vertices[0].X, Vertices[0].Y, Vertices[0].Z);
		}
		return new Point3D();
	}

	public Point3D CalculateMassCenterFromVertices(List<Point3D> Vertices)
	{
		if (Vertices.Count != 0)
		{
			if (Vertices.Count != 1)
			{
				double num = 0.0;
				double num2 = 0.0;
				double num3 = 0.0;
				for (int i = 0; i <= Vertices.Count - 1; i++)
				{
					num += Vertices[i].X;
					num2 += Vertices[i].Y;
					num3 += Vertices[i].Z;
				}
				double x = num / (double)Vertices.Count;
				double y = num2 / (double)Vertices.Count;
				double z = num3 / (double)Vertices.Count;
				return new Point3D(x, y, z);
			}
			return new Point3D(Vertices[0].X, Vertices[0].Y, Vertices[0].Z);
		}
		return new Point3D();
	}

	public Point3D CalculateMassCenterFromEdges(List<Point3D> Vertices)
	{
		if (Vertices.Count != 0)
		{
			if (Vertices.Count != 1)
			{
				double num = 0.0;
				double num2 = 0.0;
				double num3 = 0.0;
				double num4 = 0.0;
				double num5 = 0.0;
				double num6 = 0.0;
				double num7 = 0.0;
				double num8 = Vertices[0].X;
				double num9 = Vertices[0].Y;
				double num10 = Vertices[0].Z;
				double num11 = 0.0;
				double num12 = 0.0;
				double num13 = 0.0;
				double num14 = 0.0;
				for (int i = 1; i <= Vertices.Count - 1; i++)
				{
					num5 = Vertices[i].X;
					num6 = Vertices[i].Y;
					num7 = Vertices[i].Z;
					num11 = num5 - num8;
					num12 = num6 - num9;
					num13 = num7 - num10;
					num14 = Math.Sqrt(num11 * num11 + num12 * num12 + num13 * num13);
					num += (num8 + num5) / 2.0 * num14;
					num2 += (num9 + num6) / 2.0 * num14;
					num3 += (num10 + num7) / 2.0 * num14;
					num4 += num14;
					num8 = num5;
					num9 = num6;
					num10 = num7;
				}
				double x = num / num4;
				double y = num2 / num4;
				double z = num3 / num4;
				return new Point3D(x, y, z);
			}
			return new Point3D(Vertices[0].X, Vertices[0].Y, Vertices[0].Z);
		}
		return new Point3D();
	}

	public void FixPoints(List<Point3D> PL, ref List<List<Point3D>> PLFixed)
	{
		List<Point3D> list = new List<Point3D>();
		PLFixed = new List<List<Point3D>>();
		list.Add(PL[0]);
		list.Add(PL[1]);
		double num = PointAngle(PL[1], PL[0]);
		for (int i = 2; i <= PL.Count - 1; i++)
		{
			double num2 = PointAngle(PL[i], PL[i - 1]);
			double num3 = Point3D.Distance(PL[i], PL[i - 1]);
			double value = num2 - num;
			if (num3 > 0.1)
			{
				if (!(Math.Abs(value) < 5.0))
				{
					PLFixed.Add(list);
					list = new List<Point3D>();
					list.Add(PL[i]);
				}
				else
				{
					list.Add(PL[i]);
				}
				num = num2;
			}
		}
		if (list.Count > 0)
		{
		}
	}

