	public void DevidePointsByLength(ref List<Point3D> PointsDevided, double Length)
	{
		List<Point3D> copiedPoint = new List<Point3D>();
		Copy(PointsDevided, ref copiedPoint);
		PointsDevided.Clear();
		DevidePointsByLength(copiedPoint, Length, ref PointsDevided);
	}

	public void DevidePointsByLength(List<Point3D> Points, double Length, ref List<Point3D> PointsDevided)
	{
		LinearPath linearPath = new LinearPath(Points);
		Point3D[] pointsByLengthPerSegment = linearPath.GetPointsByLengthPerSegment(Length);
		PointsDevided = new List<Point3D>();
		if (pointsByLengthPerSegment != null)
		{
			for (int i = 0; i <= pointsByLengthPerSegment.Length - 1; i++)
			{
				PointsDevided.Add(ToPoint3D(pointsByLengthPerSegment[i]));
			}
		}
	}

	public void DevideLinePointsByLength(Point3D FirstPoint, Point3D SecondPoint, double Length, ref List<Point3D> PointsDevided)
	{
