		{
			for (int i = 0; i <= pointsByLengthPerSegment.Length - 1; i++)
			{
				PointsDevided.Add(ToPoint3D(pointsByLengthPerSegment[i]));
			}
		}
	}

	public void DevidePointList(List<Pnt6D> Points, double Length, ref List<Pnt6D> Vertices)
	{
		try
		{
			Vertices.Clear();
			if (Length <= 0.0 || Points.Count <= 1)
			{
				return;
			}
			for (int i = 1; i <= Points.Count - 1; i++)
			{
				List<Pnt6D> Vertices2 = new List<Pnt6D>();
				LineToLineer(Points[i - 1], Points[i], Length, ref Vertices2);
				if (Vertices2.Count > 1)
				{
					Pnt6D.Add(Vertices2, ref Vertices);
				}
				if (i < Points.Count - 1 && Vertices.Count > 0)
				{
					Vertices.RemoveAt(Vertices.Count - 1);
				}
			}
			CheckDuplicatedPointsWithPrevious(ref Vertices);
		}
		catch (Exception mSException)
		{
			string text = "Len:" + Length;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void DevidePointList(List<Pnt6DS> Points, double Length, ref List<Pnt6DS> Vertices)
	{
		try
		{
			Vertices.Clear();
			if (Length <= 0.0 || Points.Count <= 1)
			{
				return;
			}
			Vertices.Add(new Pnt6DS(Points[0]));
			for (int i = 1; i <= Points.Count - 1; i++)
			{
				double num = Length6D(new Pnt6D(Points[i - 1]), new Pnt6D(Points[i]));
				if (!(num > Length))
				{
					Vertices.Add(new Pnt6DS(Points[i]));
					continue;
				}
				List<Pnt6D> Vertices2 = new List<Pnt6D>();
				LineToLineer(new Pnt6D(Points[i - 1]), new Pnt6D(Points[i]), Length, ref Vertices2);
				for (int j = 1; j <= Vertices2.Count - 1; j++)
				{
					Pnt6DS pnt6DS = new Pnt6DS(Vertices2[j]);
					pnt6DS.S = Points[i - 1].S;
					Vertices.Add(pnt6DS);
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "Len:" + Length;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void DevidePointListAngleAndLength(List<Pnt6DS> Points, double XYZLength, double ABCLength, ref List<Pnt6DS> Vertices)
	{
		try
		{
			Vertices.Clear();
			if (XYZLength <= 0.0 || ABCLength <= 0.0 || Points.Count <= 1)
			{
				return;
			}
			Vertices.Add(new Pnt6DS(Points[0]));
			for (int i = 1; i <= Points.Count - 1; i++)
			{
				Length6D(new Pnt6D(Points[i - 1]), new Pnt6D(Points[i]));
				double num = Length3D(new Pnt3D(Points[i - 1].X, Points[i - 1].Y, Points[i - 1].Z), new Pnt3D(Points[i].X, Points[i].Y, Points[i].Z));
				double num2 = Length3D(new Pnt3D(Points[i - 1].A, Points[i - 1].B, Points[i - 1].C), new Pnt3D(Points[i].A, Points[i].B, Points[i].C));
				int num3 = (int)buNumeric5.RoundToUpper(num / XYZLength);
				int num4 = (int)buNumeric5.RoundToUpper(num2 / ABCLength);
				if (num4 <= num3)
				{
					if (num3 <= 2)
					{
						Vertices.Add(new Pnt6DS(Points[i]));
						continue;
					}
					List<Point3D> Values = new List<Point3D>();
					List<Point3D> Values2 = new List<Point3D>();
					buNumeric5.DevideMinMaxValueByNumber(new Point3D(Points[i - 1].X, Points[i - 1].Y, Points[i - 1].Z), new Point3D(Points[i].X, Points[i].Y, Points[i].Z), num3, ref Values);
					buNumeric5.DevideMinMaxValueByNumber(new Point3D(Points[i - 1].A, Points[i - 1].B, Points[i - 1].C), new Point3D(Points[i].A, Points[i].B, Points[i].C), num3, ref Values2);
					if (Values.Count != Values2.Count)
					{
						Vertices.Add(new Pnt6DS(Points[i]));
						continue;
					}
					for (int j = 1; j <= Values.Count - 1; j++)
					{
						Vertices.Add(new Pnt6DS(Values[j].X, Values[j].Y, Values[j].Z, Values2[j].X, Values2[j].Y, Values2[j].Z, Points[i].S));
					}
					continue;
				}
				if (num4 <= 2)
				{
					Vertices.Add(new Pnt6DS(Points[i]));
					continue;
				}
				List<Point3D> Values3 = new List<Point3D>();
				List<Point3D> Values4 = new List<Point3D>();
				buNumeric5.DevideMinMaxValueByNumber(new Point3D(Points[i - 1].X, Points[i - 1].Y, Points[i - 1].Z), new Point3D(Points[i].X, Points[i].Y, Points[i].Z), num4, ref Values3);
				buNumeric5.DevideMinMaxValueByNumber(new Point3D(Points[i - 1].A, Points[i - 1].B, Points[i - 1].C), new Point3D(Points[i].A, Points[i].B, Points[i].C), num4, ref Values4);
				if (Values3.Count != Values4.Count)
				{
					Vertices.Add(new Pnt6DS(Points[i]));
					continue;
				}
				for (int k = 1; k <= Values3.Count - 1; k++)
				{
					Vertices.Add(new Pnt6DS(Values3[k].X, Values3[k].Y, Values3[k].Z, Values4[k].X, Values4[k].Y, Values4[k].Z, Points[i].S));
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "Len:" + XYZLength;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public int DevidePointList(List<Point3D> refPoints, double DevideLength, double StartLength, double EndLength, bool DevideMiddlePoints, DevideTipType DevidePoint, ref List<Point3D> calcStartPoints, ref List<Point3D> calcMiddlePoints, ref List<Point3D> calcEndPoints)
	{
		try
		{
			double num = 0.0;
			double num2 = 0.0;
			double num3 = 0.0;
			double num4 = 0.0;
			bool flag = false;
			bool flag2 = false;
			bool flag3 = false;
			calcStartPoints.Clear();
			calcMiddlePoints.Clear();
			calcEndPoints.Clear();
			num = Length3D(refPoints);
			if (refPoints.Count > 1)
			{
				if (!(num < StartLength + EndLength))
				{
					calcStartPoints.Add(ToPoint3D(refPoints[0]));
					for (int i = 1; i <= refPoints.Count - 1; i++)
					{
						double num5 = Length3D(refPoints[i - 1], refPoints[i]);
						num2 += num5;
						num3 = num - num2;
						if (!flag && num2 > StartLength)
						{
							double angle = PointAngle(new Point3D(refPoints[i].X, refPoints[i].Y), new Point3D(refPoints[i - 1].X, refPoints[i - 1].Y));
							Point3D EndPnt = new Point3D();
							if (StartLength - num4 > 0.1)
							{
								LineWithLengthAndAngle(new Point3D(refPoints[i - 1].X, refPoints[i - 1].Y), StartLength - num4, angle, Plane.XY, ref EndPnt);
								calcStartPoints.Add(new Point3D(EndPnt.X, EndPnt.Y, EndPnt.Z));
								calcMiddlePoints.Add(new Point3D(EndPnt.X, EndPnt.Y, EndPnt.Z));
							}
							flag = true;
						}
						if (!flag && !flag)
						{
							calcStartPoints.Add(ToPoint3D(refPoints[i]));
						}
						if (num3 < EndLength && !flag3)
						{
							double angle2 = PointAngle(refPoints[i - 1], refPoints[i]);
							Point3D EndPnt2 = new Point3D();
							LineWithLengthAndAngle(new Point3D(refPoints[i].X, refPoints[i].Y), EndLength - num3, angle2, Plane.XY, ref EndPnt2);
							calcEndPoints.Add(new Point3D(EndPnt2.X, EndPnt2.Y, EndPnt2.Z));
							if (!flag3)
							{
								calcMiddlePoints.Add(new Point3D(EndPnt2.X, EndPnt2.Y, EndPnt2.Z));
							}
							flag3 = true;
							flag2 = true;
						}
						if (!flag2 && flag && !flag3)
						{
							calcMiddlePoints.Add(ToPoint3D(refPoints[i]));
						}
						if (calcEndPoints.Count > 0)
						{
							calcEndPoints.Add(ToPoint3D(refPoints[i]));
						}
						num4 = num2;
					}
					DevidePointsByLength(ref calcStartPoints, DevideLength);
					DevidePointsByLength(ref calcEndPoints, DevideLength);
					if (DevideMiddlePoints)
					{
						DevidePointsByLength(ref calcMiddlePoints, DevideLength);
					}
					return 2;
				}
				Copy(refPoints, ref calcMiddlePoints);
				return 1;
			}
			return 0;
		}
		catch (Exception mSException)
		{
			string text = "DevideLength: " + DevideLength + " - StartLength: " + StartLength + " - EndLength: " + EndLength + " - DevidePoint: " + DevidePoint;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return -1;
		}
	}

	public void CoordinateFromPlaneAndCorner(SizeObject Size, CornerLocation Corner, planeBoxNames Plane, ref buShape Item, ref Point3D calcPoint, double SingX = 1.0, double SingY = 1.0)
	{
		Point3D point3D = new Point3D(Item.BasePoint.X, Item.BasePoint.Y, Item.BasePoint.Z);
		Item.Corner = Corner;
		if (Plane == planeBoxNames.Top || Plane == planeBoxNames.Bottom || Plane == planeBoxNames.Free)
		{
			double z = Size.Depth;
			Item.CornerPoint = new Point3D(0.0, 0.0, Size.Depth);
			if (Plane == planeBoxNames.Bottom)
			{
				z = 0.0;
				Item.CornerPoint = new Point3D(0.0, 0.0, 0.0);
			}
			if (Corner == CornerLocation.RightTop || Corner == CornerLocation.RightCenter || Corner == CornerLocation.RightBottom)
			{
				if (!(SingX > 0.0))
				{
					Item.CornerPoint.X = 0.0;
				}
				else
				{
					Item.CornerPoint.X = Size.Width;
				}
			}
			if (Corner == CornerLocation.LeftBottom || Corner == CornerLocation.LeftCenter || Corner == CornerLocation.LeftTop)
			{
				if (!(SingX > 0.0))
				{
					Item.CornerPoint.X = 0.0 - Size.Width;
				}
				else
				{
					Item.CornerPoint.X = 0.0;
				}
			}
			if (Corner == CornerLocation.TopCenter || Corner == CornerLocation.LeftTop || Corner == CornerLocation.RightTop)
			{
				if (!(SingY > 0.0))
				{
					Item.CornerPoint.Y = 0.0;
				}
				else
				{
					Item.CornerPoint.Y = Size.Height;
				}
			}
			if (Corner == CornerLocation.BottomCenter || Corner == CornerLocation.LeftBottom || Corner == CornerLocation.RightBottom)
			{
				if (!(SingY > 0.0))
				{
					Item.CornerPoint.Y = 0.0 - Size.Height;
				}
				else
				{
					Item.CornerPoint.Y = 0.0;
				}
			}
			if (Corner == CornerLocation.RightCenter || Corner == CornerLocation.LeftCenter)
			{
				if (!(SingY > 0.0))
				{
					Item.CornerPoint.Y = (0.0 - Size.Height) / 2.0;
				}
				else
				{
					Item.CornerPoint.Y = Size.Height / 2.0;
				}
			}
			if (Corner == CornerLocation.BottomCenter || Corner == CornerLocation.BottomCenter)
			{
				if (!(SingX > 0.0))
				{
					Item.CornerPoint.X = (0.0 - Size.Width) / 2.0;
				}
				else
				{
					Item.CornerPoint.X = Size.Width / 2.0;
				}
			}
			if (Corner == CornerLocation.RightTop)
			{
				calcPoint.X = Size.Width - point3D.X;
				calcPoint.Y = Size.Height - point3D.Y;
				calcPoint.Z = z;
			}
			if (Corner == CornerLocation.RightBottom)
			{
				calcPoint.X = Size.Width - point3D.X;
				calcPoint.Y = point3D.Y;
				calcPoint.Z = z;
			}
			if (Corner == CornerLocation.RightCenter)
			{
				calcPoint.X = Size.Width - point3D.X;
				calcPoint.Y = Size.Height / 2.0 + point3D.Y;
				calcPoint.Z = z;
			}
			if (Corner == CornerLocation.LeftTop)
			{
				calcPoint.X = point3D.X;
				calcPoint.Y = Size.Height - point3D.Y;
				calcPoint.Z = z;
			}
			if (Corner == CornerLocation.LeftBottom)
			{
				calcPoint.X = point3D.X;
				calcPoint.Y = point3D.Y;
				calcPoint.Z = z;
			}
			if (Corner == CornerLocation.LeftCenter)
			{
				calcPoint.X = point3D.X;
				calcPoint.Y = Size.Height / 2.0 + point3D.Y;
				calcPoint.Z = z;
			}
			if (Corner == CornerLocation.BottomCenter)
			{
				calcPoint.X = Size.Width / 2.0 + point3D.X;
				calcPoint.Y = point3D.Y;
				calcPoint.Z = z;
			}
			if (Corner == CornerLocation.TopCenter)
			{
				calcPoint.X = Size.Width / 2.0 + point3D.X;
				calcPoint.Y = Size.Height - point3D.Y;
				calcPoint.Z = z;
			}
		}
		if (Plane == planeBoxNames.Right || Plane == planeBoxNames.Left)
		{
			double x = 0.0;
			Item.CornerPoint = new Point3D(0.0, 0.0, 0.0);
			if (Plane == planeBoxNames.Right)
			{
				if (!(SingX > 0.0))
				{
					x = 0.0;
					Item.CornerPoint.X = 0.0;
				}
				else
				{
					x = Size.Width;
					Item.CornerPoint.X = Size.Width;
				}
			}
			if (Plane == planeBoxNames.Left)
			{
				if (!(SingX > 0.0))
				{
					x = 0.0 - Size.Width;
					Item.CornerPoint.X = 0.0 - Size.Width;
				}
				else
				{
					x = 0.0;
					Item.CornerPoint.X = 0.0;
				}
			}
			if (Corner == CornerLocation.RightTop || Corner == CornerLocation.RightCenter || Corner == CornerLocation.RightBottom)
			{
				if (clsVar5.ShapeSettingsParameters.LeftRigthViewType != LeftRightType.Left)
				{
					if (!(SingY > 0.0))
					{
						Item.CornerPoint.Y = 0.0;
					}
					else
					{
						Item.CornerPoint.Y = 0.0;
					}
				}
				else if (!(SingY > 0.0))
				{
					Item.CornerPoint.Y = 0.0 - Size.Height;
				}
				else
				{
					Item.CornerPoint.Y = Size.Height;
				}
			}
			if (Corner == CornerLocation.LeftBottom || Corner == CornerLocation.LeftCenter || Corner == CornerLocation.LeftTop)
			{
				if (clsVar5.ShapeSettingsParameters.LeftRigthViewType != LeftRightType.Left)
				{
					if (!(SingY > 0.0))
					{
						Item.CornerPoint.Y = 0.0 - Size.Height;
					}
					else
					{
						Item.CornerPoint.Y = Size.Height;
					}
				}
				else if (!(SingY > 0.0))
				{
					Item.CornerPoint.Y = 0.0;
				}
				else
				{
					Item.CornerPoint.Y = 0.0;
				}
			}
			if (Corner == CornerLocation.TopCenter || Corner == CornerLocation.LeftTop || Corner == CornerLocation.RightTop)
			{
				Item.CornerPoint.Z = Size.Depth;
			}
			if (Corner == CornerLocation.BottomCenter || Corner == CornerLocation.LeftBottom || Corner == CornerLocation.RightBottom)
			{
				Item.CornerPoint.Z = 0.0;
			}
			if (Corner == CornerLocation.RightCenter || Corner == CornerLocation.LeftCenter)
			{
				Item.CornerPoint.Z = Size.Depth / 2.0;
			}
			if (Corner == CornerLocation.BottomCenter || Corner == CornerLocation.BottomCenter)
			{
				if (!(SingY > 0.0))
				{
					Item.CornerPoint.Y = (0.0 - Size.Height) / 2.0;
				}
				else
				{
					Item.CornerPoint.Y = Size.Height / 2.0;
				}
			}
			if (Corner == CornerLocation.RightBottom)
			{
				calcPoint.X = x;
				calcPoint.Y = Item.CornerPoint.Y + point3D.Y;
				if (clsVar5.ShapeSettingsParameters.LeftRigthViewType == LeftRightType.Right)
				{
					calcPoint.Y = Item.CornerPoint.Y - point3D.Y;
				}
				calcPoint.Z = point3D.Z;
			}
			if (Corner == CornerLocation.RightTop)
			{
				calcPoint.X = x;
				calcPoint.Y = Item.CornerPoint.Y + point3D.Y;
				if (clsVar5.ShapeSettingsParameters.LeftRigthViewType == LeftRightType.Right)
				{
					calcPoint.Y = Item.CornerPoint.Y - point3D.Y;
				}
				calcPoint.Z = Size.Depth - point3D.Z;
			}
			if (Corner == CornerLocation.LeftBottom)
			{
				calcPoint.X = x;
				calcPoint.Y = Item.CornerPoint.Y - point3D.Y;
				if (clsVar5.ShapeSettingsParameters.LeftRigthViewType == LeftRightType.Right)
				{
					calcPoint.Y = Item.CornerPoint.Y + point3D.Y;
				}
				calcPoint.Z = point3D.Z;
			}
			if (Corner == CornerLocation.LeftTop)
			{
				calcPoint.X = x;
				calcPoint.Y = Item.CornerPoint.Y - point3D.Y;
				if (clsVar5.ShapeSettingsParameters.LeftRigthViewType == LeftRightType.Right)
				{
					calcPoint.Y = Item.CornerPoint.Y + point3D.Y;
				}
				calcPoint.Z = Size.Depth - point3D.Z;
			}
			if (Corner == CornerLocation.RightCenter)
			{
				calcPoint.X = x;
				calcPoint.Y = Item.CornerPoint.Y + point3D.Y;
				if (clsVar5.ShapeSettingsParameters.LeftRigthViewType == LeftRightType.Right)
				{
					calcPoint.Y = Item.CornerPoint.Y - point3D.Y;
				}
				calcPoint.Z = Size.Depth / 2.0 + point3D.Z;
			}
			if (Corner == CornerLocation.LeftCenter)
			{
				calcPoint.X = x;
				calcPoint.Y = Item.CornerPoint.Y - point3D.Y;
				if (clsVar5.ShapeSettingsParameters.LeftRigthViewType == LeftRightType.Right)
				{
					calcPoint.Y = Item.CornerPoint.Y + point3D.Y;
				}
				calcPoint.Z = Size.Depth / 2.0 + point3D.Z;
			}
			if (Corner == CornerLocation.TopCenter)
			{
				calcPoint.X = x;
				calcPoint.Y = Size.Height / 2.0 + point3D.Y;
				if (clsVar5.ShapeSettingsParameters.LeftRigthViewType == LeftRightType.Right)
				{
					calcPoint.Y = Size.Height / 2.0 - point3D.Y;
				}
				calcPoint.Z = Size.Depth - point3D.Z;
			}
			if (Corner == CornerLocation.BottomCenter)
			{
				calcPoint.X = x;
				calcPoint.Y = Size.Height / 2.0 + point3D.Y;
				if (clsVar5.ShapeSettingsParameters.LeftRigthViewType == LeftRightType.Right)
				{
					calcPoint.Y = Size.Height / 2.0 - point3D.Y;
				}
				calcPoint.Z = point3D.Z;
			}
		}
		if (Plane == planeBoxNames.Front || Plane == planeBoxNames.Back)
		{
			double y = 0.0;
			Item.CornerPoint = new Point3D(0.0, 0.0, 0.0);
			if (Plane == planeBoxNames.Back)
			{
				if (!(SingY > 0.0))
				{
					y = 0.0;
					Item.CornerPoint.Y = 0.0;
				}
				else
				{
					y = Size.Height;
					Item.CornerPoint.Y = Size.Height;
				}
			}
			if (Plane == planeBoxNames.Front)
			{
				if (!(SingY > 0.0))
				{
					y = 0.0 - Size.Height;
					Item.CornerPoint.Y = 0.0 - Size.Height;
				}
				else
				{
					y = 0.0;
					Item.CornerPoint.Y = 0.0;
