	}

	public void CoordinateFromObjectLocation(ObjectAlignment Alignment, planeBoxNames Plane, List<buEntity> Entities, ref Point3D MoveDistance, bool OnlyFirstEntity = false)
	{
		Point3D MinPoint = new Point3D();
		Point3D MidPoint = new Point3D();
		Point3D MaxPoint = new Point3D();
		if (OnlyFirstEntity)
		{
			if (Entities.Count > 0)
			{
				BoxSizeCalculate(Entities[0], ref MinPoint, ref MidPoint, ref MaxPoint);
			}
		}
		else
		{
			BoxSizeCalculate(Entities, ref MinPoint, ref MidPoint, ref MaxPoint);
		}
		if (Plane == planeBoxNames.Top || Plane == planeBoxNames.Free)
		{
			if (Alignment == ObjectAlignment.TopLeft)
			{
				MoveDistance.X = 0.0 - MinPoint.X;
				MoveDistance.Y = 0.0 - MaxPoint.Y;
				MoveDistance.Z = 0.0 - MaxPoint.Z;
			}
			if (Alignment == ObjectAlignment.TopCenter)
			{
				MoveDistance.X = 0.0 - MidPoint.X;
				MoveDistance.Y = 0.0 - MaxPoint.Y;
				MoveDistance.Z = 0.0 - MaxPoint.Z;
			}
			if (Alignment == ObjectAlignment.TopRight)
			{
				MoveDistance.X = 0.0 - MaxPoint.X;
				MoveDistance.Y = 0.0 - MaxPoint.Y;
				MoveDistance.Z = 0.0 - MaxPoint.Z;
			}
			if (Alignment == ObjectAlignment.MiddleLeft)
			{
				MoveDistance.X = 0.0 - MinPoint.X;
				MoveDistance.Y = 0.0 - MidPoint.Y;
				MoveDistance.Z = 0.0 - MaxPoint.Z;
			}
			if (Alignment == ObjectAlignment.MiddleCenter)
			{
				MoveDistance.X = 0.0 - MidPoint.X;
				MoveDistance.Y = 0.0 - MidPoint.Y;
				MoveDistance.Z = 0.0 - MaxPoint.Z;
			}
			if (Alignment == ObjectAlignment.MiddleRight)
			{
				MoveDistance.X = 0.0 - MaxPoint.X;
				MoveDistance.Y = 0.0 - MidPoint.Y;
				MoveDistance.Z = 0.0 - MaxPoint.Z;
			}
			if (Alignment == ObjectAlignment.BottomLeft)
			{
				MoveDistance.X = 0.0 - MinPoint.X;
				MoveDistance.Y = 0.0 - MinPoint.Y;
				MoveDistance.Z = 0.0 - MaxPoint.Z;
			}
			if (Alignment == ObjectAlignment.BottomCenter)
			{
				MoveDistance.X = 0.0 - MidPoint.X;
				MoveDistance.Y = 0.0 - MinPoint.Y;
				MoveDistance.Z = 0.0 - MaxPoint.Z;
			}
			if (Alignment == ObjectAlignment.BottomRight)
			{
				MoveDistance.X = 0.0 - MaxPoint.X;
				MoveDistance.Y = 0.0 - MinPoint.Y;
				MoveDistance.Z = 0.0 - MaxPoint.Z;
			}
		}
		if (Plane == planeBoxNames.Bottom)
		{
			if (Alignment == ObjectAlignment.TopLeft)
			{
				MoveDistance.X = 0.0 - MinPoint.X;
				MoveDistance.Y = 0.0 - MaxPoint.Y;
				MoveDistance.Z = 0.0 - MinPoint.Z;
			}
			if (Alignment == ObjectAlignment.TopCenter)
			{
				MoveDistance.X = 0.0 - MidPoint.X;
				MoveDistance.Y = 0.0 - MaxPoint.Y;
				MoveDistance.Z = 0.0 - MinPoint.Z;
			}
			if (Alignment == ObjectAlignment.TopRight)
			{
				MoveDistance.X = 0.0 - MaxPoint.X;
				MoveDistance.Y = 0.0 - MaxPoint.Y;
				MoveDistance.Z = 0.0 - MinPoint.Z;
			}
			if (Alignment == ObjectAlignment.MiddleLeft)
			{
				MoveDistance.X = 0.0 - MinPoint.X;
				MoveDistance.Y = 0.0 - MidPoint.Y;
				MoveDistance.Z = 0.0 - MinPoint.Z;
			}
			if (Alignment == ObjectAlignment.MiddleCenter)
