	public void CoordinateFromObjectLocation(ObjectAlignment Alignment, planeBoxNames Plane, Entity Entities, ref Point3D MoveDistance, bool OnlyFirstEntity = false)
	{
		List<Entity> list = new List<Entity>();
		list.Add(Entities);
		CoordinateFromObjectLocation(Alignment, Plane, list, ref MoveDistance, OnlyFirstEntity);
	}

