	public void EntityEntityTouchPoint(buEntity FirstEntity, buEntity SecondEntity, double Resolution, ref bool isTouch, ref StartEndType FirstEntityTouchPoint, ref StartEndType SecondEntityTouchPoint)
	{
		Point3D pntTouch = new Point3D();
		EntityEntityTouchPoint(FirstEntity, SecondEntity, Resolution, ref isTouch, ref FirstEntityTouchPoint, ref SecondEntityTouchPoint, ref pntTouch);
	}

	public void EntityEntityTouchPoint(buEntity FirstEntity, buEntity SecondEntity, double Resolution, ref bool isTouch, ref StartEndType FirstEntityTouchPoint, ref StartEndType SecondEntityTouchPoint, ref Point3D pntTouch)
	{
		isTouch = false;
		if (buCompare5.EQ(FirstEntity.Vertices[0], SecondEntity.Vertices[0], Resolution))
		{
			FirstEntityTouchPoint = StartEndType.Start;
			SecondEntityTouchPoint = StartEndType.Start;
			pntTouch = ToPoint3D(FirstEntity.Vertices[0]);
			isTouch = true;
		}
		if (buCompare5.EQ(FirstEntity.Vertices[0], SecondEntity.Vertices[SecondEntity.Vertices.Count - 1], Resolution))
		{
			FirstEntityTouchPoint = StartEndType.Start;
			SecondEntityTouchPoint = StartEndType.End;
			pntTouch = ToPoint3D(FirstEntity.Vertices[0]);
			isTouch = true;
		}
		if (buCompare5.EQ(FirstEntity.Vertices[FirstEntity.Vertices.Count - 1], SecondEntity.Vertices[0], Resolution))
		{
			FirstEntityTouchPoint = StartEndType.End;
			SecondEntityTouchPoint = StartEndType.Start;
			pntTouch = ToPoint3D(FirstEntity.Vertices[FirstEntity.Vertices.Count - 1]);
			isTouch = true;
		}
		if (buCompare5.EQ(FirstEntity.Vertices[FirstEntity.Vertices.Count - 1], SecondEntity.Vertices[SecondEntity.Vertices.Count - 1], Resolution))
		{
			FirstEntityTouchPoint = StartEndType.End;
			SecondEntityTouchPoint = StartEndType.End;
			pntTouch = ToPoint3D(FirstEntity.Vertices[FirstEntity.Vertices.Count - 1]);
			isTouch = true;
		}
	}

	public void XYFromZ(Point3D StartPoint, Point3D EndPoint, double ZValue, ref Point3D CalcPoint)
	{
		try
		{
			double num = StartPoint.X - EndPoint.X;
			double num2 = StartPoint.Y - EndPoint.Y;
			double num3 = StartPoint.Z - EndPoint.Z;
			double num4 = StartPoint.Z - ZValue;
			if (num3 == 0.0)
			{
				CalcPoint = new Point3D(StartPoint.X, StartPoint.Y, StartPoint.Z);
				return;
			}
			double num5 = num4 / num3;
			CalcPoint = new Point3D(StartPoint.X - num * num5, StartPoint.Y - num2 * num5, ZValue);
		}
		catch (Exception mSException)
		{
			string text = "StartPoint: " + StartPoint.ToString() + " - EndPoint: " + EndPoint.ToString() + " - ZValue: " + ZValue;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void CircularZHeightRampByLengthAndHeight(double Length, double ZUp, double ZDown, double ArcRatio, int Count, ref List<double> Heights, ref List<Point3D> Points)
	{
		List<Point3D> Vertices = new List<Point3D>();
		Point3D ArcCenter = new Point3D();
		double ArcSA = 0.0;
		double ArcEA = 0.0;
		double num = 0.0;
		Point3D point3D = new Point3D(0.0, ZUp, 0.0);
		Point3D point3D2 = new Point3D(Length, ZDown, 0.0);
		if (ZDown > ZUp)
		{
			point3D = new Point3D(0.0, ZDown, 0.0);
			point3D2 = new Point3D(Length, ZUp, 0.0);
		}
		num = Length / ArcRatio;
		double radius = num;
		for (double num2 = 1.0; num2 <= 1000.0; num2 += 0.5)
		{
			Point3D startPoint = new Point3D(point3D2.X, point3D2.Y + num2);
			double num3 = Length3D(startPoint, point3D);
			Math.Abs(num3 - num2);
			if (buCompare5.EQ(num3, num2, 1.0))
			{
				radius = num3;
				num2 = 1000.0;
			}
		}
		ArcWithTwoPointAndRadius(point3D, point3D2, radius, CW: false, Plane.XY, ref ArcCenter, ref ArcSA, ref ArcEA);
		ArcWithCenter(ArcCenter, radius, ArcSA, ArcEA, Plane.XY, new EntityResolution(1.0, Count - 1, 10.0, EntityResolutionType.ByNumber), ref Vertices);
		RotateByMatrix(new Point3D(), 90.0, VectorType.XVector, ref Vertices);
		if (!(ZUp > ZDown))
		{
			if (Vertices[0].Z > Vertices[Vertices.Count - 1].Z)
			{
				Vertices.Reverse();
			}
		}
		else if (Vertices[0].Z < Vertices[Vertices.Count - 1].Z)
		{
			Vertices.Reverse();
		}
		for (int i = 0; i <= Vertices.Count - 1; i++)
		{
			Heights.Add(Vertices[i].Z);
		}
		Points.Clear();
		Copy(Vertices, ref Points);
	}

	public bool isEntityEntityBoxBoundingIntersect(Entity entFirst, Entity entSecond)
	{
		try
		{
			if (!((entFirst.BoxMax != null) & (entSecond.BoxMax != null)))
			{
				return false;
			}
			Size3D intersectionBox = null;
			return Utility.DoOverlapOrTouchWithIntersectionBox(entFirst.BoxMin, entFirst.BoxMax, entSecond.BoxMin, entSecond.BoxMax, out intersectionBox);
		}
		catch (Exception mSException)
		{
			string text = "isEntityEntityBoxBoundingIntersect: ";
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return false;
		}
	}

	public void PointConversionByPlane(Plane FromPlane, Plane ToPlane, Point3D RefPoint, ref Point3D CalcPoint)
	{
		try
		{
			if (isPlaneXYorYX(FromPlane))
			{
				if (isPlaneXYorYX(ToPlane))
				{
					CalcPoint.X = RefPoint.X;
					CalcPoint.Y = RefPoint.Y;
					CalcPoint.Z = RefPoint.Z;
				}
				if (isPlaneXZorZX(ToPlane))
				{
					CalcPoint.X = RefPoint.X;
					CalcPoint.Z = RefPoint.Y;
					CalcPoint.Y = RefPoint.Z;
				}
				if (isPlaneYZorZY(ToPlane))
				{
					CalcPoint.Y = RefPoint.X;
					CalcPoint.Z = RefPoint.Y;
					CalcPoint.X = RefPoint.Z;
				}
			}
			if (isPlaneXZorZX(FromPlane))
			{
				if (isPlaneXYorYX(ToPlane))
				{
					CalcPoint.X = RefPoint.X;
					CalcPoint.Z = RefPoint.Y;
					CalcPoint.Y = RefPoint.Z;
				}
				if (isPlaneXZorZX(ToPlane))
				{
					CalcPoint.X = RefPoint.X;
					CalcPoint.Y = RefPoint.Y;
					CalcPoint.Z = RefPoint.Z;
				}
				if (isPlaneYZorZY(ToPlane))
				{
					CalcPoint.Y = RefPoint.X;
					CalcPoint.X = RefPoint.Y;
					CalcPoint.Z = RefPoint.Z;
				}
			}
			if (isPlaneYZorZY(FromPlane))
			{
				if (isPlaneYZorZY(ToPlane))
				{
					CalcPoint.X = RefPoint.X;
					CalcPoint.Y = RefPoint.Y;
					CalcPoint.Z = RefPoint.Z;
				}
				if (isPlaneXYorYX(ToPlane))
				{
					CalcPoint.Z = RefPoint.X;
					CalcPoint.X = RefPoint.Y;
					CalcPoint.Y = RefPoint.Z;
				}
				if (isPlaneXZorZX(ToPlane))
				{
					CalcPoint.Y = RefPoint.X;
					CalcPoint.X = RefPoint.Y;
					CalcPoint.Z = RefPoint.Z;
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "FromPlane: " + FromPlane.ToString() + " - ToPlane: " + ToPlane.ToString() + " - RefPoint: " + RefPoint.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void PointConversionByPlane(Plane FromPlane, Plane ToPlane, List<Point3D> RefPoint, ref List<Point3D> CalcPoint)
	{
		CalcPoint = new List<Point3D>();
		for (int i = 0; i <= RefPoint.Count - 1; i++)
		{
			Point3D CalcPoint2 = new Point3D();
			PointConversionByPlane(FromPlane, ToPlane, RefPoint[i], ref CalcPoint2);
			CalcPoint.Add(CalcPoint2);
		}
	}

	public void PointConversionByPlane(Plane FromPlane, Plane ToPlane, List<List<Point3D>> RefPoint, ref List<List<Point3D>> CalcPoint)
	{
		CalcPoint = new List<List<Point3D>>();
		for (int i = 0; i <= RefPoint.Count - 1; i++)
		{
			List<Point3D> CalcPoint2 = new List<Point3D>();
			PointConversionByPlane(FromPlane, ToPlane, RefPoint[i], ref CalcPoint2);
			CalcPoint.Add(CalcPoint2);
		}
	}

	public void ShiftPointsByLength(Point3D FirstRefPoints, Point3D SecondRefPoints, ref List<Point3D> Points)
	{
		ShiftPointsByLength(FirstRefPoints, SecondRefPoints, OnlyXYPlane: false, ref Points);
	}

	public void ShiftPointsByLength(Point3D FirstRefPoints, Point3D SecondRefPoints, bool OnlyXYPlane, ref List<Point3D> Points)
	{
		double num = double.MaxValue;
		int num2 = 0;
		for (int i = 0; i <= Points.Count - 1; i++)
		{
			double num3 = Length3D(FirstRefPoints, Points[i]);
			if (OnlyXYPlane)
			{
				num3 = Length3D(FirstRefPoints, Points[i], Plane.XY);
			}
			if (num3 < num)
			{
				num2 = i;
				num = num3;
			}
		}
		for (int j = 0; j <= Points.Count - 1; j++)
		{
			double num4 = Length3D(SecondRefPoints, Points[j]);
			if (OnlyXYPlane)
			{
				num4 = Length3D(SecondRefPoints, Points[j], Plane.XY);
			}
			if (num4 < num)
			{
				num = num4;
			}
		}
		if (num2 <= 0)
		{
			return;
		}
		List<Point3D> copiedPoint = new List<Point3D>();
		Copy(Points, ref copiedPoint);
		Points.Clear();
		for (int k = num2; k <= copiedPoint.Count - 1; k++)
		{
			Points.Add(ToPoint3D(copiedPoint[k]));
		}
		for (int l = 0; l < num2; l++)
		{
			if (l != 0)
			{
				Points.Add(ToPoint3D(copiedPoint[l]));
			}
			else if (!buCompare5.EQ(Points[Points.Count - 1], copiedPoint[l]))
			{
				Points.Add(ToPoint3D(copiedPoint[l]));
			}
		}
	}

	public void ShiftPointsByLength(Point3D RefPoints, ref List<Point3D> Points, bool OnlyXY = false)
	{
		double num = double.MaxValue;
		int num2 = 0;
		bool flag = IsClosed(Points);
		for (int i = 0; i <= Points.Count - 1; i++)
		{
			double num3 = 0.0;
			num3 = ((!OnlyXY) ? Length3D(RefPoints, Points[i]) : Length3D(RefPoints, Points[i], Plane.XY));
			if (num3 < num)
			{
				num2 = i;
				num = num3;
			}
		}
		if (num2 > 0)
		{
			List<Point3D> copiedPoint = new List<Point3D>();
			Copy(Points, ref copiedPoint);
			Points.Clear();
			for (int j = num2; j <= copiedPoint.Count - 1; j++)
			{
				Points.Add(ToPoint3D(copiedPoint[j]));
			}
			for (int k = 0; k < num2; k++)
			{
				if (k != 0)
				{
					Points.Add(ToPoint3D(copiedPoint[k]));
				}
				else if (!buCompare5.EQ(Points[Points.Count - 1], copiedPoint[k]))
				{
					Points.Add(ToPoint3D(copiedPoint[k]));
				}
			}
		}
		if ((flag & (Points.Count > 2)) && Points[0] != Points[Points.Count - 1])
		{
			Points.Add(ToPoint3D(Points[0]));
		}
	}

	public void ShiftList(ref List<Point3D> List, int ShiftValue)
	{
		if (ShiftValue == 0 || ShiftValue >= List.Count)
		{
			return;
		}
		if (ShiftValue < 0)
		{
			List<Point3D> copiedPoint = new List<Point3D>();
			Copy(List, ref copiedPoint);
			List.Clear();
			for (int i = Math.Abs(ShiftValue); i <= copiedPoint.Count - 1; i++)
			{
				List.Add(ToPoint3D(copiedPoint[i]));
			}
			for (int j = 0; j < Math.Abs(ShiftValue); j++)
			{
				List.Add(ToPoint3D(copiedPoint[j]));
			}
		}
		if (ShiftValue > 0)
		{
			List<Point3D> copiedPoint2 = new List<Point3D>();
			Copy(List, ref copiedPoint2);
			List.Clear();
			for (int k = copiedPoint2.Count - Math.Abs(ShiftValue) - 1; k <= copiedPoint2.Count - 1; k++)
			{
				List.Add(ToPoint3D(copiedPoint2[k]));
			}
			for (int l = 0; l < copiedPoint2.Count - Math.Abs(ShiftValue) - 1; l++)
			{
				List.Add(ToPoint3D(copiedPoint2[l]));
			}
		}
	}

	public static void OffsetPoint3D(ref List<Point3D> pnt, double offsetX, double offsetY, double offsetZ)
	{
		for (int i = 0; i < pnt.Count; i++)
		{
			pnt[i] = new Point3D(pnt[i].X + offsetX, pnt[i].Y + offsetY, pnt[i].Z + offsetZ);
		}
	}

	public static void OffsetPoint3D(ref Point3D[] pnt, double offsetX, double offsetY, double offsetZ)
	{
		for (int i = 0; i < pnt.Length; i++)
		{
			pnt[i] = new Point3D(pnt[i].X + offsetX, pnt[i].Y + offsetY, pnt[i].Z + offsetZ);
		}
	}

	public static void OffsetPoint3D(ref Point3D pnt, double offsetX, double offsetY, double offsetZ)
	{
		pnt = new Point3D(pnt.X + offsetX, pnt.Y + offsetY, pnt.Z + offsetZ);
	}

	public Pnt3D SnapFunction(Point3D Base, Vec3D SnapDistances, Plane RefPlane)
	{
		try
		{
			Pnt3D pnt3D = new Pnt3D();
			if (isPlaneXYorYX(RefPlane))
			{
				pnt3D.X = Math.Round(Base.X / SnapDistances.X) * SnapDistances.X;
				pnt3D.Y = Math.Round(Base.Y / SnapDistances.Y) * SnapDistances.Y;
				pnt3D.Z = 0.0;
			}
			if (isPlaneXZorZX(RefPlane))
			{
				pnt3D.X = Math.Round(Base.X / SnapDistances.X) * SnapDistances.X;
				pnt3D.Y = 0.0;
				pnt3D.Z = Math.Round(Base.Z / SnapDistances.Z) * SnapDistances.Z;
			}
			if (isPlaneYZorZY(RefPlane))
			{
				pnt3D.X = 0.0;
				pnt3D.Y = Math.Round(Base.Y / SnapDistances.Y) * SnapDistances.Y;
				pnt3D.Z = Math.Round(Base.Z / SnapDistances.Z) * SnapDistances.Z;
			}
			return pnt3D;
		}
		catch (Exception mSException)
		{
			string text = "Base: " + Base.ToString() + " - SnapDistances: " + SnapDistances.ToString() + " - Plane: " + RefPlane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return new Pnt3D();
		}
	}

	public void OrthoFunction(Point3D RefPnt, Point3D CenterPnt, Plane RefPlane, ref Point3D OrthoPnt, ref int OrthoDir)
	{
		try
		{
			Pnt3D pnt3D = new Pnt3D();
			if (!(RefPnt != null) || !(CenterPnt != null))
			{
				return;
			}
			double num;
			if (isPlaneXYorYX(RefPlane))
			{
				pnt3D.X = CenterPnt.X;
				pnt3D.Y = CenterPnt.Y;
				if (RefPnt.X - pnt3D.X == 0.0)
				{
					OrthoPnt.X = RefPnt.X;
					OrthoPnt.Y = RefPnt.Y;
				}
				else
				{
					OrthoPnt.X = RefPnt.X;
					OrthoPnt.Y = RefPnt.Y;
					num = (RefPnt.Y - pnt3D.Y) / (RefPnt.X - pnt3D.X);
					if (((RefPnt.X > pnt3D.X) & (RefPnt.Y > pnt3D.Y)) && num > 1.0)
					{
						OrthoPnt.X = pnt3D.X;
						OrthoPnt.Y = RefPnt.Y;
						OrthoDir = 2;
					}
					if (((RefPnt.X > pnt3D.X) & (RefPnt.Y > pnt3D.Y)) && num < 1.0)
					{
						OrthoPnt.X = RefPnt.X;
						OrthoPnt.Y = pnt3D.Y;
						OrthoDir = 1;
					}
					if (((RefPnt.X > pnt3D.X) & (RefPnt.Y < pnt3D.Y)) && num < -1.0)
					{
						OrthoPnt.X = pnt3D.X;
						OrthoPnt.Y = RefPnt.Y;
						OrthoDir = 4;
					}
					if (((RefPnt.X > pnt3D.X) & (RefPnt.Y < pnt3D.Y)) && num > -1.0)
					{
						OrthoPnt.X = RefPnt.X;
						OrthoPnt.Y = pnt3D.Y;
						OrthoDir = 1;
					}
					if (((RefPnt.X < pnt3D.X) & (RefPnt.Y < pnt3D.Y)) && num > 1.0)
					{
						OrthoPnt.X = pnt3D.X;
						OrthoPnt.Y = RefPnt.Y;
						OrthoDir = 4;
					}
					if (((RefPnt.X < pnt3D.X) & (RefPnt.Y < pnt3D.Y)) && num < 1.0)
					{
						OrthoPnt.X = RefPnt.X;
						OrthoPnt.Y = pnt3D.Y;
						OrthoDir = 3;
					}
					if (((RefPnt.X < pnt3D.X) & (RefPnt.Y > pnt3D.Y)) && num < -1.0)
					{
						OrthoPnt.X = pnt3D.X;
						OrthoPnt.Y = RefPnt.Y;
						OrthoDir = 2;
					}
					if (((RefPnt.X < pnt3D.X) & (RefPnt.Y > pnt3D.Y)) && num > -1.0)
					{
						OrthoPnt.X = RefPnt.X;
						OrthoPnt.Y = pnt3D.Y;
						OrthoDir = 3;
					}
				}
			}
			if (isPlaneXZorZX(RefPlane))
			{
				pnt3D.X = CenterPnt.X;
				pnt3D.Z = CenterPnt.Z;
				if (RefPnt.X - pnt3D.X == 0.0)
				{
					OrthoPnt.X = RefPnt.X;
					OrthoPnt.Z = RefPnt.Z;
				}
				else
				{
					OrthoPnt.X = RefPnt.X;
					OrthoPnt.Z = RefPnt.Z;
					num = (RefPnt.Z - pnt3D.Z) / (RefPnt.X - pnt3D.X);
					if (((RefPnt.X > pnt3D.X) & (RefPnt.Z > pnt3D.Z)) && num > 1.0)
					{
						OrthoPnt.X = pnt3D.X;
						OrthoPnt.Z = RefPnt.Z;
						OrthoDir = 2;
					}
					if (((RefPnt.X > pnt3D.X) & (RefPnt.Z > pnt3D.Z)) && num < 1.0)
					{
						OrthoPnt.X = RefPnt.X;
						OrthoPnt.Z = pnt3D.Z;
						OrthoDir = 1;
					}
					if (((RefPnt.X > pnt3D.X) & (RefPnt.Z < pnt3D.Z)) && num < -1.0)
					{
						OrthoPnt.X = pnt3D.X;
						OrthoPnt.Z = RefPnt.Z;
						OrthoDir = 4;
					}
					if (((RefPnt.X > pnt3D.X) & (RefPnt.Z < pnt3D.Z)) && num > -1.0)
					{
						OrthoPnt.X = RefPnt.X;
						OrthoPnt.Z = pnt3D.Z;
						OrthoDir = 1;
					}
					if (((RefPnt.X < pnt3D.X) & (RefPnt.Z < pnt3D.Z)) && num > 1.0)
					{
						OrthoPnt.X = pnt3D.X;
						OrthoPnt.Z = RefPnt.Z;
						OrthoDir = 4;
					}
					if (((RefPnt.X < pnt3D.X) & (RefPnt.Z < pnt3D.Z)) && num < 1.0)
					{
						OrthoPnt.X = RefPnt.X;
						OrthoPnt.Z = pnt3D.Z;
						OrthoDir = 3;
					}
					if (((RefPnt.X < pnt3D.X) & (RefPnt.Z > pnt3D.Z)) && num < -1.0)
					{
						OrthoPnt.X = pnt3D.X;
						OrthoPnt.Z = RefPnt.Z;
						OrthoDir = 2;
					}
					if (((RefPnt.X < pnt3D.X) & (RefPnt.Z > pnt3D.Z)) && num > -1.0)
					{
						OrthoPnt.X = RefPnt.X;
						OrthoPnt.Z = pnt3D.Z;
						OrthoDir = 3;
					}
				}
			}
			if (!isPlaneYZorZY(RefPlane))
			{
				return;
			}
			pnt3D.Y = CenterPnt.Y;
			pnt3D.Z = CenterPnt.Z;
			if (RefPnt.Y - pnt3D.Y == 0.0)
			{
				OrthoPnt.Y = RefPnt.Y;
				OrthoPnt.Z = RefPnt.Z;
				return;
			}
			OrthoPnt.Y = RefPnt.Y;
			OrthoPnt.Z = RefPnt.Z;
			num = (RefPnt.Z - pnt3D.Z) / (RefPnt.Y - pnt3D.Y);
			if (((RefPnt.Y > pnt3D.Y) & (RefPnt.Z > pnt3D.Z)) && num > 1.0)
			{
				OrthoPnt.Y = pnt3D.Y;
				OrthoPnt.Z = RefPnt.Z;
				OrthoDir = 2;
			}
			if (((RefPnt.Y > pnt3D.Y) & (RefPnt.Z > pnt3D.Z)) && num < 1.0)
			{
				OrthoPnt.Y = RefPnt.Y;
				OrthoPnt.Z = pnt3D.Z;
				OrthoDir = 1;
			}
			if (((RefPnt.Y > pnt3D.Y) & (RefPnt.Z < pnt3D.Z)) && num < -1.0)
			{
				OrthoPnt.Y = pnt3D.Y;
				OrthoPnt.Z = RefPnt.Z;
				OrthoDir = 4;
			}
			if (((RefPnt.Y > pnt3D.Y) & (RefPnt.Z < pnt3D.Z)) && num > -1.0)
			{
				OrthoPnt.Y = RefPnt.Y;
				OrthoPnt.Z = pnt3D.Z;
				OrthoDir = 1;
			}
			if (((RefPnt.Y < pnt3D.Y) & (RefPnt.Z < pnt3D.Z)) && num > 1.0)
			{
				OrthoPnt.Y = pnt3D.Y;
				OrthoPnt.Z = RefPnt.Z;
				OrthoDir = 4;
			}
			if (((RefPnt.Y < pnt3D.Y) & (RefPnt.Z < pnt3D.Z)) && num < 1.0)
			{
				OrthoPnt.Y = RefPnt.Y;
				OrthoPnt.Z = pnt3D.Z;
				OrthoDir = 3;
			}
			if (((RefPnt.Y < pnt3D.Y) & (RefPnt.Z > pnt3D.Z)) && num < -1.0)
			{
				OrthoPnt.Y = pnt3D.Y;
				OrthoPnt.Z = RefPnt.Z;
				OrthoDir = 2;
			}
			if (((RefPnt.Y < pnt3D.Y) & (RefPnt.Z > pnt3D.Z)) && num > -1.0)
			{
				OrthoPnt.Y = RefPnt.Y;
				OrthoPnt.Z = pnt3D.Z;
				OrthoDir = 3;
			}
		}
		catch (Exception mSException)
		{
			string text = "RefPnt: " + RefPnt.ToString() + " - CenterPnt: " + CenterPnt.ToString() + " - Plane: " + RefPlane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

