	public void BoxSizeCalculateSelected(EntityList refEntities, ref Point3D MinPoint, ref Point3D MidPoint, ref Point3D MaxPoint)
	{
		MinPoint = new Point3D(double.MaxValue, double.MaxValue, double.MaxValue);
		MaxPoint = new Point3D(double.MinValue, double.MinValue, double.MinValue);
		for (int i = 0; i <= refEntities.Count - 1; i++)
		{
			Entity entity = refEntities[i];
			Point3D point3D = new Point3D();
			if (!refEntities[i].Selected)
			{
				continue;
			}
			if (entity.BoxMin == null)
			{
				if (!(entity is Text))
				{
					entity.Regen(new RegenParams(0.001));
				}
				else
				{
					entity.Regen(new RegenParams(0.001, baseModel));
				}
			}
			if (entity.BoxMin != null)
			{
				Point3D point3D2 = new Point3D(entity.BoxMin.X + point3D.X, entity.BoxMin.Y + point3D.Y, entity.BoxMin.Z + point3D.Z);
				if (point3D2.X < MinPoint.X)
				{
					MinPoint.X = point3D2.X;
				}
				if (point3D2.Y < MinPoint.Y)
				{
					MinPoint.Y = point3D2.Y;
				}
				if (point3D2.Z < MinPoint.Z)
				{
					MinPoint.Z = point3D2.Z;
				}
			}
			if (entity.BoxMax != null)
			{
				Point3D point3D3 = new Point3D(entity.BoxMax.X + point3D.X, entity.BoxMax.Y + point3D.Y, entity.BoxMax.Z + point3D.Z);
				if (MaxPoint.X < point3D3.X)
				{
					MaxPoint.X = point3D3.X;
				}
				if (MaxPoint.Y < point3D3.Y)
				{
					MaxPoint.Y = point3D3.Y;
				}
				if (MaxPoint.Z < point3D3.Z)
				{
					MaxPoint.Z = point3D3.Z;
				}
			}
		}
		MidPoint = MiddlePointOfLine(MinPoint, MaxPoint);
	}

