	public void BoxSizeCornerPoints(Point3D MinPoint, Point3D MaxPoint, Plane refPlane, ref Point3D LeftBottom, ref Point3D RightBottom, ref Point3D RightTop, ref Point3D LeftTop)
	{
		if (isPlaneXYorYX(refPlane))
		{
			LeftBottom.X = MinPoint.X;
			LeftBottom.Y = MinPoint.Y;
			LeftBottom.Z = MinPoint.Z;
			RightBottom.X = MaxPoint.X;
			RightBottom.Y = MinPoint.Y;
			RightBottom.Z = MinPoint.Z;
			RightTop.X = MaxPoint.X;
			RightTop.Y = MaxPoint.Y;
			RightTop.Z = MinPoint.Z;
			LeftTop.X = MinPoint.X;
			LeftTop.Y = MaxPoint.Y;
			LeftTop.Z = MinPoint.Z;
		}
		if (isPlaneXZorZX(refPlane))
		{
			LeftBottom.X = MinPoint.X;
			LeftBottom.Y = MinPoint.Y;
			LeftBottom.Z = MinPoint.Z;
			RightBottom.X = MaxPoint.X;
			RightBottom.Y = MinPoint.Y;
			RightBottom.Z = MinPoint.Z;
			RightTop.X = MaxPoint.X;
			RightTop.Y = MinPoint.Y;
			RightTop.Z = MaxPoint.Z;
			LeftTop.X = MinPoint.X;
			LeftTop.Y = MinPoint.Y;
			LeftTop.Z = MaxPoint.Z;
		}
		if (isPlaneYZorZY(refPlane))
		{
			LeftBottom.X = MinPoint.X;
			LeftBottom.Y = MinPoint.Y;
			LeftBottom.Z = MinPoint.Z;
			RightBottom.X = MinPoint.X;
			RightBottom.Y = MaxPoint.Y;
			RightBottom.Z = MinPoint.Z;
			RightTop.X = MinPoint.X;
			RightTop.Y = MaxPoint.Y;
			RightTop.Z = MaxPoint.Z;
			LeftTop.X = MinPoint.X;
			LeftTop.Y = MinPoint.Y;
			LeftTop.Z = MaxPoint.Z;
		}
	}

	public bool isBoxSizesIntersection(Point3D refMinPoint, Point3D refMaxPoint, Point3D checkMinPoint, Point3D checkMaxPoint, Plane refPlane)
	{
		if (!((refMinPoint == null) | (refMaxPoint == null) | (checkMinPoint == null) | (checkMaxPoint == null)))
		{
			Point3D LeftBottom = new Point3D();
			Point3D RightBottom = new Point3D();
			Point3D RightTop = new Point3D();
			Point3D LeftTop = new Point3D();
			BoxSizeCornerPoints(refMinPoint, refMaxPoint, refPlane, ref LeftBottom, ref RightBottom, ref RightTop, ref LeftTop);
			if (!IsPointInsideBoxsize(LeftBottom, checkMinPoint, checkMaxPoint, refPlane))
			{
				if (!IsPointInsideBoxsize(RightBottom, checkMinPoint, checkMaxPoint, refPlane))
				{
					if (!IsPointInsideBoxsize(RightTop, checkMinPoint, checkMaxPoint, refPlane))
					{
						if (!IsPointInsideBoxsize(LeftTop, checkMinPoint, checkMaxPoint, refPlane))
						{
							BoxSizeCornerPoints(checkMinPoint, checkMaxPoint, refPlane, ref LeftBottom, ref RightBottom, ref RightTop, ref LeftTop);
							if (!IsPointInsideBoxsize(LeftBottom, refMinPoint, refMaxPoint, refPlane))
							{
								if (!IsPointInsideBoxsize(RightBottom, refMinPoint, refMaxPoint, refPlane))
								{
									if (!IsPointInsideBoxsize(RightTop, refMinPoint, refMaxPoint, refPlane))
									{
										if (!IsPointInsideBoxsize(LeftTop, refMinPoint, refMaxPoint, refPlane))
										{
											return false;
										}
										return true;
									}
									return true;
								}
								return true;
							}
							return true;
						}
						return true;
					}
					return true;
				}
				return true;
			}
			return true;
		}
		return false;
	}

	public bool isBoxSizeInsideBoxSize(Point3D refMinPoint, Point3D refMaxPoint, Point3D checkMinPoint, Point3D checkMaxPoint, Plane refPlane)
	{
		if (!((refMinPoint == null) | (refMaxPoint == null) | (checkMinPoint == null) | (checkMaxPoint == null)))
		{
			if (!isPlaneXYorYX(refPlane) || !((checkMinPoint.X >= refMinPoint.X) & (checkMinPoint.Y >= refMinPoint.Y)) || !((checkMaxPoint.X <= refMaxPoint.X) & (checkMaxPoint.Y <= refMaxPoint.Y)))
			{
				if (!isPlaneXZorZX(refPlane) || !((checkMinPoint.X > refMinPoint.X) & (checkMinPoint.Z > refMinPoint.Z)) || !((checkMaxPoint.X < refMaxPoint.X) & (checkMaxPoint.Z < refMaxPoint.Z)))
				{
					if (!isPlaneYZorZY(refPlane) || !((checkMinPoint.Y > refMinPoint.Y) & (checkMinPoint.Z > refMinPoint.Z)) || !((checkMaxPoint.Y < refMaxPoint.Y) & (checkMaxPoint.Z < refMaxPoint.Z)))
					{
						return false;
					}
					return true;
				}
				return true;
			}
			return true;
		}
		return false;
	}

	public void BoxSizeWithContentAlignment(List<Point3D> RefPoints, WorkPlane Plane, ref AlingmentPoints3D AlignPoints)
	{
		try
		{
			Point3D MinPoint = new Point3D();
			Point3D MaxPoint = new Point3D();
			Point3D MidPoint = new Point3D();
			BoxSizeCalculate(RefPoints, ref MinPoint, ref MidPoint, ref MaxPoint);
			if (WorkPlane.isPlaneXY(Plane))
			{
				AlignPoints.pntTopLeft = new Point3D(MinPoint.X, MaxPoint.Y, MinPoint.Z);
				AlignPoints.pntTopCenter = new Point3D(MidPoint.X, MaxPoint.Y, MinPoint.Z);
				AlignPoints.pntTopRight = new Point3D(MaxPoint.X, MaxPoint.Y, MinPoint.Z);
				AlignPoints.pntMiddleLeft = new Point3D(MinPoint.X, MidPoint.Y, MinPoint.Z);
				AlignPoints.pntMiddleCenter = new Point3D(MidPoint.X, MidPoint.Y, MinPoint.Z);
				AlignPoints.pntMiddleRight = new Point3D(MaxPoint.X, MidPoint.Y, MinPoint.Z);
				AlignPoints.pntBottomLeft = new Point3D(MinPoint.X, MinPoint.Y, MinPoint.Z);
				AlignPoints.pntBottomCenter = new Point3D(MidPoint.X, MinPoint.Y, MinPoint.Z);
				AlignPoints.pntBottomRight = new Point3D(MaxPoint.X, MinPoint.Y, MinPoint.Z);
			}
			if (WorkPlane.isPlaneXZ(Plane))
			{
				AlignPoints.pntTopLeft = new Point3D(MinPoint.X, MinPoint.Y, MaxPoint.Z);
				AlignPoints.pntTopCenter = new Point3D(MidPoint.X, MinPoint.Y, MaxPoint.Z);
				AlignPoints.pntTopRight = new Point3D(MaxPoint.X, MinPoint.Y, MaxPoint.Z);
				AlignPoints.pntMiddleLeft = new Point3D(MinPoint.X, MinPoint.Y, MidPoint.Z);
				AlignPoints.pntMiddleCenter = new Point3D(MidPoint.X, MinPoint.Y, MidPoint.Z);
				AlignPoints.pntMiddleRight = new Point3D(MaxPoint.X, MinPoint.Y, MidPoint.Z);
				AlignPoints.pntBottomLeft = new Point3D(MinPoint.X, MinPoint.Y, MinPoint.Z);
				AlignPoints.pntBottomCenter = new Point3D(MidPoint.X, MinPoint.Y, MinPoint.Z);
				AlignPoints.pntBottomRight = new Point3D(MaxPoint.X, MinPoint.Y, MinPoint.Z);
			}
			if (WorkPlane.isPlaneYZ(Plane))
			{
				AlignPoints.pntTopLeft = new Point3D(MinPoint.X, MinPoint.Y, MaxPoint.Z);
				AlignPoints.pntTopCenter = new Point3D(MinPoint.X, MidPoint.Y, MaxPoint.Z);
				AlignPoints.pntTopRight = new Point3D(MinPoint.X, MaxPoint.Y, MaxPoint.Z);
				AlignPoints.pntMiddleLeft = new Point3D(MinPoint.X, MinPoint.Y, MidPoint.Z);
				AlignPoints.pntMiddleCenter = new Point3D(MinPoint.X, MidPoint.Y, MidPoint.Z);
				AlignPoints.pntMiddleRight = new Point3D(MinPoint.X, MaxPoint.Y, MidPoint.Z);
				AlignPoints.pntBottomLeft = new Point3D(MinPoint.X, MinPoint.Y, MinPoint.Z);
				AlignPoints.pntBottomCenter = new Point3D(MinPoint.X, MidPoint.Y, MinPoint.Z);
				AlignPoints.pntBottomRight = new Point3D(MinPoint.X, MaxPoint.Y, MinPoint.Z);
			}
		}
		catch (Exception mSException)
		{
			string text = "RefPoints: " + RefPoints.Count + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

