	public void AddValueToPointList(double x, double y, double z, ref List<Point3D> pntList)
	{
		for (int i = 0; i <= pntList.Count - 1; i++)
		{
			Point3D value = new Point3D(pntList[i].X + x, pntList[i].Y + y, pntList[i].Z + z);
			pntList[i] = value;
		}
	}

	public void AddValueToPointList(double x, double y, double z, ref List<PointRGB> pntList)
	{
		for (int i = 0; i <= pntList.Count - 1; i++)
		{
			Color color = Color.FromArgb(255, pntList[i].R, pntList[i].G, pntList[i].B);
			PointRGB value = new PointRGB(pntList[i].X + x, pntList[i].Y + y, pntList[i].Z + z, color.R, color.G, color.B);
			pntList[i] = value;
		}
	}

	public void AddPointOffsetedPath(List<Point3D> ModifiedPoints, List<Point3D> SortedOriginalPoints, double Offset, bool Closed, ClockDirectionType ClockDir, double Resolution, ref List<Point3D> CalcPoints)
	{
		double num = PointAngle(SortedOriginalPoints[1], SortedOriginalPoints[0], Plane.XY);
		Point3D EndPnt = new Point3D();
		Point3D EndPnt2 = new Point3D();
		LineWithLengthAndAngle(SortedOriginalPoints[0], Math.Abs(Offset), num + 90.0, Plane.XY, ref EndPnt);
		LineWithLengthAndAngle(SortedOriginalPoints[0], Math.Abs(Offset), num - 90.0, Plane.XY, ref EndPnt2);
		List<Point3D> copiedPoint = new List<Point3D>();
		Copy(ModifiedPoints, ref copiedPoint);
		for (int i = 1; i <= copiedPoint.Count - 1; i++)
		{
			Point3D point3D = new Point3D();
			if (isPointOverLine(copiedPoint[i - 1], copiedPoint[i], EndPnt, Resolution))
			{
				copiedPoint.Insert(i, new Point3D(point3D.X, point3D.Y, copiedPoint[i].Z));
				i = copiedPoint.Count;
			}
			if (i <= copiedPoint.Count - 1 && isPointOverLine(copiedPoint[i - 1], copiedPoint[i], EndPnt2, Resolution))
			{
				copiedPoint.Insert(i, new Point3D(point3D.X, point3D.Y, copiedPoint[i].Z));
				i = copiedPoint.Count;
			}
		}
		ClockDirectionType clockDirection = GetClockDirection(ModifiedPoints, Plane.XY);
		if (clockDirection != ClockDir && Closed)
		{
			ModifiedPoints.Reverse();
		}
		CalcPoints = new List<Point3D>(copiedPoint);
	}

	public void SetValueToPointList(double x, double y, double z, bool XEnable, bool YEnable, bool ZEnable, ref List<Point3D> pntList)
	{
		for (int i = 0; i <= pntList.Count - 1; i++)
		{
			Point3D point3D = new Point3D();
			if (!XEnable)
			{
				point3D.X = pntList[i].X;
			}
			else
			{
				point3D.X = x;
			}
			if (!YEnable)
			{
				point3D.Y = pntList[i].Y;
			}
			else
			{
				point3D.Y = y;
			}
			if (!ZEnable)
			{
				point3D.Z = pntList[i].Z;
			}
			else
			{
				point3D.Z = z;
			}
			pntList[i] = point3D;
		}
	}

	public ClockDirectionType GetClockDirection(List<Entity> refEntities)
	{
		List<Point3D> Points = new List<Point3D>();
		EntitiesToPointsWithCamDirection(refEntities, 0.01, ref Points);
		if (!Utility.IsOrientedClockwise(Points))
		{
			return ClockDirectionType.CCW;
		}
		return ClockDirectionType.CW;
	}

	public ClockDirectionType GetClockDirection(buEntity refEntities)
	{
		List<Point3D> Points = new List<Point3D>();
		EntitiesToPointsWithCamDirection(refEntities, 0.01, ref Points);
		if (!Utility.IsOrientedClockwise(Points))
		{
			return ClockDirectionType.CCW;
		}
		return ClockDirectionType.CW;
	}

