	public ClockDirectionType GetClockDirection(List<Point3D> Vertices, Plane refPlane, ref double TotalArea)
	{
		try
		{
			double num = 0.0;
			double num2 = 0.0;
			List<Point3D> copiedPoint = new List<Point3D>();
			Copy(Vertices, ref copiedPoint);
			if (!IsClosed(copiedPoint))
			{
				copiedPoint.Add(ToPoint3D(Vertices[0]));
			}
			if (isPlaneXYorYX(refPlane))
			{
				for (int i = 1; i <= copiedPoint.Count - 1; i++)
				{
					_ = copiedPoint[i].X - copiedPoint[i - 1].X;
					_ = copiedPoint[i].Y + copiedPoint[i - 1].Y;
					num += (copiedPoint[i].X - copiedPoint[i - 1].X) * (copiedPoint[i].Y + copiedPoint[i - 1].Y) / 2.0;
					num2 += (copiedPoint[i - 1].X * copiedPoint[i].Y - copiedPoint[i].X * copiedPoint[i - 1].Y) / 2.0;
				}
			}
			if (isPlaneXZorZX(refPlane))
			{
				for (int j = 1; j <= copiedPoint.Count - 1; j++)
				{
					num += (copiedPoint[j].X - copiedPoint[j - 1].X) * (copiedPoint[j].Z + copiedPoint[j - 1].Z) / 2.0;
				}
			}
			if (isPlaneYZorZY(refPlane))
			{
				for (int k = 1; k <= copiedPoint.Count - 1; k++)
				{
					num += (copiedPoint[k].Y - copiedPoint[k - 1].Y) * (copiedPoint[k].Z + copiedPoint[k - 1].Z) / 2.0;
				}
			}
			TotalArea = num;
			if (!(num > 0.0))
			{
				return ClockDirectionType.CCW;
			}
			return ClockDirectionType.CW;
		}
		catch (Exception mSException)
		{
			string text = "Vertices: " + Vertices.Count;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return ClockDirectionType.CW;
		}
	}

	public bool IsPointInsideWindow(Point3D Base, Point3D ControledPoint, double WindowSize, Plane refPlane)
	{
		try
		{
			if (!isPlaneXYorYX(refPlane))
			{
				if (!isPlaneXZorZX(refPlane))
				{
					if (!isPlaneYZorZY(refPlane))
					{
						if (((Base.X - WindowSize / 2.0 <= ControledPoint.X) & (ControledPoint.X <= Base.X + WindowSize / 2.0)) && ((Base.Y - WindowSize / 2.0 <= ControledPoint.Y) & (ControledPoint.Y <= Base.Y + WindowSize / 2.0)) && ((Base.Z - WindowSize / 2.0 <= ControledPoint.Z) & (ControledPoint.Z <= Base.Z + WindowSize / 2.0)))
						{
							return true;
						}
					}
					else if (((Base.Y - WindowSize / 2.0 <= ControledPoint.Y) & (ControledPoint.Y <= Base.Y + WindowSize / 2.0)) && ((Base.Z - WindowSize / 2.0 <= ControledPoint.Z) & (ControledPoint.Z <= Base.Z + WindowSize / 2.0)))
					{
						return true;
					}
				}
				else if (((Base.X - WindowSize / 2.0 <= ControledPoint.X) & (ControledPoint.X <= Base.X + WindowSize / 2.0)) && ((Base.Z - WindowSize / 2.0 <= ControledPoint.Z) & (ControledPoint.Z <= Base.Z + WindowSize / 2.0)))
				{
					return true;
				}
			}
			else if (((Base.X - WindowSize / 2.0 <= ControledPoint.X) & (ControledPoint.X <= Base.X + WindowSize / 2.0)) && ((Base.Y - WindowSize / 2.0 <= ControledPoint.Y) & (ControledPoint.Y <= Base.Y + WindowSize / 2.0)))
			{
				return true;
			}
			return false;
		}
		catch (Exception mSException)
		{
			string text = "Base: " + Base.ToString() + " - ControledPoint: " + ControledPoint.ToString() + " - Resolution: " + WindowSize;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return false;
		}
	}

	public bool IsPointInsideWindow(Point3D Base, Point3D ControledPoint, double Width, double Height, Plane refPlane)
	{
		try
		{
			if (isPlaneXYorYX(refPlane) && ((Base.X - Width / 2.0 <= ControledPoint.X) & (ControledPoint.X <= Base.X + Width / 2.0)) && ((Base.Y - Height / 2.0 <= ControledPoint.Y) & (ControledPoint.Y <= Base.Y + Height / 2.0)))
			{
				return true;
			}
			if (isPlaneXZorZX(refPlane) && ((Base.X - Width / 2.0 <= ControledPoint.X) & (ControledPoint.X <= Base.X + Width / 2.0)) && ((Base.Z - Height / 2.0 <= ControledPoint.Z) & (ControledPoint.Z <= Base.Z + Height / 2.0)))
			{
				return true;
			}
			if (isPlaneYZorZY(refPlane) && ((Base.Y - Width / 2.0 <= ControledPoint.Y) & (ControledPoint.Y <= Base.Y + Width / 2.0)) && ((Base.Z - Height / 2.0 <= ControledPoint.Z) & (ControledPoint.Z <= Base.Z + Height / 2.0)))
			{
				return true;
			}
		}
		catch (Exception mSException)
		{
			string text = "Base: " + Base.ToString() + " - ControledPoint: " + ControledPoint.ToString() + " - Width: " + Width + " - Height: " + Height;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return false;
		}
		return false;
	}

	public bool IsPointInsideWindow(Point3D LeftBottom, Point3D RightTop, Point3D ControledPoint, Plane refPlane, bool UseEqualCondition)
	{
		try
		{
			if (!UseEqualCondition)
			{
				if (isPlaneXYorYX(refPlane) && ((LeftBottom.X < ControledPoint.X) & (ControledPoint.X < RightTop.X)) && ((LeftBottom.Y < ControledPoint.Y) & (ControledPoint.Y < RightTop.Y)))
				{
					return true;
				}
				if (isPlaneXZorZX(refPlane) && ((LeftBottom.X < ControledPoint.X) & (ControledPoint.X < RightTop.X)) && ((LeftBottom.Z < ControledPoint.Z) & (ControledPoint.Z < RightTop.Z)))
				{
					return true;
				}
				if (isPlaneYZorZY(refPlane) && ((LeftBottom.Y < ControledPoint.Y) & (ControledPoint.Y < RightTop.Y)) && ((LeftBottom.Z < ControledPoint.Z) & (ControledPoint.Z < RightTop.Z)))
				{
					return true;
				}
			}
			else
			{
				if (isPlaneXYorYX(refPlane) && (buCompare5.LE(LeftBottom.X, ControledPoint.X) & buCompare5.LE(ControledPoint.X, RightTop.X)) && (buCompare5.LE(LeftBottom.Y, ControledPoint.Y) & buCompare5.LE(ControledPoint.Y, RightTop.Y)))
				{
					return true;
				}
				if (isPlaneXZorZX(refPlane) && ((LeftBottom.X <= ControledPoint.X) & (ControledPoint.X <= RightTop.X)) && ((LeftBottom.Z <= ControledPoint.Z) & (ControledPoint.Z <= RightTop.Z)))
				{
					return true;
				}
				if (isPlaneYZorZY(refPlane) && ((LeftBottom.Y <= ControledPoint.Y) & (ControledPoint.Y <= RightTop.Y)) && ((LeftBottom.Z <= ControledPoint.Z) & (ControledPoint.Z <= RightTop.Z)))
				{
					return true;
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "LeftBottom: " + LeftBottom.ToString() + " - RightTop: " + RightTop.ToString() + " - ControledPoint: " + ControledPoint.ToString() + " - UseEqualCondition: " + UseEqualCondition;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return false;
		}
		return false;
	}

