	public void ShiftPointList(ref List<Point3D> List, int ShiftValue)
	{
		if (ShiftValue == 0 || ShiftValue >= List.Count)
		{
			return;
		}
		if (ShiftValue < 0)
		{
			List<Point3D> CopyPnt = new List<Point3D>();
			ToPoint3D(List, ref CopyPnt);
			if (IsClosed(CopyPnt) && ShiftValue != 0)
			{
				CopyPnt.RemoveAt(CopyPnt.Count - 1);
			}
			List.Clear();
			for (int i = Math.Abs(ShiftValue); i <= CopyPnt.Count - 1; i++)
			{
				List.Add(ToPoint3D(CopyPnt[i]));
			}
			for (int j = 0; j < Math.Abs(ShiftValue); j++)
			{
				List.Add(ToPoint3D(CopyPnt[j]));
			}
			List.Add(new Point3D(List[0].X, List[0].Y, List[0].Z));
		}
		if (ShiftValue > 0)
		{
			List<Point3D> CopyPnt2 = new List<Point3D>();
			ToPoint3D(List, ref CopyPnt2);
			List.Clear();
			for (int k = CopyPnt2.Count - Math.Abs(ShiftValue) - 1; k <= CopyPnt2.Count - 1; k++)
			{
				List.Add(ToPoint3D(CopyPnt2[k]));
			}
			for (int l = 0; l < CopyPnt2.Count - Math.Abs(ShiftValue) - 1; l++)
			{
				List.Add(ToPoint3D(CopyPnt2[l]));
			}
		}
	}

