	public void PointFilterByLengthCornerPoint(double FilterLength, ref List<Point3D> Vertice)
	{
		try
		{
			List<Point3D> list = new List<Point3D>();
			List<Point3D> list2 = new List<Point3D>();
			double num = 0.0;
			if (Vertice.Count <= 0)
			{
				return;
			}
			for (int i = 0; i <= Vertice.Count - 1; i++)
			{
				list.Add(ToPoint3D(Vertice[i]));
			}
			list2.Add(ToPoint3D(list[0]));
			AngleVector angleVector = new AngleVector();
			for (int j = 1; j <= list.Count - 1; j++)
			{
				num = Length3D(list2[list2.Count - 1], list[j]);
				double num2 = Length2D(list2[list2.Count - 1], list[j], Plane.YZ);
				double num3 = Length2D(list2[list2.Count - 1], list[j], Plane.XZ);
				double num4 = Length2D(list2[list2.Count - 1], list[j], Plane.YZ);
				new Point3D(list[j - 1].X, list[j - 1].Y, list[j - 1].Z);
				new Point3D(list[j].X, list[j].Y, list[j].Z);
				AngleVector angleVector2 = new AngleVector();
				angleVector2.X = PointAngle(list[j], list[j - 1], Plane.YZ);
				angleVector2.Y = PointAngle(list[j], list[j - 1], Plane.XZ);
				angleVector2.Z = PointAngle(list[j], list[j - 1], Plane.XY);
				bool flag = false;
				double num5 = Math.Abs(angleVector2.X - angleVector.X);
				double num6 = Math.Abs(angleVector2.Y - angleVector.Y);
				double num7 = Math.Abs(angleVector2.Z - angleVector.Z);
				if (num5 > 360.0)
				{
					num5 -= 360.0;
				}
				if (num6 > 360.0)
				{
					num6 -= 360.0;
				}
				if (num7 > 360.0)
				{
					num7 -= 360.0;
				}
				if (num5 > 180.0)
				{
					num5 -= 180.0;
				}
				if (num6 > 180.0)
				{
					num6 -= 180.0;
				}
				if (num7 > 180.0)
				{
					num7 -= 180.0;
				}
				if (num2 < 0.1)
				{
					num5 = 0.0;
				}
				if (num3 < 0.1)
				{
					num6 = 0.0;
				}
				if (num4 < 0.1)
				{
					num7 = 0.0;
				}
				if (((num5 > 30.0 && num5 < 170.0) || (num6 > 30.0 && num6 < 170.0) || (num7 > 30.0 && num7 < 170.0)) && j > 1)
				{
					flag = true;
				}
				if (flag)
				{
					list2.Add(ToPoint3D(list[j]));
				}
				else if (num > FilterLength)
				{
					if (!(num < FilterLength * 2.0))
					{
						int num8 = Convert.ToInt32(num / FilterLength);
						Line line = new Line(list2[list2.Count - 1], list[j]);
						double num9 = (line.Domain.t1 - line.Domain.t0) / (double)num8;
						for (int k = 1; k < num8; k++)
						{
							Point3D item = line.PointAt(num9 * (double)k);
							list2.Add(item);
						}
					}
					else
					{
						list2.Add(ToPoint3D(list[j]));
					}
				}
				angleVector = new AngleVector(angleVector2);
			}
			if ((list.Count >= 2) & (list2.Count == 1))
			{
				list2.Add(ToPoint3D(list[list.Count - 1]));
			}
			if (!buCompare5.EQ(list2[list2.Count - 1], list[list.Count - 1]))
			{
				list2.Add(ToPoint3D(list[list.Count - 1]));
			}
			Vertice.Clear();
			Vertice = new List<Point3D>();
			Copy(list2, ref Vertice);
		}
		catch (Exception mSException)
		{
			string text = "FilterLength: " + FilterLength;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void PointFilterByLength(double FilterLength, ref List<Point3D> Vertice)
	{
		try
		{
			List<Point3D> list = new List<Point3D>();
			List<Point3D> list2 = new List<Point3D>();
			double num = 0.0;
			if (Vertice.Count <= 0)
			{
				return;
			}
			for (int i = 0; i <= Vertice.Count - 1; i++)
			{
				list.Add(ToPoint3D(Vertice[i]));
			}
			list2.Add(ToPoint3D(list[0]));
			for (int j = 1; j <= list.Count - 1; j++)
			{
				num = Length3D(list2[list2.Count - 1], list[j]);
				if (!(num > FilterLength))
				{
					continue;
				}
				if (!(num < FilterLength * 2.0))
				{
					int num2 = Convert.ToInt32(num / FilterLength);
					Line line = new Line(list2[list2.Count - 1], list[j]);
					double num3 = (line.Domain.t1 - line.Domain.t0) / (double)num2;
					for (int k = 1; k < num2; k++)
					{
						Point3D item = line.PointAt(num3 * (double)k);
						list2.Add(item);
					}
				}
				else
				{
					list2.Add(ToPoint3D(list[j]));
				}
			}
			if ((list.Count >= 2) & (list2.Count == 1))
			{
				list2.Add(ToPoint3D(list[list.Count - 1]));
			}
			if (!buCompare5.EQ(list2[list2.Count - 1], list[list.Count - 1]))
			{
				list2.Add(ToPoint3D(list[list.Count - 1]));
			}
			Vertice.Clear();
			Vertice = new List<Point3D>();
			Copy(list2, ref Vertice);
		}
		catch (Exception mSException)
		{
			string text = "FilterLength: " + FilterLength;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void RemoveSmallLengthFromPoints(double Length, ref List<Point3D> Vertice)
	{
		try
		{
			new List<Point3D>();
			List<Point3D> list = new List<Point3D>();
			double num = 0.0;
			if (Vertice.Count <= 0)
			{
				return;
			}
			list.Add(ToPoint3D(Vertice[0]));
			for (int i = 1; i <= Vertice.Count - 1; i++)
			{
				num += Length3D(list[list.Count - 1], Vertice[i]);
				if (num > Length)
				{
					list.Add(ToPoint3D(Vertice[i]));
					num = 0.0;
				}
			}
			if (!buCompare5.EQ(Vertice[Vertice.Count - 1], list[list.Count - 1]))
			{
				list.Add(ToPoint3D(Vertice[Vertice.Count - 1]));
			}
			Vertice.Clear();
			Vertice = new List<Point3D>();
			Copy(list, ref Vertice);
		}
		catch (Exception mSException)
		{
			string text = "RemoveSmallLengthFromPoints: " + Length;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public static void Copy(List<List<Point3D>> refPoint, ref List<List<Point3D>> copiedPoint)
	{
		copiedPoint = new List<List<Point3D>>();
		if (refPoint == null)
		{
			return;
		}
		for (int i = 0; i <= refPoint.Count - 1; i++)
		{
			List<Point3D> list = new List<Point3D>();
			for (int j = 0; j <= refPoint[i].Count - 1; j++)
			{
				list.Add(ToPoint3D(refPoint[i][j]));
			}
			copiedPoint.Add(list);
		}
