	public void Vector3DToVectorXYZ(Vector3D baseVactor, ref Vector3D VectorX, ref Vector3D VectorY, ref Vector3D VectorZ)
	{
		if (!(baseVactor.X > 0.0))
		{
			if (!(baseVactor.X < 0.0))
			{
				VectorX = new Vector3D(0.0, 0.0, 0.0);
			}
			else
			{
				VectorX = Vector3D.AxisMinusX;
			}
		}
		else
		{
			VectorX = Vector3D.AxisX;
		}
		if (!(baseVactor.Y > 0.0))
		{
			if (!(baseVactor.Y < 0.0))
			{
				VectorY = new Vector3D(0.0, 0.0, 0.0);
			}
			else
			{
				VectorY = Vector3D.AxisMinusY;
			}
		}
		else
		{
			VectorY = Vector3D.AxisY;
		}
		if (!(baseVactor.Z > 0.0))
		{
			if (!(baseVactor.Z < 0.0))
			{
				VectorZ = new Vector3D(0.0, 0.0, 0.0);
			}
			else
			{
				VectorZ = Vector3D.AxisMinusZ;
			}
		}
		else
		{
			VectorZ = Vector3D.AxisZ;
		}
	}

	public static bool isVectorXPlus(Vector3D refVector, double Resolution = 0.001)
	{
		if (!(buCompare5.EQ(refVector.X, 1.0, Resolution) & buCompare5.EQ(refVector.Y, 0.0, Resolution) & buCompare5.EQ(refVector.Z, 0.0, Resolution)))
		{
			return false;
		}
		return true;
	}

