	public void HatchLinear(List<Point3D> Points, double ZPosition, double Step, HorizontalVertical Direction, Plane refPlane, ref List<buEntity> calcLines)
	{
		Point3D MinPoint = new Point3D();
		Point3D MaxPoint = new Point3D();
		BoxSizeCalculate(Points, ref MinPoint, ref MaxPoint);
		if (calcLines == null)
		{
			calcLines = new List<buEntity>();
		}
		calcLines.Clear();
		List<Point3D> list = new List<Point3D>();
		for (int i = 0; i <= Points.Count - 1; i++)
		{
			list.Add(new Point3D(Points[i].X, Points[i].Y, 0.0));
		}
		if (Direction != HorizontalVertical.Horizontal)
		{
			return;
		}
		double x = MinPoint.X - 10.0;
		double x2 = MaxPoint.X + 10.0;
		double y = MinPoint.Y;
		double y2 = MaxPoint.Y;
		double num = y2 - y - Step;
		int num2 = (int)buNumeric5.RoundToLower(num / Step);
		double num3 = num / (double)num2;
		double num4 = MinPoint.Y;
		for (int j = 1; j <= num2 + 1; j++)
		{
			num4 = ((j == 1) ? (num4 + Math.Round(num3 / 2.0, 3)) : (num4 + Math.Round(num3, 3)));
			Line line = new Line(new Point3D(x, num4, 0.0), new Point3D(x2, num4, 0.0));
			LinearPath c = new LinearPath(list);
			Point3D[] source = line.IntersectWith(c);
			List<Point3D> SortingPoints = new List<Point3D>();
			SortingPoints.AddRange(source.ToArray());
			SortDeltaX(new Point3D(-100000.0, -100000.0, 0.0), SortDirectionType.Lower, ref SortingPoints);
			if (SortingPoints.Count >= 2)
			{
				buEntity item = new buLine(new Point3D(SortingPoints[0].X, num4, Math.Round(ZPosition, 3)), new Point3D(SortingPoints[SortingPoints.Count - 1].X, num4, Math.Round(ZPosition, 3)));
				calcLines.Add(item);
			}
		}
	}

	public void HatchLinear(Point3D StartPoint, double Width, double Height, double Step, HorizontalVertical Direction, HatchCuttingMode Mode, Plane refPlane, ref List<List<Entity>> calcEntities)
	{
		if (calcEntities == null)
		{
			calcEntities = new List<List<Entity>>();
		}
		calcEntities.Clear();
		if (Direction == HorizontalVertical.Horizontal)
		{
			int num = (int)buNumeric5.RoundToLower(Height / Step);
			if (num == 0)
			{
				num = 1;
			}
			double num2 = Height / (double)num;
			double num3 = 0.0;
			new Point3D();
			List<Entity> list = new List<Entity>();
			for (int i = 0; i <= num; i++)
			{
				if (isPlaneXYorYX(refPlane))
				{
					num3 = (double)i * num2;
					if (Mode == HatchCuttingMode.Forward)
					{
						list = new List<Entity>();
						Entity item = new Line(new Point3D(StartPoint.X, StartPoint.Y + num3, StartPoint.Z), new Point3D(StartPoint.X + Width, StartPoint.Y + num3, StartPoint.Z));
						list.Add(item);
						calcEntities.Add(list);
					}
					if (Mode == HatchCuttingMode.Backward)
					{
						list = new List<Entity>();
						Entity item2 = new Line(new Point3D(StartPoint.X + Width, StartPoint.Y + num3, StartPoint.Z), new Point3D(StartPoint.X, StartPoint.Y + num3, StartPoint.Z));
						list.Add(item2);
						calcEntities.Add(list);
					}
					if (Mode == HatchCuttingMode.ForwardBackward)
					{
						list = new List<Entity>();
						Entity item3 = null;
						if (i % 2 == 0)
						{
							item3 = new Line(new Point3D(StartPoint.X, StartPoint.Y + num3, StartPoint.Z), new Point3D(StartPoint.X + Width, StartPoint.Y + num3, StartPoint.Z));
						}
						if (i % 2 == 1)
						{
							item3 = new Line(new Point3D(StartPoint.X + Width, StartPoint.Y + num3, StartPoint.Z), new Point3D(StartPoint.X, StartPoint.Y + num3, StartPoint.Z));
						}
						list.Add(item3);
						calcEntities.Add(list);
					}
				}
				if (!isPlaneXZorZX(refPlane))
				{
					continue;
				}
				num3 = (double)i * num2;
				if (Mode == HatchCuttingMode.Forward)
				{
					list = new List<Entity>();
					Entity item4 = new Line(new Point3D(StartPoint.X, StartPoint.Y, StartPoint.Z + num3), new Point3D(StartPoint.X + Width, StartPoint.Y, StartPoint.Z + num3));
					list.Add(item4);
					calcEntities.Add(list);
				}
				if (Mode == HatchCuttingMode.Backward)
				{
					list = new List<Entity>();
					Entity item5 = new Line(new Point3D(StartPoint.X + Width, StartPoint.Y, StartPoint.Z + num3), new Point3D(StartPoint.X, StartPoint.Y, StartPoint.Z + num3));
					list.Add(item5);
					calcEntities.Add(list);
				}
				if (Mode == HatchCuttingMode.ForwardBackward)
				{
					list = new List<Entity>();
					Entity item6 = null;
					if (i % 2 == 0)
					{
						item6 = new Line(new Point3D(StartPoint.X, StartPoint.Y, StartPoint.Z + num3), new Point3D(StartPoint.X + Width, StartPoint.Y, StartPoint.Z + num3));
					}
					if (i % 2 == 1)
					{
						item6 = new Line(new Point3D(StartPoint.X + Width, StartPoint.Y, StartPoint.Z + num3), new Point3D(StartPoint.X, StartPoint.Y, StartPoint.Z + num3));
					}
					list.Add(item6);
					calcEntities.Add(list);
				}
			}
		}
		if (Direction != HorizontalVertical.Vertical)
		{
			return;
		}
		int num4 = (int)buNumeric5.RoundToLower(Width / Step);
		if (num4 == 0)
		{
			num4 = 1;
		}
		double num5 = Width / (double)num4;
		double num6 = 0.0;
		new Point3D();
		List<Entity> list2 = new List<Entity>();
		for (int j = 0; j <= num4; j++)
		{
			if (isPlaneXYorYX(refPlane))
			{
				num6 = (double)j * num5;
				if (Mode == HatchCuttingMode.Forward)
				{
					list2 = new List<Entity>();
					Entity item7 = new Line(new Point3D(StartPoint.X + num6, StartPoint.Y, StartPoint.Z), new Point3D(StartPoint.X + num6, StartPoint.Y + Height, StartPoint.Z));
					list2.Add(item7);
					calcEntities.Add(list2);
				}
				num6 = (double)j * num5;
				if (Mode == HatchCuttingMode.Forward)
				{
					list2 = new List<Entity>();
					Entity item8 = new Line(new Point3D(StartPoint.X + num6, StartPoint.Y + Height, StartPoint.Z), new Point3D(StartPoint.X + num6, StartPoint.Y, StartPoint.Z));
					list2.Add(item8);
					calcEntities.Add(list2);
				}
				if (Mode == HatchCuttingMode.ForwardBackward)
				{
					list2 = new List<Entity>();
					Entity item9 = null;
					if (j % 2 == 0)
					{
						item9 = new Line(new Point3D(StartPoint.X + num6, StartPoint.Y, StartPoint.Z), new Point3D(StartPoint.X + num6, StartPoint.Y + Height, StartPoint.Z));
					}
					if (j % 2 == 1)
					{
						item9 = new Line(new Point3D(StartPoint.X + num6, StartPoint.Y + Height, StartPoint.Z), new Point3D(StartPoint.X + num6, StartPoint.Y, StartPoint.Z));
					}
					list2.Add(item9);
					calcEntities.Add(list2);
				}
			}
			if (!isPlaneXZorZX(refPlane))
			{
				continue;
			}
			num6 = (double)j * num5;
			if (Mode == HatchCuttingMode.Forward)
			{
				list2 = new List<Entity>();
				Entity item10 = new Line(new Point3D(StartPoint.X + num6, StartPoint.Y, StartPoint.Z), new Point3D(StartPoint.X + num6, StartPoint.Y, StartPoint.Z + Height));
				list2.Add(item10);
				calcEntities.Add(list2);
			}
			num6 = (double)j * num5;
			if (Mode == HatchCuttingMode.Forward)
			{
				list2 = new List<Entity>();
				Entity item11 = new Line(new Point3D(StartPoint.X + num6, StartPoint.Y, StartPoint.Z + Height), new Point3D(StartPoint.X + num6, StartPoint.Y, StartPoint.Z));
				list2.Add(item11);
				calcEntities.Add(list2);
			}
			if (Mode == HatchCuttingMode.ForwardBackward)
			{
				list2 = new List<Entity>();
				Entity item12 = null;
				if (j % 2 == 0)
				{
					item12 = new Line(new Point3D(StartPoint.X + num6, StartPoint.Y, StartPoint.Z), new Point3D(StartPoint.X + num6, StartPoint.Y, StartPoint.Z + Height));
				}
				if (j % 2 == 1)
				{
					item12 = new Line(new Point3D(StartPoint.X + num6, StartPoint.Y, StartPoint.Z + Height), new Point3D(StartPoint.X + num6, StartPoint.Y, StartPoint.Z));
				}
				list2.Add(item12);
				calcEntities.Add(list2);
			}
		}
	}

