	public void Move(double dX, double dY, double dZ, ref buEntitiesGroup refEntities, double Regen = 0.01)
	{
		if (refEntities.Outside != null)
		{
			for (int i = 0; i <= refEntities.Outside.Entities.Count - 1; i++)
			{
				buEntity refEntities2 = refEntities.Outside.Entities[i];
				Move(dX, dY, dZ, ref refEntities2, Regen);
			}
			if (refEntities.Outside.Points != null)
			{
				Move(dX, dY, dZ, ref refEntities.Outside.Points);
			}
		}
		if (refEntities.Text != null)
		{
			for (int j = 0; j <= refEntities.Text.Entities.Count - 1; j++)
			{
				buEntity refEntities3 = refEntities.Text.Entities[j];
				Move(dX, dY, dZ, ref refEntities3, Regen);
			}
			if (refEntities.Text.Points != null)
			{
				Move(dX, dY, dZ, ref refEntities.Text.Points);
			}
		}
		if (refEntities.Inside != null)
		{
			for (int k = 0; k <= refEntities.Inside.Count - 1; k++)
			{
				for (int l = 0; l <= refEntities.Inside[k].Entities.Count - 1; l++)
				{
					buEntity refEntities4 = refEntities.Inside[k].Entities[l];
					Move(dX, dY, dZ, ref refEntities4, Regen);
				}
				if (refEntities.Inside[k].Points != null)
				{
					Move(dX, dY, dZ, ref refEntities.Inside[k].Points);
				}
			}
		}
		if (refEntities.OpenEntities != null)
		{
			for (int m = 0; m <= refEntities.OpenEntities.Count - 1; m++)
			{
				for (int n = 0; n <= refEntities.OpenEntities[m].Entities.Count - 1; n++)
				{
					buEntity refEntities5 = refEntities.OpenEntities[m].Entities[n];
					Move(dX, dY, dZ, ref refEntities5, Regen);
				}
				if (refEntities.OpenEntities[m].Points != null)
				{
					Move(dX, dY, dZ, ref refEntities.OpenEntities[m].Points);
				}
			}
		}
		if (refEntities.Solid == null)
		{
			return;
		}
		for (int num = 0; num <= refEntities.Solid.Entities.Count - 1; num++)
		{
			buEntity refEntities6 = refEntities.Solid.Entities[num];
			Move(dX, dY, dZ, ref refEntities6, Regen);
			if (refEntities.Solid.Points != null)
			{
				Move(dX, dY, dZ, ref refEntities.Solid.Points);
			}
		}
	}

