	public void Scale(Point3D Center, double RatioX, double RatioY, double RatioZ, ref Point3D CalcPnt)
	{
		try
		{
			Point3D point3D = new Point3D(CalcPnt.X, CalcPnt.Y, CalcPnt.Z);
			point3D -= Center;
			if (RatioX != 1.0)
			{
				point3D.X *= RatioX;
			}
			if (RatioY != 1.0)
			{
				point3D.Y *= RatioY;
			}
			if (RatioZ != 1.0)
			{
				point3D.Z *= RatioZ;
			}
			point3D += Center;
			CalcPnt.X = point3D.X;
			CalcPnt.Y = point3D.Y;
			CalcPnt.Z = point3D.Z;
		}
		catch (Exception mSException)
		{
			string text = "Center: " + Center.ToString() + " - RatioX: " + RatioX + " - RatioY: " + RatioY + " - RatioZ: " + RatioZ;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

