	public void Rotate(Point3D RotatePoint, double RotateAngle, Vector3D RotateVector, ref buEntitiesGroup refEntities)
	{
		if (refEntities.Outside != null)
		{
			for (int i = 0; i <= refEntities.Outside.Entities.Count - 1; i++)
			{
				buEntity refEntity = refEntities.Outside.Entities[i];
				Rotate(RotatePoint, RotateAngle, RotateVector, ref refEntity);
			}
			if (refEntities.Outside.Points != null)
			{
				Rotate(RotatePoint, RotateAngle, Vector3DToPlane(RotateVector), ref refEntities.Outside.Points);
			}
		}
		if (refEntities.Text != null)
		{
			for (int j = 0; j <= refEntities.Text.Entities.Count - 1; j++)
			{
				buEntity refEntity2 = refEntities.Text.Entities[j];
				Rotate(RotatePoint, RotateAngle, RotateVector, ref refEntity2);
			}
			if (refEntities.Text.Points != null)
			{
				Rotate(RotatePoint, RotateAngle, Vector3DToPlane(RotateVector), ref refEntities.Text.Points);
			}
		}
		if (refEntities.Solid != null)
		{
			for (int k = 0; k <= refEntities.Solid.Entities.Count - 1; k++)
			{
				buEntity refEntity3 = refEntities.Solid.Entities[k];
				Rotate(RotatePoint, RotateAngle, RotateVector, ref refEntity3);
			}
			if (refEntities.Solid.Points != null)
			{
				Rotate(RotatePoint, RotateAngle, Vector3DToPlane(RotateVector), ref refEntities.Solid.Points);
			}
		}
		if (refEntities.Inside != null)
		{
			for (int l = 0; l <= refEntities.Inside.Count - 1; l++)
			{
				for (int m = 0; m <= refEntities.Inside[l].Entities.Count - 1; m++)
				{
					buEntity refEntity4 = refEntities.Inside[l].Entities[m];
					Rotate(RotatePoint, RotateAngle, RotateVector, ref refEntity4);
				}
				if (refEntities.Inside[l].Points != null)
				{
					Rotate(RotatePoint, RotateAngle, Vector3DToPlane(RotateVector), ref refEntities.Inside[l].Points);
				}
			}
		}
		if (refEntities.OpenEntities == null)
		{
			return;
		}
		for (int n = 0; n <= refEntities.OpenEntities.Count - 1; n++)
		{
			for (int num = 0; num <= refEntities.OpenEntities[n].Entities.Count - 1; num++)
			{
				buEntity refEntity5 = refEntities.OpenEntities[n].Entities[num];
				Rotate(RotatePoint, RotateAngle, RotateVector, ref refEntity5);
			}
			if (refEntities.OpenEntities[n].Points != null)
			{
				Rotate(RotatePoint, RotateAngle, Vector3DToPlane(RotateVector), ref refEntities.OpenEntities[n].Points);
			}
		}
	}

	public void Rotate(Point3D CenterPoint, double Angle, Vector3D RotateVector, ref List<Point3D> Points)
