			if ((RotateVector == Vector3D.AxisX) | (RotateVector == Vector3D.AxisMinusX))
			{
				plane = Plane.YZ;
			}
			if ((RotateVector == Vector3D.AxisY) | (RotateVector == Vector3D.AxisMinusY))
			{
				plane = Plane.XZ;
			}
			for (int i = 0; i <= Points.Count - 1; i++)
			{
				num = Length3D(Points[i], CenterPoint, plane);
				num2 = PointAngle(Points[i], CenterPoint, plane);
