	public void Mirror(Point3D BasePoint, Point3D MirrorPoint, Plane planeMirror, ref buEntitiesGroup EntGroup)
	{
		if (EntGroup.Outside.Entities.Count > 0)
		{
			Mirror(BasePoint, MirrorPoint, planeMirror, ref EntGroup.Outside.Entities);
			if (EntGroup.Outside.Points != null)
			{
				Mirror(BasePoint, MirrorPoint, planeMirror, ref EntGroup.Outside.Points);
			}
		}
		if (EntGroup.Outside.pntMassCenter != null)
		{
			Mirror(BasePoint, MirrorPoint, planeMirror, ref EntGroup.Outside.pntMassCenter);
		}
		if (EntGroup.Inside != null && EntGroup.Inside.Count > 0)
		{
			for (int i = 0; i <= EntGroup.Inside.Count - 1; i++)
			{
				Mirror(BasePoint, MirrorPoint, planeMirror, ref EntGroup.Inside[i].Entities);
				if (EntGroup.Inside[i].Points != null)
				{
					Mirror(BasePoint, MirrorPoint, planeMirror, ref EntGroup.Inside[i].Points);
				}
				if (EntGroup.Inside[i].pntMassCenter != null)
				{
					Mirror(BasePoint, MirrorPoint, planeMirror, ref EntGroup.Inside[i].pntMassCenter);
				}
			}
		}
		if (EntGroup.OpenEntities != null && EntGroup.OpenEntities.Count > 0)
		{
			for (int j = 0; j <= EntGroup.OpenEntities.Count - 1; j++)
			{
				Mirror(BasePoint, MirrorPoint, planeMirror, ref EntGroup.OpenEntities[j].Entities);
				if (EntGroup.OpenEntities[j].Points != null)
				{
					Mirror(BasePoint, MirrorPoint, planeMirror, ref EntGroup.OpenEntities[j].Points);
				}
				if (EntGroup.OpenEntities[j].pntMassCenter != null)
				{
					Mirror(BasePoint, MirrorPoint, planeMirror, ref EntGroup.OpenEntities[j].pntMassCenter);
				}
			}
		}
		if (EntGroup.Text != null && EntGroup.Text.Entities.Count > 0)
		{
			Mirror(BasePoint, MirrorPoint, planeMirror, ref EntGroup.Text.Entities);
			if (EntGroup.Text.Points != null)
			{
				Mirror(BasePoint, MirrorPoint, planeMirror, ref EntGroup.Text.Points);
			}
			if (EntGroup.Text.pntMassCenter != null)
			{
				Mirror(BasePoint, MirrorPoint, planeMirror, ref EntGroup.Text.pntMassCenter);
			}
		}
		if (EntGroup.Solid != null && EntGroup.Solid.Entities.Count > 0)
		{
			Mirror(BasePoint, MirrorPoint, planeMirror, ref EntGroup.Solid.Entities);
			if (EntGroup.Solid.Points != null)
			{
				Mirror(BasePoint, MirrorPoint, planeMirror, ref EntGroup.Solid.Points);
			}
			if (EntGroup.Solid.pntMassCenter != null)
			{
				Mirror(BasePoint, MirrorPoint, planeMirror, ref EntGroup.Solid.pntMassCenter);
			}
		}
	}

	public void MirrorCornerLocation(CornerLocation baseCorner, VectorXYType MirrorVector, ref CornerLocation mirroredCorner)
	{
		switch (MirrorVector)
		{
		case VectorXYType.XVector:
			switch (baseCorner)
			{
			case CornerLocation.BottomCenter:
				mirroredCorner = CornerLocation.TopCenter;
				break;
			case CornerLocation.LeftTop:
				mirroredCorner = CornerLocation.LeftBottom;
				break;
			case CornerLocation.LeftBottom:
				mirroredCorner = CornerLocation.LeftTop;
				break;
			case CornerLocation.LeftCenter:
				mirroredCorner = CornerLocation.LeftCenter;
				break;
			case CornerLocation.RightTop:
				mirroredCorner = CornerLocation.RightBottom;
				break;
			case CornerLocation.RightBottom:
				mirroredCorner = CornerLocation.RightTop;
				break;
			case CornerLocation.RightCenter:
				mirroredCorner = CornerLocation.RightCenter;
				break;
			case CornerLocation.TopCenter:
				mirroredCorner = CornerLocation.BottomCenter;
				break;
			}
			break;
		case VectorXYType.YVector:
			switch (baseCorner)
			{
			default:
				switch (baseCorner)
				{
				case CornerLocation.RightCenter:
					mirroredCorner = CornerLocation.RightCenter;
					break;
				case CornerLocation.LeftCenter:
					mirroredCorner = CornerLocation.LeftCenter;
					break;
				}
				break;
			case CornerLocation.LeftTop:
				mirroredCorner = CornerLocation.RightTop;
				break;
			case CornerLocation.LeftBottom:
				mirroredCorner = CornerLocation.RightBottom;
				break;
			case CornerLocation.LeftCenter:
				mirroredCorner = CornerLocation.RightCenter;
				break;
			case CornerLocation.RightTop:
				mirroredCorner = CornerLocation.LeftTop;
				break;
			case CornerLocation.RightBottom:
				mirroredCorner = CornerLocation.LeftBottom;
				break;
			case CornerLocation.RightCenter:
				mirroredCorner = CornerLocation.LeftCenter;
				break;
			case CornerLocation.TopCenter:
				mirroredCorner = CornerLocation.TopCenter;
				break;
			case CornerLocation.BottomCenter:
				mirroredCorner = CornerLocation.BottomCenter;
				break;
			}
			break;
		}
	}

