	}

	public void OffsetOpenContour(List<Point3D> RefPoints, double Offset, OffsetCornerType CornerTypes, CamOpenContourType OpenContourType, Plane Plane, double PlaneOffset, ref List<List<Point3D>> OffsetedPoints)
	{
		bool flag = false;
		ClipperOffset clipperOffset = new ClipperOffset();
		clipperOffset.MiterLimit = 100.0;
		new buClipper();
		List<IntPoint> list = new List<IntPoint>();
		List<IntPoint> list2 = new List<IntPoint>();
		List<List<IntPoint>> solution = new List<List<IntPoint>>();
		OffsetedPoints = new List<List<Point3D>>();
		if (RefPoints.Count > 1 && buCompare5.EQ(RefPoints[0], RefPoints[RefPoints.Count - 1], buSystem.resolutionCompare))
		{
			flag = true;
		}
		JoinType joinType = JoinType.jtRound;
		if (CornerTypes == OffsetCornerType.Round)
		{
			joinType = JoinType.jtRound;
		}
		if (CornerTypes == OffsetCornerType.Line)
		{
			joinType = JoinType.jtMiter;
		}
		if (CornerTypes == OffsetCornerType.Chamfer)
		{
			joinType = JoinType.jtSquare;
		}
		if (isPlaneXZorZX(Plane))
		{
			for (int i = 0; i <= RefPoints.Count - 1; i++)
			{
				Point3D CalcPoint = new Point3D();
				PointConversionByPlane(Plane, Plane.XY, RefPoints[i], ref CalcPoint);
				RefPoints[i] = ToPoint3D(CalcPoint);
			}
		}
		if (isPlaneYZorZY(Plane))
		{
			for (int j = 0; j <= RefPoints.Count - 1; j++)
			{
				Point3D CalcPoint2 = new Point3D();
				PointConversionByPlane(Plane, Plane.XY, RefPoints[j], ref CalcPoint2);
				RefPoints[j] = ToPoint3D(CalcPoint2);
			}
		}
		for (int k = 0; k <= RefPoints.Count - 1; k++)
		{
			IntPoint item = new IntPoint(Convert.ToInt32(RefPoints[k].X * (double)buSystem.DoubleToIntegerConts), Convert.ToInt32(RefPoints[k].Y * (double)buSystem.DoubleToIntegerConts));
			list.Add(item);
		}
		list2 = new List<IntPoint>(list);
		EndType endType = EndType.etClosedPolygon;
		if (!flag)
		{
			if (CornerTypes == OffsetCornerType.Line || CornerTypes == OffsetCornerType.Chamfer)
			{
				endType = EndType.etOpenSquare;
			}
			if (CornerTypes == OffsetCornerType.Round)
			{
				endType = EndType.etOpenRound;
			}
			if (OpenContourType == CamOpenContourType.Left || OpenContourType == CamOpenContourType.Right)
			{
				endType = EndType.etOpenButt;
			}
			Offset = Math.Abs(Offset);
		}
		clipperOffset.AddPath(list2, joinType, endType);
		clipperOffset.Execute(ref solution, Offset * (double)buSystem.DoubleToIntegerConts);
		if (solution.Count >= 1)
		{
			for (int l = 0; l <= solution.Count - 1; l++)
			{
				double num = double.MaxValue;
				int num2 = 0;
				List<Point3D> list3 = new List<Point3D>();
				for (int m = 0; m <= solution[l].Count - 1; m++)
				{
					Point3D point3D = new Point3D((double)solution[l][m].X / (double)buSystem.DoubleToIntegerConts, (double)solution[l][m].Y / (double)buSystem.DoubleToIntegerConts, solution[l][m].Z);
					point3D.Z = PlaneOffset;
					list3.Add(point3D);
					double num3 = Point3D.Distance(RefPoints[0], point3D);
					if (num3 < num)
					{
						num = num3;
						num2 = l;
					}
				}
				if (num2 == 0)
				{
				}
				if (list3.Count >= 2 && !buCompare5.EQ(list3[0], list3[list3.Count - 1], buSystem.resolutionCompare))
				{
					Point3D point3D2 = ToPoint3D(list3[0]);
					point3D2.Z = PlaneOffset;
					list3.Add(ToPoint3D(list3[0]));
				}
				OffsetedPoints.Add(list3);
			}
		}
		if (isPlaneXZorZX(Plane))
		{
			for (int n = 0; n <= OffsetedPoints.Count - 1; n++)
			{
				for (int num4 = 0; num4 <= OffsetedPoints[n].Count - 1; num4++)
				{
					Point3D CalcPoint3 = new Point3D();
					PointConversionByPlane(Plane.XY, Plane, OffsetedPoints[n][num4], ref CalcPoint3);
					OffsetedPoints[n][num4] = ToPoint3D(CalcPoint3);
				}
			}
		}
		if (!isPlaneYZorZY(Plane))
		{
			return;
		}
		for (int num5 = 0; num5 <= OffsetedPoints.Count - 1; num5++)
		{
			for (int num6 = 0; num6 <= OffsetedPoints[num5].Count - 1; num6++)
			{
				Point3D CalcPoint4 = new Point3D();
				PointConversionByPlane(Plane.XY, Plane, OffsetedPoints[num5][num6], ref CalcPoint4);
				OffsetedPoints[num5][num6] = ToPoint3D(CalcPoint4);
			}
		}
	}

