	public void OpenProfileCalculation(List<Point3D> OffsetedPoints, List<Point3D> EntityPoints, double Offset, Plane Plane, CamOpenContourType2 ContourDirection, ref List<Point3D> CalcPoints)
	{
		if (Offset == 0.0 || ContourDirection == CamOpenContourType2.Center)
		{
			return;
		}
		int num = -1;
		int num2 = -1;
		List<Point3D> copiedPoint = new List<Point3D>();
		Copy(OffsetedPoints, ref copiedPoint);
		CheckDuplicatedPointsWithPrevious(ref copiedPoint);
		ShiftPointsByLength(EntityPoints[0], EntityPoints[1], OnlyXYPlane: true, ref copiedPoint);
		Length3D(copiedPoint[0], EntityPoints[0]);
		Length3D(copiedPoint[1], EntityPoints[1]);
		if (copiedPoint.Count > 1)
		{
			double value = Length3D(copiedPoint[0], EntityPoints[0], Plane);
			double value2 = Length3D(copiedPoint[1], EntityPoints[0], Plane);
			if (buCompare5.EQ(value, value2))
			{
				ShiftList(ref copiedPoint, -1);
			}
		}
		for (int i = 0; i <= copiedPoint.Count - 1; i++)
		{
			double value3 = Length3D(EntityPoints[0], copiedPoint[i], Plane);
			double value4 = Length3D(EntityPoints[EntityPoints.Count - 1], copiedPoint[i], Plane);
			if (buCompare5.EQ(value3, Math.Abs(Offset)) && num == -1)
			{
				num = i;
			}
			if (buCompare5.EQ(value4, Math.Abs(Offset)))
			{
				num2 = i;
			}
		}
		List<Point3D> list = new List<Point3D>();
		List<Point3D> list2 = new List<Point3D>();
		for (int j = num; j < num2; j++)
		{
			if (j >= 0)
			{
				Point3D item = ToPoint3D(copiedPoint[j]);
				list.Add(item);
			}
		}
		for (int k = num2; k <= copiedPoint.Count - 1; k++)
		{
			if (k >= 0)
			{
				Point3D item2 = ToPoint3D(copiedPoint[k]);
				list2.Add(item2);
			}
		}
		list2.Reverse();
		if (list2.Count > 1)
		{
			double value5 = Length3D(list2[0], EntityPoints[0], Plane);
			double value6 = Length3D(list2[1], EntityPoints[0], Plane);
			if (buCompare5.EQ(value5, value6))
			{
				list2.RemoveAt(0);
			}
			if (list2.Count > 1)
			{
				value5 = Length3D(list2[list2.Count - 1], EntityPoints[EntityPoints.Count - 1], Plane);
				value6 = Length3D(list2[list2.Count - 2], EntityPoints[EntityPoints.Count - 1], Plane);
				if (buCompare5.EQ(value5, value6))
				{
					list2.RemoveAt(list2.Count - 1);
				}
			}
		}
		if (list.Count > 1)
		{
			double value7 = Length3D(list[0], EntityPoints[0], Plane);
			double value8 = Length3D(list[1], EntityPoints[0], Plane);
			if (buCompare5.EQ(value7, value8))
			{
				list.RemoveAt(0);
			}
			value7 = Length3D(list[list.Count - 1], EntityPoints[EntityPoints.Count - 1], Plane);
			value8 = Length3D(list[list.Count - 2], EntityPoints[EntityPoints.Count - 1], Plane);
			if (buCompare5.EQ(value7, value8))
			{
				list.RemoveAt(list.Count - 1);
			}
		}
		double num3 = 0.0;
		double num4 = 0.0;
		if (list.Count > 1)
		{
			num3 = PointAngle(list[1], EntityPoints[0], Plane);
		}
		if (list2.Count > 1)
		{
			num4 = PointAngle(list2[1], EntityPoints[0], Plane);
		}
		double num5 = Math.Abs(num3 - num4);
		if (num5 > 180.0)
		{
			if (!(num3 < num4))
			{
				num4 += 360.0;
			}
			else
			{
				num3 += 360.0;
			}
		}
		if (ContourDirection == CamOpenContourType2.Right)
		{
			if (!(num3 < num4))
			{
				Copy(list2, ref CalcPoints);
			}
			else
			{
				Copy(list, ref CalcPoints);
			}
		}
		if (ContourDirection == CamOpenContourType2.Left)
		{
			if (!(num3 > num4))
			{
				Copy(list2, ref CalcPoints);
			}
			else
			{
				Copy(list, ref CalcPoints);
			}
		}
	}

