	public void OffsetEntityAsClosed(buEntity RefEntity, double Offset, ref List<Point3D> calcPoints, ref buEntity OffsetedEntity)
	{
		buEntity OffsetedEntity2 = new buEntity();
		buEntity OffsetedEntity3 = new buEntity();
		OffsetEntity(RefEntity, Offset, CamOpenContourType.Left, ref OffsetedEntity2);
		OffsetEntity(RefEntity, Offset, CamOpenContourType.Right, ref OffsetedEntity3);
		new List<Point3D>();
		List<Point3D> copiedPoint = new List<Point3D>();
		if (calcPoints == null)
		{
			calcPoints = new List<Point3D>();
		}
		calcPoints.Clear();
		Copy(OffsetedEntity2.Vertices, ref calcPoints);
		Copy(OffsetedEntity3.Vertices, ref copiedPoint);
		copiedPoint.Reverse();
		calcPoints.AddRange(copiedPoint);
		if (calcPoints.Count > 0)
		{
			CheckDuplicatedPointsWithPrevious(ref calcPoints);
			if (!IsClosed(calcPoints))
			{
				calcPoints.Add(new Point3D(calcPoints[0].X, calcPoints[0].Y, calcPoints[0].Z));
			}
			OffsetedEntity = new buLinearPath(calcPoints);
