	public void OffsetEntityAndCreateEntityByDirection(buEntity RefEntity, double Offset, double EntityWidth, CamOpenContourType Direction, double LeadInDistance, double LeadOutDistance, ref List<Point3D> calcPoints, ref buEntity calcEntity, ref List<buEntity> OffsetedEntities, ref List<buEntity> ConnectionEntities)
	{
		buEntity OffsetedEntity = new buEntity();
		buEntity OffsetedEntity2 = new buEntity();
		OffsetEntity(RefEntity, Offset, Direction, ref OffsetedEntity);
		OffsetEntity(OffsetedEntity, EntityWidth, Direction, ref OffsetedEntity2);
		if (OffsetedEntities == null)
		{
			OffsetedEntities = new List<buEntity>();
		}
		if (ConnectionEntities == null)
		{
			ConnectionEntities = new List<buEntity>();
		}
		OffsetedEntities.Clear();
		ConnectionEntities.Clear();
		new List<Point3D>();
		List<Point3D> copiedPoint = new List<Point3D>();
		if (calcPoints == null)
		{
			calcPoints = new List<Point3D>();
		}
		calcPoints.Clear();
		Copy(OffsetedEntity.Vertices, ref calcPoints);
		Copy(OffsetedEntity2.Vertices, ref copiedPoint);
		copiedPoint.Reverse();
		calcPoints.AddRange(copiedPoint);
		if (calcPoints.Count > 0)
		{
			CheckDuplicatedPointsWithPrevious(ref calcPoints);
			if (!IsClosed(calcPoints))
			{
				calcPoints.Add(new Point3D(calcPoints[0].X, calcPoints[0].Y, calcPoints[0].Z));
			}
			calcEntity = new buLinearPath(calcPoints);
		}
		buEntity copiedEntity = null;
		buEntity copiedEntity2 = null;
		buEntity.Copy(OffsetedEntity, ref copiedEntity);
		buEntity.Copy(OffsetedEntity2, ref copiedEntity2);
		EntityUpdateByCutLength(ref copiedEntity, 0.0 - LeadInDistance, 0.0 - LeadOutDistance, StartPointType.StartAndEnd);
		EntityUpdateByCutLength(ref copiedEntity2, 0.0 - LeadInDistance, 0.0 - LeadOutDistance, StartPointType.StartAndEnd);
		OffsetedEntities.Add(copiedEntity);
		OffsetedEntities.Add(copiedEntity2);
		ConnectionEntities.Add(new buLine(OffsetedEntity.EndPoint, OffsetedEntity2.EndPoint));
		ConnectionEntities.Add(new buLine(OffsetedEntity.StartPoint, OffsetedEntity2.StartPoint));
	}

	public void OffsetEntity(buEntity RefEntity, double Offset, CamOpenContourType OpenContourType, ref buEntity OffsetedEntity)
	{
		try
		{
			if (buCompare5.EQ(Offset, 0.0))
			{
				buEntity.Copy(RefEntity, ref OffsetedEntity);
				return;
			}
			if (RefEntity.GetType() == typeof(buLine))
			{
				buLine buLine2 = new buLine(RefEntity.Vertices[0], RefEntity.Vertices[1]);
				if (RefEntity.sortDirection == entitySortDirection.Reverse)
				{
					buLine2 = new buLine(RefEntity.Vertices[1], RefEntity.Vertices[0]);
				}
				List<List<Point3D>> OffsetedPoints = new List<List<Point3D>>();
				OffsetContour(buLine2.Vertices, Offset, OffsetCornerType.Line, OpenContourType, Plane.XY, 0.0, ref OffsetedPoints);
				if (OffsetedPoints.Count > 0)
				{
					double num = PointAngle(buLine2.Vertices[1], buLine2.Vertices[0]);
					for (int i = 1; i <= OffsetedPoints[0].Count - 1; i++)
					{
						Point3D point3D = ToPoint3D(OffsetedPoints[0][i - 1]);
						Point3D point3D2 = ToPoint3D(OffsetedPoints[0][i]);
						double value = Length3D(point3D, point3D2, Plane.XY);
						double value2 = Length3D(buLine2.StartPoint, buLine2.EndPoint);
						if (!buCompare5.EQ(value2, value))
						{
							continue;
						}
						double num2 = 0.0;
						double num3 = 0.0;
						double value3 = Length3D(point3D, buLine2.Vertices[0], Plane.XY);
						double value4 = Length3D(point3D2, buLine2.Vertices[0], Plane.XY);
						if (buCompare5.EQ(Math.Abs(Offset), value3, 0.05))
						{
							num2 = PointAngle(point3D2, buLine2.Vertices[0]);
							double num4 = num2 - num;
							if (num4 > 180.0)
							{
								num += 360.0;
								num4 = num2 - num;
							}
							if (num4 < -180.0)
							{
								num2 += 360.0;
								num4 = num2 - num;
							}
							if (OpenContourType == CamOpenContourType.Left && num4 > 0.0)
							{
								OffsetedEntity = new buLine(point3D, point3D2);
							}
							if (OpenContourType == CamOpenContourType.Right && num4 < 0.0)
							{
								OffsetedEntity = new buLine(point3D, point3D2);
							}
						}
						if (buCompare5.EQ(Math.Abs(Offset), value4, 0.05))
						{
							num3 = PointAngle(point3D, buLine2.Vertices[0]);
							double num5 = num3 - num;
							if (num5 > 180.0)
							{
								num += 360.0;
								num5 = num3 - num;
							}
							if (num5 < -180.0)
							{
								num3 += 360.0;
								num5 = num3 - num;
							}
							if (OpenContourType == CamOpenContourType.Left && num5 > 0.0)
							{
								OffsetedEntity = new buLine(point3D2, point3D);
							}
							if (OpenContourType == CamOpenContourType.Right && num5 < 0.0)
							{
								OffsetedEntity = new buLine(point3D2, point3D);
							}
						}
					}
				}
			}
			if (RefEntity.GetType() == typeof(buLinearPath))
			{
				List<List<Point3D>> OffsetedPoints2 = new List<List<Point3D>>();
				OffsetContour(RefEntity.Vertices, Offset, OffsetCornerType.Line, OpenContourType, Plane.XY, 0.0, ref OffsetedPoints2);
				if (OffsetedPoints2.Count > 0)
				{
					List<Point3D> CalcPoints = new List<Point3D>();
					OpenProfileCalculation(OffsetedPoints2[0], RefEntity.Vertices, Offset, Plane.XY, OpenContourType, ref CalcPoints);
					OffsetedEntity = new buLinearPath(CalcPoints);
				}
			}
			if (RefEntity.GetType() == typeof(buCircle))
			{
