	public bool ExtendArc(ICurve arcCurve, bool nearStart, List<Point3D> IntersectionList, ref ICurve calcEnt)
	{
		Arc arc = arcCurve as Arc;
		new Circle(arc.Plane, arc.Center, arc.Radius);
		List<Point3D> list = new List<Point3D>();
		list = new List<Point3D>(IntersectionList);
		if (list.Count <= 0)
		{
			return false;
		}
		if (!nearStart)
		{
			Point3D point3D = method_1(arc.EndPoint, list);
			Vector3D vector3D = new Vector3D(arc.Center, arc.StartPoint);
			vector3D.Normalize();
			Vector3D vector3D2 = Vector3D.Cross(Vector3D.AxisZ, vector3D);
			vector3D2.Normalize();
			new Plane(arc.Center, vector3D, vector3D2);
			Vector2D vector2D = new Vector2D(arc.Center, arc.StartPoint);
			vector2D.Normalize();
			Vector2D vector2D2 = new Vector2D(arc.Center, point3D);
			vector2D2.Normalize();
			Vector2D.SignedAngleBetween(vector2D, vector2D2);
			Plane plane = (Plane)arc.Plane.Clone();
			plane.Origin = new Point3D();
			calcEnt = new Arc(plane, arc.Center, arc.StartPoint, point3D);
		}
		else
		{
			Point3D point3D2 = method_1(arc.StartPoint, list);
			Vector3D vector3D3 = new Vector3D(arc.Center, arc.EndPoint);
			vector3D3.Normalize();
			Vector3D vector3D4 = Vector3D.Cross(Vector3D.AxisZ, vector3D3);
			vector3D4.Normalize();
			new Plane(arc.Center, vector3D3, vector3D4);
			Vector2D vector2D3 = new Vector2D(arc.Center, arc.EndPoint);
			vector2D3.Normalize();
			Vector2D vector2D4 = new Vector2D(arc.Center, point3D2);
			vector2D4.Normalize();
			Vector2D.SignedAngleBetween(vector2D3, vector2D4);
			Plane plane2 = (Plane)arc.Plane.Clone();
			plane2.Origin = new Point3D();
			calcEnt = new Arc(plane2, arc.Center, point3D2, arc.EndPoint);
		}
		return true;
	}

	private Point3D method_1(Point3D point3D_0, List<Point3D> list_0)
	{
		double num = double.MaxValue;
		Point3D result = null;
		foreach (Point3D item in list_0)
		{
			double num2 = Point3D.DistanceSquared(point3D_0, item);
			if (!(num2 >= num) && !point3D_0.Equals(item))
			{
				num = num2;
				result = item;
			}
		}
		return result;
	}

	public EntityList AlingEntities(EntityList refEntities, List<List<int>> SelectionList, AlignmentEvent Alignment)
	{
		if (SelectionList.Count >= 2)
		{
			List<Entity> list = new List<Entity>();
			Point3D MinPoint = new Point3D();
			Point3D MidPoint = new Point3D();
			Point3D MaxPoint = new Point3D();
			Point3D MinPoint2 = new Point3D();
			Point3D MidPoint2 = new Point3D();
			Point3D MaxPoint2 = new Point3D();
			for (int i = 0; i <= SelectionList.Count - 1; i++)
			{
				List<Entity> list2 = new List<Entity>();
				for (int j = 0; j <= SelectionList[i].Count - 1; j++)
				{
					if ((SelectionList[i][j] >= 0) & (SelectionList[i][j] <= refEntities.Count - 1))
					{
						if (i != 0)
						{
							list2.Add(refEntities[SelectionList[i][j]]);
						}
						else
						{
							list.Add(refEntities[SelectionList[i][j]]);
						}
					}
				}
				if (i != 0)
				{
					BoxSizeCalculate(list2, ref MinPoint2, ref MidPoint2, ref MaxPoint2);
					if (Alignment == AlignmentEvent.Left)
					{
						double dx = MinPoint.X - MinPoint2.X;
						for (int k = 0; k <= SelectionList[i].Count - 1; k++)
						{
							if ((SelectionList[i][k] >= 0) & (SelectionList[i][k] <= refEntities.Count - 1))
							{
								refEntities[SelectionList[i][k]].Translate(dx, 0.0);
								refEntities[SelectionList[i][k]].Regen(0.01);
							}
						}
					}
					if (Alignment == AlignmentEvent.Right)
					{
						double dx2 = MaxPoint.X - MaxPoint2.X;
						for (int l = 0; l <= SelectionList[i].Count - 1; l++)
						{
							if ((SelectionList[i][l] >= 0) & (SelectionList[i][l] <= refEntities.Count - 1))
							{
								refEntities[SelectionList[i][l]].Translate(dx2, 0.0);
								refEntities[SelectionList[i][l]].Regen(0.01);
							}
						}
					}
					if (Alignment == AlignmentEvent.Top)
					{
						double dy = MaxPoint.Y - MaxPoint2.Y;
						for (int m = 0; m <= SelectionList[i].Count - 1; m++)
						{
							if ((SelectionList[i][m] >= 0) & (SelectionList[i][m] <= refEntities.Count - 1))
							{
								refEntities[SelectionList[i][m]].Translate(0.0, dy);
								refEntities[SelectionList[i][m]].Regen(0.01);
							}
						}
					}
					if (Alignment == AlignmentEvent.Bottom)
					{
						double dy2 = MinPoint.Y - MinPoint2.Y;
						for (int n = 0; n <= SelectionList[i].Count - 1; n++)
						{
							if ((SelectionList[i][n] >= 0) & (SelectionList[i][n] <= refEntities.Count - 1))
							{
								refEntities[SelectionList[i][n]].Translate(0.0, dy2);
								refEntities[SelectionList[i][n]].Regen(0.01);
							}
						}
					}
					if (Alignment == AlignmentEvent.HorizontalCenter)
					{
						double dy3 = MidPoint.Y - MidPoint2.Y;
						for (int num = 0; num <= SelectionList[i].Count - 1; num++)
						{
							if ((SelectionList[i][num] >= 0) & (SelectionList[i][num] <= refEntities.Count - 1))
							{
								refEntities[SelectionList[i][num]].Translate(0.0, dy3);
								refEntities[SelectionList[i][num]].Regen(0.01);
							}
						}
					}
					if (Alignment != AlignmentEvent.VerticalCenter)
					{
						continue;
					}
					double dx3 = MidPoint.X - MidPoint2.X;
					for (int num2 = 0; num2 <= SelectionList[i].Count - 1; num2++)
					{
						if ((SelectionList[i][num2] >= 0) & (SelectionList[i][num2] <= refEntities.Count - 1))
						{
							refEntities[SelectionList[i][num2]].Translate(dx3, 0.0);
							refEntities[SelectionList[i][num2]].Regen(0.01);
						}
					}
				}
				else
				{
					BoxSizeCalculate(list, ref MinPoint, ref MidPoint, ref MaxPoint);
				}
			}
		}
		return refEntities;
	}

	public EntityList EqualDistanceEntities(EntityList refEntities, List<List<int>> SelectionList, EqualDistance EqualType, double Distance)
	{
		if (SelectionList.Count >= 2)
		{
			Point3D MidPoint = new Point3D();
			new Point3D();
			Point3D MaxPoint = new Point3D();
			Point3D MinPoint = new Point3D();
			Point3D MidPoint2 = new Point3D();
			Point3D MaxPoint2 = new Point3D();
			for (int i = 0; i <= SelectionList.Count - 1; i++)
			{
				List<Entity> list = new List<Entity>();
				List<Entity> list2 = new List<Entity>();
				if (i <= 0)
				{
					continue;
				}
				for (int j = 0; j <= SelectionList[i - 1].Count - 1; j++)
				{
					if ((SelectionList[i - 1][j] >= 0) & (SelectionList[i - 1][j] <= refEntities.Count - 1))
					{
						list2.Add(refEntities[SelectionList[i - 1][j]]);
					}
				}
				for (int k = 0; k <= SelectionList[i].Count - 1; k++)
				{
					if ((SelectionList[i][k] >= 0) & (SelectionList[i][k] <= refEntities.Count - 1))
					{
						list.Add(refEntities[SelectionList[i][k]]);
					}
				}
				if (!((list2.Count > 0) & (list.Count > 0)))
				{
					continue;
				}
				BoxSizeCalculate(list2, ref MinPoint, ref MidPoint, ref MaxPoint);
				BoxSizeCalculate(list, ref MinPoint, ref MidPoint2, ref MaxPoint2);
				if (EqualType == EqualDistance.Horizontal)
				{
					double dx = Distance + (MaxPoint.X - MinPoint.X);
					for (int l = 0; l <= SelectionList[i].Count - 1; l++)
					{
						if ((SelectionList[i][l] >= 0) & (SelectionList[i][l] <= refEntities.Count - 1))
						{
							refEntities[SelectionList[i][l]].Translate(dx, 0.0);
							refEntities[SelectionList[i][l]].Regen(0.01);
						}
					}
				}
				if (EqualType != EqualDistance.Vertical)
				{
					continue;
				}
				double dy = Distance + (MaxPoint.Y - MinPoint.Y);
				for (int m = 0; m <= SelectionList[i].Count - 1; m++)
				{
					if ((SelectionList[i][m] >= 0) & (SelectionList[i][m] <= refEntities.Count - 1))
					{
						refEntities[SelectionList[i][m]].Translate(0.0, dy);
						refEntities[SelectionList[i][m]].Regen(0.01);
					}
				}
			}
		}
		return refEntities;
	}

	public void FilletPointList(List<Point3D> refPoints, double FilletRadius, Plane refPlane, ref List<Point3D> filletedPoints)
	{
		bool flag = false;
		if (filletedPoints == null)
		{
			filletedPoints = new List<Point3D>();
		}
		filletedPoints.Clear();
		for (int i = 1; i <= refPoints.Count - 1; i++)
		{
			double num = Point3D.Distance(refPoints[i - 1], refPoints[i]);
			if (num < FilletRadius)
			{
				flag = true;
			}
		}
		if (!flag)
		{
			if (!(FilletRadius <= 0.0))
			{
				filletedPoints.Add(ToPoint3D(refPoints[0]));
				for (int j = 1; j <= refPoints.Count - 2; j++)
				{
					Line line = new Line(refPoints[j - 1], refPoints[j]);
					Line line2 = new Line(refPoints[j], refPoints[j + 1]);
					ICurve c = line;
					ICurve c2 = line2;
					Arc fillet = null;
					if (!(line.Direction == line2.Direction))
					{
						Curve.Fillet(c, c2, refPlane.AxisZ, FilletRadius, flip1: false, flip2: false, trim1: true, trim2: true, out fillet);
						if (fillet == null)
						{
							Curve.Fillet(c, c2, refPlane.AxisZ, FilletRadius, flip1: true, flip2: false, trim1: true, trim2: true, out fillet);
						}
						if (fillet == null)
						{
							Curve.Fillet(c, c2, refPlane.AxisZ, FilletRadius, flip1: false, flip2: true, trim1: true, trim2: true, out fillet);
						}
						if (fillet == null)
						{
							Curve.Fillet(c, c2, refPlane.AxisZ, FilletRadius, flip1: true, flip2: true, trim1: true, trim2: true, out fillet);
						}
						if (fillet == null)
						{
							filletedPoints.Add(ToPoint3D(refPoints[j]));
							continue;
						}
						if (fillet.Vertices == null)
						{
							double deviation = RegenDevisionFromRadius(fillet.Radius);
							fillet.Regen(deviation);
						}
						filletedPoints.Add(ToPoint3D(line.EndPoint));
						for (int k = 1; k <= fillet.Vertices.Length - 2; k++)
						{
							filletedPoints.Add(ToPoint3D(fillet.Vertices[k]));
						}
						filletedPoints.Add(ToPoint3D(line2.StartPoint));
					}
					else
					{
						filletedPoints.Add(ToPoint3D(refPoints[j]));
					}
				}
				filletedPoints.Add(ToPoint3D(refPoints[refPoints.Count - 1]));
				CheckDuplicatedPointsWithPrevious(ref filletedPoints);
			}
			else
			{
				Copy(refPoints, ref filletedPoints);
			}
		}
		else
		{
			Copy(refPoints, ref filletedPoints);
		}
	}

	public void ChamferPointList(List<Point3D> refPoints, double ChamferLen, Plane refPlane, ref List<Point3D> filletedPoints)
	{
		if (filletedPoints == null)
		{
			filletedPoints = new List<Point3D>();
		}
		filletedPoints.Clear();
		if (!(ChamferLen <= 0.0))
		{
			filletedPoints.Add(ToPoint3D(refPoints[0]));
			for (int i = 1; i <= refPoints.Count - 2; i++)
			{
				Line line = new Line(refPoints[i - 1], refPoints[i]);
				Line line2 = new Line(refPoints[i], refPoints[i + 1]);
				ICurve c = line;
				ICurve c2 = line2;
				Line chamfer = null;
				if (!(line.Direction == line2.Direction))
				{
					Curve.Chamfer(c, c2, refPlane.AxisZ, ChamferLen, flip1: false, flip2: false, trim1: true, trim2: true, out chamfer);
					if (chamfer == null)
					{
						Curve.Chamfer(c, c2, refPlane.AxisZ, ChamferLen, flip1: true, flip2: false, trim1: true, trim2: true, out chamfer);
					}
					if (chamfer == null)
					{
						Curve.Chamfer(c, c2, refPlane.AxisZ, ChamferLen, flip1: false, flip2: true, trim1: true, trim2: true, out chamfer);
					}
					if (chamfer == null)
					{
						Curve.Chamfer(c, c2, refPlane.AxisZ, ChamferLen, flip1: true, flip2: true, trim1: true, trim2: true, out chamfer);
					}
					if (chamfer == null)
					{
						filletedPoints.Add(ToPoint3D(refPoints[i]));
						continue;
					}
					if (chamfer.Vertices == null)
					{
						chamfer.Regen(0.01);
					}
					filletedPoints.Add(ToPoint3D(line.EndPoint));
					for (int j = 1; j <= chamfer.Vertices.Length - 2; j++)
					{
						filletedPoints.Add(ToPoint3D(chamfer.Vertices[j]));
					}
					filletedPoints.Add(ToPoint3D(line2.StartPoint));
				}
				else
				{
					filletedPoints.Add(ToPoint3D(refPoints[i]));
				}
			}
			filletedPoints.Add(ToPoint3D(refPoints[refPoints.Count - 1]));
			CheckDuplicatedPointsWithPrevious(ref filletedPoints);
		}
		else
		{
			Copy(refPoints, ref filletedPoints);
		}
	}

	public void ToolTotalLengthCalculate(ref ToolBase5 Tool)
	{
		Tool.Geometry.ArborLength = 0.0;
		if (Tool.Geometry.DrawArbor & (Tool.Geometry.ArborPoints.Count > 0))
		{
			Tool.Geometry.ArborLength = Tool.Geometry.ArborPoints[Tool.Geometry.ArborPoints.Count - 1].Y;
		}
		Tool.Geometry.HolderLength = 0.0;
		if (Tool.Geometry.DrawHolder & (Tool.Geometry.HolderPoints.Count > 0))
		{
			Tool.Geometry.HolderLength = Tool.Geometry.HolderPoints[Tool.Geometry.HolderPoints.Count - 1].Y;
		}
		Tool.Geometry.TotalLength = Tool.Geometry.Length + Tool.Geometry.ArborLength + Tool.Geometry.HolderLength;
	}

	public void FindToolSmallMillingDiameter(List<ToolGroup5> Tools, ref ToolBase5 foundTool)
	{
		double num = double.MaxValue;
		foundTool = null;
		for (int i = 0; i <= Tools.Count - 1; i++)
		{
			for (int j = 0; j <= Tools[i].Tools.Count - 1; j++)
			{
				if (Tools[i].Tools[j].Geometry.Diameter < num)
				{
					foundTool = new ToolBase5(Tools[i].Tools[j]);
					num = Tools[i].Tools[j].Geometry.Diameter;
				}
			}
		}
	}

