	public void ToolDimensionEntities(ToolBase5 Tool, ref List<Entity> dimEntities, double TextHeight = 10.0)
	{
		dimEntities.Clear();
		Point3D point3D = new Point3D();
		Point3D point3D2 = new Point3D(0.0, 0.0, Tool.Geometry.Length);
		Point3D point3D3 = new Point3D(50.0, 0.0, Tool.Geometry.Length / 2.0);
		Plane drawingPlane = null;
		double diameter = Tool.Geometry.Diameter;
		if (Tool.Geometry.GeometryType != ToolType.Saw)
		{
			diameter = Tool.Geometry.Diameter;
			point3D = new Point3D(0.0, 0.0, 0.0);
			point3D2 = new Point3D(0.0, 0.0, Tool.Geometry.Length);
			point3D3 = new Point3D(Tool.Geometry.Diameter * 2.0 + 10.0, 0.0, Tool.Geometry.Length / 2.0);
			LinearDimCalculate(point3D, point3D2, point3D3, diameter, Plane.XZ, ref drawingPlane);
			LinearDim item = new LinearDim(drawingPlane, point3D, point3D2, point3D3, diameter);
			dimEntities.Add(item);
			point3D = new Point3D();
			point3D2 = new Point3D(0.0, 0.0, Tool.Geometry.CutLength);
			point3D3 = new Point3D(Tool.Geometry.Diameter * 2.0, 0.0, Tool.Geometry.CutLength / 2.0);
			LinearDimCalculate(point3D, point3D2, point3D3, diameter, Plane.XZ, ref drawingPlane);
			item = new LinearDim(drawingPlane, point3D, point3D2, point3D3, diameter);
			dimEntities.Add(item);
			point3D = new Point3D((0.0 - Tool.Geometry.Diameter) / 2.0, 0.0, 0.0);
			point3D2 = new Point3D(Tool.Geometry.Diameter / 2.0, 0.0, 0.0);
			point3D3 = new Point3D(0.0, 0.0, (0.0 - Tool.Geometry.Diameter) * 2.0);
			LinearDimCalculate(point3D, point3D2, point3D3, diameter, Plane.XZ, ref drawingPlane);
			item = new LinearDim(drawingPlane, point3D, point3D2, point3D3, diameter);
			dimEntities.Add(item);
			if (Tool.Geometry.DrawArbor)
			{
				double num = Tool.Geometry.ArborPoints[Tool.Geometry.ArborPoints.Count - 1].Y + Tool.Geometry.Length;
				double num2 = 0.0;
				double num3 = 0.0;
				for (int i = 0; i <= Tool.Geometry.ArborPoints.Count - 1; i++)
				{
					if (Tool.Geometry.ArborPoints[i].X > num2)
					{
						num2 = Tool.Geometry.ArborPoints[i].X;
					}
				}
				point3D = new Point3D();
				point3D2 = new Point3D(0.0, 0.0, num);
				point3D3 = new Point3D(0.0 - (num2 + 10.0), 0.0, num / 2.0);
				LinearDimCalculate(point3D, point3D2, point3D3, diameter, Plane.XZ, ref drawingPlane);
				item = new LinearDim(drawingPlane, point3D, point3D2, point3D3, diameter);
				dimEntities.Add(item);
				if (Tool.Geometry.DrawHolder)
				{
					num += Tool.Geometry.HolderPoints[Tool.Geometry.HolderPoints.Count - 1].Y;
					for (int j = 0; j <= Tool.Geometry.HolderPoints.Count - 1; j++)
					{
						if (Tool.Geometry.HolderPoints[j].X > num3)
						{
							num3 = Tool.Geometry.HolderPoints[j].X;
						}
					}
					point3D = new Point3D();
					point3D2 = new Point3D(0.0, 0.0, num);
					point3D3 = new Point3D(0.0 - (num3 + 10.0), 0.0, num / 2.0);
					LinearDimCalculate(point3D, point3D2, point3D3, diameter, Plane.XZ, ref drawingPlane);
					item = new LinearDim(drawingPlane, point3D, point3D2, point3D3, diameter);
					dimEntities.Add(item);
				}
				if (Tool.Geometry.DrawArbor & Tool.Geometry.DrawHolder)
				{
					double z = Tool.Geometry.Length + Tool.Geometry.ArborPoints[Tool.Geometry.ArborPoints.Count - 1].Y + Tool.Geometry.HolderPoints[Tool.Geometry.HolderPoints.Count - 1].Y;
					double num4 = Tool.Geometry.ArborPoints[Tool.Geometry.ArborPoints.Count - 1].Y + Tool.Geometry.HolderPoints[Tool.Geometry.HolderPoints.Count - 1].Y;
					_ = Tool.Geometry.Length + Tool.Geometry.ArborPoints[Tool.Geometry.ArborPoints.Count - 1].Y;
					point3D = new Point3D(0.0, 0.0, Tool.Geometry.Length);
					point3D2 = new Point3D(0.0, 0.0, z);
					point3D3 = new Point3D(num3 + 10.0, 0.0, Tool.Geometry.Length + num4 / 2.0);
					LinearDimCalculate(point3D, point3D2, point3D3, diameter, Plane.XZ, ref drawingPlane);
					item = new LinearDim(drawingPlane, point3D, point3D2, point3D3, diameter);
					dimEntities.Add(item);
				}
			}
			if (Tool.Geometry.GeometryType == ToolType.Bullnose)
			{
				Point3D center = new Point3D((0.0 - Tool.Geometry.Diameter) / 2.0 + Tool.Geometry.RoundRadius, 0.0, Tool.Geometry.RoundRadius);
				point3D3 = new Point3D((0.0 - Tool.Geometry.Diameter) * 2.0, 0.0, -25.0);
				Circle circle = new Circle(Plane.XZ, center, Tool.Geometry.RoundRadius);
				RadialDim item2 = new RadialDim(circle, point3D3, diameter);
				dimEntities.Add(item2);
			}
			if (Tool.Geometry.GeometryType == ToolType.Sphere)
			{
				Point3D center2 = new Point3D(0.0, 0.0, Tool.Geometry.RoundRadius);
				point3D3 = new Point3D((0.0 - Tool.Geometry.Diameter) * 2.0, 0.0, (0.0 - Tool.Geometry.Diameter) * 1.0);
				Circle circle2 = new Circle(Plane.XZ, center2, Tool.Geometry.Diameter / 2.0);
				DiametricDim item3 = new DiametricDim(circle2, point3D3, diameter);
				dimEntities.Add(item3);
			}
			if (Tool.Geometry.GeometryType == ToolType.Taper)
			{
				point3D = new Point3D((0.0 - Tool.Geometry.Diameter) / 2.0, 0.0, 0.0);
				point3D2 = new Point3D(Tool.Geometry.Diameter / 2.0, 0.0, 0.0);
				point3D3 = new Point3D(0.0, 0.0, (0.0 - Tool.Geometry.Diameter) * 1.0);
				Point3D EndPnt = new Point3D();
				Point3D EndPnt2 = new Point3D();
				Point3D point3D4 = new Point3D(0.0, 0.0, Tool.Geometry.CutLength);
				LineWithLengthAndAngle(point3D, Tool.Geometry.CutLength, 90.0 + Tool.Geometry.TaperAngle, ref EndPnt);
				LineWithLengthAndAngle(point3D2, Tool.Geometry.CutLength, 90.0 - Tool.Geometry.TaperAngle, ref EndPnt2);
				LinearDimCalculate(EndPnt, EndPnt2, point3D4, diameter, Plane.XZ, ref drawingPlane);
				item = new LinearDim(drawingPlane, EndPnt, EndPnt2, point3D4, diameter);
				dimEntities.Add(item);
			}
			return;
		}
		diameter = Tool.Geometry.Diameter * 0.1;
		point3D = new Point3D((0.0 - Tool.Geometry.Diameter) / 2.0, 0.0, 0.0);
		point3D2 = new Point3D(Tool.Geometry.Diameter / 2.0, 0.0, 0.0);
		point3D3 = new Point3D(0.0, Tool.Geometry.Diameter / 2.0 + 10.0, 0.0);
		LinearDimCalculate(point3D, point3D2, point3D3, diameter, Plane.XY, ref drawingPlane);
		LinearDim item4 = new LinearDim(drawingPlane, point3D, point3D2, point3D3, diameter);
		dimEntities.Add(item4);
		point3D = new Point3D();
		point3D2 = new Point3D(0.0, 0.0, Tool.Geometry.Length);
		point3D3 = new Point3D(Tool.Geometry.Diameter / 2.0 + Tool.Geometry.Thickness * 4.0, 0.0, Tool.Geometry.Length / 2.0);
		LinearDimCalculate(point3D, point3D2, point3D3, diameter, Plane.XZ, ref drawingPlane);
		item4 = new LinearDim(drawingPlane, point3D, point3D2, point3D3, diameter);
		diameter = Tool.Geometry.Thickness;
		point3D = new Point3D(0.0, Tool.Geometry.Diameter / 2.0, 0.0);
		point3D2 = new Point3D(0.0, Tool.Geometry.Diameter / 2.0, Tool.Geometry.Thickness);
		point3D3 = new Point3D(0.0, Tool.Geometry.Diameter / 2.0 + 10.0, Tool.Geometry.Thickness / 2.0);
		LinearDimCalculate(point3D, point3D2, point3D3, diameter, Plane.ZY, ref drawingPlane);
		item4 = new LinearDim(drawingPlane, point3D, point3D2, point3D3, diameter);
		dimEntities.Add(item4);
		if (Tool.Geometry.DrawArbor)
		{
			double num5 = Tool.Geometry.ArborPoints[Tool.Geometry.ArborPoints.Count - 1].Y + Tool.Geometry.Length;
			if (Tool.Geometry.DrawHolder)
			{
				num5 += Tool.Geometry.HolderPoints[Tool.Geometry.HolderPoints.Count - 1].Y;
			}
			point3D = new Point3D();
			point3D2 = new Point3D(0.0, 0.0, num5);
			point3D3 = new Point3D(Tool.Geometry.Diameter / 2.0 + Tool.Geometry.Thickness * 4.0, 0.0, num5 / 2.0);
			LinearDimCalculate(point3D, point3D2, point3D3, diameter, Plane.XZ, ref drawingPlane);
			item4 = new LinearDim(drawingPlane, point3D, point3D2, point3D3, diameter);
			dimEntities.Add(item4);
		}
	}

	public void GetMaxMinAnglesOfEntities(List<buEntity> refEntities, ref double MinAngle, ref double MaxAngle)
	{
		MinAngle = 99999999.0;
		MaxAngle = -999999999.0;
		for (int i = 0; i <= refEntities.Count - 1; i++)
		{
			if (refEntities[i].sortDirection != entitySortDirection.Normal)
			{
				for (int num = refEntities[i].Vertices.Count - 2; num >= 0; num--)
				{
					double num2 = PointAngle(refEntities[i].Vertices[num], refEntities[i].Vertices[num + 1]);
					if (num2 < MinAngle)
					{
						MinAngle = num2;
					}
					if (num2 > MaxAngle)
					{
						MaxAngle = num2;
					}
				}
				ToPoint3D(refEntities[i].Vertices[0]);
				continue;
			}
			for (int j = 1; j <= refEntities[i].Vertices.Count - 1; j++)
			{
				double num3 = PointAngle(refEntities[i].Vertices[j], refEntities[i].Vertices[j - 1]);
				if (num3 < MinAngle)
				{
					MinAngle = num3;
				}
				if (num3 > MaxAngle)
				{
					MaxAngle = num3;
				}
			}
			ToPoint3D(refEntities[i].Vertices[refEntities[i].Vertices.Count - 1]);
		}
	}

	public void GetMaxMinTotalAnglesOfEntities(List<buEntity> refEntities, ref double StartAngle, ref double EndAngle, ref double TotalAngle, ref double MaxAng, ref double MinAng)
	{
		StartAngle = 0.0;
		EndAngle = 0.0;
		TotalAngle = 0.0;
		double num = 0.0;
		double num2 = 0.0;
		bool flag = false;
		MaxAng = -9999999.0;
		MinAng = 9999999.0;
		for (int i = 0; i <= refEntities.Count - 1; i++)
		{
			if (refEntities[i].sortDirection != entitySortDirection.Normal)
			{
				for (int num3 = refEntities[i].Vertices.Count - 2; num3 >= 0; num3--)
				{
					double num4 = PointAngle(refEntities[i].Vertices[num3], refEntities[i].Vertices[num3 + 1]);
					if (flag)
					{
						num = num4 - num2;
						if (Math.Abs(num) > 180.0)
						{
						}
					}
					else
					{
						StartAngle = num4;
						flag = true;
					}
					if (num4 > MaxAng)
					{
						MaxAng = num4;
					}
					if (num4 < MinAng)
					{
						MinAng = num4;
					}
					num2 = num4;
				}
				ToPoint3D(refEntities[i].Vertices[0]);
				continue;
			}
			for (int j = 1; j <= refEntities[i].Vertices.Count - 1; j++)
			{
				if (j != 570)
				{
				}
				double num5 = PointAngle(refEntities[i].Vertices[j], refEntities[i].Vertices[j - 1]);
				if (flag)
				{
					num = num5 - num2;
					if (Math.Abs(num) > 180.0)
					{
						if (num > 180.0)
						{
							num5 -= 360.0;
						}
						if (num < -180.0)
						{
							num5 += 360.0;
						}
						num = num5 - num2;
					}
					TotalAngle += num;
				}
				else
				{
					StartAngle = num5;
					flag = true;
				}
				num2 = num5;
				if (num5 > MaxAng)
				{
					MaxAng = num5;
				}
				if (num5 < MinAng)
				{
					MinAng = num5;
				}
			}
			ToPoint3D(refEntities[i].Vertices[refEntities[i].Vertices.Count - 1]);
		}
	}

	public static double PointAngleByPlane(Point3D TipPoint, Point3D BasePoint, Plane RefPlane)
	{
		try
		{
			Vector3D asVector = (TipPoint - BasePoint).AsVector;
			Math.Sqrt(asVector.X * asVector.X + asVector.Y * asVector.Y);
			Math.Sqrt(asVector.X * asVector.X + asVector.Z * asVector.Z);
			Math.Sqrt(asVector.Y * asVector.Y + asVector.Z * asVector.Z);
			double num = Utility.RadToDeg(Math.Atan2(asVector.Y, asVector.X));
			if (Math.Round(num, 5) < 0.0)
			{
				num += 360.0;
			}
			double num2 = Utility.RadToDeg(Math.Atan2(asVector.Z, asVector.X));
			if (Math.Round(num2, 5) < 0.0)
			{
				num2 += 360.0;
			}
			double num3 = Utility.RadToDeg(Math.Atan2(asVector.Z, asVector.Y));
			if (Math.Round(num3, 5) < 0.0)
			{
				num3 += 360.0;
			}
			if (!isPlaneXZorZX(RefPlane))
			{
				if (!isPlaneYZorZY(RefPlane))
				{
					return num;
				}
				return num3;
			}
			return num2;
		}
		catch (Exception mSException)
		{
			string text = "";
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return 0.0;
		}
	}

	public double PointAngle(Point3D TipPoint, Point3D BasePoint, Plane RefPlane)
	{
		try
		{
			Vector3D asVector = (TipPoint - BasePoint).AsVector;
			Math.Sqrt(asVector.X * asVector.X + asVector.Y * asVector.Y);
			Math.Sqrt(asVector.X * asVector.X + asVector.Z * asVector.Z);
			Math.Sqrt(asVector.Y * asVector.Y + asVector.Z * asVector.Z);
			double num = Utility.RadToDeg(Math.Atan2(asVector.Y, asVector.X));
			if (Math.Round(num, 5) < 0.0)
			{
				num += 360.0;
			}
			double num2 = Utility.RadToDeg(Math.Atan2(asVector.Z, asVector.X));
			if (Math.Round(num2, 5) < 0.0)
			{
				num2 += 360.0;
			}
			double num3 = Utility.RadToDeg(Math.Atan2(asVector.Z, asVector.Y));
			if (Math.Round(num3, 5) < 0.0)
			{
				num3 += 360.0;
			}
			if (!isPlaneXZorZX(RefPlane))
			{
				if (!isPlaneYZorZY(RefPlane))
				{
					return num;
				}
				return num3;
			}
			return num2;
		}
		catch (Exception mSException)
		{
			string text = "";
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return 0.0;
		}
	}

	public double PointAngle(Point3D TipPoint, Point3D BasePoint)
