	public double PointAngle(double xTip, double yTip, double xBase, double yBase)
	{
		try
		{
			double num = Utility.RadToDeg(Math.Atan2(yTip - yBase, xTip - xBase));
			if (num < 0.0)
			{
				num += 360.0;
			}
			return num;
		}
		catch (Exception)
		{
			return 0.0;
		}
	}

	public void VectorAngle(Vector3D Vec, ref double AngXY, ref double AngXZ, ref double AngYZ)
