		AngXZ = PointAngle(new Point3D(Vec.X, Vec.Y, Vec.Z), new Point3D(), Plane.XZ);
		AngYZ = PointAngle(new Point3D(Vec.X, Vec.Y, Vec.Z), new Point3D(), Plane.YZ);
	}

