	public double AngleOfTwoLines(Point3D FirstLineStart, Point3D FirstLineEnd, Point3D SecondLineStart, Point3D SecondLineEnd, Plane Plane)
	{
		try
		{
			double num = 0.0;
			Point3D point3D = new Point3D();
			Point3D point3D2 = new Point3D();
			Point3D pntIntersect = new Point3D();
			new Line(FirstLineStart, FirstLineEnd);
			new Line(SecondLineStart, SecondLineEnd);
			if (LineLineIntersection(FirstLineStart, FirstLineEnd, SecondLineStart, SecondLineEnd, Plane, ref pntIntersect))
			{
				double num2 = Point3D.Distance(FirstLineStart, pntIntersect);
				double num3 = Point3D.Distance(FirstLineEnd, pntIntersect);
				double num4 = Point3D.Distance(SecondLineStart, pntIntersect);
				double num5 = Point3D.Distance(SecondLineEnd, pntIntersect);
				point3D = ((num2 > num3) ? new Point3D(FirstLineStart.X, FirstLineStart.Y, FirstLineStart.Z) : new Point3D(FirstLineEnd.X, FirstLineEnd.Y, FirstLineEnd.Z));
				point3D2 = ((num4 > num5) ? new Point3D(SecondLineStart.X, SecondLineStart.Y, SecondLineStart.Z) : new Point3D(SecondLineEnd.X, SecondLineEnd.Y, SecondLineEnd.Z));
				double num6 = PointAngle(point3D, pntIntersect, Plane);
				double num7 = PointAngle(point3D2, pntIntersect, Plane);
				num = Math.Abs(num6 - num7);
				if (num > 180.0)
				{
					num = 360.0 - num;
				}
				return num;
			}
			return 180.0;
		}
		catch (Exception mSException)
		{
			string text = "FirstLineStart: " + FirstLineStart.ToString() + " - FirstLineEnd: " + FirstLineEnd.ToString() + " - SecondLineStart: " + SecondLineStart.ToString() + " - SecondLineEnd: " + SecondLineEnd.ToString() + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return 0.0;
		}
	}

	public double PlaneAngleYZ(Plane plane)
	{
		double num = 0.0;
		num = buConversion5.RadianToDegree(plane.Equation.Angle);
		num = PointAngle(new Point3D(plane.AxisY.X, plane.AxisY.Y, plane.AxisY.Z), new Point3D(), Plane.YZ);
		num -= 90.0;
		if (num > 180.0)
		{
			num -= 180.0;
		}
		return num;
	}

	public static Plane WorkPlaneToPlane(WorkPlane plane)
	{
		if (plane.PlaneName != planeNames.Top)
		{
			if (plane.PlaneName != planeNames.Bottom)
			{
				if (plane.PlaneName != planeNames.Front)
				{
					if (plane.PlaneName != planeNames.Back)
					{
						if (plane.PlaneName != planeNames.Right)
						{
							if (plane.PlaneName != planeNames.Left)
							{
								return new Plane(new Vector3D(plane.Normalies.X, plane.Normalies.Y, plane.Normalies.Z));
							}
							return Plane.ZY;
						}
						return Plane.YZ;
					}
					return new Plane(new Point3D(0.0, 0.0, 0.0), new Point3D(1.0, 0.0, 0.0), new Point3D(0.0, 0.0, -1.0));
				}
				return new Plane(new Point3D(0.0, 0.0, 0.0), new Point3D(1.0, 0.0, 0.0), new Point3D(0.0, 0.0, 1.0));
			}
			return Plane.YX;
		}
		return Plane.XY;
	}

	public static WorkPlane PlaneToWorkPlane(Plane plane)
	{
		WorkPlane workPlane = new WorkPlane(new Vec3D(plane.Equation.X, plane.Equation.Y, plane.Equation.Z));
		if (!isPlaneXY(plane))
		{
			if (!isPlaneYX(plane))
			{
				if (!isPlaneXZ(plane))
				{
					if (!isPlaneZX(plane))
					{
						if (!isPlaneYZ(plane))
						{
							if (!isPlaneZY(plane))
							{
								workPlane.PlaneName = planeNames.Free;
								workPlane.PlaneType = planeType.Angle;
							}
							else
							{
								workPlane.PlaneName = planeNames.Left;
								workPlane.PlaneType = planeType.ZY;
							}
						}
						else
						{
							workPlane.PlaneName = planeNames.Right;
							workPlane.PlaneType = planeType.YZ;
						}
					}
					else
					{
						workPlane.PlaneName = planeNames.Back;
						workPlane.PlaneType = planeType.ZX;
					}
				}
				else
				{
					workPlane.PlaneName = planeNames.Front;
					workPlane.PlaneType = planeType.XZ;
				}
			}
			else
			{
				workPlane.PlaneName = planeNames.Bottom;
				workPlane.PlaneType = planeType.YX;
			}
		}
		else
		{
			workPlane.PlaneName = planeNames.Top;
			workPlane.PlaneType = planeType.XY;
		}
		return workPlane;
	}

	public static string PlaneToString(Plane refPlane)
	{
		string text = AppLanguage.CadCamDynamic[43];
		try
		{
			return isPlaneXY(refPlane) ? (text + " XY") : (isPlaneYX(refPlane) ? (text + " YX") : (isPlaneXZ(refPlane) ? (text + " XZ") : (isPlaneZX(refPlane) ? (text + " ZX") : (isPlaneYZ(refPlane) ? (text + " YZ") : (isPlaneZY(refPlane) ? (text + " ZY") : (text + " Free"))))));
		}
		catch (Exception value)
		{
			Console.WriteLine(value);
			return "Null";
		}
	}

	public static bool isPlaneXY(Plane refPlane)
	{
		if (!(buCompare5.EQ(refPlane.Equation.X, 0.0, 0.001) & buCompare5.EQ(refPlane.Equation.Y, 0.0, 0.001) & buCompare5.EQ(refPlane.Equation.Z, 1.0, 0.001)))
		{
			return false;
		}
		return true;
	}

	public static bool isPlaneXYorYX(Plane refPlane)
	{
		return isPlaneXY(refPlane) | isPlaneYX(refPlane);
	}

	public static bool isPlaneYX(Plane refPlane)
	{
		if (!(buCompare5.EQ(refPlane.Equation.X, 0.0, 0.001) & buCompare5.EQ(refPlane.Equation.Y, 0.0, 0.001) & buCompare5.EQ(refPlane.Equation.Z, -1.0, 0.001)))
		{
			return false;
		}
		return true;
	}

	public static bool isPlaneXZ(Plane refPlane)
	{
		if (!(buCompare5.EQ(refPlane.Equation.X, 0.0, 0.001) & buCompare5.EQ(refPlane.Equation.Y, -1.0, 0.001) & buCompare5.EQ(refPlane.Equation.Z, 0.0, 0.001)))
		{
			return false;
		}
		return true;
	}

	public static bool isPlaneZX(Plane refPlane)
	{
		if (!(buCompare5.EQ(refPlane.Equation.X, 0.0, 0.001) & buCompare5.EQ(refPlane.Equation.Y, 1.0, 0.001) & buCompare5.EQ(refPlane.Equation.Z, 0.0, 0.001)))
		{
			return false;
		}
		return true;
	}

	public static bool isPlaneXZorZX(Plane refPlane)
	{
		return isPlaneXZ(refPlane) | isPlaneZX(refPlane);
	}

	public static bool isPlaneYZ(Plane refPlane)
	{
		if (!(buCompare5.EQ(refPlane.Equation.X, 1.0, 0.001) & buCompare5.EQ(refPlane.Equation.Y, 0.0, 0.001) & buCompare5.EQ(refPlane.Equation.Z, 0.0, 0.001)))
		{
			return false;
		}
		return true;
	}

	public static bool isPlaneZY(Plane refPlane)
	{
		if (!(buCompare5.EQ(refPlane.Equation.X, -1.0, 0.001) & buCompare5.EQ(refPlane.Equation.Y, 0.0, 0.001) & buCompare5.EQ(refPlane.Equation.Z, 0.0, 0.001)))
		{
			return false;
		}
		return true;
	}

	public static bool isPlaneYZorZY(Plane refPlane)
	{
		return isPlaneYZ(refPlane) | isPlaneZY(refPlane);
	}

	public static Plane Vector3DToPlane(Vector3D Vec)
	{
		if (!(Vec == Vector3D.AxisZ))
		{
			if (!(Vec == Vector3D.AxisX))
			{
				if (!(Vec == Vector3D.AxisY))
				{
					return Plane.XY;
				}
				return Plane.XZ;
			}
			return Plane.YZ;
		}
		return Plane.XY;
	}

	public bool isPlanesSame(Plane refPlane, Plane checkPlane)
	{
		if (!(refPlane == checkPlane))
		{
			return false;
		}
		return true;
	}

	public viewType PlaneNameToViewType(planeBoxNames planeName, bool FromBoxPlane = false)
	{
		if (FromBoxPlane)
		{
			if (planeName == planeBoxNames.Top)
			{
				return viewType.Top;
			}
			if (planeName == planeBoxNames.Bottom)
			{
				return viewType.Bottom;
			}
			if (planeName == planeBoxNames.Front)
			{
				return viewType.Front;
			}
			switch (planeName)
			{
			case planeBoxNames.Front:
				return viewType.Rear;
			case planeBoxNames.Left:
				return viewType.Left;
			case planeBoxNames.Right:
				return viewType.Right;
			}
		}
		else
		{
			if (planeName == planeBoxNames.Top || planeName == planeBoxNames.Bottom)
			{
				return viewType.Top;
			}
			if (planeName == planeBoxNames.Front || planeName == planeBoxNames.Front)
			{
				return viewType.Front;
			}
			if (planeName == planeBoxNames.Left || planeName == planeBoxNames.Right)
			{
				return viewType.Right;
			}
		}
		return viewType.Other;
	}

	public Plane PlaneNameToPlane(planeBoxNames planeName)
	{
		Plane refPlane = null;
		PlaneNameToPlane(planeName, ref refPlane);
		return refPlane;
	}

	public void PlaneNameToPlane(planeBoxNames planeName, ref Plane refPlane)
	{
		if (planeName == planeBoxNames.Top)
		{
			refPlane = Plane.XY;
		}
		if (planeName == planeBoxNames.Bottom)
		{
			refPlane = Plane.XY;
		}
		if (planeName == planeBoxNames.Front)
		{
			refPlane = Plane.XZ;
		}
		if (planeName == planeBoxNames.Back)
		{
			refPlane = Plane.XZ;
		}
		if (planeName == planeBoxNames.Left)
		{
			refPlane = Plane.YZ;
		}
		if (planeName == planeBoxNames.Right)
		{
			refPlane = Plane.YZ;
		}
	}

	public void PlaneToEntity(Plane refPlane, double Width, double Height, double Thickness, ref Entity entPlane)
	{
		CompositeCurve outer = CompositeCurve.CreateRectangle(refPlane, Width, Height);
		devDept.Eyeshot.Entities.Region region = new devDept.Eyeshot.Entities.Region(outer);
		entPlane = region.ExtrudeAsMesh(Thickness, 0.1, Mesh.natureType.RichSmooth);
	}

	public void PlaneToEntity(Plane refPlane, double Width, double Height, double Thickness, UCSObjectData UcsData, ref Entity entPlane, ref Entity entXArrow, ref Entity entYArrow, ref Entity entZArrow, ref Entity entBall)
	{
		CompositeCurve outer = CompositeCurve.CreateRectangle(refPlane, Width, Height);
		devDept.Eyeshot.Entities.Region region = new devDept.Eyeshot.Entities.Region(outer);
		entPlane = region.ExtrudeAsMesh(Thickness, 0.1, Mesh.natureType.RichSmooth);
		PlaneToUCSEntity(refPlane, UcsData, ref entXArrow, ref entYArrow, ref entZArrow, ref entBall);
	}

	public void PlaneToUCSEntity(Plane refPlane, UCSObjectData UcsData, ref Entity entXArrow, ref Entity entYArrow, ref Entity entZArrow, ref Entity entBall)
	{
		entXArrow = Mesh.CreateArrow(refPlane.Origin, refPlane.AxisX, UcsData.ArrowDiameter / 2.0, UcsData.ArrowTotalLen - UcsData.ArrowConeLen, UcsData.ArrowConeDiameter / 2.0, UcsData.ArrowConeLen, 15, Mesh.natureType.RichSmooth, Mesh.edgeStyleType.Sharp);
		entXArrow.Color = UcsData.XAxisColor;
		entXArrow.ColorMethod = colorMethodType.byEntity;
		entYArrow = Mesh.CreateArrow(refPlane.Origin, refPlane.AxisY, UcsData.ArrowDiameter / 2.0, UcsData.ArrowTotalLen - UcsData.ArrowConeLen, UcsData.ArrowConeDiameter / 2.0, UcsData.ArrowConeLen, 15, Mesh.natureType.RichSmooth, Mesh.edgeStyleType.Sharp);
		entYArrow.Color = UcsData.YAxisColor;
		entYArrow.ColorMethod = colorMethodType.byEntity;
		entZArrow = Mesh.CreateArrow(refPlane.Origin, refPlane.AxisZ, UcsData.ArrowDiameter / 2.0, UcsData.ArrowTotalLen - UcsData.ArrowConeLen, UcsData.ArrowConeDiameter / 2.0, UcsData.ArrowConeLen, 15, Mesh.natureType.RichSmooth, Mesh.edgeStyleType.Sharp);
		entZArrow.Color = UcsData.ZAxisColor;
		entZArrow.ColorMethod = colorMethodType.byEntity;
		entBall = Mesh.CreateSphere(UcsData.BallDiameter / 2.0, 15, 10, Mesh.natureType.RichSmooth);
		entBall.Color = UcsData.BallColor;
		entBall.ColorMethod = colorMethodType.byEntity;
		entBall.Translate(refPlane.Origin.X, refPlane.Origin.Y, refPlane.Origin.Z);
	}

	public void PlaneCreate(ProfilePlaneDef Type, int Index, bool Create, Point3D pntPlane, double Angle, double Length, double Height, double Thickness, UCSObjectData UcsData, ref SelectedPlaneInfo P)
	{
		string explanation = P.Explanation;
		if (Create)
		{
			P = new SelectedPlaneInfo();
		}
		P.PlaneType = Type;
		if (Create)
		{
			if (Type != ProfilePlaneDef.Top0)
			{
				if (!(Type == ProfilePlaneDef.Back45 || Type == ProfilePlaneDef.Back90))
				{
					if (!(Type == ProfilePlaneDef.Front45 || Type == ProfilePlaneDef.Front90))
					{
						P.pntPlane = new Point3D(0.0, pntPlane.Y, pntPlane.Z);
						P.Angle = Angle;
						explanation = buLangTranslate.preDef.Top + " " + buLangTranslate.preDef.Plane + ": " + (P.Angle + P.AngleOffset).ToString("f1") + " °";
					}
					else
					{
						P.pntPlane = new Point3D(0.0, pntPlane.Y, pntPlane.Z);
						if (Type == ProfilePlaneDef.Front45)
						{
							P.Angle = 45.0;
						}
						if (Type == ProfilePlaneDef.Front90)
						{
							P.Angle = 90.0;
							P.pntPlane.Z = 0.0;
						}
						explanation = buLangTranslate.preDef.Front + " " + buLangTranslate.preDef.Plane + ": " + (P.Angle + P.AngleOffset).ToString("f1") + " °";
					}
				}
				else
				{
					P.pntPlane = new Point3D(0.0, 0.0, pntPlane.Z);
					if (Type == ProfilePlaneDef.Back45)
					{
						P.Angle = -45.0;
					}
					if (Type == ProfilePlaneDef.Back90)
					{
						P.Angle = -90.0;
					}
					explanation = buLangTranslate.preDef.Back + " " + buLangTranslate.preDef.Plane + ": " + (P.Angle + P.AngleOffset).ToString("f1") + " °";
				}
			}
			else
			{
				P.pntPlane = new Point3D(0.0, pntPlane.Y, pntPlane.Z);
				P.Angle = 0.0;
				explanation = buLangTranslate.preDef.Top + " " + buLangTranslate.preDef.Plane + ": " + (P.Angle + P.AngleOffset).ToString("f1") + " °";
			}
		}
		P.AngleOffset = 0.0;
		P.refPlane = new Plane(new Point3D(0.0, P.pntPlane.Y, P.pntPlane.Z), Vector3D.AxisX, Vector3D.AxisY);
		P.refPlane.Rotate(buConversion5.DegreeToRadian(P.Angle), P.refPlane.AxisX, P.pntPlane);
		P.refPlane.UpdateEquation();
		P.Length = Length;
		P.Height = Height;
		P.Thickness = Thickness;
		buCall.buVector5_0.PlaneToEntity(P.refPlane, P.Length, P.Height, P.Thickness, UcsData, ref P.entityPlane, ref P.entityXVector, ref P.entityYVector, ref P.entityZVector, ref P.entityBall);
		P.Explanation = explanation;
		P.Index = Index;
	}

	public void GetSinglePathFromBasicSorting(List<buEntity> refEntities, ref List<buEntity> sortedEntities)
	{
		sortedEntities.Clear();
		SortbuSettings sortbuSettings = new SortbuSettings();
		sortbuSettings.Option.NextGroupRules = SortingNextGroupFindRulesType.ClosestLength;
		for (int i = 0; i <= refEntities.Count - 1; i++)
		{
			List<buEntity> SortedEntities = new List<buEntity>();
			SortEntitiesByRefPoint(refEntities[i].StartPoint, ref refEntities, sortbuSettings, ref SortedEntities);
			List<List<buEntity>> SplitedEntitites = new List<List<buEntity>>();
			EntitiesSplitByUpperLine(SortedEntities, ref SplitedEntitites);
			if (SplitedEntitites.Count == 1)
			{
				buEntity.Copy(SortedEntities, ref sortedEntities);
				i = refEntities.Count;
			}
		}
		if (sortedEntities.Count != 0)
		{
			return;
		}
		for (int j = 0; j <= refEntities.Count - 1; j++)
		{
			List<buEntity> SortedEntities2 = new List<buEntity>();
			SortEntitiesByRefPoint(refEntities[j].EndPoint, ref refEntities, sortbuSettings, ref SortedEntities2);
			List<List<buEntity>> SplitedEntitites2 = new List<List<buEntity>>();
			EntitiesSplitByUpperLine(SortedEntities2, ref SplitedEntitites2);
			if (SplitedEntitites2.Count == 1)
			{
				buEntity.Copy(SortedEntities2, ref sortedEntities);
				j = refEntities.Count;
			}
		}
	}

	public void GetNumberOfTouchForPoint(Point3D RefPoint, List<Entity> refEntities, double Resolution, int ExceptionIndex, ref int NumberOfTouch)
	{
		NumberOfTouch = 0;
		for (int i = 0; i <= refEntities.Count - 1; i++)
		{
			if (ExceptionIndex != i && ((refEntities[i] is ICurve) & refEntities[i].Selectable))
			{
				ICurve curve = (ICurve)refEntities[i];
				if (buCompare5.EQ(RefPoint, curve.StartPoint, Resolution))
				{
					NumberOfTouch++;
				}
				if (buCompare5.EQ(RefPoint, curve.EndPoint, Resolution))
				{
