	public void GetNumberOfTouchForPoint(Point3D RefPoint, List<buEntity> refEntities, double Resolution, int ExceptionIndex, ref int NumberOfTouch)
	{
		NumberOfTouch = 0;
		for (int i = 0; i <= refEntities.Count - 1; i++)
		{
			if (ExceptionIndex != i && refEntities[i].Info.Selectable)
			{
				buEntity buEntity2 = refEntities[i];
				if (buCompare5.EQ(RefPoint, buEntity2.StartPoint, Resolution))
				{
					NumberOfTouch++;
				}
				if (buCompare5.EQ(RefPoint, buEntity2.EndPoint, Resolution))
				{
					NumberOfTouch++;
				}
			}
		}
	}

