	public bool GetClosedEntitiesByRefPointUsingCrossLines(Point3D RefPoint, ref List<Entity> BaseRefEntities, SortSettings Settings, ref List<Entity> SortedEntities, ref SortResult Result)
	{
		try
		{
			List<PointWithIndex> list = new List<PointWithIndex>();
			for (int i = 0; i < 72; i++)
			{
				Point3D EndPnt = new Point3D();
				LineWithLengthAndAngle(RefPoint, 5000.0, (double)i * 5.0, ref EndPnt);
				Line line = new Line(RefPoint, EndPnt);
				List<PointWithIndex> list2 = new List<PointWithIndex>();
				for (int j = 0; j <= BaseRefEntities.Count - 1; j++)
				{
					Point3D[] array = line.IntersectWith((ICurve)BaseRefEntities[j]);
					if (array == null || array.Length == 0)
					{
						continue;
					}
					for (int k = 0; k <= array.Length - 1; k++)
					{
						bool flag = true;
						if (list2.Count > 0)
						{
							for (int l = 0; l <= list2.Count - 1; l++)
							{
								if (list2[l].Index == j)
								{
									flag = false;
								}
							}
						}
						if (flag)
						{
							PointWithIndex pointWithIndex = new PointWithIndex();
							pointWithIndex.Pnt = ToPoint3D(array[k]);
							pointWithIndex.Index = j;
							list2.Add(pointWithIndex);
						}
					}
				}
				double num = double.MaxValue;
				int num2 = -1;
				for (int m = 0; m <= list2.Count - 1; m++)
				{
					double num3 = Point3D.Distance(list2[m].Pnt, RefPoint);
					if (num3 < num)
					{
						num2 = m;
						num = num3;
					}
				}
				if (num2 < 0)
				{
					continue;
				}
				bool flag2 = true;
				for (int n = 0; n <= list.Count - 1; n++)
				{
					if (list[n].Index == list2[num2].Index)
					{
						flag2 = false;
					}
				}
				if (flag2)
				{
					list.Add(new PointWithIndex(list2[num2]));
				}
			}
			if (list.Count <= 0)
			{
				return false;
			}
			List<Entity> BaseRefEntities2 = new List<Entity>();
			for (int num4 = 0; num4 <= list.Count - 1; num4++)
			{
				Entity entity = CopyEntities(BaseRefEntities[list[num4].Index]);
				((CustomData)entity.EntityData).OriginalEntityIndex = list[num4].Index;
				BaseRefEntities2.Add(entity);
			}
			if (GetClosedEntitiesByRefPoint(RefPoint, ref BaseRefEntities2, Settings, ref SortedEntities, ref Result))
			{
				return true;
			}
			return GetClosedEntitiesByRefPoint(RefPoint, ref BaseRefEntities, Settings, ref SortedEntities, ref Result);
		}
		catch (Exception mSException)
		{
			string text = "";
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return false;
		}
	}

