							refPoint = ToPoint3D(point3D2);
						}
						if (num4 >= 0)
						{
							copiedEnt.RemoveAt(num4);
							refPoint = ToPoint3D(point3D2);
						}
						flag3 = false;
						num3 = -1;
						num4 = -1;
						AskMe.Return = false;
						k = BaseRefEntities.Count;
					}
					if (list.Count > 0)
					{
						flag2 = true;
						if (list.Count == 1)
						{
							num4 = list[0].Index;
							((CustomData)copiedEnt[list[0].Index].EntityData).CamSelected = true;
							SortedEntities.Add(list[0].Entity);
							if (num5 == 1 && !flag3)
							{
								num4 = -1;
							}
							refPoint = ToPoint3D(list[0].NextPoint);
							ToPoint3D(list[0].NextPoint);
							point3D2 = ToPoint3D(list[0].NextPoint);
							list2.Add(ToPoint3D(list[0].NextPoint));
							num3 = -1;
							if (buCompare5.EQ(point3D, point3D2, 0.1))
							{
								return true;
							}
							if (Settings.Option.StopPoint != null && buCompare5.EQ(RefPoint, Settings.Option.StopPoint, Settings.Option.Resolution))
							{
								Result.ResultType = SortingResultType.Done;
								return true;
							}
						}
						if (list.Count > 1 && ((((Settings.Option.IntersectionRules == SortingIntersectionRulesType.LowerIndex) | (Settings.Option.IntersectionRules == SortingIntersectionRulesType.ClosestLength) | (Settings.Option.IntersectionRules == SortingIntersectionRulesType.HigherIndex) | (Settings.Option.IntersectionRules == SortingIntersectionRulesType.FromDrawing)) ? 1u : 0u) & 1u & ((!AskMe.Return) ? 1u : 0u)) != 0)
						{
							((CustomData)copiedEnt[list[0].Index].EntityData).CamSelected = true;
							SortedEntities.Add(list[0].Entity);
							refPoint = ToPoint3D(list[0].NextPoint);
							ToPoint3D(list[0].NextPoint);
							point3D2 = ToPoint3D(list[0].NextPoint);
							num3 = list[0].Index;
							num4 = -1;
							flag3 = true;
							if (buCompare5.EQ(point3D, point3D2, 0.1))
							{
								return true;
							}
						}
					}
					num5 = list.Count;
					flag = false;
					num2++;
				}
			}
			return false;
		}
		catch (Exception mSException)
		{
			string text = "";
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return false;
		}
	}

	public bool SortNextRuleCondition(SortingNextGroupFindRulesType Rule, double DistanceX, double DistanceY, double ClosestX, double ClosestY)
	{
		bool result = false;
		if (Rule == SortingNextGroupFindRulesType.MinXMinY && ((DistanceX <= ClosestX) | buCompare5.EQ(DistanceX, ClosestX, buSystem.resolutionCompare)))
		{
			result = true;
			if (buCompare5.EQ(DistanceX, ClosestX, buSystem.resolutionCompare) && DistanceY > ClosestY)
			{
				result = false;
			}
		}
		if (Rule == SortingNextGroupFindRulesType.MaxXMinY && ((DistanceX >= ClosestX) | buCompare5.EQ(DistanceX, ClosestX, buSystem.resolutionCompare)))
		{
			result = true;
			if (buCompare5.EQ(DistanceX, ClosestX, buSystem.resolutionCompare) && DistanceY > ClosestY)
			{
				result = false;
			}
		}
		if (Rule == SortingNextGroupFindRulesType.MinXMaxY && ((DistanceX <= ClosestX) | buCompare5.EQ(DistanceX, ClosestX, buSystem.resolutionCompare)))
		{
			result = true;
			if (buCompare5.EQ(DistanceX, ClosestX, buSystem.resolutionCompare) && DistanceY < ClosestY)
			{
				result = false;
			}
		}
		if (Rule == SortingNextGroupFindRulesType.MaxXMaxY && ((DistanceX >= ClosestX) | buCompare5.EQ(DistanceX, ClosestX, buSystem.resolutionCompare)))
		{
			result = true;
			if (buCompare5.EQ(DistanceX, ClosestX, buSystem.resolutionCompare) && DistanceY < ClosestY)
			{
				result = false;
			}
		}
		if (Rule == SortingNextGroupFindRulesType.MinYMinX && ((DistanceY <= ClosestY) | buCompare5.EQ(DistanceY, ClosestY, buSystem.resolutionCompare)))
		{
			result = true;
			if (buCompare5.EQ(DistanceY, ClosestY, buSystem.resolutionCompare) && DistanceX > ClosestX)
			{
				result = false;
			}
		}
		if (Rule == SortingNextGroupFindRulesType.MaxYMinX && ((DistanceY >= ClosestY) | buCompare5.EQ(DistanceY, ClosestY, buSystem.resolutionCompare)))
		{
			result = true;
			if (buCompare5.EQ(DistanceY, ClosestY, buSystem.resolutionCompare) && DistanceX > ClosestX)
			{
				result = false;
			}
		}
		if (Rule == SortingNextGroupFindRulesType.MinYMaxX && ((DistanceY <= ClosestY) | buCompare5.EQ(DistanceY, ClosestY, buSystem.resolutionCompare)))
		{
			result = true;
			if (buCompare5.EQ(DistanceY, ClosestY, buSystem.resolutionCompare) && DistanceX < ClosestX)
			{
				result = false;
			}
		}
		if (Rule == SortingNextGroupFindRulesType.MaxYMaxX && ((DistanceY >= ClosestY) | buCompare5.EQ(DistanceY, ClosestY, buSystem.resolutionCompare)))
		{
			result = true;
			if (buCompare5.EQ(DistanceY, ClosestY, buSystem.resolutionCompare) && DistanceX < ClosestX)
			{
				result = false;
			}
		}
		return result;
	}

	public int MostClosestPoint(Point3D RefPoint, List<Entity> refEntities, SortSettings Settings, ref int Sequence, ref Point3D pntFound, ref StartEndType FoundLocation)
	{
		try
		{
			double num = double.MaxValue;
			double closestX = double.MaxValue;
			double closestY = double.MaxValue;
			Sequence = -1;
			if ((Settings.Option.NextGroupRules == SortingNextGroupFindRulesType.MaxXMinY) | (Settings.Option.NextGroupRules == SortingNextGroupFindRulesType.MaxXMaxY) | (Settings.Option.NextGroupRules == SortingNextGroupFindRulesType.MinYMaxX) | (Settings.Option.NextGroupRules == SortingNextGroupFindRulesType.MaxYMaxX))
			{
				closestX = double.MinValue;
			}
			if ((Settings.Option.NextGroupRules == SortingNextGroupFindRulesType.MaxXMaxY) | (Settings.Option.NextGroupRules == SortingNextGroupFindRulesType.MaxYMaxX) | (Settings.Option.NextGroupRules == SortingNextGroupFindRulesType.MaxYMinX) | (Settings.Option.NextGroupRules == SortingNextGroupFindRulesType.MinXMaxY))
			{
				closestY = double.MinValue;
			}
			for (int i = 0; i <= refEntities.Count - 1; i++)
			{
				Entity entity = refEntities[i];
				bool camSelected = GetCamSelected(refEntities[i]);
				if (!(((refEntities[i] is ICurve) & refEntities[i].Selectable) && !camSelected))
				{
					continue;
				}
				ICurve curve = (ICurve)refEntities[i];
				bool flag = true;
				if (!Settings.Filter.UsePointEntities & (refEntities[i].GetType() == typeof(devDept.Eyeshot.Entities.Point)))
				{
					flag = false;
				}
				if (!flag)
				{
					continue;
				}
				if (!((Settings.Option.NextGroupRules == SortingNextGroupFindRulesType.MinXMinY) | (Settings.Option.NextGroupRules == SortingNextGroupFindRulesType.MaxXMinY) | (Settings.Option.NextGroupRules == SortingNextGroupFindRulesType.MinYMinX) | (Settings.Option.NextGroupRules == SortingNextGroupFindRulesType.MaxYMinX) | (Settings.Option.NextGroupRules == SortingNextGroupFindRulesType.MaxXMinY) | (Settings.Option.NextGroupRules == SortingNextGroupFindRulesType.MaxXMaxY) | (Settings.Option.NextGroupRules == SortingNextGroupFindRulesType.MaxYMinX) | (Settings.Option.NextGroupRules == SortingNextGroupFindRulesType.MaxYMaxX)))
				{
					double num2 = Point3D.Distance(curve.StartPoint, RefPoint);
					if (num2 < num)
					{
						num = num2;
						Sequence = i;
						FoundLocation = StartEndType.Start;
						pntFound = ToPoint3D(curve.StartPoint);
					}
					num2 = Point3D.Distance(curve.EndPoint, RefPoint);
					if (num2 < num)
					{
						num = num2;
						Sequence = i;
						FoundLocation = StartEndType.End;
						pntFound = ToPoint3D(curve.EndPoint);
					}
					if (!((refEntities[i] is CompositeCurve) & !Settings.ClosestPoint.UseStartEndPointCompositeCurve))
					{
						continue;
					}
					CompositeCurve compositeCurve = refEntities[i] as CompositeCurve;
					for (int j = 0; j <= compositeCurve.CurveList.Count - 1; j++)
					{
						ICurve curve2 = compositeCurve.CurveList[j];
						num2 = Point3D.Distance(curve2.StartPoint, RefPoint);
						if (num2 < num)
						{
							num = num2;
							Sequence = i;
							FoundLocation = StartEndType.Start;
							pntFound = ToPoint3D(curve2.StartPoint);
						}
						num2 = Point3D.Distance(curve2.EndPoint, RefPoint);
						if (num2 < num)
						{
							num = num2;
							Sequence = i;
							FoundLocation = StartEndType.End;
							pntFound = ToPoint3D(curve2.EndPoint);
						}
					}
					continue;
				}
				Point3D pnt = ToPoint3D(curve.StartPoint);
				double num3 = DeltaX(RefPoint, curve.StartPoint);
				double num4 = DeltaY(RefPoint, curve.StartPoint);
				if (Settings.Option.UseBoxBoundingForMinMax)
				{
					if ((Settings.Option.NextGroupRules == SortingNextGroupFindRulesType.MinXMinY) | (Settings.Option.NextGroupRules == SortingNextGroupFindRulesType.MinYMinX))
					{
						num3 = DeltaX(RefPoint, entity.BoxMin);
						num4 = DeltaY(RefPoint, entity.BoxMin);
						pnt = ToPoint3D(entity.BoxMin);
					}
					if ((Settings.Option.NextGroupRules == SortingNextGroupFindRulesType.MaxXMinY) | (Settings.Option.NextGroupRules == SortingNextGroupFindRulesType.MinYMaxX))
					{
						num3 = DeltaX(RefPoint, entity.BoxMax);
						num4 = DeltaY(RefPoint, entity.BoxMin);
						pnt = new Point3D(entity.BoxMax.X, entity.BoxMin.Y, entity.BoxMin.Z);
					}
					if ((Settings.Option.NextGroupRules == SortingNextGroupFindRulesType.MinXMaxY) | (Settings.Option.NextGroupRules == SortingNextGroupFindRulesType.MaxYMinX))
					{
						num3 = DeltaX(RefPoint, entity.BoxMin);
						num4 = DeltaY(RefPoint, entity.BoxMax);
						pnt = new Point3D(entity.BoxMin.X, entity.BoxMax.Y, entity.BoxMin.Z);
					}
					if ((Settings.Option.NextGroupRules == SortingNextGroupFindRulesType.MaxXMaxY) | (Settings.Option.NextGroupRules == SortingNextGroupFindRulesType.MaxYMaxX))
					{
						num3 = DeltaX(RefPoint, entity.BoxMax);
						num4 = DeltaY(RefPoint, entity.BoxMax);
						pnt = ToPoint3D(entity.BoxMax);
					}
				}
				if (SortNextRuleCondition(Settings.Option.NextGroupRules, num3, num4, closestX, closestY))
				{
					closestX = num3;
					closestY = num4;
					Sequence = i;
					FoundLocation = StartEndType.Start;
					pntFound = ToPoint3D(pnt);
				}
				if (!Settings.Option.UseBoxBoundingForMinMax)
				{
					num3 = DeltaX(RefPoint, curve.EndPoint);
					num4 = DeltaY(RefPoint, curve.EndPoint);
					if (SortNextRuleCondition(Settings.Option.NextGroupRules, num3, num4, closestX, closestY))
					{
						closestX = num3;
						closestY = num4;
						Sequence = i;
						FoundLocation = StartEndType.End;
						pntFound = ToPoint3D(curve.EndPoint);
					}
				}
				if (!((refEntities[i] is CompositeCurve) & !Settings.ClosestPoint.UseStartEndPointCompositeCurve))
				{
					continue;
				}
				CompositeCurve compositeCurve2 = refEntities[i] as CompositeCurve;
				for (int k = 0; k <= compositeCurve2.CurveList.Count - 1; k++)
				{
					ICurve curve3 = compositeCurve2.CurveList[k];
					pnt = ToPoint3D(curve3.StartPoint);
					num3 = DeltaX(curve3.StartPoint, RefPoint);
					num4 = DeltaY(curve3.StartPoint, RefPoint);
					if (Settings.Option.UseBoxBoundingForMinMax)
					{
						Entity entity2 = compositeCurve2.CurveList[k] as Entity;
						if ((Settings.Option.NextGroupRules == SortingNextGroupFindRulesType.MinXMinY) | (Settings.Option.NextGroupRules == SortingNextGroupFindRulesType.MinYMinX))
						{
							num3 = DeltaX(RefPoint, entity2.BoxMin);
							num4 = DeltaY(RefPoint, entity2.BoxMin);
							pnt = ToPoint3D(entity2.BoxMin);
						}
						if ((Settings.Option.NextGroupRules == SortingNextGroupFindRulesType.MaxXMinY) | (Settings.Option.NextGroupRules == SortingNextGroupFindRulesType.MinYMaxX))
						{
							num3 = DeltaX(RefPoint, entity2.BoxMax);
							num4 = DeltaY(RefPoint, entity2.BoxMin);
							pnt = new Point3D(entity2.BoxMax.X, entity2.BoxMin.Y, entity2.BoxMin.Z);
						}
						if ((Settings.Option.NextGroupRules == SortingNextGroupFindRulesType.MinXMaxY) | (Settings.Option.NextGroupRules == SortingNextGroupFindRulesType.MaxYMinX))
						{
							num3 = DeltaX(RefPoint, entity2.BoxMin);
							num4 = DeltaY(RefPoint, entity2.BoxMax);
							pnt = new Point3D(entity2.BoxMin.X, entity2.BoxMax.Y, entity2.BoxMin.Z);
						}
						if ((Settings.Option.NextGroupRules == SortingNextGroupFindRulesType.MaxXMaxY) | (Settings.Option.NextGroupRules == SortingNextGroupFindRulesType.MaxYMaxX))
						{
							num3 = DeltaX(RefPoint, entity2.BoxMax);
							num4 = DeltaY(RefPoint, entity2.BoxMax);
							pnt = ToPoint3D(entity2.BoxMax);
						}
					}
					if (SortNextRuleCondition(Settings.Option.NextGroupRules, num3, num4, closestX, closestY))
					{
						closestX = num3;
						closestY = num4;
						Sequence = i;
						FoundLocation = StartEndType.Start;
						pntFound = ToPoint3D(pnt);
					}
					if (!Settings.Option.UseBoxBoundingForMinMax)
					{
						num3 = DeltaX(curve3.EndPoint, RefPoint);
						num4 = DeltaY(curve3.EndPoint, RefPoint);
						if (SortNextRuleCondition(Settings.Option.NextGroupRules, num3, num4, closestX, closestY))
						{
							closestX = num3;
							closestY = num4;
							Sequence = i;
							FoundLocation = StartEndType.End;
							pntFound = ToPoint3D(curve3.EndPoint);
						}
					}
				}
			}
			if (Sequence < 0)
			{
				return 0;
			}
			return 1;
		}
		catch (Exception mSException)
		{
			string text = "RefPoint: " + RefPoint.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return 0;
		}
	}

