	public bool FindPath(SortbuFoundItems Item, List<buEntity> CircularEntities, Point3D basePoint, Point3D StopPoint, SortbuSettings Settings, ref List<buEntity> SortEntites)
	{
		bool result = false;
		Point3D point3D = ToPoint3D(basePoint);
		List<SortbuFoundItems> list = new List<SortbuFoundItems>();
		List<buEntity> list2 = new List<buEntity>();
		if (Item != null)
		{
			point3D = ToPoint3D(Item.NextPoint);
			SortEntites.Add(Item.Entity);
			if ((buCompare5.EQ(Item.Entity.StartPoint, StopPoint, Settings.Option.Resolution) | buCompare5.EQ(Item.Entity.EndPoint, StopPoint, Settings.Option.Resolution)) && !buCompare5.EQ(basePoint, StopPoint))
			{
				return true;
			}
		}
		for (int i = 0; i <= CircularEntities.Count - 1; i++)
		{
			buEntity copiedEntity = null;
			buEntity.Copy(CircularEntities[i], ref copiedEntity);
			copiedEntity.Info.Sequence = i;
			list2.Add(copiedEntity);
		}
		for (int j = 0; j <= CircularEntities.Count - 1; j++)
		{
			list.Clear();
			if (list.Count == 0)
			{
				for (int k = 0; k <= list2.Count - 1; k++)
				{
					buEntity buEntity2 = list2[k];
					if (buEntity2.Vertices.Count > 0)
					{
						new Point3D();
						bool flag = false;
						SortbuFoundItems sortbuFoundItems = new SortbuFoundItems();
						isEntityIDAvailable(buEntity2.Info.ID, SortEntites);
						bool flag2 = false;
						if (Item != null && ((Item.Entity.Info.ID != null) & (buEntity2.Info.ID != null)) && ((Item.Entity.Info.ID.Length > 0) & (buEntity2.Info.ID.Length > 0)) && Item.Entity.Info.ID == buEntity2.Info.ID)
						{
							flag2 = true;
						}
						if (buCompare5.EQ(buEntity2.StartPoint, point3D, Settings.Option.Resolution) && (Settings.Option.IgnoreCamSelected | !buEntity2.Info.CamSelected) && !flag2)
						{
							sortbuFoundItems.StartPoint = ToPoint3D(buEntity2.StartPoint);
							sortbuFoundItems.NextPoint = ToPoint3D(buEntity2.EndPoint);
							sortbuFoundItems.Direction = camPathDirectionType.Normal;
							buEntity.Copy(list2[k], ref sortbuFoundItems.Entity);
							SetSortDirection(entitySortDirection.Normal, ref sortbuFoundItems.Entity);
							sortbuFoundItems.Entity.Info.Sequence = 0;
							sortbuFoundItems.Index = k;
							list.Add(sortbuFoundItems);
							flag = true;
						}
						if (buCompare5.EQ(buEntity2.EndPoint, point3D, Settings.Option.Resolution) && !flag && (Settings.Option.IgnoreCamSelected | !buEntity2.Info.CamSelected) && !flag2)
						{
							sortbuFoundItems.StartPoint = ToPoint3D(buEntity2.EndPoint);
							sortbuFoundItems.NextPoint = ToPoint3D(buEntity2.StartPoint);
							sortbuFoundItems.Direction = camPathDirectionType.Reverse;
							buEntity.Copy(list2[k], ref sortbuFoundItems.Entity);
							SetSortDirection(entitySortDirection.Reverse, ref sortbuFoundItems.Entity);
							sortbuFoundItems.Entity.Info.Sequence = 0;
							sortbuFoundItems.Index = k;
							list.Add(sortbuFoundItems);
						}
					}
				}
			}
			if ((list.Count == 1) & (StopPoint != null))
			{
				SortEntites.Add(list[0].Entity);
				list2.RemoveAt(list[0].Index);
				point3D = ToPoint3D(list[0].NextPoint);
				if (buCompare5.EQ(point3D, StopPoint, Settings.Option.Resolution))
				{
					return true;
				}
			}
			if ((list.Count > 1) & (StopPoint != null))
			{
				SortEntites.Add(list[0].Entity);
				list2.RemoveAt(list[0].Index);
				point3D = ToPoint3D(list[0].NextPoint);
				if (buCompare5.EQ(point3D, StopPoint, Settings.Option.Resolution))
				{
					return true;
				}
			}
		}
		return result;
	}

