									buLine buLine4 = new buLine(pntEnd2, RefPoint);
									buLine4.typeDefination = entityTypeDefination.Upper;
									SortedEntities.Add(buLine4);
									PointClickData.CatchPoint = ToPoint3D(RefPoint);
									PointClickData.PreCatchPoint = ToPoint3D(RefPoint);
								}
								break;
							}
							int num4 = int.MaxValue;
							int num5 = -1;
							for (int m = 0; m <= list4.Count - 1; m++)
							{
								if (list4[m].Count < num4)
								{
									num4 = list4[m].Count;
									num5 = m;
								}
							}
							if (num5 < 0)
							{
								break;
							}
							for (int n = 0; n <= list4[num5].Count - 1; n++)
							{
								int entityIndexByID2 = GetEntityIndexByID(BaseRefEntities, list4[num5][n].Info.ID);
								if (entityIndexByID2 >= 0)
								{
									BaseRefEntities[entityIndexByID2].Info.CamSelected = true;
								}
							}
							SortedEntities.AddRange(list4[num5]);
							Point3D pntEnd3 = new Point3D();
							GetEntityEndPointByCamDirection(SortedEntities[SortedEntities.Count - 1], ref pntEnd3);
							PointClickData.PreCatchPoint = ToPoint3D(pntEnd3);
							PointClickData.CatchPoint = ToPoint3D(pntEnd3);
							break;
						}
					}
					num++;
					continue;
				}
				if (SortedEntities.Count > 0)
				{
					Point3D pntEnd4 = new Point3D();
					GetEntityEndPointByCamDirection(SortedEntities[SortedEntities.Count - 1], ref pntEnd4);
					buLine buLine5 = new buLine(pntEnd4, RefPoint);
					buLine5.typeDefination = entityTypeDefination.Upper;
					SortedEntities.Add(buLine5);
					PointClickData.CatchPoint = ToPoint3D(RefPoint);
					PointClickData.PreCatchPoint = ToPoint3D(RefPoint);
				}
				break;
			}
		}
		else
		{
			buLine buLine6 = new buLine(PointClickData.CatchPoint, RefPoint);
			buLine6.typeDefination = entityTypeDefination.Upper;
			SortedEntities.Add(buLine6);
			PointClickData.CatchPoint = ToPoint3D(RefPoint);
			if (PointClickData.CatchPoint != null)
			{
				PointClickData.PreCatchPoint = ToPoint3D(PointClickData.CatchPoint);
			}
			PointClickData.isPointOnEntity = true;
		}
	}

