	public List<Point3D> SortByDistance(Point3D refPoint, List<Point3D> lst)
	{
		List<Point3D> list = new List<Point3D>();
		list.Add(lst[NearestPoint(refPoint, lst)]);
		lst.Remove(list[0]);
		int num = 0;
		for (int i = 0; i < lst.Count + num; i++)
		{
			list.Add(lst[NearestPoint(list[list.Count - 1], lst)]);
			lst.Remove(list[list.Count - 1]);
			num++;
		}
		return list;
	}

