	public int NearestPoint(Point3D srcPt, List<Point3D> lookIn)
	{
		KeyValuePair<double, int> keyValuePair = default(KeyValuePair<double, int>);
		for (int i = 0; i < lookIn.Count; i++)
		{
			double num = Math.Sqrt(Math.Pow(srcPt.X - lookIn[i].X, 2.0) + Math.Pow(srcPt.Y - lookIn[i].Y, 2.0));
			if (i != 0)
			{
				if (num < keyValuePair.Key)
				{
					keyValuePair = new KeyValuePair<double, int>(num, i);
				}
			}
			else
			{
				keyValuePair = new KeyValuePair<double, int>(num, i);
			}
		}
		return keyValuePair.Value;
	}

