	public void FindInternalEntitiesAtClosedContour(List<Point3D> ClosedContour, List<Entity> Entities, Plane refPlane, ref List<List<Entity>> ClosedEntities, ref List<List<Entity>> NotClosedEntities)
	{
		List<List<Point3D>> ClosedPoints = new List<List<Point3D>>();
		FindInternalEntitiesAtClosedContour(ClosedContour, Entities, refPlane, ref ClosedEntities, ref ClosedPoints, ref NotClosedEntities);
	}

	public void FindInternalEntitiesAtClosedContour(List<Point3D> ClosedContour, List<Entity> Entities, Plane refPlane, ref List<List<Entity>> ClosedEntities, ref List<List<Point3D>> ClosedPoints, ref List<List<Entity>> NotClosedEntities)
	{
		try
		{
			List<Entity> BaseRefEntities = new List<Entity>();
			List<Entity> SortedEntities = new List<Entity>();
			List<List<Entity>> SplitedEntitites = new List<List<Entity>>();
			SortSettings sortSettings = new SortSettings();
			Point3D MinPoint = new Point3D();
			Point3D MidPoint = new Point3D();
			Point3D MaxPoint = new Point3D();
			BoxSizeCalculate(ClosedContour, ref MinPoint, ref MidPoint, ref MaxPoint);
			sortSettings.Option.NextGroupRules = SortingNextGroupFindRulesType.ClosestLength;
			sortSettings.Option.IntersectionRules = SortingIntersectionRulesType.LowerIndex;
			for (int i = 0; i <= Entities.Count - 1; i++)
			{
				if (Entities[i].BoxMax == null)
				{
					Entities[i].Regen(buSystem.RegenDeviation);
				}
				if (!Entities[i].Visible)
				{
					continue;
				}
				bool flag = IsPointInsideWindow(MinPoint, MaxPoint, Entities[i].BoxMin, refPlane, UseEqualCondition: false);
				bool flag2 = IsPointInsideWindow(MinPoint, MaxPoint, Entities[i].BoxMax, refPlane, UseEqualCondition: false);
				bool flag3 = flag && flag2;
				if (flag && flag2)
				{
					for (int j = 0; j <= Entities[i].Vertices.Length - 1; j++)
					{
						bool flag4 = IsPointInsidePolygon(ClosedContour, Entities[i].Vertices[j]);
						flag3 = flag3 && flag4;
					}
				}
				if (flag3)
				{
					bool flag5 = true;
					if (Entities[i] is devDept.Eyeshot.Entities.Point)
					{
						flag5 = false;
					}
					if (flag5)
					{
						BaseRefEntities.Add(CopyEntities(Entities[i]));
					}
				}
			}
			if (BaseRefEntities.Count > 0)
			{
				SortResult Result = new SortResult();
				SortEntitiesByRefPoint(BaseRefEntities[0].Vertices[0], ref BaseRefEntities, sortSettings, ref SortedEntities, ref Result);
			}
			EntitiesSplitByUpperLine(SortedEntities, ref SplitedEntitites);
			for (int k = 0; k <= SplitedEntitites.Count - 1; k++)
			{
				if (!IsEntitiesClosedPath(SplitedEntitites[k]))
				{
					List<Entity> copiedEnt = new List<Entity>();
					CopyEntities(SplitedEntitites[k], ref copiedEnt);
					NotClosedEntities.Add(copiedEnt);
					continue;
				}
				List<Entity> copiedEnt2 = new List<Entity>();
				CopyEntities(SplitedEntitites[k], ref copiedEnt2);
				ClosedEntities.Add(copiedEnt2);
				List<Point3D> Points = new List<Point3D>();
				EntitiesToPointsWithCamDirection(SplitedEntitites[k], buSystem.RegenDeviation, ref Points);
				CheckDuplicatedPointsWithPrevious(0.01, ref Points);
				ClosedPoints.Add(Points);
			}
		}
		catch (Exception mSException)
		{
			string text = "ClosedContour: " + ClosedContour.Count + " - Entities: " + Entities.Count + " - Plane: " + refPlane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void FindInternalEntitiesAtClosedContour(List<Point3D> ClosedContour, List<buEntity> Entities, Plane refPlane, ref List<List<buEntity>> ClosedEntities, ref List<List<buEntity>> NotClosedEntities)
	{
		List<List<Point3D>> ClosedPoints = new List<List<Point3D>>();
		FindInternalEntitiesAtClosedContour(ClosedContour, Entities, refPlane, ref ClosedEntities, ref ClosedPoints, ref NotClosedEntities);
	}

	public void FindInternalEntitiesAtClosedContour(List<Point3D> ClosedContour, List<buEntity> Entities, Plane refPlane, ref List<List<buEntity>> ClosedEntities, ref List<List<Point3D>> ClosedPoints, ref List<List<buEntity>> NotClosedEntities)
