				{
					for (int j = 0; j <= Entities[i].Vertices.Count - 1; j++)
					{
						bool flag4 = IsPointInsidePolygon(ClosedContour, Entities[i].Vertices[j]);
						flag3 = flag3 && flag4;
					}
				}
				if (flag3)
				{
					bool flag5 = true;
					if (Entities[i] is buPoint)
					{
						flag5 = false;
					}
					if (flag5)
					{
						BaseRefEntities.Add(buEntity.Copy(Entities[i]));
