			}
			EntitiesSplitByUpperLine(SortedEntities, ref SplitedEntitites);
			for (int k = 0; k <= SplitedEntitites.Count - 1; k++)
			{
				if (!IsEntitiesClosedPath(SplitedEntitites[k]))
				{
					List<buEntity> copiedEntities = new List<buEntity>();
					buEntity.Copy(SplitedEntitites[k], ref copiedEntities);
					NotClosedEntities.Add(copiedEntities);
					continue;
				}
				List<buEntity> copiedEntities2 = new List<buEntity>();
				buEntity.Copy(SplitedEntitites[k], ref copiedEntities2);
				ClosedEntities.Add(copiedEntities2);
				List<Point3D> Points = new List<Point3D>();
				EntitiesToPointsWithCamDirection(SplitedEntitites[k], buSystem.RegenDeviation, ref Points);
				CheckDuplicatedPointsWithPrevious(0.01, ref Points);
				ClosedPoints.Add(Points);
			}
		}
		catch (Exception mSException)
		{
			string text = "ClosedContour: " + ClosedContour.Count + " - Entities: " + Entities.Count + " - Plane: " + refPlane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void FindInternalEntitiesFromEntitiesMethodBoxBounding(List<buEntity> OutsidesEntities, List<buEntity> InsideEntities, Plane refPlane, ref List<buEntity> FoundInsideEntities, double SortResolution = 0.05)
	{
		try
		{
			List<buEntity> copiedEntities = new List<buEntity>();
			buEntity.Copy(InsideEntities, ref copiedEntities);
			Point3D MinPoint = new Point3D();
			Point3D MidPoint = new Point3D();
			Point3D MaxPoint = new Point3D();
			BoxSizeCalculate(OutsidesEntities, ref MinPoint, ref MidPoint, ref MaxPoint);
			for (int num = copiedEntities.Count - 1; num >= 0; num--)
			{
				Point3D MinPoint2 = new Point3D();
				Point3D MidPoint2 = new Point3D();
				Point3D MaxPoint2 = new Point3D();
				BoxSizeCalculate(copiedEntities[num], ref MinPoint2, ref MidPoint2, ref MaxPoint2);
				if (isBoxSizeInsideBoxSize(MinPoint, MaxPoint, MinPoint2, MaxPoint2, refPlane))
				{
					buEntity copiedEntity = null;
					buEntity.Copy(copiedEntities[num], ref copiedEntity);
					if (copiedEntity != null)
					{
						FoundInsideEntities.Add(copiedEntity);
					}
					copiedEntities.RemoveAt(num);
				}
			}
		}
		catch (Exception)
		{
		}
	}

