	public void FindOutsideAndInsidentitiesFromEntities(Point3D RefPoint, List<Entity> AllEntities, Plane refPlane, ref List<Entity> OutsideEntities, ref List<List<Entity>> InsideEntities, ref List<List<Entity>> NotInsideEntities)
	{
		double num = double.MinValue;
		double num2 = double.MinValue;
		int num3 = -1;
		SortSettings sortSettings = new SortSettings();
		SortResult Result = new SortResult();
		sortSettings.Option.IntersectionRules = SortingIntersectionRulesType.LowerIndex;
		sortSettings.Option.NextGroupRules = SortingNextGroupFindRulesType.ClosestLength;
		List<Entity> SortedEntities = new List<Entity>();
		List<List<Entity>> SplitedEntitites = new List<List<Entity>>();
		SortEntitiesByRefPoint(RefPoint, ref AllEntities, sortSettings, ref SortedEntities, ref Result);
		EntitiesSplitByUpperLine(SortedEntities, ref SplitedEntitites);
		for (int i = 0; i <= SplitedEntitites.Count - 1; i++)
		{
			Point3D MinPoint = new Point3D();
			Point3D MaxPoint = new Point3D();
			BoxSizeCalculate(SplitedEntitites[i], ref MinPoint, ref MaxPoint);
			double num4 = MaxPoint.X - MinPoint.X;
			double num5 = MaxPoint.Y - MinPoint.Y;
			if (num4 > num && num5 > num2)
			{
				num = num4;
				num2 = num5;
				num3 = i;
			}
		}
		if (num3 < 0)
		{
			return;
		}
		CopyEntities(SplitedEntitites[num3], ref OutsideEntities);
		SplitedEntitites.RemoveAt(num3);
		isVerticesNull(buSystem.RegenDeviation, ref OutsideEntities);
		Point3D MinPoint2 = new Point3D();
		Point3D MaxPoint2 = new Point3D();
		BoxSizeCalculate(OutsideEntities, ref MinPoint2, ref MaxPoint2);
		List<Point3D> Points = new List<Point3D>();
		EntitiesToPointsWithCamDirection(OutsideEntities, buSystem.RegenDeviation, ref Points);
		for (int j = 0; j <= SplitedEntitites.Count - 1; j++)
		{
			Point3D MinPoint3 = new Point3D();
			Point3D MaxPoint3 = new Point3D();
			BoxSizeCalculate(SplitedEntitites[j], ref MinPoint3, ref MaxPoint3);
			if (!isBoxSizeInsideBoxSize(MinPoint2, MaxPoint2, MinPoint3, MaxPoint3, refPlane))
			{
				List<Entity> copiedEnt = new List<Entity>();
				CopyEntities(SplitedEntitites[j], ref copiedEnt);
				NotInsideEntities.Add(copiedEnt);
				continue;
			}
			bool flag = true;
			for (int k = 0; k <= SplitedEntitites[j].Count - 1; k++)
			{
				Entity entity = SplitedEntitites[j][k];
				if (entity.Vertices == null)
				{
					entity.Regen(new RegenParams(buSystem.RegenDeviation));
				}
				for (int l = 0; l <= entity.Vertices.Length - 1; l++)
				{
					if (!IsPointInsidePolygon(Points, entity.Vertices[l]))
					{
						flag = false;
						l = entity.Vertices.Length;
					}
				}
			}
			if (!flag)
			{
				List<Entity> copiedEnt2 = new List<Entity>();
				CopyEntities(SplitedEntitites[j], ref copiedEnt2);
				NotInsideEntities.Add(copiedEnt2);
			}
			else
			{
				List<Entity> copiedEnt3 = new List<Entity>();
				CopyEntities(SplitedEntitites[j], ref copiedEnt3);
				InsideEntities.Add(copiedEnt3);
			}
		}
	}

