				if (Points4.Count >= 3)
				{
					list3.Add(list[k]);
				}
			}
			f_ProgressCalculation.Init((double)k / (double)(list.Count - 1) * 100.0, 25.0, "Analyse Outside");
			f_ProgressCalculation.Refresh();
		}
		for (int num = 0; num <= list3.Count - 1; num++)
