				bool flag2 = isBoxSizeInsideBoxSize(MinPoint, MaxPoint, MinPoint2, MaxPoint2, refPlane);
				List<Point3D> Points6 = new List<Point3D>();
				EntitiesToPointsWithCamDirection(list4[num2], 0.05, ref Points6);
				for (int num3 = 0; num3 <= Points6.Count - 1; num3++)
				{
					if (flag2 = IsPointInsidePolygon(Points5, Points6[num3], Plane.XY, CheckOver: false))
					{
						num3 = Points6.Count;
					}
				}
				if (flag2)
				{
					List<Entity> copiedEntity2 = new List<Entity>();
					buEntity.Copy(list4[num2], ref copiedEntity2);
					entitiesGroup2.Inside.Add(copiedEntity2);
					list4.RemoveAt(num2);
				}
			}
			for (int num4 = list2.Count - 1; num4 >= 0; num4--)
			{
				Point3D MinPoint3 = new Point3D();
				Point3D MidPoint3 = new Point3D();
				Point3D MaxPoint3 = new Point3D();
				BoxSizeCalculate(list2[num4], ref MinPoint3, ref MidPoint3, ref MaxPoint3);
				if (isBoxSizeInsideBoxSize(MinPoint, MaxPoint, MinPoint3, MaxPoint3, refPlane))
				{
					List<Entity> copiedEntity3 = new List<Entity>();
					buEntity.Copy(list2[num4], ref copiedEntity3);
					entitiesGroup2.Inside.Add(copiedEntity3);
