		List<List<Entity>> SplitedEntitites = new List<List<Entity>>();
		List<List<Entity>> list = new List<List<Entity>>();
		List<List<Entity>> list2 = new List<List<Entity>>();
		Groups.Clear();
		Groups = new List<EntitiesGroup>();
