		EntitiesSplitByUpperLine(SortedEntities, ref SplitedEntitites);
		for (int i = 0; i <= SplitedEntitites.Count - 1; i++)
		{
			if (!isEntitiesClosed(SplitedEntitites[i]))
			{
				list2.Add(CopyEntities(SplitedEntitites[i]));
			}
			else
			{
				list.Add(CopyEntities(SplitedEntitites[i]));
			}
		}
		SplitedEntitites.Clear();
		if (list.Count <= 0)
		{
			return;
		}
		List<bool> list3 = new List<bool>();
		for (int j = 0; j <= list.Count - 1; j++)
		{
			list3.Add(item: false);
		}
		for (int k = 0; k <= list.Count - 1; k++)
		{
			new List<int>();
			bool flag = false;
			bool flag2 = false;
			for (int l = 0; l <= list.Count - 1; l++)
			{
				if (k != l)
				{
					bool flag3 = isEntitiesGroupInsideEntities(list[k], list[l], refPlane);
					flag = flag || flag3;
				}
			}
			for (int m = 0; m <= list.Count - 1; m++)
			{
				if (k != m)
				{
					bool flag4 = isEntitiesGroupInsideEntities(list[m], list[k], refPlane);
					flag2 = flag2 || flag4;
				}
			}
			if (flag)
			{
				EntitiesGroup entitiesGroup = new EntitiesGroup();
				CopyEntities(list[k], ref entitiesGroup.Outside);
				Groups.Add(entitiesGroup);
				list3[k] = true;
