			if (!flag && !flag2)
			{
				EntitiesGroup entitiesGroup2 = new EntitiesGroup();
				CopyEntities(list[k], ref entitiesGroup2.Outside);
				Groups.Add(entitiesGroup2);
				list3[k] = true;
			}
		}
		for (int n = 0; n <= Groups.Count - 1; n++)
