	public void FindEntitiesGroupFromEntities(Point3D RefPoint, List<buEntity> AllEntities, Plane refPlane, ref List<buEntitiesGroup> Groups, FindEntitiesGroupSettings Settings)
	{
		SortbuSettings sortbuSettings = new SortbuSettings();
		SortbuResult Result = new SortbuResult();
		sortbuSettings.Option.IntersectionRules = Settings.IntersectionRules;
		sortbuSettings.Option.NextGroupRules = Settings.NextFroupRules;
		sortbuSettings.Option.Resolution = Settings.SortResolution;
		List<buEntity> SortedEntities = new List<buEntity>();
		List<List<buEntity>> SplitedEntitites = new List<List<buEntity>>();
		List<List<buEntity>> list = new List<List<buEntity>>();
		List<List<buEntity>> list2 = new List<List<buEntity>>();
		if (Groups == null)
		{
			Groups = new List<buEntitiesGroup>();
		}
		Groups.Clear();
		Groups = new List<buEntitiesGroup>();
		SortEntitiesByRefPoint(RefPoint, ref AllEntities, sortbuSettings, ref SortedEntities, ref Result);
		EntitiesSplitByUpperLine(SortedEntities, ref SplitedEntitites);
		for (int i = 0; i <= SplitedEntitites.Count - 1; i++)
		{
			if (!isEntitiesClosed(SplitedEntitites[i]))
			{
				if (SplitedEntitites[i].Count != 1 || !(SplitedEntitites[i][0] is buLinearPath))
				{
					list2.Add(CopyEntities(SplitedEntitites[i]));
					continue;
				}
				buEntity refLinearPath = SplitedEntitites[i][0] as buLinearPath;
				if (refLinearPath.Vertices.Count <= 4)
				{
					list2.Add(CopyEntities(SplitedEntitites[i]));
					continue;
				}
				int num = 0;
				if (!buCompare5.EQ(refLinearPath.Vertices[0], refLinearPath.Vertices[refLinearPath.Vertices.Count - 2]))
				{
					if (!buCompare5.EQ(refLinearPath.Vertices[0], refLinearPath.Vertices[refLinearPath.Vertices.Count - 3]))
					{
						if (buCompare5.EQ(refLinearPath.Vertices[0], refLinearPath.Vertices[refLinearPath.Vertices.Count - 4]))
						{
							num = 4;
						}
					}
					else
					{
						num = 3;
					}
				}
				else
				{
					num = 2;
				}
				if (!(num >= 2 && num <= 4))
				{
					list2.Add(CopyEntities(SplitedEntitites[i]));
					continue;
				}
				buEntity trimedEntity = null;
				MakeIsClosedEntityWithTrim(num, ref refLinearPath, ref trimedEntity);
				SplitedEntitites[i][0] = refLinearPath;
				list.Add(CopyEntities(SplitedEntitites[i]));
				if (trimedEntity != null)
				{
					List<buEntity> list3 = new List<buEntity>();
					list3.Add(trimedEntity);
					list2.Add(list3);
				}
			}
			else
			{
				List<Point3D> Points = new List<Point3D>();
				ClockDirectionType clockDirection = GetClockDirection(SplitedEntitites[i]);
				if (clockDirection != Settings.ClockDirection)
				{
					List<buEntity> ChangedEntities = SplitedEntitites[i];
					ChangeEntitiesDirection(ref ChangedEntities);
				}
				EntitiesToPointsWithCamDirection(SplitedEntitites[i], ref Points);
				if (Points.Count > 3)
				{
					list.Add(CopyEntities(SplitedEntitites[i]));
				}
			}
		}
		SplitedEntitites.Clear();
		if (list.Count <= 0)
		{
			buEntitiesGroup buEntitiesGroup2 = new buEntitiesGroup();
			for (int j = 0; j <= list2.Count - 1; j++)
			{
				List<buEntity> copiedEntities = new List<buEntity>();
				buEntity.Copy(list2[j], ref copiedEntities);
				buEntityList buEntityList2 = new buEntityList(copiedEntities);
				if (buEntitiesGroup2.OpenEntities == null)
				{
					buEntitiesGroup2.OpenEntities = new List<buEntityList>();
				}
				buEntityList2.Points = new List<Point3D>();
				EntitiesToPointsWithCamDirection(copiedEntities, ref buEntityList2.Points);
				buEntitiesGroup2.OpenEntities.Add(buEntityList2);
			}
			Groups.Add(buEntitiesGroup2);
			return;
		}
		new List<bool>();
		List<List<buEntity>> list4 = new List<List<buEntity>>();
		List<List<buEntity>> list5 = new List<List<buEntity>>();
		for (int k = 0; k <= list.Count - 1; k++)
		{
			Point3D MinPoint = new Point3D();
			Point3D MidPoint = new Point3D();
			Point3D MaxPoint = new Point3D();
			BoxSizeCalculate(list[k], ref MinPoint, ref MidPoint, ref MaxPoint);
			bool flag = false;
			for (int l = 0; l <= list.Count - 1; l++)
			{
				if (k != l)
				{
					Point3D MinPoint2 = new Point3D();
					Point3D MidPoint2 = new Point3D();
					Point3D MaxPoint2 = new Point3D();
					BoxSizeCalculate(list[l], ref MinPoint2, ref MidPoint2, ref MaxPoint2);
					flag |= isBoxSizeInsideBoxSize(MinPoint2, MaxPoint2, MinPoint, MaxPoint, refPlane);
				}
			}
			if (flag)
			{
				List<Point3D> Points2 = new List<Point3D>();
				EntitiesToPointsWithCamDirection(list[k], ref Points2);
				if (Points2.Count >= 3)
				{
					list5.Add(list[k]);
				}
			}
			else
			{
				List<Point3D> Points3 = new List<Point3D>();
				EntitiesToPointsWithCamDirection(list[k], ref Points3);
				if (Points3.Count >= 3)
				{
					list4.Add(list[k]);
				}
			}
		}
		for (int m = 0; m <= list4.Count - 1; m++)
		{
			buEntitiesGroup buEntitiesGroup3 = new buEntitiesGroup();
