	public bool GetClosestIntersectPointsFromEntities(List<Entity> EntityList, Entity entityIntersect, Point3D refPoint, double Angle, ref List<Point3D> pntIntersect, ref PointAndAngleRange pntRange, ref int EntityIndex, ref List<PointAndIndex> touchDomainPoints)
	{
		try
		{
			List<PointAndIndex> list = new List<PointAndIndex>();
			for (int i = 0; i <= EntityList.Count - 1; i++)
			{
				Point3D[] array = ((ICurve)entityIntersect).IntersectWith((ICurve)EntityList[i]);
				if (array != null && array.Length != 0)
				{
					for (int j = 0; j <= array.Length - 1; j++)
					{
						PointAndIndex item = new PointAndIndex(array[j], i);
						list.Add(item);
					}
				}
			}
			if (list.Count <= 0)
			{
				return false;
			}
			list = SortByDistance(list, new PointAndIndex(refPoint, -1));
			int num = 1;
			double num2 = Point3D.Distance(list[0].refPoint, refPoint);
			if (num2 > 0.1)
			{
				num = 0;
			}
			if (!((num >= 0) & (list.Count > 0)))
			{
				return false;
			}
			int index = list[num].Index;
			double t = 0.0;
			double num3 = Angle + 180.0;
			if (num3 >= 360.0)
			{
				num3 -= 360.0;
			}
			((ICurve)EntityList[index]).ClosestPointTo(list[num].refPoint, out t);
			bool flag = true;
			for (int k = 0; k <= touchDomainPoints.Count - 1; k++)
			{
				double num4 = Math.Abs(touchDomainPoints[k].DomainValue - t);
				if (list[num].Index == touchDomainPoints[k].Index && num4 < 5.0)
				{
					flag = false;
				}
			}
			if (!(((t - ((ICurve)EntityList[index]).Domain.t0 > 0.2) & (((ICurve)EntityList[index]).Domain.t1 - t > 0.2)) && flag))
			{
				return false;
			}
			Point3D tipPoint = ((ICurve)EntityList[index]).PointAt(t - 0.2);
			Point3D tipPoint2 = ((ICurve)EntityList[index]).PointAt(t + 0.2);
			double num5 = PointAngle(tipPoint, list[num].refPoint, Plane.XY);
			double num6 = PointAngle(tipPoint2, list[num].refPoint, Plane.XY);
			double num7 = 0.0;
			num7 = ((num5 > num6) ? (num5 - num6) : (num6 - num5));
			if (buCompare5.EQ(num7, 180.0, 0.1))
			{
				if (num5 > num6)
				{
					double num8 = num5;
					num5 = num6;
					num6 = num8;
				}
				if (num3 < num5 || num3 > num6)
				{
					double num9 = num5;
					num5 = num6;
					num6 = num9 + 360.0;
					if (num5 > 360.0 && num6 > 360.0)
					{
						num5 -= 360.0;
						num6 -= 360.0;
					}
				}
				pntRange = new PointAndAngleRange();
				if (!(num5 < num6))
				{
					pntRange.AngleMin = num6;
					pntRange.AngleMax = num5;
				}
				else
				{
					pntRange.AngleMin = num5;
					pntRange.AngleMax = num6;
				}
				if (!buCompare5.EQ(pntRange.AngleMax, 0.0, 0.1))
				{
				}
				pntRange.refPoint = ToPoint3D(list[num].refPoint);
				touchDomainPoints.Add(new PointAndIndex(list[num].refPoint, list[num].Index, t));
				EntityIndex = index;
			}
			return true;
		}
		catch (Exception)
		{
			return false;
		}
	}

	public void FindInsideAndOutsidePointsFromPoints(List<List<Point3D>> refPoints, ref List<ContourPoints5> PointsGroups, Plane refPlane)
	{
		List<List<Point3D>> copiedPoint = new List<List<Point3D>>();
		new List<List<Point3D>>();
		List<List<Point3D>> list = new List<List<Point3D>>();
		PointsGroups = new List<ContourPoints5>();
		Copy(refPoints, ref copiedPoint);
		for (int i = 0; i <= copiedPoint.Count - 1; i++)
		{
			bool flag = false;
			Point3D MinPoint = new Point3D();
			Point3D MaxPoint = new Point3D();
			BoxSizeCalculate(copiedPoint[i], ref MinPoint, ref MaxPoint);
			for (int j = 0; j <= copiedPoint.Count - 1; j++)
			{
				Point3D MinPoint2 = new Point3D();
				Point3D MaxPoint2 = new Point3D();
				BoxSizeCalculate(copiedPoint[j], ref MinPoint2, ref MaxPoint2);
				if (i != j)
				{
					bool flag2 = isBoxSizeInsideBoxSize(MinPoint2, MaxPoint2, MinPoint, MaxPoint, refPlane);
					flag = flag || flag2;
				}
			}
			if (!flag)
			{
				ContourPoints5 contourPoints = new ContourPoints5();
				Copy(copiedPoint[i], ref contourPoints.Outter);
				PointsGroups.Add(contourPoints);
			}
			else
			{
				List<Point3D> copiedPoint2 = new List<Point3D>();
				Copy(copiedPoint[i], ref copiedPoint2);
				list.Add(copiedPoint2);
			}
		}
		for (int k = 0; k <= PointsGroups.Count - 1; k++)
		{
			Point3D MinPoint3 = new Point3D();
			Point3D MaxPoint3 = new Point3D();
			BoxSizeCalculate(PointsGroups[k].Outter, ref MinPoint3, ref MaxPoint3);
			for (int l = 0; l <= list.Count - 1; l++)
			{
				Point3D MinPoint4 = new Point3D();
				Point3D MaxPoint4 = new Point3D();
				BoxSizeCalculate(list[l], ref MinPoint4, ref MaxPoint4);
				if (isBoxSizeInsideBoxSize(MinPoint3, MaxPoint3, MinPoint4, MaxPoint4, refPlane))
				{
					List<Point3D> copiedPoint3 = new List<Point3D>();
					Copy(list[l], ref copiedPoint3);
					PointsGroups[k].Inside.Add(copiedPoint3);
				}
			}
		}
	}

