	public void FindInternalEntitiesFromContourEntities(List<Entity> ContourEntities, List<Entity> AllEntities, FindInternalEntitiesFromContourSettings Settings, Plane refPlane, ref List<List<Entity>> InnerEntities, ref List<List<Entity>> AuxEntities, ref List<Entity> TextEntities)
	{
		Point3D MinPoint = new Point3D();
		Point3D MidPoint = new Point3D();
		Point3D MaxPoint = new Point3D();
		List<Entity> BaseRefEntities = new List<Entity>();
		List<Entity> BaseRefEntities2 = new List<Entity>();
		BoxSizeCalculate(ContourEntities, ref MinPoint, ref MidPoint, ref MaxPoint);
		for (int i = 0; i <= AllEntities.Count - 1; i++)
		{
			bool flag = false;
			bool flag2 = true;
			if (Settings.UseEntityInfoData & (Settings.refEntityInfoData != ((CustomData)AllEntities[i].EntityData).infoData))
			{
				flag2 = false;
			}
			if (AllEntities[i] is Text)
			{
				flag2 = true;
			}
			Point3D MinPoint2 = new Point3D(double.MaxValue, double.MaxValue, double.MaxValue);
			Point3D MidPoint2 = new Point3D();
			Point3D MaxPoint2 = new Point3D(double.MinValue, double.MinValue, double.MinValue);
			BoxSizeCalculate(AllEntities[i], ref MinPoint2, ref MidPoint2, ref MaxPoint2);
			if (!(Settings.CurveCheckBoxsizeCover && flag2))
			{
				continue;
			}
			bool flag3 = IsPointInsideBoxsize(MinPoint2, MinPoint, MaxPoint, refPlane);
			bool flag4 = IsPointInsideBoxsize(MaxPoint2, MinPoint, MaxPoint, refPlane);
			if (flag3 && flag4)
			{
				if ((AllEntities[i] is ICurve) & (AllEntities[i].LayerName != ContourEntities[0].LayerName))
				{
					if (!(AllEntities[i].GetType() == typeof(devDept.Eyeshot.Entities.Point)))
					{
						if (Settings.InnerEntitiesLayerName.Count <= 0)
						{
							BaseRefEntities.Add(CopyEntities(AllEntities[i]));
						}
						else
						{
							bool flag5 = false;
							for (int j = 0; j <= Settings.InnerEntitiesLayerName.Count - 1; j++)
							{
								if (AllEntities[i].LayerName == Settings.InnerEntitiesLayerName[j])
								{
									flag5 = true;
								}
							}
							if (!flag5)
							{
								BaseRefEntities2.Add(CopyEntities(AllEntities[i]));
							}
							else
							{
								BaseRefEntities.Add(CopyEntities(AllEntities[i]));
							}
						}
						flag = true;
					}
					else if (Settings.AddPoint)
					{
						if (Settings.InnerEntitiesLayerName.Count <= 0)
						{
							BaseRefEntities.Add(CopyEntities(AllEntities[i]));
						}
						else
						{
							bool flag6 = false;
							for (int k = 0; k <= Settings.InnerEntitiesLayerName.Count - 1; k++)
							{
								if (AllEntities[i].LayerName == Settings.InnerEntitiesLayerName[k])
								{
									flag6 = true;
								}
							}
							if (!flag6)
							{
								BaseRefEntities2.Add(CopyEntities(AllEntities[i]));
							}
							else
							{
								BaseRefEntities.Add(CopyEntities(AllEntities[i]));
							}
						}
						flag = true;
					}
				}
				if ((AllEntities[i] is Text) & (Settings.GetTextStrings & Settings.TextCheckBoxsizeCover))
				{
					TextEntities.Add(CopyEntities(AllEntities[i]));
					flag = true;
				}
			}
			if (!flag && ((AllEntities[i] is Text) & (Settings.GetTextStrings & Settings.TextForInsertionPoint)) && IsPointInsideBoxsize(((Text)AllEntities[i]).InsertionPoint, MinPoint, MaxPoint, refPlane))
			{
				TextEntities.Add(CopyEntities(AllEntities[i]));
				flag = true;
			}
			if (flag)
			{
				continue;
			}
			for (int l = 0; l <= ContourEntities.Count - 1; l++)
			{
				Point3D[] array = null;
				if ((AllEntities[i] is ICurve) & Settings.CurveCheckIntersections)
				{
					array = ((ICurve)AllEntities[i]).IntersectWith((ICurve)ContourEntities[l]);
				}
				if (array == null || array.Length == 0)
				{
					continue;
				}
				if ((AllEntities[i] is ICurve) & (AllEntities[i].LayerName != ContourEntities[0].LayerName))
				{
					if (!(AllEntities[i].GetType() == typeof(devDept.Eyeshot.Entities.Point)))
