	public void FindInternalEntitiesFromOutterReferance(List<Entity> ContourEntities, List<Entity> AllEntities, FindInternalEntitiesFromContourSettings Settings, Plane refPlane, ref List<List<Entity>> InnerEntities, ref List<List<Entity>> AuxEntities, ref List<Entity> TextEntities)
	{
		List<Entity> BaseRefEntities = new List<Entity>();
		List<Entity> BaseRefEntities2 = new List<Entity>();
		Point3D MinPoint = new Point3D();
		Point3D MaxPoint = new Point3D();
		if (ContourEntities.Count <= 0)
		{
			return;
		}
