		if (BaseRefEntities.Count > 0)
		{
			List<Entity> SortedEntities = new List<Entity>();
			SortSettings sortSettings = new SortSettings();
			SortResult Result = new SortResult();
			sortSettings.Option.NextGroupRules = SortingNextGroupFindRulesType.ClosestLength;
			sortSettings.Option.IntersectionRules = SortingIntersectionRulesType.FromDrawing;
			SortEntitiesByRefPoint(((ICurve)BaseRefEntities[0]).StartPoint, ref BaseRefEntities, sortSettings, ref SortedEntities, ref Result);
			InnerEntities.Clear();
			EntitiesSplitByUpperLine(SortedEntities, ref InnerEntities);
		}
		if (BaseRefEntities2.Count > 0)
		{
			List<Entity> SortedEntities2 = new List<Entity>();
			SortSettings sortSettings2 = new SortSettings();
			SortResult Result2 = new SortResult();
			sortSettings2.Option.NextGroupRules = SortingNextGroupFindRulesType.ClosestLength;
			sortSettings2.Option.IntersectionRules = SortingIntersectionRulesType.FromDrawing;
			SortEntitiesByRefPoint(((ICurve)BaseRefEntities2[0]).StartPoint, ref BaseRefEntities2, sortSettings2, ref SortedEntities2, ref Result2);
			AuxEntities.Clear();
			EntitiesSplitByUpperLine(SortedEntities2, ref AuxEntities);
		}
