	public void SelectionFromEntity(List<Entity> EntList, BlockKeyedCollection Blocks, Point3D refPoint, int Index, entitySortDirection Direction, ref SelectionEntity S)
	{
		S = new SelectionEntity(Index);
		S.SelectedEntity = EntList[Index];
		DrawCurveOrBlockRef(S.SelectedEntity, Blocks, ref S.SelectedVertices);
		SetSortDirection(Direction, ref S.SelectedEntity);
		if (S.SelectedEntity is CompositeCurve)
		{
			double num = double.MaxValue;
			for (int i = 0; i <= ((CompositeCurve)S.SelectedEntity).CurveList.Count - 1; i++)
			{
				ICurve curve = ((CompositeCurve)S.SelectedEntity).CurveList[i];
				double t = 0.0;
				curve.ClosestPointTo(refPoint, out t);
				Point3D a = curve.PointAt(t);
				double num2 = Point3D.Distance(a, refPoint);
				if (((t > 0.0) & (t > curve.Domain.Min) & (t < curve.Domain.Max)) && num2 < num)
				{
					num = num2;
					Entity refEntity = (Entity)((Entity)curve).Clone();
					buEntity.Copy(refEntity, ref S.SelectedSubEntity);
				}
			}
		}
		S.SelectedLinearPaths = new List<Entity>();
		for (int j = 0; j <= S.SelectedVertices.Count - 1; j++)
		{
			LinearPath item = new LinearPath(S.SelectedVertices[j]);
			S.SelectedLinearPaths.Add(item);
		}
		if (S.SelectedEntity.BoxMin == null)
		{
			S.SelectedEntity.Regen(0.01);
		}
		S.pntClick = ToPoint3D(refPoint);
		S.BoxMin = ToPoint3D(S.SelectedEntity.BoxMin);
		S.BoxMax = ToPoint3D(S.SelectedEntity.BoxMax);
		S.EntitiesBoxPointList.Add(S.BoxMin);
		S.EntitiesBoxPointList.Add(S.BoxMax);
		SelectionAlingPoints(ref S);
	}

	public void SelectionAlingPoints(ref SelectionEntity SelEntity)
	{
		if (!(SelEntity.SelectedEntity.GetType() == typeof(Circle)))
		{
			if (!(SelEntity.SelectedEntity.GetType() == typeof(Arc)))
			{
				if (!(SelEntity.SelectedEntity.GetType() == typeof(Ellipse)))
				{
					if (!(SelEntity.SelectedEntity.GetType() == typeof(EllipticalArc)))
					{
						if (!(SelEntity.SelectedEntity.GetType() == typeof(Line)))
						{
							if (!(SelEntity.SelectedEntity.GetType() == typeof(Curve)))
							{
								if (!(SelEntity.SelectedEntity.GetType() == typeof(LinearPath)))
								{
									if (!(SelEntity.SelectedEntity.GetType() == typeof(CompositeCurve)))
									{
										if (!(SelEntity.SelectedEntity.GetType() == typeof(ICurve)))
										{
											if (!(SelEntity.SelectedEntity.GetType() == typeof(Text)))
											{
												if (SelEntity.SelectedEntity.BoxMax == null)
												{
													SelEntity.SelectedEntity.Regen(0.01);
												}
												SelEntity.AlingPoints.MovePoints.Add(ToPoint3D(Point3D.MidPoint(SelEntity.SelectedEntity.BoxMax, SelEntity.SelectedEntity.BoxMin)));
											}
											else
											{
												if (SelEntity.SelectedEntity.BoxMax == null)
												{
													SelEntity.SelectedEntity.Regen(new RegenParams(0.01));
												}
												SelEntity.AlingPoints.MovePoints.Add(ToPoint3D(Point3D.MidPoint(SelEntity.SelectedEntity.BoxMax, SelEntity.SelectedEntity.BoxMin)));
											}
										}
										else
										{
											SelEntity.AlingPoints.TipPoints.Add(ToPoint3D(((ICurve)SelEntity.SelectedEntity).StartPoint));
											SelEntity.AlingPoints.TipPoints.Add(ToPoint3D(((ICurve)SelEntity.SelectedEntity).EndPoint));
											if (SelEntity.SelectedEntity.BoxMax == null)
											{
												SelEntity.SelectedEntity.Regen(0.01);
											}
											SelEntity.AlingPoints.MovePoints.Add(ToPoint3D(Point3D.MidPoint(SelEntity.SelectedEntity.BoxMax, SelEntity.SelectedEntity.BoxMin)));
										}
									}
									else
									{
										for (int i = 0; i <= ((CompositeCurve)SelEntity.SelectedEntity).CurveList.Count - 1; i++)
										{
											SelEntity.AlingPoints.TipPoints.Add(ToPoint3D(SelEntity.SelectedEntity.Vertices[i]));
										}
										if (SelEntity.SelectedEntity.BoxMax == null)
										{
											SelEntity.SelectedEntity.Regen(0.01);
										}
										SelEntity.AlingPoints.MovePoints.Add(ToPoint3D(Point3D.MidPoint(SelEntity.SelectedEntity.BoxMax, SelEntity.SelectedEntity.BoxMin)));
									}
								}
								else
								{
									for (int j = 0; j <= SelEntity.SelectedEntity.Vertices.Length - 1; j++)
									{
										SelEntity.AlingPoints.TipPoints.Add(ToPoint3D(SelEntity.SelectedEntity.Vertices[j]));
									}
									if (SelEntity.SelectedEntity.BoxMax == null)
									{
										SelEntity.SelectedEntity.Regen(0.01);
									}
									SelEntity.AlingPoints.MovePoints.Add(ToPoint3D(Point3D.MidPoint(SelEntity.SelectedEntity.BoxMax, SelEntity.SelectedEntity.BoxMin)));
								}
							}
							else
							{
								Curve curve = SelEntity.SelectedEntity as Curve;
								for (int k = 0; k <= curve.ControlPoints.Length - 1; k++)
								{
									SelEntity.AlingPoints.TipPoints.Add(ToPoint3D(curve.ControlPoints[k]));
								}
								if (SelEntity.SelectedEntity.BoxMax == null)
								{
									SelEntity.SelectedEntity.Regen(0.01);
								}
								SelEntity.AlingPoints.MovePoints.Add(ToPoint3D(Point3D.MidPoint(SelEntity.SelectedEntity.BoxMax, SelEntity.SelectedEntity.BoxMin)));
							}
						}
						else
						{
							SelEntity.AlingPoints.TipPoints.Add(ToPoint3D(((Line)SelEntity.SelectedEntity).StartPoint));
							SelEntity.AlingPoints.TipPoints.Add(ToPoint3D(((Line)SelEntity.SelectedEntity).EndPoint));
							SelEntity.AlingPoints.MovePoints.Add(ToPoint3D(((Line)SelEntity.SelectedEntity).MidPoint));
						}
					}
					else
					{
						SelEntity.AlingPoints.TipPoints.Add(ToPoint3D(((EllipticalArc)SelEntity.SelectedEntity).StartPoint));
						SelEntity.AlingPoints.TipPoints.Add(ToPoint3D(((EllipticalArc)SelEntity.SelectedEntity).EndPoint));
						SelEntity.AlingPoints.MovePoints.Add(ToPoint3D(((EllipticalArc)SelEntity.SelectedEntity).Center));
					}
				}
				else
				{
					SelEntity.AlingPoints.TipPoints.Add(ToPoint3D(((Ellipse)SelEntity.SelectedEntity).StartPoint));
					SelEntity.AlingPoints.MovePoints.Add(ToPoint3D(((Ellipse)SelEntity.SelectedEntity).Center));
				}
			}
			else
			{
				SelEntity.AlingPoints.TipPoints.Add(ToPoint3D(((Arc)SelEntity.SelectedEntity).StartPoint));
				SelEntity.AlingPoints.TipPoints.Add(ToPoint3D(((Arc)SelEntity.SelectedEntity).EndPoint));
				SelEntity.AlingPoints.MovePoints.Add(ToPoint3D(((Arc)SelEntity.SelectedEntity).Center));
			}
		}
		else
		{
			SelEntity.AlingPoints.TipPoints.Add(ToPoint3D(((Circle)SelEntity.SelectedEntity).StartPoint));
			SelEntity.AlingPoints.MovePoints.Add(ToPoint3D(((Circle)SelEntity.SelectedEntity).Center));
		}
	}

	public void SelectedEntitiesToEntityList(EntityList Entities, bool Clone, ref List<Entity> selectedEntities)
	{
		selectedEntities.Clear();
		for (int i = 0; i <= Entities.Count - 1; i++)
		{
			if (Entities[i].Selected)
			{
				if (!Clone)
				{
					selectedEntities.Add(Entities[i]);
				}
				else
				{
					selectedEntities.Add((Entity)Entities[i].Clone());
				}
			}
		}
	}

	public void SelectedEntitiesToEntityList(EntityList Entities, ref List<buEntity> selectedEntities)
	{
		selectedEntities.Clear();
		for (int i = 0; i <= Entities.Count - 1; i++)
		{
			if (Entities[i].Selected)
			{
				buEntity copiedEntity = null;
				buEntity.Copy(Entities[i], ref copiedEntity);
				if (copiedEntity != null)
				{
					selectedEntities.Add(copiedEntity);
				}
			}
		}
	}

	public void SelectClosedArea(Point3D refPoint, List<Entity> refEntities)
	{
		try
		{
			List<Entity> list = new List<Entity>();
			bool flag = false;
			List<PointAndAngleRange> list2 = new List<PointAndAngleRange>();
			List<int> List = new List<int>();
			List<PointAndIndex> touchDomainPoints = new List<PointAndIndex>();
			for (double num = 0.0; num <= 360.0; num += 20.0)
			{
				Point3D EndPnt = new Point3D();
				LineWithLengthAndAngle(refPoint, 10000.0, num, ref EndPnt);
				Line entityIntersect = new Line(refPoint, EndPnt);
				List<Point3D> pntIntersect = new List<Point3D>();
				new List<int>();
				PointAndAngleRange pntRange = new PointAndAngleRange();
				int EntityIndex = -1;
				if (GetClosestIntersectPointsFromEntities(refEntities, entityIntersect, refPoint, num, ref pntIntersect, ref pntRange, ref EntityIndex, ref touchDomainPoints) & (pntRange.AngleMin != pntRange.AngleMax))
				{
					if (EntityIndex >= 0)
					{
						buNumeric5.AddValueToList(EntityIndex, ref List);
					}
					list2.Add(pntRange);
					Line item = new Line(refPoint, pntRange.refPoint);
					list.Add(item);
				}
			}
			List<int> list3 = new List<int>();
			if (List.Count > 0)
			{
				List<Entity> BaseRefEntities = new List<Entity>();
				for (int i = 0; i <= List.Count - 1; i++)
				{
					Entity copiedEntity = null;
					buEntity.Copy(refEntities[List[i]], ref copiedEntity);
					if (copiedEntity.Vertices == null)
					{
						RegenEntity(buSystem.RegenDeviation, ref copiedEntity);
					}
					BaseRefEntities.Add(copiedEntity);
				}
				SortSettings sortSettings = new SortSettings();
				SortResult Result = new SortResult();
				List<Entity> SortedEntities = new List<Entity>();
				sortSettings.Option.NextGroupRules = SortingNextGroupFindRulesType.NoNextGroup;
				sortSettings.Option.IntersectionRules = SortingIntersectionRulesType.LowerIndex;
				SortEntitiesByRefPoint(BaseRefEntities[0].Vertices[0], ref BaseRefEntities, sortSettings, ref SortedEntities, ref Result);
				if (isEntitiesClosed(SortedEntities))
				{
					for (int j = 0; j <= List.Count - 1; j++)
					{
						list3.Add(List[j]);
					}
					flag = true;
				}
			}
			if (flag)
			{
				return;
			}
			for (int k = 1; k <= 20; k++)
			{
				List<PointAndAngleRange> list4 = new List<PointAndAngleRange>();
				for (int l = 0; l <= list2.Count - 1; l++)
				{
					double num2 = (list2[l].AngleMax - 5.0 - (list2[l].AngleMin + 5.0)) / 10.0;
					for (double num3 = list2[l].AngleMin + 5.0; num3 <= list2[l].AngleMax - 5.0; num3 += num2)
					{
						Point3D EndPnt2 = new Point3D();
						LineWithLengthAndAngle(list2[l].refPoint, 100000.0, num3, ref EndPnt2);
						Line entityIntersect2 = new Line(list2[l].refPoint, EndPnt2);
						List<Point3D> pntIntersect2 = new List<Point3D>();
						new List<int>();
						PointAndAngleRange pntRange2 = new PointAndAngleRange();
						int EntityIndex2 = -1;
						if (GetClosestIntersectPointsFromEntities(refEntities, entityIntersect2, list2[l].refPoint, num3, ref pntIntersect2, ref pntRange2, ref EntityIndex2, ref touchDomainPoints) & (pntRange2.AngleMax != pntRange2.AngleMin))
						{
							if (EntityIndex2 >= 0)
							{
								buNumeric5.AddValueToList(EntityIndex2, ref List);
							}
							Line item2 = new Line(list2[l].refPoint, pntRange2.refPoint);
							list.Add(item2);
							list4.Add(pntRange2);
						}
					}
				}
				list2.Clear();
				list2 = new List<PointAndAngleRange>();
