	public bool isSelectedIndexAvailableInSelectionList(List<List<int>> baseSelection, List<int> refSelection)
	{
		for (int i = 0; i <= refSelection.Count - 1; i++)
		{
			for (int j = 0; j <= baseSelection.Count - 1; j++)
			{
				for (int k = 0; k <= baseSelection[j].Count - 1; k++)
				{
					if (refSelection[i] == baseSelection[j][k])
					{
						return true;
					}
				}
			}
		}
		return false;
	}

	public bool isSelectedIndexInsideSelectionList(SelectionOperation SelectedList, int Index)
	{
		if (Index >= 0)
		{
			for (int i = 0; i <= SelectedList.Selections.Count - 1; i++)
			{
				if (SelectedList.Selections[i].Index == Index)
				{
					return true;
				}
			}
		}
		return false;
	}

