	public void ArcToLineer(Pnt3D Center, double Radius, double SA, double EA, double Length, WorkPlane Plane, ref List<Pnt3D> Vertices)
	{
		try
		{
			double num = 0.0;
			double num2 = 0.0;
			double num3 = 0.0;
			int num4 = 0;
			Pnt3D pnt3D = new Pnt3D();
			if (!buCompare5.EQ(SA, EA))
			{
				num = EA - SA;
				num3 = Math.PI * 2.0 * Radius * (EA - SA) / 360.0;
				num4 = (int)(num3 / Length);
				if (num4 > 0)
				{
					if (num4 > 0)
					{
						num2 = num / (double)num4;
					}
					Vertices.Clear();
					for (int i = 0; i <= num4; i++)
					{
						pnt3D = new Pnt3D();
						if (WorkPlane.isPlaneXY(Plane))
						{
							pnt3D.X = Center.X + Radius * Math.Cos(buConversion5.DegreeToRadian(SA + (double)i * num2));
							pnt3D.Y = Center.Y + Radius * Math.Sin(buConversion5.DegreeToRadian(SA + (double)i * num2));
							pnt3D.Z = Center.Z;
						}
						if (WorkPlane.isPlaneXZ(Plane))
						{
							pnt3D.X = Center.X + Radius * Math.Cos(buConversion5.DegreeToRadian(SA + (double)i * num2));
							pnt3D.Y = Center.Y;
							pnt3D.Z = Center.Z + Radius * Math.Sin(buConversion5.DegreeToRadian(SA + (double)i * num2));
						}
						if (WorkPlane.isPlaneYZ(Plane))
						{
							pnt3D.X = Center.X;
							pnt3D.Y = Center.Y + Radius * Math.Cos(buConversion5.DegreeToRadian(SA + (double)i * num2));
							pnt3D.Z = Center.Z + Radius * Math.Sin(buConversion5.DegreeToRadian(SA + (double)i * num2));
						}
						Vertices.Add(pnt3D);
					}
				}
				else
				{
					Vertices.Clear();
				}
			}
			else
			{
				Vertices.Clear();
			}
		}
		catch (Exception mSException)
		{
			string text = "Center:" + Center.ToString() + "R: " + Radius + " - SA: " + SA + " - EA: " + EA + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

