	{
		Entity calcEntity2 = null;
		Entity textEntity2 = null;
		CreateCamHeightPlane(Height, refPlane, pntMin, pntMax, color, Transparent, TextString, HeightType, ref calcEntity2, ref textEntity2);
		buEntity.Copy(calcEntity2, ref calcEntity);
		buEntity.Copy(textEntity2, ref textEntity);
