	public void CreateCamHeightPlane(double Height, planeBoxNames refPlane, Point3D pntMin, Point3D pntMax, Color color, int Transparent, string TextString, CamPlaneHeightType HeightType, ref Entity calcEntity, ref Entity textEntity)
	{
		if ((refPlane == planeBoxNames.Top || refPlane == planeBoxNames.Bottom) && (!buCompare5.EQ(pntMax.X, pntMin.X) & !buCompare5.EQ(pntMax.Y, pntMin.Y)))
		{
			CompositeCurve compositeCurve = CompositeCurve.CreateRectangle(Plane.XY, pntMax.X - pntMin.X, pntMax.Y - pntMin.Y);
			compositeCurve.Translate(pntMin.X, pntMin.Y);
			devDept.Eyeshot.Entities.Region region = new devDept.Eyeshot.Entities.Region(compositeCurve);
			Mesh mesh = region.ExtrudeAsMesh(0.01, 0.01, Mesh.natureType.RichSmooth);
			mesh.Color = Color.FromArgb(Transparent, color);
			mesh.ColorMethod = colorMethodType.byEntity;
			mesh.Translate(0.0, 0.0, Height);
			calcEntity = mesh;
			double num = (pntMax.Y - pntMin.Y) / 20.0;
			if (num < 1.0)
			{
				num = 1.0;
			}
			Text text = null;
			if (HeightType == CamPlaneHeightType.Bottom)
			{
				text = new Text(Plane.XY, TextString, num, Text.alignmentType.BottomLeft);
				text.Translate(pntMin.X, pntMin.Y, Height);
			}
			if (HeightType == CamPlaneHeightType.Top)
			{
				text = new Text(Plane.XY, TextString, num, Text.alignmentType.BottomCenter);
				text.Translate((pntMin.X + pntMax.X) / 2.0, pntMin.Y, Height);
			}
			if (HeightType == CamPlaneHeightType.Retract)
			{
				text = new Text(Plane.XY, TextString, num, Text.alignmentType.BottomRight);
				text.Translate(pntMax.X, pntMin.Y, Height);
			}
			if (HeightType == CamPlaneHeightType.Clearance)
			{
				text = new Text(Plane.XY, TextString, num, Text.alignmentType.BottomCenter);
				text.Translate((pntMin.X + pntMax.X) / 2.0, pntMin.Y, Height);
			}
			text.Color = Color.FromArgb(Transparent, color);
			text.ColorMethod = colorMethodType.byEntity;
			textEntity = text;
		}
		if (refPlane == planeBoxNames.Left || refPlane == planeBoxNames.Right)
		{
			buString5.MessageBoxInfo("Not Ready");
		}
		if (refPlane == planeBoxNames.Front || refPlane == planeBoxNames.Bottom)
		{
			buString5.MessageBoxInfo("Not Ready");
		}
	}

	public void CamStepHeightCalculation(camStep5 Step, ref List<double> Heights)
	{
		Heights.Clear();
		if (Step.DepthStepMode != CamStepDepthMode.ConstantDepthStep)
		{
			if (Step.DepthStepMode == CamStepDepthMode.NumberOfSlices)
			{
				double num = Step.StartValue - Step.EndValue;
				double num2 = num / (double)Step.NumberOfSlice;
				double num3 = Step.StartValue;
				for (int i = 1; i <= Step.NumberOfSlice; i++)
				{
					num3 -= num2;
					Heights.Add(num3);
				}
			}
		}
		else
		{
			double num4 = Step.StartValue - Step.EndValue;
			int num5 = (int)Math.Ceiling(num4 / Step.DepthStep);
			double num6 = num4 / (double)num5;
			double num7 = Step.StartValue;
			for (int j = 1; j <= num5; j++)
			{
				num7 -= num6;
				Heights.Add(num7);
			}
		}
	}

	public void CamTangentCalculation(ref double RefAngle, double PreviousAngle, camParameters5 camPars)
	{
		double num = RefAngle - PreviousAngle;
		double num2 = Math.Round(Math.Abs(num) / 360.0, 0);
		if (!(Math.Abs(num) >= 715.0))
		{
		}
		if (num2 <= 0.0)
		{
			num2 = 1.0;
		}
		if (!((Math.Abs(num) > 170.0) & (Math.Abs(num) < 210.0)))
		{
			if (Math.Abs(num) >= 210.0)
			{
				if (!(num > 0.0))
				{
					RefAngle += 360.0 * num2;
				}
				else
				{
					RefAngle -= 360.0 * num2;
				}
			}
		}
		else if (!(num > 0.0))
		{
		}
		if (camPars.Strategy.MinTangentValue == camPars.Strategy.MaxTangentValue)
		{
			return;
		}
		if (RefAngle > camPars.Strategy.MaxTangentValue)
		{
			double num3 = camPars.Strategy.MaxTangentValue - camPars.Strategy.MinTangentValue;
			if (!(num3 >= 360.0))
			{
				RefAngle -= camPars.Strategy.MaxTangentValue - camPars.Strategy.MinTangentValue;
			}
			else
			{
				RefAngle -= 360.0;
			}
		}
		if (RefAngle < camPars.Strategy.MinTangentValue)
		{
			double num4 = camPars.Strategy.MaxTangentValue - camPars.Strategy.MinTangentValue;
			if (!(num4 >= 360.0))
			{
				RefAngle += camPars.Strategy.MaxTangentValue - camPars.Strategy.MinTangentValue;
			}
			else
			{
				RefAngle += 360.0;
			}
		}
	}

	public void CamAddtoOtherCam(camTp AddingCam, ref camTp AddedCam)
	{
		if (AddingCam.CamPoints.Count > 0)
		{
