		CopyCamEntities(AddingCam.EntitiesG0, ref AddedCam.EntitiesG0);
		CopiedEntity = new List<Entity>();
		CopyCamEntities(AddingCam.EntitiesLeadIn, ref AddedCam.EntitiesLeadIn);
		CopyCamEntities(AddingCam.EntitiesLeadOut, ref AddedCam.EntitiesLeadOut);
		CopyCamEntities(AddingCam.EntitiesLeave, ref AddedCam.EntitiesLeave);
		CopyCamEntities(AddingCam.EntitiesMark, ref AddedCam.EntitiesMark);
		CopyCamEntities(AddingCam.EntitiesOther, ref AddedCam.EntitiesOther);
		CopyCamEntities(AddingCam.EntitiesPlunge, ref AddedCam.EntitiesPlunge);
		CopyCamEntities(AddingCam.EntitiesG1, ref AddedCam.EntitiesG1);
