	public void CopyCamEntities(Entity refEntity, ref Entity CopiedEntity)
	{
		try
		{
			if (!(refEntity.GetType() == typeof(buLinearPathCam)))
			{
				if (!(refEntity.GetType() == typeof(buCompositeCurveCam)))
				{
					if (!(refEntity.GetType() == typeof(buArcCam)))
					{
						if (!(refEntity.GetType() == typeof(buLineCam)))
						{
							if (!(refEntity.GetType() == typeof(buUpperLineEnt)))
							{
								CopyEntities(refEntity, ref CopiedEntity);
							}
							else
							{
								CopiedEntity = new buUpperLineEnt((buUpperLineEnt)refEntity);
							}
						}
						else
						{
							CopiedEntity = new buLineCam((buLineCam)refEntity);
						}
					}
					else
					{
						CopiedEntity = new buArcCam((buArcCam)refEntity);
					}
				}
				else
				{
					CopiedEntity = new buCompositeCurveCam((buCompositeCurveCam)refEntity);
				}
			}
			else
			{
				CopiedEntity = new buLinearPathCam((buLinearPathCam)refEntity);
			}
		}
		catch (Exception mSException)
		{
			string text = "";
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

