	public int FontToVectorConvert(Point3D Location, Font fFont, string ConvertString, Plane refPlane, Point3D PlaneOffset, ref List<PointsList> CalculatedPoints)
	{
		Graphics fx = null;
		new List<PointsList>();
		int result = FontToVectorConvert(fx, fFont, ConvertString, ref CalculatedPoints);
		for (int i = 0; i <= CalculatedPoints.Count - 1; i++)
		{
			for (int j = 0; j <= CalculatedPoints[i].Points.Count - 1; j++)
			{
				for (int k = 0; k <= CalculatedPoints[i].Points[j].Count - 1; k++)
				{
					Point3D point3D = ToPoint3D(CalculatedPoints[i].Points[j][k]);
					if (isPlaneXYorYX(refPlane))
					{
						point3D.Z = PlaneOffset.Z;
					}
					if (isPlaneXZorZX(refPlane))
					{
						point3D.Z = point3D.Y;
						point3D.Y = PlaneOffset.Y;
					}
					if (isPlaneYZorZY(refPlane))
					{
						double y = point3D.Y;
						point3D.Y = point3D.X;
						point3D.Z = y;
						point3D.X = PlaneOffset.X;
					}
					CalculatedPoints[i].Points[j][k] = point3D;
				}
			}
		}
		return result;
	}

	public int FontToVectorConvert(Graphics fx, Font fFont, string ConvertString, ref List<PointsList> CalculatedPoints)
	{
		try
		{
			PointF[] array = null;
			byte[] array2 = null;
			bool flag = true;
			if (fx == null)
			{
				flag = false;
			}
			using (GraphicsPath graphicsPath = new GraphicsPath())
			{
				graphicsPath.AddString(ConvertString, fFont.FontFamily, (int)fFont.Style, fFont.Size, new PointF(0f, 0f), StringFormat.GenericDefault);
				graphicsPath.Flatten();
				if (graphicsPath.PointCount == 0)
				{
					return -1;
				}
				array = graphicsPath.PathPoints;
				array2 = graphicsPath.PathTypes;
			}
			List<Polygon> list = new List<Polygon>();
			List<PolygonPoint> list2 = null;
			Pen pen = Pens.Yellow;
			int num = 0;
			int num2 = -1;
			for (int i = 0; i < array.Length; i++)
			{
				switch (array2[i] & 7)
				{
				case 1:
					if (flag)
					{
						fx.DrawLine(pen, array[i - 1], array[i]);
					}
					if ((array2[i] & 0x80) == 0)
					{
						list2.Add(new PolygonPoint(array[i].X, array[i].Y));
						break;
					}
					if (array[i] != array[num2])
					{
						list2.Add(new PolygonPoint(array[i].X, array[i].Y));
					}
					list.Add(new Polygon(list2));
					if (flag)
					{
						fx.FillRectangle(Brushes.DarkBlue, array[i].X - 1.5f, array[i].Y - 1.5f, 3f, 3f);
						fx.DrawLine(pen, array[i], array[num2]);
					}
					list2 = null;
					break;
				case 0:
					list2 = new List<PolygonPoint>
					{
						new PolygonPoint(array[i].X, array[i].Y)
					};
					num2 = i;
					pen = pen_0[num % pen_0.Length];
					num++;
					if (flag)
					{
						fx.FillRectangle(Brushes.DarkOrange, array[i].X - 1.5f, array[i].Y - 1.5f, 3f, 3f);
					}
					break;
				default:
					throw new Exception("Unsupported point type");
				}
			}
			CalculatedPoints.Clear();
			new List<Point3D>();
			List<List<Point3D>> list3 = new List<List<Point3D>>();
			foreach (Polygon item in list)
			{
				PointsList pointsList = new PointsList();
				List<Point3D> mirrorPoint = new List<Point3D>();
				new List<List<Point3D>>();
				Point3D MinPoint = new Point3D();
				Point3D MaxPoint = new Point3D();
				Point3D MinPoint2 = new Point3D();
				Point3D MidPoint = new Point3D();
				Point3D MaxPoint2 = new Point3D();
				for (int j = 0; j <= item.Points.Count - 1; j++)
				{
					mirrorPoint.Add(new Point3D(item.Points[j].X, item.Points[j].Y, 0.0));
				}
				if (mirrorPoint.Count > 2 && !buCompare5.EQ(mirrorPoint[0], mirrorPoint[mirrorPoint.Count - 1], buSystem.resolutionCompare))
				{
					mirrorPoint.Add(ToPoint3D(mirrorPoint[0]));
				}
				Mirror(new Point3D(), new Point3D(1.0, 0.0, 0.0), Plane.XY, ref mirrorPoint);
				BoxSizeCalculate(mirrorPoint, ref MinPoint, ref MaxPoint);
				if (list3.Count != 0)
				{
					BoxSizeCalculate(list3, ref MinPoint2, ref MidPoint, ref MaxPoint2);
					if (!isBoxSizeInsideBoxSize(MinPoint2, MaxPoint2, MinPoint, MaxPoint, Plane.XY))
					{
						PointsList pointsList2 = new PointsList();
						pointsList2.Points = list3;
						CalculatedPoints.Add(pointsList2);
						list3 = new List<List<Point3D>>();
						list3.Add(mirrorPoint);
					}
					else
					{
						list3.Add(mirrorPoint);
					}
				}
				else
				{
					list3.Add(mirrorPoint);
				}
				if (mirrorPoint.Count <= 0)
				{
				}
				if (pointsList.Points.Count <= 2)
				{
				}
			}
			if (list3.Count > 0)
			{
				PointsList pointsList3 = new PointsList();
				pointsList3.Points = list3;
				CalculatedPoints.Add(pointsList3);
			}
			Point3D MinPoint3 = new Point3D();
			Point3D MidPoint2 = new Point3D();
			Point3D MaxPoint3 = new Point3D();
			BoxSizeCalculate(CalculatedPoints, ref MinPoint3, ref MidPoint2, ref MaxPoint3);
			for (int k = 0; k <= CalculatedPoints.Count - 1; k++)
			{
				Move(MinPoint3, new Point3D(), ref CalculatedPoints[k].Points);
			}
			return 1;
		}
		catch (Exception mSException)
		{
			string text = "ConvertString: " + ConvertString.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return -1;
		}
	}

