	public double TimeFromVelocityDistanceAcceleration(double Vel, double Distance, double Acc, double Dec)
	{
		if (!(Vel <= 0.0 || Distance <= 0.0))
		{
			if (!(Acc <= 0.0 || Dec <= 0.0))
			{
				double num = 0.0;
				double num2 = Vel / Acc;
				double num3 = Vel / Dec;
				double num4 = 0.5 * num2 * Vel;
				double num5 = 0.5 * num3 * Vel;
				double num6 = Distance - num4 - num5;
				double num7 = num6 / Vel;
				if (num6 < 0.0)
				{
					num7 = 0.0;
					num2 = Math.Sqrt(Distance / 2.0 / Acc);
					num3 = Math.Sqrt(Distance / 2.0 / Acc);
				}
				return num2 + num3 + num7;
			}
			return Distance / Vel;
		}
		return 0.0;
	}

	public double CalculateTotalTimeFromTrapezLinearMove(double MaxVelocity, double Acceleration, double Deceleration, double Distance)
	{
		double num = MaxVelocity * MaxVelocity / (2.0 * Acceleration);
		double num2 = MaxVelocity * MaxVelocity / (2.0 * Deceleration);
		if (!(num + num2 < Distance))
		{
			if (!buCompare5.EQ(num + num2, Distance, 0.1))
			{
				return Math.Sqrt(2.0 * Distance / Acceleration);
			}
			double num3 = MaxVelocity / Acceleration;
			double num4 = MaxVelocity / Deceleration;
			return num3 + num4;
		}
		double num5 = MaxVelocity / Acceleration;
		double num6 = MaxVelocity / Deceleration;
		double num7 = Distance - (num + num2);
		double num8 = num7 / MaxVelocity;
		return num5 + num8 + num6;
	}

	public double CalculateTotalTimeFromConstantMove(double MaxVelocity, double Distance)
	{
		double result = 0.0;
		if (Math.Abs(MaxVelocity) > 0.0)
		{
			result = Distance / Math.Abs(MaxVelocity);
		}
		return result;
	}

	public double CalculateTotalTimeFromTrapezJerkMove(double MaxVelocity, double MaxAcceleration, double MaxJerk, double Distance)
	{
		double num = Math.Sqrt(MaxAcceleration / MaxJerk);
		double num2 = 1.0 / 6.0 * MaxJerk * Math.Pow(num, 3.0);
		if (!(num2 * 2.0 < Distance))
		{
			return 2.0 * num;
		}
		double x = (MaxVelocity - MaxAcceleration * num) / MaxAcceleration;
		_ = MaxAcceleration * Math.Pow(x, 2.0);
		double num3 = Distance - 2.0 * num2;
		double num4 = num3 / MaxVelocity;
		return 2.0 * num + num4;
	}

	public void CheckDuplicatedPointsWithPrevious(ref List<Point3D> Points)
	{
		try
		{
			List<Point3D> copiedPoint = new List<Point3D>();
			if (Points.Count <= 0)
			{
				return;
			}
			Copy(Points, ref copiedPoint);
			Points.Clear();
			Points.Add(ToPoint3D(copiedPoint[0]));
			for (int i = 1; i <= copiedPoint.Count - 1; i++)
			{
				if (!buCompare5.EQ(Points[Points.Count - 1], copiedPoint[i]))
				{
					Points.Add(ToPoint3D(copiedPoint[i]));
				}
			}
			if (Points.Count > 0 && !buCompare5.EQ(Points[Points.Count - 1], copiedPoint[copiedPoint.Count - 1]))
			{
				Points.RemoveAt(Points.Count - 1);
