	public static Point3D ToPoint3D(Point3D Pnt, int Round = 0)
	{
		if (!(Pnt != null))
		{
			return new Point3D();
		}
		if (Round != 0)
		{
			return new Point3D(Math.Round(Pnt.X, Round), Math.Round(Pnt.Y, Round), Math.Round(Pnt.Z, Round));
		}
		return new Point3D(Pnt.X, Pnt.Y, Pnt.Z);
	}

