	public static Point3D Point3DDecodeFromString(string Value)
	{
		try
		{
			CultureInfo provider = new CultureInfo("en-US", useUserOverride: false);
			string numberDecimalSeparator = Application.CurrentCulture.NumberFormat.NumberDecimalSeparator;
			if (Value.IndexOf("|") >= 0)
			{
				string[] array = Value.Split('|');
				if (array != null && array.Length == 2)
				{
					Value = array[0];
				}
			}
			if (!(numberDecimalSeparator == ","))
			{
			}
			Point3D point3D = new Point3D();
			Value = Value.Replace("X:", "");
			Value = Value.Replace("Y:", "");
			Value = Value.Replace("Z:", "");
			Value = Value.Replace("(", "");
			Value = Value.Replace(")", "");
			string[] array2 = Value.Split(';');
			if (array2.Length != 3)
			{
				array2 = Value.Split(',');
			}
			if (array2.Length == 2)
			{
				point3D.X = double.Parse(array2[0], provider);
				point3D.Y = double.Parse(array2[1], provider);
				point3D.Z = 0.0;
			}
			if (array2.Length > 2)
			{
				point3D.X = double.Parse(array2[0], provider);
				point3D.Y = double.Parse(array2[1], provider);
				point3D.Z = double.Parse(array2[2], provider);
			}
			return point3D;
		}
		catch (Exception)
		{
			return new Point3D();
		}
	}

	public static Vector3D Vector3DDecodeFromString(string Value)
	{
		try
		{
			CultureInfo provider = new CultureInfo("en-US", useUserOverride: false);
			string numberDecimalSeparator = Application.CurrentCulture.NumberFormat.NumberDecimalSeparator;
			if (Value.IndexOf("|") >= 0)
			{
				string[] array = Value.Split('|');
				if (array != null && array.Length == 2)
				{
					Value = array[0];
				}
			}
			if (!(numberDecimalSeparator == ","))
			{
			}
			Vector3D result = null;
			Value = Value.Replace("X:", "");
			Value = Value.Replace("Y:", "");
			Value = Value.Replace("Z:", "");
			Value = Value.Replace("(", "");
			Value = Value.Replace(")", "");
			string[] array2 = Value.Split(';');
			if (array2.Length != 3)
			{
				array2 = Value.Split(',');
			}
			if (array2.Length == 2)
			{
				result = new Vector3D(double.Parse(array2[0], provider), double.Parse(array2[1], provider), 0.0);
			}
			if (array2.Length > 2)
			{
				result = new Vector3D(double.Parse(array2[0], provider), double.Parse(array2[1], provider), double.Parse(array2[2], provider));
			}
			return result;
		}
		catch (Exception)
		{
			return new Vector3D();
		}
	}

