	public bool isEntitiesClosed(List<Entity> refEntities)
	{
		if (refEntities.Count <= 0)
		{
			return false;
		}
		if (!((refEntities[0] is ICurve) & (refEntities[refEntities.Count - 1] is ICurve)))
		{
			return false;
		}
		Point3D point3D = new Point3D();
		Point3D point3D2 = new Point3D();
		entitySortDirection sortDirection = GetSortDirection(refEntities[0]);
		entitySortDirection sortDirection2 = GetSortDirection(refEntities[refEntities.Count - 1]);
		point3D = ((sortDirection == entitySortDirection.Normal) ? ((ICurve)refEntities[0]).StartPoint : ((ICurve)refEntities[0]).EndPoint);
		point3D2 = ((sortDirection2 == entitySortDirection.Normal) ? ((ICurve)refEntities[refEntities.Count - 1]).EndPoint : ((ICurve)refEntities[refEntities.Count - 1]).StartPoint);
		if (!buCompare5.EQ(point3D, point3D2, buSystem.resolutionCompare))
		{
			return false;
		}
