	public bool IsPointInsideWindow(Point3D LeftBottom, Point3D RightTop, Point3D ControledPoint, WorkPlane Plane, bool UseEqualCondition)
	{
		try
		{
			if (!UseEqualCondition)
			{
				if (WorkPlane.isPlaneXY(Plane) && ((LeftBottom.X < ControledPoint.X) & (ControledPoint.X < RightTop.X)) && ((LeftBottom.Y < ControledPoint.Y) & (ControledPoint.Y < RightTop.Y)))
				{
					return true;
				}
				if (WorkPlane.isPlaneXZ(Plane) && ((LeftBottom.X < ControledPoint.X) & (ControledPoint.X < RightTop.X)) && ((LeftBottom.Z < ControledPoint.Z) & (ControledPoint.Z < RightTop.Z)))
				{
					return true;
				}
				if (WorkPlane.isPlaneYZ(Plane) && ((LeftBottom.Y < ControledPoint.Y) & (ControledPoint.Y < RightTop.Y)) && ((LeftBottom.Z < ControledPoint.Z) & (ControledPoint.Z < RightTop.Z)))
				{
					return true;
				}
			}
			else
			{
				if (WorkPlane.isPlaneXY(Plane) && ((LeftBottom.X <= ControledPoint.X) & (ControledPoint.X <= RightTop.X)) && ((LeftBottom.Y <= ControledPoint.Y) & (ControledPoint.Y <= RightTop.Y)))
				{
					return true;
				}
				if (WorkPlane.isPlaneXZ(Plane) && ((LeftBottom.X <= ControledPoint.X) & (ControledPoint.X <= RightTop.X)) && ((LeftBottom.Z <= ControledPoint.Z) & (ControledPoint.Z <= RightTop.Z)))
				{
					return true;
				}
				if (WorkPlane.isPlaneYZ(Plane) && ((LeftBottom.Y <= ControledPoint.Y) & (ControledPoint.Y <= RightTop.Y)) && ((LeftBottom.Z <= ControledPoint.Z) & (ControledPoint.Z <= RightTop.Z)))
				{
					return true;
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "LeftBottom: " + LeftBottom.ToString() + " - RightTop: " + RightTop.ToString() + " - ControledPoint: " + ControledPoint.ToString() + " - UseEqualCondition: " + UseEqualCondition + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return false;
		}
		return false;
	}

