			double num2 = Length3D(LineStart, RefPoint, Plane);
			double value2 = num + num2;
			ClosestPoint = -1;
			if (!(num2 < num))
			{
				ClosestPoint = 1;
				InsideDistance = num;
			}
			else
			{
				ClosestPoint = 0;
				InsideDistance = num2;
			}
			if (!buCompare5.EQ(value2, value, Resolution))
