				value2 = ((((CustomData)RefEntities[RefEntities.Count - 1].EntityData).sortDirection == entitySortDirection.Normal) ? ToPoint3D(RefEntities[RefEntities.Count - 1].Vertices[RefEntities[RefEntities.Count - 1].Vertices.Length - 1]) : ToPoint3D(RefEntities[RefEntities.Count - 1].Vertices[0]));
			}
			if (RefEntities.Count == 1 && RefEntities[0].Vertices.Length > 2)
			{
				value = ToPoint3D(RefEntities[0].Vertices[0]);
				value2 = ToPoint3D(RefEntities[0].Vertices[RefEntities[0].Vertices.Length - 1]);
			}
			if (!buCompare5.EQ(value, value2))
			{
				return false;
			}
			return true;
		}
		catch (Exception mSException)
		{
			string text = "RefEntities: " + RefEntities.Count;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return false;
		}
	}

	public bool IsEntitiesClosedPath(List<buEntity> RefEntities)
	{
		try
		{
			Point3D value = new Point3D();
			Point3D value2 = new Point3D(10.0, 10.0, 10.0);
			if (RefEntities.Count > 1)
			{
				value = ((RefEntities[0].sortDirection == entitySortDirection.Normal) ? ToPoint3D(RefEntities[0].StartPoint) : ToPoint3D(RefEntities[0].EndPoint));
				value2 = ((RefEntities[RefEntities.Count - 1].sortDirection == entitySortDirection.Normal) ? ToPoint3D(RefEntities[RefEntities.Count - 1].EndPoint) : ToPoint3D(RefEntities[RefEntities.Count - 1].StartPoint));
			}
			if (RefEntities.Count == 1)
			{
				value = ToPoint3D(RefEntities[0].StartPoint);
				value2 = ToPoint3D(RefEntities[0].EndPoint);
			}
			if (!buCompare5.EQ(value, value2))
			{
				return false;
			}
			return true;
		}
		catch (Exception mSException)
		{
			string text = "RefEntities: " + RefEntities.Count;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return false;
		}
	}

	public double GetTimeFromDistanceAndAcc(double Distance, double Acc)
	{
		return Math.Sqrt(2.0 * Distance / Acc);
	}

	public void SaveDxfFile(string FileName, Design refModel)
	{
		WriteFileAsync writeFileAsync = null;
		WriteAutodeskParams writeAutodeskParams = new WriteAutodeskParams(refModel.Document);
		writeAutodeskParams.Version = autodeskVersionType.Acad2010;
		writeFileAsync = new WriteAutodesk(writeAutodeskParams, FileName);
		refModel.DoWork(writeFileAsync);
	}

	public void ReadDxfFile(string FileName, Design refModel, ref List<Entity> Entities)
	{
		ReadFileAsync readFileAsync = new ReadAutodesk(FileName);
		((ReadAutodesk)readFileAsync).ExtrudeByThickness = false;
		readFileAsync.DoWork();
		if (readFileAsync.Entities != null)
		{
			Entities.AddRange(readFileAsync.Entities);
		}
	}

	public void ReadStlFile(string FileName, ref List<Entity> Entities)
	{
		ReadSTL readSTL = new ReadSTL(FileName);
		readSTL.DoWork();
		if (readSTL.Entities != null)
		{
			Entities.AddRange(readSTL.Entities);
		}
	}

	public void ReadStepFile(string FileName, ref List<Entity> Entities)
	{
		ReadSTEP readSTEP = new ReadSTEP(FileName);
		readSTEP.DoWork();
		if (readSTEP.Entities != null)
		{
			Entities.AddRange(readSTEP.Entities);
		}
	}

	public void ReadStepFile(string FileName, ref Design refViewport)
	{
		ReadSTEP readSTEP = new ReadSTEP(FileName);
		readSTEP.DoWork();
		if (readSTEP.Entities != null)
		{
			readSTEP.OpenTo(refViewport);
		}
	}

